final_template:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "reserved_subnet_cidr" {
  description = "CIDR block for the reserved subnet"
  type        = string
  default     = "10.0.0.0/24"
}

variable "sandbox_subnet_cidr" {
  description = "CIDR block for the sandbox subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "web_subnet_cidr" {
  description = "CIDR block for the web subnet"
  type        = string
  default     = "10.0.2.0/24"
}

variable "database_subnet_cidr" {
  description = "CIDR block for the database subnet"
  type        = string
  default     = "10.0.3.0/24"
}

variable "gameserver_subnet_cidr" {
  description = "CIDR block for the gameserver subnet"
  type        = string
  default     = "10.0.4.0/22"
}

variable "internal_domain" {
  description = "Domain name for the private DNS zone and DHCP options"
  type        = string
  default     = "internal"
}

variable "ssh_ips" {
  description = "List of CIDR blocks allowed SSH access for the Home SSH security group"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "main-igw"
  }
}

# Subnets
resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = var.reserved_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved-subnet"
  }
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = var.sandbox_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "sandbox-subnet"
  }
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = var.web_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "web-subnet"
  }
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = var.database_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "database-subnet"
  }
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = var.gameserver_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "gameserver-subnet"
  }
}

# Route Tables
resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "reserved-route-table"
  }
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "sandbox-route-table"
  }
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "web-route-table"
  }
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "database-route-table"
  }
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "gameserver-route-table"
  }
}

# Default routes to IGW
resource "aws_route" "reserved_default" {
  route_table_id         = aws_route_table.reserved.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route" "sandbox_default" {
  route_table_id         = aws_route_table.sandbox.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route" "web_default" {
  route_table_id         = aws_route_table.web.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route" "database_default" {
  route_table_id         = aws_route_table.database.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route" "gameserver_default" {
  route_table_id         = aws_route_table.gameserver.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

# Route Table Associations
resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_route_table_association" "sandbox" {
  subnet_id      = aws_subnet.sandbox.id
  route_table_id = aws_route_table.sandbox.id
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table_association" "gameserver" {
  subnet_id      = aws_subnet.gameserver.id
  route_table_id = aws_route_table.gameserver.id
}

# Network ACLs

# Sandbox NACL
resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main_vpc.id
  subnet_ids = [aws_subnet.sandbox.id]

  tags = {
    Name = "sandbox-nacl"
  }
}

resource "aws_network_acl_rule" "sandbox_inbound_tcp" {
  network_acl_id = aws_network_acl.sandbox.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "sandbox_outbound_tcp" {
  network_acl_id = aws_network_acl.sandbox.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

# Web NACL
resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main_vpc.id
  subnet_ids = [aws_subnet.web.id]

  tags = {
    Name = "web-nacl"
  }
}

resource "aws_network_acl_rule" "web_inbound_ssh" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "web_inbound_http" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "web_inbound_https" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "web_inbound_ephemeral" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 130
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "web_outbound_all" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

# Database NACL
resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main_vpc.id
  subnet_ids = [aws_subnet.database.id]

  tags = {
    Name = "database-nacl"
  }
}

resource "aws_network_acl_rule" "database_inbound_from_web" {
  network_acl_id = aws_network_acl.database.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.web_subnet_cidr
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "database_inbound_from_gameserver" {
  network_acl_id = aws_network_acl.database.id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.gameserver_subnet_cidr
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "database_outbound_to_web" {
  network_acl_id = aws_network_acl.database.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.web_subnet_cidr
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "database_outbound_to_gameserver" {
  network_acl_id = aws_network_acl.database.id
  rule_number    = 110
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.gameserver_subnet_cidr
  from_port      = 0
  to_port        = 65535
}

# Gameserver NACL
resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main_vpc.id
  subnet_ids = [aws_subnet.gameserver.id]

  tags = {
    Name = "gameserver-nacl"
  }
}

resource "aws_network_acl_rule" "gameserver_inbound_ssh" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "gameserver_inbound_tcp_27015" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 27015
  to_port        = 27015
}

resource "aws_network_acl_rule" "gameserver_inbound_tcp_27020" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 27020
  to_port        = 27020
}

resource "aws_network_acl_rule" "gameserver_inbound_udp_27015" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 130
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 27015
  to_port        = 27015
}

resource "aws_network_acl_rule" "gameserver_inbound_udp_27020" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 140
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 27020
  to_port        = 27020
}

resource "aws_network_acl_rule" "gameserver_inbound_ephemeral_tcp" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 150
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "gameserver_inbound_ephemeral_udp" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 160
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "gameserver_outbound_all_tcp" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "gameserver_outbound_all_udp" {
  network_acl_id = aws_network_acl.gameserver.id
  rule_number    = 110
  egress         = true
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

# Security Groups

# Home SSH SG
resource "aws_security_group" "home_ssh" {
  name        = "home-ssh-sg"
  description = "Security group allowing SSH from configurable IPs"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.ssh_ips
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "home-ssh-sg"
  }
}

# Packer SSH SG
resource "aws_security_group" "packer_ssh" {
  name        = "packer-ssh-sg"
  description = "Security group allowing SSH from restricted IPs"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "packer-ssh-sg"
  }
}

# Route53 Private Zone
resource "aws_route53_zone" "private_zone" {
  name = var.internal_domain

  vpc {
    vpc_id = aws_vpc.main_vpc.id
  }

  comment = "Private DNS zone for internal"

  lifecycle {
    prevent_destroy = true
  }
}

# DHCP Options
resource "aws_vpc_dhcp_options" "dhcp_opts" {
  domain_name         = var.internal_domain
  domain_name_servers = ["10.0.0.2", "8.8.8.8"]

  tags = {
    Name = "internal-dhcp"
  }
}

resource "aws_vpc_dhcp_options_association" "dhcp_assoc" {
  vpc_id          = aws_vpc.main_vpc.id
  dhcp_options_id = aws_vpc_dhcp_options.dhcp_opts.id
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main_vpc.id
}

output "reserved_subnet_id" {
  value = aws_subnet.reserved.id
}

output "sandbox_subnet_id" {
  value = aws_subnet.sandbox.id
}

output "web_subnet_id" {
  value = aws_subnet.web.id
}

output "database_subnet_id" {
  value = aws_subnet.database.id
}

output "gameserver_subnet_id" {
  value = aws_subnet.gameserver.id
}

output "home_ssh_security_group_id" {
  value = aws_security_group.home_ssh.id
}

output "private_dns_zone_id" {
  value = aws_route53_zone.private_zone.zone_id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "server_name" {
  description = "Optional name for the Transfer server. Used as a tag value only."
  type        = string
  default     = null
}

variable "endpoint_type" {
  description = "The type of endpoint for the Transfer server. Valid values: PUBLIC, VPC, VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"
  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "subnet_ids" {
  description = "List of subnet IDs for VPC endpoint type. If null and endpoint_type is VPC, two subnets will be created."
  type        = list(string)
  default     = null
}

variable "vpc_id" {
  description = "VPC ID for VPC endpoint type when subnet_ids are provided (i.e., when the VPC is not created by this template)."
  type        = string
  default     = null

  validation {
    condition = (
      var.endpoint_type != "VPC" ||
      var.subnet_ids == null ||
      var.vpc_id != null
    )
    error_message = "When endpoint_type is VPC and subnet_ids is provided, vpc_id must also be provided."
  }
}

variable "address_allocation_ids" {
  description = "List of Elastic IP allocation IDs for VPC endpoint type. Required if subnet_ids is provided."
  type        = list(string)
  default     = null
}

variable "identity_provider_type" {
  description = "Identity provider type: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, or AWS_LAMBDA."
  type        = string
  default     = "SERVICE_MANAGED"
  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "AWS_LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be one of: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, AWS_LAMBDA."
  }
}

variable "api_gateway_url" {
  description = "URL of the API Gateway endpoint for identity provider type API_GATEWAY."
  type        = string
  default     = null
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role for logging. If null, a new role will be created."
  type        = string
  default     = null
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch log group for structured logging."
  type        = string
  default     = "/aws/transfer/server"
}

variable "security_policy_name" {
  description = "Security policy name for the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "pre_authentication_login_banner" {
  description = "Pre-authentication login banner."
  type        = string
  default     = ""
}

variable "post_authentication_login_banner" {
  description = "Post-authentication login banner."
  type        = string
  default     = ""
}

variable "certificate" {
  description = "ARN of an ACM certificate for FTPS."
  type        = string
  default     = null
}

variable "host_key" {
  description = "Host key (private key) for the server. Sensitive."
  type        = string
  default     = null
  sensitive   = true
}

variable "protocols" {
  description = "List of protocols to enable. Default includes SFTP, FTPS, FTP."
  type        = list(string)
  default     = ["SFTP", "FTPS", "FTP"]
}

variable "as2_transport" {
  description = "Enable AS2 transport. If true, 'AS2' is added to the protocols list."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for creating a CNAME record to the server endpoint."
  type        = string
  default     = null
}

variable "subdomain" {
  description = "Subdomain for the Route53 CNAME record."
  type        = string
  default     = "sftp"
}

variable "users" {
  description = "Map of usernames to home directory S3 paths (e.g., /bucket-name/home/user)."
  type        = map(string)
  default     = {}
}

variable "ssh_public_keys" {
  description = "Map of usernames to lists of SSH public keys to associate."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "A map of tags to apply to all created resources."
  type        = map(string)
  default     = {}
}

locals {
  # Determine if VPC resources are needed
  create_vpc = var.endpoint_type == "VPC" && var.subnet_ids == null

  # Number of subnets to create (default 2)
  subnet_count = local.create_vpc ? 2 : 0

  # Protocols: include AS2 if enabled
  protocols = var.as2_transport ? concat(var.protocols, ["AS2"]) : var.protocols

  # Parse home directory map to extract bucket name and path
  user_bucket_paths = {
    for username, home_dir in var.users : username => {
      bucket = split("/", trimprefix(home_dir, "/"))[0]
      path   = home_dir
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

# ----------------------------------------------------------------------------
# VPC and Subnets (only for VPC endpoint type when subnet_ids not provided)
# ----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "transfer-sftp-vpc"
  })
}

resource "aws_subnet" "public" {
  count = local.create_vpc ? local.subnet_count : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = cidrsubnet(aws_vpc.main[0].cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.tags, {
    Name = "transfer-sftp-subnet-${count.index + 1}"
  })
}

# ----------------------------------------------------------------------------
# Security Group for VPC endpoint
# ----------------------------------------------------------------------------
resource "aws_security_group" "transfer" {
  count = var.endpoint_type == "VPC" ? 1 : 0

  name        = "transfer-sftp-sg"
  description = "Security group for AWS Transfer Family SFTP server (VPC endpoint)"
  vpc_id      = local.create_vpc ? aws_vpc.main[0].id : var.vpc_id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "transfer-sftp-sg"
  })
}

# ----------------------------------------------------------------------------
# Elastic IPs (only when VPC endpoint and subnets are created)
# ----------------------------------------------------------------------------
resource "aws_eip" "transfer" {
  count = local.create_vpc ? local.subnet_count : 0

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "transfer-sftp-eip-${count.index + 1}"
  })
}

# ----------------------------------------------------------------------------
# IAM Role for Logging
# ----------------------------------------------------------------------------
resource "aws_iam_role" "logging" {
  count = var.logging_role_arn == null ? 1 : 0

  name = "transfer-sftp-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = var.logging_role_arn == null ? 1 : 0

  role       = aws_iam_role.logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# ----------------------------------------------------------------------------
# IAM Role for API Gateway Authentication (if identity provider type is API_GATEWAY)
# ----------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name = "transfer-sftp-api-gateway-auth-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "api_gateway" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name = "transfer-sftp-api-gateway-logs"
  role = aws_iam_role.api_gateway[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------------
# CloudWatch Log Group
# ----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "transfer" {
  name = var.cloudwatch_log_group_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# Transfer Server
# ----------------------------------------------------------------------------
resource "aws_transfer_server" "main" {
  domain                       = "S3"
  endpoint_type                = var.endpoint_type
  protocols                    = local.protocols
  identity_provider_type       = var.identity_provider_type
  logging_role                 = var.logging_role_arn != null ? var.logging_role_arn : aws_iam_role.logging[0].arn
  security_policy_name         = var.security_policy_name
  pre_authentication_login_banner = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner
  certificate                  = var.certificate
  host_key                     = var.host_key
  structured_log_destinations  = [aws_cloudwatch_log_group.transfer.arn]
  url                          = var.identity_provider_type == "API_GATEWAY" ? var.api_gateway_url : null
  invocation_role              = var.identity_provider_type == "API_GATEWAY" ? aws_iam_role.api_gateway[0].arn : null

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "VPC" ? [1] : []
    content {
      vpc_id               = local.create_vpc ? aws_vpc.main[0].id : var.vpc_id
      subnet_ids           = local.create_vpc ? aws_subnet.public[*].id : var.subnet_ids
      address_allocation_ids = local.create_vpc ? aws_eip.transfer[*].allocation_id : var.address_allocation_ids
      security_group_ids     = [aws_security_group.transfer[0].id]
    }
  }

  tags = merge(var.tags, {
    Name = "transfer-sftp-server-${var.server_name != null ? var.server_name : random_pet.server_name.id}"
  })
}

# ----------------------------------------------------------------------------
# Route53 CNAME Record (optional)
# ----------------------------------------------------------------------------
resource "aws_route53_record" "sftp" {
  count = var.route53_zone_id != null ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.main.endpoint]
}

# ----------------------------------------------------------------------------
# IAM Roles and Policies for Users
# ----------------------------------------------------------------------------
resource "aws_iam_role" "transfer_user" {
  for_each = var.users

  name = "transfer-sftp-user-${each.key}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.tags, {
    Name = "transfer-sftp-user-${each.key}"
  })
}

data "aws_iam_policy_document" "user_policy" {
  for_each = var.users

  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [
      "arn:aws:s3:::${local.user_bucket_paths[each.key].bucket}"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:PutObjectVersion",
      "s3:DeleteObjectVersion"
    ]
    resources = [
      "arn:aws:s3:::${local.user_bucket_paths[each.key].path}*",
      "arn:aws:s3:::${local.user_bucket_paths[each.key].path}/*"
    ]
  }
}

resource "aws_iam_role_policy" "user_policy" {
  for_each = var.users

  name   = "transfer-sftp-user-policy-${each.key}"
  role   = aws_iam_role.transfer_user[each.key].id
  policy = data.aws_iam_policy_document.user_policy[each.key].json
}

# ----------------------------------------------------------------------------
# Transfer Users
# ----------------------------------------------------------------------------
resource "aws_transfer_user" "user" {
  for_each = var.users

  server_id     = aws_transfer_server.main.id
  user_name     = each.key
  role          = aws_iam_role.transfer_user[each.key].arn
  home_directory = each.value

  tags = merge(var.tags, {
    Name = "transfer-sftp-user-${each.key}"
  })
}

# ----------------------------------------------------------------------------
# SSH Keys for Users (optional)
# ----------------------------------------------------------------------------
resource "aws_transfer_ssh_key" "user" {
  for_each = {
    for username, keys in var.ssh_public_keys : username => keys
    if length(keys) > 0
  }

  server_id = aws_transfer_server.main.id
  user_name = each.key
  body      = each.value[0]

  # Note: For multiple keys per user, create a separate resource per key.
  # This can be achieved by flattening the map, but for simplicity we assume one key per user.
  # If multiple keys are required, use a flattened local.
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------
output "server_arn" {
  value = aws_transfer_server.main.arn
}

output "server_id" {
  value = aws_transfer_server.main.id
}

output "endpoint" {
  value = aws_transfer_server.main.endpoint
}

output "custom_dns" {
  value = var.route53_zone_id != null ? aws_route53_record.sftp[0].name : null
}

output "security_group_id" {
  value = var.endpoint_type == "VPC" ? aws_security_group.transfer[0].id : null
}

output "elastic_ips" {
  value = local.create_vpc ? aws_eip.transfer[*].public_ip : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "name_prefix" {
  description = "Prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "enable_athena_database" {
  description = "Flag to enable Athena database creation"
  type        = bool
  default     = true
}

variable "enable_athena_workgroup" {
  description = "Flag to enable Athena workgroup creation"
  type        = bool
  default     = true
}

variable "enable_athena_named_query" {
  description = "Flag to enable Athena named query creation"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key for S3 bucket and Athena encryption. If not provided, a new key is created."
  type        = string
  default     = null
}

variable "workgroup_state" {
  description = "State of the Athena workgroup: ENABLED or DISABLED"
  type        = string
  default     = "ENABLED"
  validation {
    condition     = contains(["ENABLED", "DISABLED"], var.workgroup_state)
    error_message = "Workgroup state must be either ENABLED or DISABLED."
  }
}

variable "workgroup_description" {
  description = "Description for the Athena workgroup"
  type        = string
  default     = ""
}

variable "publish_cloudwatch_metrics_enabled" {
  description = "Enable publishing CloudWatch metrics for the workgroup"
  type        = bool
  default     = false
}

variable "bytes_scanned_cutoff_per_query" {
  description = "Bytes scanned cutoff per query in the workgroup (0 = no limit)"
  type        = number
  default     = 0
}

variable "query" {
  description = "SQL query string for the named query"
  type        = string
  default     = ""
}

variable "named_query_description" {
  description = "Description for the named query"
  type        = string
  default     = ""
}

variable "named_query_name" {
  description = "Name for the named query. If not provided, defaults to <prefix>_<environment>"
  type        = string
  default     = ""
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}

# Locals
locals {
  name_prefix_lower = lower(var.name_prefix)
  environment_lower = lower(var.environment)
  bucket_name       = "${local.name_prefix_lower}-${local.environment_lower}-athena-results"
  database_name     = "${local.name_prefix_lower}_${local.environment_lower}"
  workgroup_name    = "${local.name_prefix_lower}-${local.environment_lower}"
  named_query_name  = var.named_query_name != "" ? var.named_query_name : "${local.name_prefix_lower}_${local.environment_lower}"

  # Determine if a new KMS key must be created for S3 bucket and Athena encryption
  create_kms_key = var.kms_key_arn == null ? 1 : 0
  # S3 encryption key ARN (always a CMK, either existing or newly created)
  s3_encryption_key_arn = var.kms_key_arn != null ? var.kms_key_arn : aws_kms_key.s3_encryption_key[0].arn
  # Athena encryption key ARN – always uses the KMS key for SSE_KMS
  athena_encryption_key_arn = local.s3_encryption_key_arn
}

# S3 Bucket for Athena query results
resource "aws_s3_bucket" "athena_results" {
  bucket = local.bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_public_access_block" "athena_results" {
  bucket                  = aws_s3_bucket.athena_results.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "athena_results" {
  bucket = aws_s3_bucket.athena_results.id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket encryption uses a customer managed KMS key (CMK)
resource "aws_s3_bucket_server_side_encryption_configuration" "athena_results" {
  bucket = aws_s3_bucket.athena_results.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.s3_encryption_key_arn
    }
  }
}

# KMS Key for S3 bucket encryption and Athena encryption
resource "aws_kms_key" "s3_encryption_key" {
  count = local.create_kms_key
  description             = "KMS key for S3 bucket and Athena encryption - ${local.workgroup_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "s3_encryption_key" {
  count = local.create_kms_key
  name          = "alias/${local.workgroup_name}-s3-encryption"
  target_key_id = aws_kms_key.s3_encryption_key[0].key_id
}

# Athena Database
resource "aws_athena_database" "athena_database" {
  count = var.enable_athena_database ? 1 : 0
  name   = local.database_name
  bucket = aws_s3_bucket.athena_results.bucket
  force_destroy = true

  encryption_configuration {
    encryption_option = "SSE_S3"
  }
}

# Athena Workgroup
resource "aws_athena_workgroup" "athena_workgroup" {
  count = var.enable_athena_workgroup ? 1 : 0
  name        = local.workgroup_name
  description = var.workgroup_description
  state       = var.workgroup_state
  force_destroy = true

  configuration {
    # Enforce workgroup configuration to prevent client-side overrides
    enforce_workgroup_configuration    = true
    publish_cloudwatch_metrics_enabled = var.publish_cloudwatch_metrics_enabled
    bytes_scanned_cutoff_per_query     = var.bytes_scanned_cutoff_per_query

    result_configuration {
      output_location = "s3://${aws_s3_bucket.athena_results.bucket}/output/"

      # Static encryption configuration using SSE_KMS with the customer managed key
      encryption_configuration {
        encryption_option = "SSE_KMS"
        kms_key_arn       = local.athena_encryption_key_arn
      }
    }
  }
}

# Athena Named Query
resource "aws_athena_named_query" "athena_named_query" {
  count = var.enable_athena_named_query ? 1 : 0
  name        = local.named_query_name
  description = var.named_query_description
  query       = var.query
  database    = try(one(aws_athena_database.athena_database[*].name), null)
  workgroup   = try(one(aws_athena_workgroup.athena_workgroup[*].name), null)
}

# Outputs
output "athena_database_id" {
  description = "ID of the Athena database"
  value       = try(aws_athena_database.athena_database[0].id, null)
}

output "athena_named_query_id" {
  description = "ID of the Athena named query"
  value       = try(aws_athena_named_query.athena_named_query[0].id, null)
}

output "athena_workgroup_id" {
  description = "ID of the Athena workgroup"
  value       = try(aws_athena_workgroup.athena_workgroup[0].id, null)
}

output "athena_workgroup_arn" {
  description = "ARN of the Athena workgroup"
  value       = try(aws_athena_workgroup.athena_workgroup[0].arn, null)
}

# Terraform configuration
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider configuration (region set to us-east-1)
provider "aws" {
  region = "us-east-1"
}

# Variables
variable "name_prefix" {
  description = "Prefix for naming IAM roles and instance profile"
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Data sources for AWS managed policies
data "aws_iam_policy" "emr_service" {
  name = "AmazonEMRServicePolicy_v2"
}

data "aws_iam_policy" "emr_ec2" {
  name = "AmazonElasticMapReduceforEC2Role"
}

data "aws_iam_policy" "cloudwatch_agent" {
  name = "CloudWatchAgentServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance" {
  name = "AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy" "emr_autoscaling" {
  name = "AmazonElasticMapReduceforAutoScalingRole"
}

# Locals for reused strings
locals {
  service_role_name      = "${var.name_prefix}-emr-service"
  ec2_role_name          = "${var.name_prefix}-emr-ec2"
  autoscaling_role_name  = "${var.name_prefix}-emr-autoscaling"
  instance_profile_name  = "${var.name_prefix}-emr-instance-profile"
}

# IAM Role for EMR Service
resource "aws_iam_role" "emr_service_role" {
  name = local.service_role_name
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "emr_service" {
  role       = aws_iam_role.emr_service_role.name
  policy_arn = data.aws_iam_policy.emr_service.arn
}

# IAM Role for EC2 (used by EMR)
resource "aws_iam_role" "emr_ec2_role" {
  name = local.ec2_role_name
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "emr_ec2" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = data.aws_iam_policy.emr_ec2.arn
}

resource "aws_iam_role_policy_attachment" "emr_ec2_cloudwatch" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = data.aws_iam_policy.cloudwatch_agent.arn
}

resource "aws_iam_role_policy_attachment" "emr_ec2_ssm" {
  role       = aws_iam_role.emr_ec2_role.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance.arn
}

# Instance profile for EC2 role
resource "aws_iam_instance_profile" "emr_ec2_instance_profile" {
  name = local.instance_profile_name
  role = aws_iam_role.emr_ec2_role.name
  tags = var.tags
}

# IAM Role for Application Autoscaling
resource "aws_iam_role" "emr_autoscaling_role" {
  name = local.autoscaling_role_name
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling" {
  role       = aws_iam_role.emr_autoscaling_role.name
  policy_arn = data.aws_iam_policy.emr_autoscaling.arn
}

# Outputs
output "emr_service_role_arn" {
  value = aws_iam_role.emr_service_role.arn
}

output "emr_service_role_name" {
  value = aws_iam_role.emr_service_role.name
}

output "emr_service_role_unique_id" {
  value = aws_iam_role.emr_service_role.unique_id
}

output "emr_ec2_role_arn" {
  value = aws_iam_role.emr_ec2_role.arn
}

output "emr_ec2_role_name" {
  value = aws_iam_role.emr_ec2_role.name
}

output "emr_ec2_role_unique_id" {
  value = aws_iam_role.emr_ec2_role.unique_id
}

output "emr_autoscaling_role_arn" {
  value = aws_iam_role.emr_autoscaling_role.arn
}

output "emr_autoscaling_role_name" {
  value = aws_iam_role.emr_autoscaling_role.name
}

output "emr_autoscaling_role_unique_id" {
  value = aws_iam_role.emr_autoscaling_role.unique_id
}

output "emr_ec2_instance_profile_id" {
  value = aws_iam_instance_profile.emr_ec2_instance_profile.id
}

output "emr_ec2_instance_profile_arn" {
  value = aws_iam_instance_profile.emr_ec2_instance_profile.arn
}

output "emr_ec2_instance_profile_name" {
  value = aws_iam_instance_profile.emr_ec2_instance_profile.name
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "= 2.22.0"
    }
  }
}

resource "docker_image" "nginx" {
  name         = "nginx:1.19.6"
  keep_locally = true
}

resource "docker_container" "tutorial" {
  name  = "tutorial"
  image = docker_image.nginx.name
  ports {
    internal = 80
    external = 2224
    protocol = "tcp"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "kms_key_alias" {
  description = "Alias name for the KMS CMK (without 'alias/' prefix)"
  type        = string
  default     = "kms-cmk-example"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "cmk" {
  description              = "KMS CMK for testing and learning purposes"
  deletion_window_in_days  = 7
  enable_key_rotation      = false
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableFullAdminAccessForCurrentUser"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cmk" {
  name          = "alias/${var.kms_key_alias}"
  target_key_id = aws_kms_key.cmk.id
}

output "cmk_arn" {
  description = "ARN of the KMS CMK"
  value       = aws_kms_key.cmk.arn
}

output "cmk_alias_name" {
  description = "Alias name of the KMS CMK"
  value       = aws_kms_alias.cmk.name
}

variable "prefix" {
  description = "Prefix for all IAM resource names"
  type        = string
  default     = "homelab"
}

terraform {
  required_version = ">= 1.2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.21"
    }
  }
}

data "aws_iam_policy_document" "ec2_lab_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "ec2_lab_role" {
  name               = "${var.prefix}-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_lab_assume_role.json
  description        = "Role for EC2 home lab environment"

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "ec2_lab_policy" {
  statement {
    sid    = "EC2Management"
    effect = "Allow"
    actions = [
      "ec2:CreateLaunchTemplate",
      "ec2:CreateLaunchTemplateVersion",
      "ec2:DeleteLaunchTemplate",
      "ec2:DeleteLaunchTemplateVersion",
      "ec2:CreateFleet",
      "ec2:DeleteFleet",
      "ec2:RunInstances",
      "ec2:TerminateInstances",
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:CreateTags",
      "ec2:DeleteTags",
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeLaunchTemplates",
      "ec2:DescribeLaunchTemplateVersions",
      "ec2:DescribeFleets",
      "ec2:DescribeFleetHistory",
      "ec2:DescribeFleetInstances",
      "ec2:DescribeImages",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshots",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeAccountAttributes",
      "ec2:DescribeRegions",
      "ec2:DescribePlacementGroups",
      "ec2:DescribeCapacityReservations",
      "ec2:DescribeCapacityReservationOfferings",
      "ec2:DescribeSpotPriceHistory",
      "ec2:DescribeSpotFleetRequests",
      "ec2:DescribeSpotInstanceRequests",
      "ec2:RequestSpotInstances",
      "ec2:CancelSpotInstanceRequests",
      "ec2:ModifySpotFleetRequest",
      "ec2:AssociateIamInstanceProfile",
      "ec2:DisassociateIamInstanceProfile",
      "ec2:ReplaceIamInstanceProfileAssociation",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "PassIamRoles"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "ec2_lab_policy" {
  name        = "${var.prefix}-ec2-policy"
  description = "Policy for EC2 home lab environment"
  policy      = data.aws_iam_policy_document.ec2_lab_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "ec2_lab_attachment" {
  role       = aws_iam_role.ec2_lab_role.name
  policy_arn = aws_iam_policy.ec2_lab_policy.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# Variables
variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-cluster"
}

variable "oidc_provider_arn" {
  description = "ARN of the OIDC provider for the EKS cluster"
  type        = string
  default     = "arn:aws:iam::000000000000:oidc-provider/oidc.eks.region.amazonaws.com/id"
}

variable "cluster_ip_family" {
  description = "IP family of the EKS cluster (ipv4 or ipv6)"
  type        = string
  default     = "ipv4"
  validation {
    condition     = contains(["ipv4", "ipv6"], var.cluster_ip_family)
    error_message = "cluster_ip_family must be either ipv4 or ipv6."
  }
}

variable "create_irsa_role" {
  description = "Whether to create the IAM role for the Karpenter IRSA"
  type        = bool
  default     = true
}

variable "create_node_role" {
  description = "Whether to create the IAM role for Karpenter nodes"
  type        = bool
  default     = true
}

variable "create_health_event_rule" {
  description = "Whether to create the CloudWatch event rule for EC2 health events"
  type        = bool
  default     = true
}

variable "create_spot_interruption_rule" {
  description = "Whether to create the CloudWatch event rule for spot interruption warnings"
  type        = bool
  default     = true
}

variable "create_rebalance_rule" {
  description = "Whether to create the CloudWatch event rule for instance rebalance recommendations"
  type        = bool
  default     = true
}

variable "create_instance_state_change_rule" {
  description = "Whether to create the CloudWatch event rule for instance state-change notifications"
  type        = bool
  default     = true
}

variable "extra_node_policy_arns" {
  description = "List of additional IAM policy ARNs to attach to the node role"
  type        = list(string)
  default     = []
}

# Locals
locals {
  sqs_queue_name = "Karpenter-${var.cluster_name}"

  # Extract OIDC provider URL from ARN
  # ARN format: arn:aws:iam::account-id:oidc-provider/oidc.eks.region.amazonaws.com/id
  oidc_provider_url = regex("oidc-provider/(.+)", var.oidc_provider_arn)[0]

  # Node role ARN reference (conditional)
  node_role_arn = var.create_node_role ? aws_iam_role.karpenter_node[0].arn : null

  # Managed policies for node role
  node_managed_policies = concat(
    [
      "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
      "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
      var.cluster_ip_family == "ipv6" ? "arn:aws:iam::aws:policy/AmazonEKS_CNI_IPv6_Policy" : "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
    ],
    var.extra_node_policy_arns
  )

  # Common IAM policy statements used across multiple documents
  karpenter_controller_policy_statements = [
    {
      Sid    = "EC2Permissions"
      Effect = "Allow"
      Action = [
        "ec2:DescribeInstances",
        "ec2:DescribeLaunchTemplates",
        "ec2:DescribeSecurityGroups",
        "ec2:DescribeSubnets",
        "ec2:DescribeSpotPriceHistory",
        "ec2:DescribeAvailabilityZones",
        "ec2:DescribeInstanceTypes",
        "ec2:DescribeInstanceTypeOfferings",
        "ec2:DescribeImages",
        "ec2:DescribeTags"
      ]
      Resource = ["*"]
    },
    {
      Sid    = "ModifyEC2Resources"
      Effect = "Allow"
      Action = [
        "ec2:RunInstances",
        "ec2:TerminateInstances",
        "ec2:CreateLaunchTemplate",
        "ec2:DeleteLaunchTemplate",
        "ec2:CreateTags"
      ]
      Resource = ["*"]
      Condition = {
        StringEquals = {
          "aws:ResourceTag/karpenter.sh/discovery" = var.cluster_name
        }
      }
    },
    {
      Sid    = "SSMParameterAccess"
      Effect = "Allow"
      Action = [
        "ssm:GetParameter",
        "ssm:DescribeParameters"
      ]
      Resource = ["arn:aws:ssm:*:*:parameter/aws/service/*"]
    },
    {
      Sid    = "PassNodeRole"
      Effect = "Allow"
      Action = ["iam:PassRole"]
      Resource = local.node_role_arn != null ? [local.node_role_arn] : ["*"]
      # If node role is not created, we cannot restrict; allow all to avoid errors.
      # This is a fallback – the user should ensure node role is created if they want restriction.
      Condition = local.node_role_arn != null ? {
        StringEquals = {
          "iam:PassedToService" = "ec2.amazonaws.com"
        }
      } : null
    }
  ]
}

# IAM role for Karpenter IRSA
resource "aws_iam_role" "karpenter_irsa" {
  count = var.create_irsa_role ? 1 : 0
  name  = "KarpenterIRSA-${var.cluster_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${local.oidc_provider_url}:sub" = "system:serviceaccount:karpenter:karpenter"
            "${local.oidc_provider_url}:aud" = "sts.amazonaws.com"
          }
        }
      }
    ]
  })
}

# IAM policy for Karpenter controller
resource "aws_iam_policy" "karpenter_controller" {
  count       = var.create_irsa_role ? 1 : 0
  name        = "KarpenterController-${var.cluster_name}"
  description = "Policy for Karpenter controller to manage EC2 resources"

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.karpenter_controller_policy_statements
  })
}

# Attach policy to IRSA role
resource "aws_iam_role_policy_attachment" "karpenter_controller" {
  count      = var.create_irsa_role ? 1 : 0
  role       = aws_iam_role.karpenter_irsa[0].name
  policy_arn = aws_iam_policy.karpenter_controller[0].arn
}

# SQS Queue
resource "aws_sqs_queue" "karpenter" {
  name                      = local.sqs_queue_name
  message_retention_seconds = 300
  sqs_managed_sse_enabled   = true

  lifecycle {
    prevent_destroy = true
  }
}

# SQS Queue Policy
resource "aws_sqs_queue_policy" "karpenter" {
  queue_url = aws_sqs_queue.karpenter.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEventsService"
        Effect = "Allow"
        Principal = {
          Service = ["events.amazonaws.com", "sqs.amazonaws.com"]
        }
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.karpenter.arn
      }
    ]
  })
}

# CloudWatch Event Rules

# Health event rule
resource "aws_cloudwatch_event_rule" "health" {
  count       = var.create_health_event_rule ? 1 : 0
  name        = "Karpenter-HealthEvent-${var.cluster_name}"
  description = "Capture EC2 health events for Karpenter"

  event_pattern = jsonencode({
    source      = ["aws.health"]
    detail-type = ["AWS Health Event"]
    resources   = ["*"]
  })
}

# Spot interruption rule
resource "aws_cloudwatch_event_rule" "spot_interruption" {
  count       = var.create_spot_interruption_rule ? 1 : 0
  name        = "Karpenter-SpotInterruption-${var.cluster_name}"
  description = "Capture EC2 spot instance interruption warnings for Karpenter"

  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Spot Instance Interruption Warning"]
  })
}

# Rebalance recommendation rule
resource "aws_cloudwatch_event_rule" "rebalance" {
  count       = var.create_rebalance_rule ? 1 : 0
  name        = "Karpenter-RebalanceRecommendation-${var.cluster_name}"
  description = "Capture EC2 instance rebalance recommendations for Karpenter"

  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance Rebalance Recommendation"]
  })
}

# Instance state-change notification rule
resource "aws_cloudwatch_event_rule" "instance_state_change" {
  count       = var.create_instance_state_change_rule ? 1 : 0
  name        = "Karpenter-InstanceStateChange-${var.cluster_name}"
  description = "Capture EC2 instance state-change notifications for Karpenter"

  event_pattern = jsonencode({
    source      = ["aws.ec2"]
    detail-type = ["EC2 Instance State-change Notification"]
  })
}

# Event Targets (each pointing to SQS queue)
resource "aws_cloudwatch_event_target" "health" {
  count     = var.create_health_event_rule ? 1 : 0
  rule      = aws_cloudwatch_event_rule.health[0].name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "KarpenterHealthTarget"
}

resource "aws_cloudwatch_event_target" "spot_interruption" {
  count     = var.create_spot_interruption_rule ? 1 : 0
  rule      = aws_cloudwatch_event_rule.spot_interruption[0].name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "KarpenterSpotInterruptionTarget"
}

resource "aws_cloudwatch_event_target" "rebalance" {
  count     = var.create_rebalance_rule ? 1 : 0
  rule      = aws_cloudwatch_event_rule.rebalance[0].name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "KarpenterRebalanceTarget"
}

resource "aws_cloudwatch_event_target" "instance_state_change" {
  count     = var.create_instance_state_change_rule ? 1 : 0
  rule      = aws_cloudwatch_event_rule.instance_state_change[0].name
  arn       = aws_sqs_queue.karpenter.arn
  target_id = "KarpenterInstanceStateChangeTarget"
}

# IAM role for Karpenter Nodes
resource "aws_iam_role" "karpenter_node" {
  count = var.create_node_role ? 1 : 0
  name  = "KarpenterNodeRole-${var.cluster_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach managed policies to node role
resource "aws_iam_role_policy_attachment" "karpenter_node" {
  count      = var.create_node_role ? length(local.node_managed_policies) : 0
  role       = aws_iam_role.karpenter_node[0].name
  policy_arn = local.node_managed_policies[count.index]
}

# IAM Instance Profile for nodes
resource "aws_iam_instance_profile" "karpenter_node" {
  count = var.create_node_role ? 1 : 0
  name  = "KarpenterNodeInstanceProfile-${var.cluster_name}"
  role  = aws_iam_role.karpenter_node[0].name
}

# Outputs
output "irsa_role_name" {
  value = var.create_irsa_role ? aws_iam_role.karpenter_irsa[0].name : null
}

output "irsa_role_arn" {
  value = var.create_irsa_role ? aws_iam_role.karpenter_irsa[0].arn : null
}

output "irsa_role_unique_id" {
  value = var.create_irsa_role ? aws_iam_role.karpenter_irsa[0].unique_id : null
}

output "node_role_name" {
  value = var.create_node_role ? aws_iam_role.karpenter_node[0].name : null
}

output "node_role_arn" {
  value = var.create_node_role ? aws_iam_role.karpenter_node[0].arn : null
}

output "node_role_unique_id" {
  value = var.create_node_role ? aws_iam_role.karpenter_node[0].unique_id : null
}

output "instance_profile_name" {
  value = var.create_node_role ? aws_iam_instance_profile.karpenter_node[0].name : null
}

output "instance_profile_arn" {
  value = var.create_node_role ? aws_iam_instance_profile.karpenter_node[0].arn : null
}

output "instance_profile_unique_id" {
  value = var.create_node_role ? aws_iam_instance_profile.karpenter_node[0].unique_id : null
}

output "sqs_queue_url" {
  value = aws_sqs_queue.karpenter.id
}

output "sqs_queue_arn" {
  value = aws_sqs_queue.karpenter.arn
}

output "event_rules" {
  value = merge(
    var.create_health_event_rule ? { (aws_cloudwatch_event_rule.health[0].name) = aws_cloudwatch_event_rule.health[0].arn } : {},
    var.create_spot_interruption_rule ? { (aws_cloudwatch_event_rule.spot_interruption[0].name) = aws_cloudwatch_event_rule.spot_interruption[0].arn } : {},
    var.create_rebalance_rule ? { (aws_cloudwatch_event_rule.rebalance[0].name) = aws_cloudwatch_event_rule.rebalance[0].arn } : {},
    var.create_instance_state_change_rule ? { (aws_cloudwatch_event_rule.instance_state_change[0].name) = aws_cloudwatch_event_rule.instance_state_change[0].arn } : {}
  )
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "STAGE"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_encryption" {
  description = "Enable encryption at rest for the EFS file system"
  type        = bool
  default     = true
}

variable "performance_mode" {
  description = "EFS performance mode: generalPurpose or maxIO"
  type        = string
  default     = "generalPurpose"
  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "Performance mode must be either generalPurpose or maxIO."
  }
}

variable "throughput_mode" {
  description = "EFS throughput mode: bursting or provisioned"
  type        = string
  default     = "bursting"
  validation {
    condition     = contains(["bursting", "provisioned"], var.throughput_mode)
    error_message = "Throughput mode must be either bursting or provisioned."
  }
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s (only used if throughput_mode is provisioned)"
  type        = number
  default     = 0
}

variable "lifecycle_policies" {
  description = "List of lifecycle policies for transitioning to Infrequent Access"
  type = list(object({
    transition_to_ia = string
  }))
  default = [
    { transition_to_ia = "AFTER_30_DAYS" }
  ]
}

variable "create_mount_targets" {
  description = "Whether to create EFS mount targets in all subnets"
  type        = bool
  default     = true
}

variable "mount_target_ips" {
  description = "Optional list of IP addresses for mount targets, one per subnet. If empty, AWS assigns IP."
  type        = list(string)
  default     = []
}

variable "create_file_system_policy" {
  description = "Whether to apply an EFS file system policy"
  type        = bool
  default     = false
}

variable "file_system_policy_json" {
  description = "JSON string for the EFS file system policy"
  type        = string
  default     = ""
}

variable "create_access_point" {
  description = "Whether to create an EFS access point"
  type        = bool
  default     = false
}

variable "access_point_posix_user" {
  description = "POSIX user for the access point"
  type = object({
    gid            = number
    uid            = number
    secondary_gids = list(number)
  })
  default = {
    gid            = 1000
    uid            = 1000
    secondary_gids = []
  }
}

variable "access_point_root_directory" {
  description = "Root directory configuration for the access point"
  type = object({
    path = string
    creation_info = object({
      owner_gid   = number
      owner_uid   = number
      permissions = string
    })
  })
  default = {
    path = "/"
    creation_info = {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "755"
    }
  }
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Local values
locals {
  common_tags = merge(
    {
      Name        = var.name_prefix
      Environment = var.environment
    },
    var.tags
  )
  name_prefix_lower = lower(var.name_prefix)
  azs              = data.aws_availability_zones.available.names
  # Subnet CIDR: /20 per AZ to fit in /16 VPC (16 subnets possible)
  subnet_cidrs = [
    for i in range(length(local.azs)) :
    cidrsubnet(var.vpc_cidr, 4, i)
  ]
  # For mount targets: if IPs provided, must match number of subnets; else empty list
  mount_target_ip_list = length(var.mount_target_ips) > 0 ? var.mount_target_ips : [for i in range(length(local.azs)) : null]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-vpc" }
  )
}

# Subnets (one per AZ)
resource "aws_subnet" "efs" {
  for_each = { for idx, az in local.azs : idx => az }

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.subnet_cidrs[each.key]
  availability_zone = each.value
  map_public_ip_on_launch = false
  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-subnet-${each.key}" }
  )
}

# Route table with local route only
resource "aws_route_table" "efs" {
  vpc_id = aws_vpc.main.id
  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-rt" }
  )
}

# Subnet associations
resource "aws_route_table_association" "efs" {
  for_each = aws_subnet.efs

  subnet_id      = each.value.id
  route_table_id = aws_route_table.efs.id
}

# Security group for EFS mount targets
resource "aws_security_group" "efs_mount_target" {
  name        = "${local.name_prefix_lower}-efs-mt-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-efs-mt-sg" }
  )
}

# KMS Key (optional)
resource "aws_kms_key" "efs" {
  count = var.enable_encryption ? 1 : 0

  description             = "KMS key for EFS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow EFS Service"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "elasticfilesystem.${data.aws_region.current.id}.amazonaws.com"
          }
        }
      }
    ]
  })
  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-efs-kms" }
  )
}

resource "aws_kms_alias" "efs" {
  count = var.enable_encryption ? 1 : 0

  name          = "alias/${local.name_prefix_lower}-efs"
  target_key_id = aws_kms_key.efs[0].key_id
}

# Data sources for account and region
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# EFS File System
resource "aws_efs_file_system" "main" {
  creation_token = "${local.name_prefix_lower}-efs"
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null

  dynamic "lifecycle_policy" {
    for_each = var.lifecycle_policies
    content {
      transition_to_ia = lifecycle_policy.value.transition_to_ia
    }
  }

  encrypted  = var.enable_encryption
  kms_key_id = var.enable_encryption ? aws_kms_key.efs[0].arn : null

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-efs" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Mount Targets (conditional)
resource "aws_efs_mount_target" "main" {
  for_each = var.create_mount_targets ? aws_subnet.efs : {}

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = each.value.id
  ip_address      = local.mount_target_ip_list[tonumber(each.key)]
  security_groups = [aws_security_group.efs_mount_target.id]

  depends_on = [aws_efs_file_system.main]
}

# File System Policy (conditional)
resource "aws_efs_file_system_policy" "main" {
  count = var.create_file_system_policy ? 1 : 0

  file_system_id = aws_efs_file_system.main.id
  policy         = var.file_system_policy_json

  depends_on = [aws_efs_file_system.main]
}

# Access Point (conditional)
resource "aws_efs_access_point" "main" {
  count = var.create_access_point ? 1 : 0

  file_system_id = aws_efs_file_system.main.id

  posix_user {
    gid            = var.access_point_posix_user.gid
    uid            = var.access_point_posix_user.uid
    secondary_gids = var.access_point_posix_user.secondary_gids
  }

  root_directory {
    path = var.access_point_root_directory.path
    creation_info {
      owner_gid   = var.access_point_root_directory.creation_info.owner_gid
      owner_uid   = var.access_point_root_directory.creation_info.owner_uid
      permissions = var.access_point_root_directory.creation_info.permissions
    }
  }

  tags = merge(
    local.common_tags,
    { Name = "${local.name_prefix_lower}-efs-ap" }
  )

  depends_on = [aws_efs_file_system.main]
}

# Outputs
output "file_system_id" {
  value = aws_efs_file_system.main.id
}

output "file_system_arn" {
  value = aws_efs_file_system.main.arn
}

output "dns_name" {
  value = aws_efs_file_system.main.dns_name
}

output "kms_key_id" {
  value = var.enable_encryption ? aws_kms_key.efs[0].id : null
}

output "mount_target_ids" {
  value = var.create_mount_targets ? {
    for k, mt in aws_efs_mount_target.main : k => mt.id
  } : null
}

output "mount_target_dns_names" {
  value = var.create_mount_targets ? {
    for k, mt in aws_efs_mount_target.main : k => mt.dns_name
  } : null
}

output "mount_target_network_interface_ids" {
  value = var.create_mount_targets ? {
    for k, mt in aws_efs_mount_target.main : k => mt.network_interface_id
  } : null
}

output "mount_target_availability_zone_name" {
  value = var.create_mount_targets ? {
    for k, mt in aws_efs_mount_target.main : k => mt.availability_zone_name
  } : null
}

output "mount_target_availability_zone_id" {
  value = var.create_mount_targets ? {
    for k, mt in aws_efs_mount_target.main : k => mt.availability_zone_id
  } : null
}

output "mount_target_owner_id" {
  value = var.create_mount_targets ? {
    for k, mt in aws_efs_mount_target.main : k => mt.owner_id
  } : null
}

output "file_system_policy_id" {
  value = var.create_file_system_policy ? aws_efs_file_system_policy.main[0].id : null
}

output "access_point_id" {
  value = var.create_access_point ? aws_efs_access_point.main[0].id : null
}

output "access_point_arn" {
  value = var.create_access_point ? aws_efs_access_point.main[0].arn : null
}

output "access_point_file_system_arn" {
  value = var.create_access_point ? aws_efs_access_point.main[0].file_system_arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables for resource names
variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "main-vpc"
}

variable "public_subnet_a_name" {
  description = "Name tag for the public subnet A"
  type        = string
  default     = "public-subnet-a"
}

variable "private_subnet_b_name" {
  description = "Name tag for the private subnet B"
  type        = string
  default     = "private-subnet-b"
}

variable "private_subnet_c_name" {
  description = "Name tag for the private subnet C"
  type        = string
  default     = "private-subnet-c"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "main-igw"
}

variable "public_route_table_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "public-route-table"
}

variable "eip_name" {
  description = "Name tag for the Elastic IP"
  type        = string
  default     = "nat-eip"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "nat-gateway"
}

variable "sg_name" {
  description = "Name tag for the security group"
  type        = string
  default     = "allow-all-egress-sg"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Public Subnet A in us-east-1a
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = false

  tags = {
    Name = var.public_subnet_a_name
  }
}

# Private Subnet B in us-east-1b
resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = false

  tags = {
    Name = var.private_subnet_b_name
  }
}

# Private Subnet C in us-east-1e
resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = "us-east-1e"
  map_public_ip_on_launch = false

  tags = {
    Name = var.private_subnet_c_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = var.public_route_table_name
  }
}

# Associate public route table with public subnet A only
resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

# Elastic IP for NAT Gateway (using BYOIP pool "amazon")
resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = "amazon"

  tags = {
    Name = var.eip_name
  }
}

# NAT Gateway in private subnet B, depends on IGW
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.private_b.id

  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = var.nat_gateway_name
  }
}

# Security Group allowing all outbound traffic (default egress already allows all)
resource "aws_security_group" "allow_all_egress" {
  name        = var.sg_name
  description = "Security group that allows all outbound traffic"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = var.sg_name
  }
}

# Output the public IP of the NAT Gateway
output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway"
  value       = aws_nat_gateway.nat.public_ip
}

terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "my-bucket"
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if it contains objects"
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket"
  type        = bool
  default     = false
}

variable "object_lock_default_retention" {
  description = "Default retention settings for Object Lock (required if object_lock_enabled is true)"
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "bucket_policies" {
  description = "Map of bucket policy documents, each containing statements with actions, effect, resources, and principal"
  type = map(object({
    statements = list(object({
      actions   = list(string)
      effect    = string
      resources = list(string)
      principal = object({
        type        = string
        identifiers = list(string)
      })
    }))
  }))
  default = {}
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  bucket_policy_documents = [
    for name, policy in var.bucket_policies : jsonencode({
      Version   = "2012-10-17"
      Statement = [
        for stmt in policy.statements : {
          Effect   = stmt.effect
          Action   = stmt.actions
          Resource = stmt.resources
          Principal = {
            (stmt.principal.type) = stmt.principal.identifiers
          }
        }
      ]
    })
  ]
}

data "aws_iam_policy_document" "combined" {
  count = length(var.bucket_policies) > 0 ? 1 : 0
  source_policy_documents = local.bucket_policy_documents
}

resource "aws_kms_key" "this" {
  description             = "CMK for S3 bucket encryption"
  deletion_window_in_days = 7
}

resource "aws_s3_bucket" "this" {
  bucket = "${var.bucket_name}-${random_id.suffix.hex}"
  force_destroy = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled && var.object_lock_default_retention != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_default_retention.mode
      days  = var.object_lock_default_retention.days
      years = var.object_lock_default_retention.years
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = length(var.bucket_policies) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined[0].json
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

output "bucket_id" {
  description = "The ID (name) of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

terraform {
  required_version = ">= 1.2"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_kms_key" "s3_state" {
  description             = "CMK for S3 state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "tfstate" {
  bucket = "akbun-t101study-tfstate"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_state.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_dynamodb_table" "lock_table" {
  name         = "terraform-locks-week3-files"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "state_bucket_arn" {
  value = aws_s3_bucket.tfstate.arn
}

output "lock_table_name" {
  value = aws_dynamodb_table.lock_table.name
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

# VPC
resource "aws_vpc" "dosomething_quasar" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "dosomething_quasar" {
  vpc_id = aws_vpc.dosomething_quasar.id
  tags   = merge(local.common_tags, {
    Name = "dosomething-quasar"
  })
}

# Public Subnets
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.dosomething_quasar.id
  cidr_block              = "10.255.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.dosomething_quasar.id
  cidr_block              = "10.255.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-public-b"
  })
}

# Private RDS Subnets
resource "aws_subnet" "rds_a" {
  vpc_id                  = aws_vpc.dosomething_quasar.id
  cidr_block              = "10.255.100.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-rds-a"
  })
}

resource "aws_subnet" "rds_b" {
  vpc_id                  = aws_vpc.dosomething_quasar.id
  cidr_block              = "10.255.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-rds-b"
  })
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.dosomething_quasar.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.dosomething_quasar.id
  }
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-public"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# Private Route Table (no default route)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.dosomething_quasar.id
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-private"
  })
}

resource "aws_route_table_association" "rds_a" {
  subnet_id      = aws_subnet.rds_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "rds_b" {
  subnet_id      = aws_subnet.rds_b.id
  route_table_id = aws_route_table.private.id
}

# Security Groups
resource "aws_security_group" "quasar_bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host security group"
  vpc_id      = aws_vpc.dosomething_quasar.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/1", "128.0.0.0/1"]
  }
  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "quasar_jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD security group"
  vpc_id      = aws_vpc.dosomething_quasar.id
  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.quasar_bastion.id]
  }
  ingress {
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.quasar_ha_proxy.id]
  }
  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "quasar_ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "Load balancer security group"
  vpc_id      = aws_vpc.dosomething_quasar.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.quasar_bastion.id]
  }
  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "quasar_etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes security group"
  vpc_id      = aws_vpc.dosomething_quasar.id
  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [
      aws_security_group.quasar_bastion.id,
      aws_security_group.quasar_jenkins.id
    ]
  }
  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "quasar_postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "RDS PostgreSQL security group"
  vpc_id      = aws_vpc.dosomething_quasar.id
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.quasar_etl.id]
  }
  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

# DB Subnet Group
resource "aws_db_subnet_group" "dosomething_quasar" {
  name       = "dosomething-quasar"
  subnet_ids = [aws_subnet.rds_a.id, aws_subnet.rds_b.id]
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar"
  })
}

# Random password for RDS
resource "random_password" "rds_master_password" {
  length  = 16
  special = false
}

# Secrets Manager secret for RDS password
resource "aws_secretsmanager_secret" "rds_master_password" {
  name = "dosomething-quasar-rds-master-password"
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar-rds-master-password"
  })
}

resource "aws_secretsmanager_secret_version" "rds_master_password" {
  secret_id     = aws_secretsmanager_secret.rds_master_password.id
  secret_string = random_password.rds_master_password.result
}

# RDS Instance
resource "aws_db_instance" "dosomething_quasar" {
  identifier             = "dosomething-quasar"
  engine                 = "postgres"
  engine_version         = "15.4"
  instance_class         = "db.t3.medium"
  allocated_storage      = 20
  storage_encrypted      = true
  multi_az               = true
  db_name                = "quasar"
  username               = "admin"
  password               = random_password.rds_master_password.result
  db_subnet_group_name   = aws_db_subnet_group.dosomething_quasar.name
  vpc_security_group_ids = [aws_security_group.quasar_postgresql.id]
  backup_retention_period = 7
  skip_final_snapshot    = false
  final_snapshot_identifier = "dosomething-quasar-final-snapshot"
  lifecycle {
    prevent_destroy = true
  }
  tags = merge(local.common_tags, {
    Name = "dosomething-quasar"
  })
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.1.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.7.2"
    }
  }
}

locals {
  host_ip = "127.0.0.1"
}

resource "random_pet" "nginx" {
  count  = 4
  length = 2
}

resource "docker_image" "nginx_image" {
  name = "nginx:1.23.4"
}

resource "docker_image" "redis_image" {
  name = "redis:7.0.11"
}

resource "time_sleep" "redis_delay" {
  depends_on      = [docker_image.redis_image]
  create_duration = "120s"
}

resource "docker_container" "nginx" {
  count = 4
  name  = "nginx-${random_pet.nginx[count.index].id}-${count.index}"
  image = docker_image.nginx_image.name
  ports {
    internal = 80
  }
}

resource "docker_container" "redis" {
  name  = "data"
  image = docker_image.redis_image.name
  ports {
    internal = 6379
    external = 6379
  }
  depends_on = [time_sleep.redis_delay]
}

output "nginx_containers" {
  description = "List of all nginx containers with names and host addresses"
  value = [
    for idx in range(4) : {
      name         = docker_container.nginx[idx].name
      host_address = "${local.host_ip}:${docker_container.nginx[idx].ports[0].external}"
    }
  ]
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.60"
    }
  }
}

variable "name" {
  description = "Solution name"
  type        = string
  default     = ""
}

variable "namespace" {
  description = "Namespace"
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment"
  type        = string
  default     = ""
}

variable "attributes" {
  description = "Additional attributes"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (merged with label module tags)"
  type        = map(string)
  default     = {}
}

variable "zone_names" {
  description = "List of zone names to create"
  type        = list(string)
  default     = []
}

variable "vpc_ids" {
  description = "List of VPC IDs to associate with private zones. Empty list = public zones with DNSSEC enabled."
  type        = list(string)
  default     = []
}

variable "force_destroy" {
  description = "Allow deletion of non-empty zones"
  type        = bool
  default     = false
}

variable "records" {
  description = "List of record definitions to create for each zone"
  type = list(object({
    name                 = string
    type                 = string
    ttl                  = optional(number, 3600)
    records              = optional(list(string), [])
    alias                = optional(object({
      name                   = string
      zone_id                = string
      evaluate_target_health = bool
    }))
    weight               = optional(number)
    failover_routing_policy = optional(object({
      type = string
    }))
    set_identifier       = optional(string)
    health_check_id      = optional(string)
    allow_overwrite      = optional(bool, false)
  }))
  default = []
}

locals {
  is_public      = length(var.vpc_ids) == 0
  first_vpc      = length(var.vpc_ids) > 0 ? var.vpc_ids[0] : null
  additional_vpcs = length(var.vpc_ids) > 1 ? slice(var.vpc_ids, 1, length(var.vpc_ids)) : []

  zone_associations = flatten([
    for zone_name in var.zone_names : [
      for vpc_id in local.additional_vpcs : {
        zone_name = zone_name
        vpc_id    = vpc_id
      }
    ]
  ])

  record_list = flatten([
    for zone_name in var.zone_names : [
      for rec_idx, rec in var.records : {
        key   = "${zone_name}-${rec.name}-${rec.type}"
        value = merge(rec, { zone_name = zone_name })
      }
    ]
  ])
  record_map = { for item in local.record_list : item.key => item.value }
}

module "label" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  name        = var.name
  namespace   = var.namespace
  environment = var.environment
  attributes  = var.attributes
  tags        = var.tags
}

resource "aws_route53_zone" "this" {
  for_each = toset(var.zone_names)

  name          = each.key
  force_destroy = var.force_destroy
  tags          = merge(module.label.tags, { Name = each.key })

  dynamic "vpc" {
    for_each = local.first_vpc != null ? [local.first_vpc] : []
    content {
      vpc_id = vpc.value
    }
  }
}

resource "aws_route53_zone_association" "additional" {
  for_each = { for assoc in local.zone_associations : "${assoc.zone_name}-${assoc.vpc_id}" => assoc }

  zone_id = aws_route53_zone.this[each.value.zone_name].id
  vpc_id  = each.value.vpc_id
}

resource "aws_kms_key" "dnssec" {
  for_each = local.is_public ? toset(var.zone_names) : toset([])

  description             = "KMS key for Route53 DNSSEC signing for zone ${each.key}"
  key_usage               = "SIGN_VERIFY"
  customer_master_key_spec = "ECC_NIST_P256"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow Route53 DNSSEC Service"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
        Action = [
          "kms:Sign",
          "kms:Verify",
          "kms:DescribeKey",
          "kms:GetPublicKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = merge(module.label.tags, { Name = "dnssec-${each.key}" })
}

resource "aws_route53_key_signing_key" "this" {
  for_each = local.is_public ? toset(var.zone_names) : toset([])

  hosted_zone_id             = aws_route53_zone.this[each.key].id
  key_management_service_arn = aws_kms_key.dnssec[each.key].arn
  name                       = "ksk-${each.key}"
  status                     = "ACTIVE"
}

resource "aws_route53_record" "this" {
  for_each = local.record_map

  zone_id = aws_route53_zone.this[each.value.zone_name].id
  name    = each.value.name
  type    = each.value.type
  ttl     = each.value.ttl

  records = each.value.alias == null ? each.value.records : null

  dynamic "alias" {
    for_each = each.value.alias != null ? [each.value.alias] : []
    content {
      name                   = alias.value.name
      zone_id                = alias.value.zone_id
      evaluate_target_health = alias.value.evaluate_target_health
    }
  }

  set_identifier = each.value.set_identifier

  dynamic "weighted_routing_policy" {
    for_each = each.value.weight != null ? [each.value.weight] : []
    content {
      weight = weighted_routing_policy.value
    }
  }

  dynamic "failover_routing_policy" {
    for_each = each.value.failover_routing_policy != null ? [each.value.failover_routing_policy] : []
    content {
      type = failover_routing_policy.value.type
    }
  }

  health_check_id = each.value.health_check_id
  allow_overwrite = each.value.allow_overwrite
}

output "zone_details" {
  description = "Details of each created zone, including associated VPCs and record names/FQDNs"
  value = {
    for zone_name, zone in aws_route53_zone.this : zone_name => {
      zone_name = zone.name
      zone_id   = zone.id
      arn       = zone.arn
      vpc_ids   = var.vpc_ids
      records = {
        for rec_key, rec in aws_route53_record.this : rec.name => {
          name = rec.name
          fqdn = rec.fqdn
        } if rec.zone_id == zone.id
      }
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-west-1"
}

# ----------------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------------
variable "role_name" {
  description = "The name of the IAM role for Prisma Cloud cross-account access."
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Whether to attach the remediation (write) inline policy."
  type        = bool
  default     = false
}

# ----------------------------------------------------------------------------
# External ID (random 32-character alphanumeric string)
# ----------------------------------------------------------------------------
resource "random_password" "external_id" {
  length  = 32
  special = false
  # Keep it purely alphanumeric for compatibility
  upper   = true
  lower   = true
  numeric = true
}

# ----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------------
# IAM Role for Prisma Cloud cross-account access
# ----------------------------------------------------------------------------
data "aws_iam_policy_document" "prisma_cloud_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::188619942792:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_password.external_id.result]
    }
  }
}

resource "aws_iam_role" "prisma_cloud_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.prisma_cloud_assume_role.json
  description        = "IAM role for Prisma Cloud security monitoring and remediation."
}

# Attach the AWS managed SecurityAudit policy
resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

# Read-only inline policy with the specified actions
resource "aws_iam_role_policy" "read_only_inline" {
  name   = "PrismaCloudReadOnly"
  role   = aws_iam_role.prisma_cloud_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

# Remediation (write) inline policy – conditionally attached when read_write is true
resource "aws_iam_role_policy" "remediation_inline" {
  count = var.read_write ? 1 : 0
  name  = "PrismaCloudRemediation"
  role  = aws_iam_role.prisma_cloud_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------
output "account_id" {
  description = "The AWS account ID where the role is deployed."
  value       = data.aws_caller_identity.current.account_id
}

output "role_name" {
  description = "The name of the IAM role created for Prisma Cloud."
  value       = var.role_name
}

output "role_arn" {
  description = "The ARN of the IAM role created for Prisma Cloud."
  value       = aws_iam_role.prisma_cloud_role.arn
}

output "external_id" {
  description = "The generated external ID for secure role assumption."
  value       = random_password.external_id.result
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  sg_name_prefix_default = "vpc-endpoint-"
  create_sg              = var.create_security_group
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "VPC ID for the endpoints"
}

variable "endpoints" {
  type = map(object({
    service_name          = string
    service_type          = optional(string, "Interface")
    auto_accept           = optional(bool, false)
    policy                = optional(string)
    private_dns_enabled   = optional(bool, true)
    subnet_ids            = optional(list(string), [])
    route_table_ids       = optional(list(string), [])
    security_group_ids    = optional(list(string), [])
  }))
  default     = {}
  description = "Map of endpoint configurations"
  validation {
    condition     = alltrue([for k, v in var.endpoints : contains(["Interface", "Gateway"], v.service_type)])
    error_message = "Each endpoint's service_type must be either 'Interface' or 'Gateway'."
  }
}

variable "default_subnet_ids" {
  type        = list(string)
  default     = []
  description = "Default subnet IDs for Interface endpoints that don't specify subnet_ids"
}

variable "default_security_group_ids" {
  type        = list(string)
  default     = []
  description = "Default security group IDs for Interface endpoints that don't have their own or a created security group"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply to all resources"
}

variable "create_security_group" {
  type        = bool
  default     = false
  description = "Whether to create a dedicated security group for each Interface endpoint"
}

variable "sg_name" {
  type        = string
  default     = null
  description = "Name for the created security group (cannot be used with sg_name_prefix)"
}

variable "sg_name_prefix" {
  type        = string
  default     = null
  description = "Prefix for the created security group name (ignored if sg_name is set)"
}

variable "sg_description" {
  type        = string
  default     = "Security group for VPC endpoint"
  description = "Description for the created security group"
}

variable "sg_rules" {
  type = map(object({
    protocol                 = string
    from_port                = number
    to_port                  = number
    type                     = string
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    prefix_list_ids          = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
  }))
  default     = {}
  description = "Map of security group rules to attach to the created security group(s)"
}

variable "timeouts" {
  type = object({
    create = optional(string, "10m")
    update = optional(string, "10m")
    delete = optional(string, "10m")
  })
  default = {
    create = "10m"
    update = "10m"
    delete = "10m"
  }
  description = "Timeouts for creating, updating, and deleting VPC endpoints"
}

# Security groups for Interface endpoints (only if requested and a valid VPC ID is provided)
resource "aws_security_group" "endpoint" {
  for_each = local.create_sg && var.vpc_id != "" ? { for k, v in var.endpoints : k => v if v.service_type == "Interface" } : {}

  name        = var.sg_name != null ? var.sg_name : null
  name_prefix = var.sg_name != null ? null : (var.sg_name_prefix != null ? var.sg_name_prefix : local.sg_name_prefix_default)
  description = var.sg_description
  vpc_id      = var.vpc_id

  tags = merge(var.tags, { Name = coalesce(var.sg_name, "${local.sg_name_prefix_default}${each.key}") })

  lifecycle {
    create_before_destroy = true
  }
}

# Security group rules attached to each created security group
resource "aws_security_group_rule" "endpoint" {
  for_each = local.create_sg && var.vpc_id != "" ? toset(flatten([
    for ep_key, ep in aws_security_group.endpoint : [
      for rule_key, rule in var.sg_rules : "${ep_key}:${rule_key}"
    ]
  ])) : toset([])

  security_group_id = aws_security_group.endpoint[element(split(":", each.key), 0)].id

  type      = var.sg_rules[element(split(":", each.key), 1)].type
  protocol  = var.sg_rules[element(split(":", each.key), 1)].protocol
  from_port = var.sg_rules[element(split(":", each.key), 1)].from_port
  to_port   = var.sg_rules[element(split(":", each.key), 1)].to_port

  cidr_blocks              = var.sg_rules[element(split(":", each.key), 1)].cidr_blocks
  ipv6_cidr_blocks         = var.sg_rules[element(split(":", each.key), 1)].ipv6_cidr_blocks
  prefix_list_ids          = var.sg_rules[element(split(":", each.key), 1)].prefix_list_ids
  self                     = var.sg_rules[element(split(":", each.key), 1)].self
  source_security_group_id = var.sg_rules[element(split(":", each.key), 1)].source_security_group_id
}

# VPC Endpoints (only created when a valid VPC ID is provided)
resource "aws_vpc_endpoint" "this" {
  for_each = var.vpc_id != "" ? var.endpoints : {}

  vpc_id            = var.vpc_id
  service_name      = each.value.service_name
  vpc_endpoint_type = each.value.service_type
  auto_accept       = each.value.auto_accept
  policy            = each.value.policy
  private_dns_enabled = each.value.private_dns_enabled

  subnet_ids = each.value.service_type == "Interface" ? (
    length(each.value.subnet_ids) > 0 ? each.value.subnet_ids : var.default_subnet_ids
  ) : null

  route_table_ids = each.value.service_type == "Gateway" ? each.value.route_table_ids : null

  security_group_ids = each.value.service_type == "Interface" ? (
    local.create_sg && var.vpc_id != "" ? [aws_security_group.endpoint[each.key].id] : (
      length(each.value.security_group_ids) > 0 ? each.value.security_group_ids : var.default_security_group_ids
    )
  ) : null

  timeouts {
    create = var.timeouts.create
    update = var.timeouts.update
    delete = var.timeouts.delete
  }

  tags = var.tags
}

# Outputs
output "endpoints" {
  description = "Map of all VPC endpoints created"
  value       = aws_vpc_endpoint.this
}

output "security_group_arn" {
  description = "Map of security group ARNs keyed by endpoint name (only if create_security_group is true)"
  value       = local.create_sg && var.vpc_id != "" ? { for k, sg in aws_security_group.endpoint : k => sg.arn } : null
}

output "security_group_id" {
  description = "Map of security group IDs keyed by endpoint name (only if create_security_group is true)"
  value       = local.create_sg && var.vpc_id != "" ? { for k, sg in aws_security_group.endpoint : k => sg.id } : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  role_name = var.name != null ? var.name : (
    var.name_prefix != null ? null : "default-eks-oidc-role"
  )
  role_name_prefix = var.name_prefix != null ? var.name_prefix : null
  use_name_prefix  = var.name == null && var.name_prefix != null
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

data "aws_eks_cluster" "this" {
  for_each = var.create_role ? var.oidc_fully_qualified_subjects : {}
  name     = each.key
}

data "aws_iam_policy_document" "trust_policy" {
  count = var.create_role ? 1 : 0

  dynamic "statement" {
    for_each = var.allow_self_assume_role ? [1] : []
    content {
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:role/${local.role_name != null ? local.role_name : "placeholder"}"]
      }
      actions = ["sts:AssumeRole"]
      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role/${local.role_name != null ? local.role_name : "placeholder"}"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.oidc_fully_qualified_subjects
    content {
      effect = "Allow"
      principals {
        type        = "Federated"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:oidc-provider/${data.aws_eks_cluster.this[statement.key].identity[0].oidc[0].issuer}"]
      }
      actions = ["sts:AssumeRoleWithWebIdentity"]
      dynamic "condition" {
        for_each = statement.value
        content {
          test     = "StringEquals"
          variable = "${data.aws_eks_cluster.this[statement.key].identity[0].oidc[0].issuer}:sub"
          values   = ["system:serviceaccount:${condition.value}"]
        }
      }
    }
  }
}

resource "aws_iam_role" "this" {
  count = var.create_role ? 1 : 0

  name                 = local.use_name_prefix ? null : local.role_name
  name_prefix          = local.use_name_prefix ? local.role_name_prefix : null
  description          = var.description
  path                 = var.path
  permissions_boundary = var.permissions_boundary
  max_session_duration = var.max_session_duration
  force_detach_policies = var.force_detach_policies
  assume_role_policy   = data.aws_iam_policy_document.trust_policy[0].json
  tags                 = var.tags
}

resource "aws_iam_role_policy_attachment" "this" {
  for_each = var.create_role ? var.policy_arns : {}

  role       = aws_iam_role.this[0].name
  policy_arn = each.value
}

output "arn" {
  value = var.create_role ? aws_iam_role.this[0].arn : null
}

output "name" {
  value = var.create_role ? aws_iam_role.this[0].name : null
}

output "path" {
  value = var.create_role ? aws_iam_role.this[0].path : null
}

output "unique_id" {
  value = var.create_role ? aws_iam_role.this[0].unique_id : null
}

variable "create_role" {
  description = "Whether to create the IAM role"
  type        = bool
  default     = false
}

variable "name" {
  description = "Name of the IAM role. One of `name` or `name_prefix` must be provided."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix to use for the IAM role name."
  type        = string
  default     = null
}

variable "description" {
  description = "Description of the IAM role"
  type        = string
  default     = ""
}

variable "path" {
  description = "Path to the IAM role"
  type        = string
  default     = "/"
}

variable "permissions_boundary" {
  description = "ARN of the permissions boundary policy to attach to the role"
  type        = string
  default     = null
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role"
  type        = number
  default     = 43200
}

variable "force_detach_policies" {
  description = "Whether to force detach any policies attached to the role on destroy"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to the role"
  type        = map(string)
  default     = {}
}

variable "policy_arns" {
  description = "A map of IAM policy ARNs to attach to the role (key = attachment name, value = policy ARN)"
  type        = map(string)
  default     = {}
}

variable "oidc_fully_qualified_subjects" {
  description = "A map of EKS cluster names to lists of service account names in the format 'namespace:serviceaccount'"
  type        = map(list(string))
  default     = {}
}

variable "allow_self_assume_role" {
  description = "Whether to allow the role to assume itself"
  type        = bool
  default     = false
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
  }
}

variable "container_name" {
  type    = string
  default = "ExampleNginxContainer"
}

variable "internal_port" {
  type    = number
  default = 80
}

variable "external_port" {
  type    = number
  default = 2224
}

resource "docker_image" "nginx" {
  name         = "nginx:1.23.4"
  keep_locally = true
}

resource "docker_container" "nginx" {
  name  = var.container_name
  image = docker_image.nginx.image_id

  ports {
    internal = var.internal_port
    external = var.external_port
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "container_count" {
  description = "Number of Nginx containers to launch"
  type        = number
  default     = 4
}

variable "base_host_port" {
  description = "Starting host port for container port mapping"
  type        = number
  default     = 8080
}

resource "random_pet" "pet_name" {
  length    = 2
  separator = "-"
}

resource "docker_image" "nginx" {
  name         = "nginx:latest"
  keep_locally = true
}

resource "docker_container" "nginx" {
  count = var.container_count
  name  = "${random_pet.pet_name.id}-${count.index}"
  image = docker_image.nginx.image_id
  ports {
    internal = 80
  }
}

output "containers" {
  description = "Details of each Nginx container (name, IP, external port)"
  value = {
    for idx, c in docker_container.nginx :
    c.name => {
      ip   = try(c.network_data[0].ip_address, "unknown")
      port = c.ports[0].external
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.1.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.7.2"
    }
  }
}

resource "random_pet" "pet" {
  length = 2
}

resource "docker_image" "nginx" {
  name         = "nginx:1.23.4"
  keep_locally = true
}

resource "docker_container" "nginx" {
  count = 4
  name  = "${random_pet.pet.id}-${count.index}"
  image = docker_image.nginx.repo_digest

  ports {
    internal = 80
    external = 0
    protocol = "tcp"
  }
}

output "container_endpoints" {
  value = [
    for container in docker_container.nginx : {
      name     = container.name
      endpoint = "http://localhost:${container.ports[0].external}"
    }
  ]
  description = "List of container names and their corresponding host endpoints."
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Variables
variable "prefix" {
  description = "Prefix for resource naming"
  type        = string
  default     = "terraform"
}

variable "admin_cidr" {
  description = "CIDR block for bastion admin access and SSH/RDP access"
  type        = string
  default     = "10.0.0.0/8"
}

variable "availability_zone" {
  description = "Availability zone for all subnets"
  type        = string
  default     = "eu-west-1a"
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  common_tags = merge(
    var.tags,
    {
      Name = "${var.prefix}-vpc"
    }
  )
  subnet_tags = {
    public  = "${var.prefix}-public-subnet"
    private = "${var.prefix}-private-subnet"
    bastion = "${var.prefix}-bastion-subnet"
  }
  sg_tags = {
    public     = "${var.prefix}-public-sg"
    private    = "${var.prefix}-private-sg"
    bastion    = "${var.prefix}-bastion-sg"
    allow_all  = "${var.prefix}-allow-all-sg"
  }
  eni_tags = {
    public  = "${var.prefix}-public-eni"
    private = "${var.prefix}-private-eni"
  }
  vpc_cidr = "172.30.0.0/23"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    { Name = "${var.prefix}-vpc" }
  )
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    { Name = "${var.prefix}-igw" }
  )
}

# Subnets
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 2, 0)   # 172.30.0.0/25
  availability_zone = var.availability_zone

  tags = merge(local.common_tags, { Name = local.subnet_tags.public })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 2, 1)   # 172.30.0.128/25
  availability_zone = var.availability_zone

  tags = merge(local.common_tags, { Name = local.subnet_tags.private })
}

resource "aws_subnet" "bastion" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 2, 2)   # 172.30.1.0/25
  availability_zone = var.availability_zone

  tags = merge(local.common_tags, { Name = local.subnet_tags.bastion })
}

# Elastic Network Interfaces
resource "aws_network_interface" "public" {
  subnet_id         = aws_subnet.public.id
  private_ips       = [cidrhost(aws_subnet.public.cidr_block, 10)]
  source_dest_check = false

  tags = merge(local.common_tags, { Name = local.eni_tags.public })
}

resource "aws_network_interface" "private" {
  subnet_id         = aws_subnet.private.id
  private_ips       = [cidrhost(aws_subnet.private.cidr_block, 10)]
  source_dest_check = false

  tags = merge(local.common_tags, { Name = local.eni_tags.private })
}

# Security Groups
resource "aws_security_group" "public" {
  name        = "${var.prefix}-public-sg"
  description = "Public SG allowing TCP, UDP, ICMP echo/reply from anywhere (SSH/RDP restricted to admin CIDR)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TCP ports 0-21 from anywhere"
    from_port   = 0
    to_port     = 21
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "TCP ports 23-3388 from anywhere"
    from_port   = 23
    to_port     = 3388
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "TCP ports 3390-65535 from anywhere"
    from_port   = 3390
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "TCP SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "TCP RDP from admin CIDR"
    from_port   = 3389
    to_port     = 3389
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP ports 0-21 from anywhere"
    from_port   = 0
    to_port     = 21
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP ports 23-3388 from anywhere"
    from_port   = 23
    to_port     = 3388
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP ports 3390-65535 from anywhere"
    from_port   = 3390
    to_port     = 65535
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP RDP from admin CIDR"
    from_port   = 3389
    to_port     = 3389
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "ICMP echo from anywhere"
    from_port   = 8
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "ICMP echo reply from anywhere"
    from_port   = 0
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = local.sg_tags.public })
}

resource "aws_security_group" "private" {
  name        = "${var.prefix}-private-sg"
  description = "Private SG allowing all traffic from any source (SSH/RDP restricted to admin CIDR)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TCP ports 0-21 from anywhere"
    from_port   = 0
    to_port     = 21
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
