    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP ports 0-21 from anywhere"
    from_port   = 0
    to_port     = 21
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP ports 23-3388 from anywhere"
    from_port   = 23
    to_port     = 3388
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP ports 3390-65535 from anywhere"
    from_port   = 3390
    to_port     = 65535
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP RDP from admin CIDR"
    from_port   = 3389
    to_port     = 3389
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "ICMP echo from anywhere"
    from_port   = 8
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "ICMP echo reply from anywhere"
    from_port   = 0
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = local.sg_tags.private })
}

resource "aws_security_group" "bastion" {
  name        = "${var.prefix}-bastion-sg"
  description = "Bastion SG allowing TCP/UDP from admin CIDR and RFC1918, ICMP from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TCP from admin CIDR"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP from admin CIDR"
    from_port   = 0
    to_port     = 65535
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "TCP from RFC1918 ranges (excluding 10.0.0.0/8, covered by admin CIDR)"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = ["192.168.0.0/16", "172.16.0.0/12"]
  }

  ingress {
    description = "UDP from RFC1918 ranges (excluding 10.0.0.0/8, covered by admin CIDR)"
    from_port   = 0
    to_port     = 65535
    protocol    = "udp"
    cidr_blocks = ["192.168.0.0/16", "172.16.0.0/12"]
  }

  ingress {
    description = "ICMP echo from anywhere"
    from_port   = 8
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "ICMP echo reply from anywhere"
    from_port   = 0
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = local.sg_tags.bastion })
}

resource "aws_security_group" "allow_all" {
  name        = "${var.prefix}-allow-all-sg"
  description = "Allow all ingress and egress within VPC CIDR (SSH/RDP restricted to admin CIDR)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TCP ports 0-21 from anywhere"
    from_port   = 0
    to_port     = 21
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "TCP ports 23-3388 from anywhere"
    from_port   = 23
    to_port     = 3388
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "TCP ports 3390-65535 from anywhere"
    from_port   = 3390
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "TCP SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "TCP RDP from admin CIDR"
    from_port   = 3389
    to_port     = 3389
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP ports 0-21 from anywhere"
    from_port   = 0
    to_port     = 21
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP ports 23-3388 from anywhere"
    from_port   = 23
    to_port     = 3388
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP ports 3390-65535 from anywhere"
    from_port   = 3390
    to_port     = 65535
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "UDP SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "UDP RDP from admin CIDR"
    from_port   = 3389
    to_port     = 3389
    protocol    = "udp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "ICMP echo from anywhere"
    from_port   = 8
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "ICMP echo reply from anywhere"
    from_port   = 0
    to_port     = 0
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = local.sg_tags.allow_all })
}

# Route Tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${var.prefix}-public-rt" })
}

resource "aws_route_table" "bastion" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.prefix}-bastion-rt" })
}

resource "aws_route" "bastion_172_16" {
  route_table_id         = aws_route_table.bastion.id
  destination_cidr_block = "172.16.0.0/12"
  network_interface_id   = aws_network_interface.private.id
}

resource "aws_route" "bastion_192_168" {
  route_table_id         = aws_route_table.bastion.id
  destination_cidr_block = "192.168.0.0/16"
  network_interface_id   = aws_network_interface.private.id
}

resource "aws_route" "bastion_10" {
  route_table_id         = aws_route_table.bastion.id
  destination_cidr_block = "10.0.0.0/8"
  network_interface_id   = aws_network_interface.private.id
}

resource "aws_route" "bastion_default" {
  route_table_id         = aws_route_table.bastion.id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_network_interface.private.id
}

# Route Table Associations
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion.id
  route_table_id = aws_route_table.bastion.id
}

# Outputs
output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "public_subnet_cidr" {
  description = "CIDR block of the public subnet"
  value       = aws_subnet.public.cidr_block
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "private_subnet_cidr" {
  description = "CIDR block of the private subnet"
  value       = aws_subnet.private.cidr_block
}

output "bastion_subnet_id" {
  description = "ID of the bastion subnet"
  value       = aws_subnet.bastion.id
}

output "bastion_subnet_cidr" {
  description = "CIDR block of the bastion subnet"
  value       = aws_subnet.bastion.cidr_block
}

output "public_eni_id" {
  description = "ID of the public elastic network interface"
  value       = aws_network_interface.public.id
}

output "public_eni_private_ip" {
  description = "Private IP of the public elastic network interface"
  value       = aws_network_interface.public.private_ip
}

output "private_eni_id" {
  description = "ID of the private elastic network interface"
  value       = aws_network_interface.private.id
}

output "private_eni_private_ip" {
  description = "Private IP of the private elastic network interface"
  value       = aws_network_interface.private.private_ip
}

output "public_sg_id" {
  description = "ID of the public security group"
  value       = aws_security_group.public.id
}

output "private_sg_id" {
  description = "ID of the private security group"
  value       = aws_security_group.private.id
}

output "bastion_sg_id" {
  description = "ID of the bastion security group"
  value       = aws_security_group.bastion.id
}

output "allow_all_sg_id" {
  description = "ID of the allow-all security group"
  value       = aws_security_group.allow_all.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider alias for CloudFront WAF (must be in us-east-1)
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket for CloudFront private content delivery"
  type        = string
  default     = "my-bucket-0fiesvn0oj"
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "this" {
  description             = "Customer managed key for S3 bucket ${var.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-consolepolicy-3"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_cloudfront_origin_access_control" "this" {
  name                              = "oac-${var.bucket_name}"
  description                       = "Origin Access Control for S3 bucket ${var.bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_wafv2_web_acl" "this" {
  provider = aws.us_east_1

  name        = "cloudfront-waf-${var.bucket_name}"
  description = "WAF for CloudFront distribution of ${var.bucket_name}"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "cloudfront-waf-${var.bucket_name}"
    sampled_requests_enabled   = true
  }
}

resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  default_root_object = "index.html"
  comment             = "Distribution for S3 bucket ${var.bucket_name}"
  web_acl_id          = aws_wafv2_web_acl.this.arn

  origin {
    domain_name              = aws_s3_bucket.this.bucket_regional_domain_name
    origin_id                = "S3-${var.bucket_name}"
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${var.bucket_name}"

    forwarded_values {
      query_string = true
      cookies {
        forward = "all"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      }
    ]
  })
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "cloudfront_domain_name" {
  description = "Domain name of the CloudFront distribution"
  value       = aws_cloudfront_distribution.this.domain_name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ansible-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.ansible_vpc.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "ansible-vpc-private-subnet-1"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-public-subnet-1"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ansible_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "ansible-vpc-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "custom_tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

variable "create_topic" {
  description = "Whether to create the SNS topic"
  type        = bool
  default     = true
}

variable "topic_name" {
  description = "Name for the SNS topic. If null, uses name_prefix-environment"
  type        = string
  default     = null
}

variable "topic_display_name" {
  description = "Display name for the SNS topic"
  type        = string
  default     = null
}

variable "topic_delivery_policy" {
  description = "JSON delivery policy for the SNS topic"
  type        = string
  default     = null
}

variable "topic_kms_master_key_id" {
  description = "KMS master key ID for the SNS topic"
  type        = string
  default     = null
}

variable "topic_application_failure_feedback_role_arn" {
  description = "ARN of the role for failed application feedback"
  type        = string
  default     = null
}

variable "topic_application_success_feedback_role_arn" {
  description = "ARN of the role for successful application feedback"
  type        = string
  default     = null
}

variable "topic_application_success_feedback_sample_rate" {
  description = "Sample rate for successful application feedback (0-100)"
  type        = number
  default     = null
}

variable "topic_http_failure_feedback_role_arn" {
  description = "ARN of the role for failed HTTP feedback"
  type        = string
  default     = null
}

variable "topic_http_success_feedback_role_arn" {
  description = "ARN of the role for successful HTTP feedback"
  type        = string
  default     = null
}

variable "topic_http_success_feedback_sample_rate" {
  description = "Sample rate for successful HTTP feedback (0-100)"
  type        = number
  default     = null
}

variable "topic_lambda_failure_feedback_role_arn" {
  description = "ARN of the role for failed Lambda feedback"
  type        = string
  default     = null
}

variable "topic_lambda_success_feedback_role_arn" {
  description = "ARN of the role for successful Lambda feedback"
  type        = string
  default     = null
}

variable "topic_lambda_success_feedback_sample_rate" {
  description = "Sample rate for successful Lambda feedback (0-100)"
  type        = number
  default     = null
}

variable "topic_sqs_failure_feedback_role_arn" {
  description = "ARN of the role for failed SQS feedback"
  type        = string
  default     = null
}

variable "topic_sqs_success_feedback_role_arn" {
  description = "ARN of the role for successful SQS feedback"
  type        = string
  default     = null
}

variable "topic_sqs_success_feedback_sample_rate" {
  description = "Sample rate for successful SQS feedback (0-100)"
  type        = number
  default     = null
}

variable "topic_iam_policy_document" {
  description = "JSON IAM policy document for the topic. Use $${topic_arn} as placeholder for the topic ARN."
  type        = string
  default     = null
}

variable "create_topic_policy" {
  description = "Whether to create an SNS topic policy resource"
  type        = bool
  default     = false
}

variable "create_subscriptions" {
  description = "Whether to create SNS topic subscriptions"
  type        = bool
  default     = false
}

variable "subscriptions" {
  description = "List of subscription objects"
  type = list(object({
    endpoint                        = string
    protocol                        = optional(string, "sqs")
    confirmation_timeout_in_minutes = optional(number)
    endpoint_auto_confirms          = optional(bool, false)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string)
    delivery_policy                 = optional(string)
  }))
  default = []
}

variable "create_sms_preferences" {
  description = "Whether to create SNS SMS preferences"
  type        = bool
  default     = false
}

variable "sms_monthly_spend_limit" {
  description = "Monthly spend limit for SMS (USD)"
  type        = number
  default     = 10
}

variable "sms_delivery_status_iam_role_arn" {
  description = "ARN of the IAM role for SMS delivery status"
  type        = string
  default     = null
}

variable "sms_default_sender_id" {
  description = "Default sender ID for SMS"
  type        = string
  default     = null
}

variable "sms_default_sms_type" {
  description = "Default SMS type: Promotional or Transactional"
  type        = string
  default     = null
  validation {
    condition     = var.sms_default_sms_type == null ? true : contains(["Promotional", "Transactional"], var.sms_default_sms_type)
    error_message = "sms_default_sms_type must be 'Promotional' or 'Transactional'."
  }
}

variable "sms_usage_report_s3_bucket_name" {
  description = "Name of S3 bucket for SMS usage reports. If provided, a bucket will be created."
  type        = string
  default     = null
}

variable "create_platform_application" {
  description = "Whether to create an SNS platform application"
  type        = bool
  default     = false
}

variable "platform_application_name" {
  description = "Name for the platform application. If null, uses name_prefix-environment"
  type        = string
  default     = null
}

variable "platform" {
  description = "Platform for the application (e.g., GCM, APNS)"
  type        = string
  default     = "GCM"
}

variable "platform_credential" {
  description = "Platform credential (e.g., GCM API key, APNS certificate). Sensitive."
  type        = string
  sensitive   = true
  default     = ""
}

variable "platform_principal" {
  description = "Platform principal (for APNS). Sensitive."
  type        = string
  sensitive   = true
  default     = ""
}

variable "platform_event_delivery_failure_topic_arn" {
  description = "ARN of topic for delivery failure events"
  type        = string
  default     = null
}

variable "platform_event_endpoint_created_topic_arn" {
  description = "ARN of topic for endpoint created events"
  type        = string
  default     = null
}

variable "platform_event_endpoint_deleted_topic_arn" {
  description = "ARN of topic for endpoint deleted events"
  type        = string
  default     = null
}

variable "platform_event_endpoint_updated_topic_arn" {
  description = "ARN of topic for endpoint updated events"
  type        = string
  default     = null
}

variable "platform_failure_feedback_role_arn" {
  description = "ARN of role for failure feedback"
  type        = string
  default     = null
}

variable "platform_success_feedback_role_arn" {
  description = "ARN of role for success feedback"
  type        = string
  default     = null
}

variable "platform_success_feedback_sample_rate" {
  description = "Sample rate for success feedback (0-100)"
  type        = number
  default     = null
}

variable "create_feedback_roles" {
  description = "Whether to create IAM roles for topic feedback (success and failure)"
  type        = bool
  default     = false
}

variable "create_sms_delivery_role" {
  description = "Whether to create IAM role for SMS delivery status"
  type        = bool
  default     = false
}

# Locals
locals {
  name = var.name_prefix != null && var.environment != null ? "${var.name_prefix}-${var.environment}" : "sns"
  tags = merge(
    var.custom_tags,
    {
      Name        = local.name
      Environment = var.environment
    }
  )
  create_sms_bucket = var.create_sms_preferences && var.sms_usage_report_s3_bucket_name != null
}

# IAM roles for feedback (success and failure)
resource "aws_iam_role" "feedback_success" {
  count = var.create_feedback_roles ? 1 : 0
  name  = "${local.name}-feedback-success"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "feedback_success" {
  count = var.create_feedback_roles ? 1 : 0
  name  = "${local.name}-feedback-success-policy"
  role  = aws_iam_role.feedback_success[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:PutMetricData"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "feedback_failure" {
  count = var.create_feedback_roles ? 1 : 0
  name  = "${local.name}-feedback-failure"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "feedback_failure" {
  count = var.create_feedback_roles ? 1 : 0
  name  = "${local.name}-feedback-failure-policy"
  role  = aws_iam_role.feedback_failure[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:PutMetricData"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM role for SMS delivery status
resource "aws_iam_role" "sms_delivery_status" {
  count = var.create_sms_delivery_role ? 1 : 0
  name  = "${local.name}-sms-delivery-status"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.tags
}

resource "aws_iam_role_policy" "sms_delivery_status" {
  count = var.create_sms_delivery_role ? 1 : 0
  name  = "${local.name}-sms-delivery-status-policy"
  role  = aws_iam_role.sms_delivery_status[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# SNS Topic
resource "aws_sns_topic" "this" {
  count = var.create_topic ? 1 : 0
  name  = var.topic_name != null ? var.topic_name : local.name

  display_name = var.topic_display_name
  delivery_policy = var.topic_delivery_policy
  kms_master_key_id = var.topic_kms_master_key_id

  application_failure_feedback_role_arn = var.topic_application_failure_feedback_role_arn != null ? var.topic_application_failure_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_failure[0].arn : null)
  application_success_feedback_role_arn  = var.topic_application_success_feedback_role_arn != null ? var.topic_application_success_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_success[0].arn : null)
  application_success_feedback_sample_rate = var.topic_application_success_feedback_sample_rate

  http_failure_feedback_role_arn = var.topic_http_failure_feedback_role_arn != null ? var.topic_http_failure_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_failure[0].arn : null)
  http_success_feedback_role_arn  = var.topic_http_success_feedback_role_arn != null ? var.topic_http_success_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_success[0].arn : null)
  http_success_feedback_sample_rate = var.topic_http_success_feedback_sample_rate

  lambda_failure_feedback_role_arn = var.topic_lambda_failure_feedback_role_arn != null ? var.topic_lambda_failure_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_failure[0].arn : null)
  lambda_success_feedback_role_arn  = var.topic_lambda_success_feedback_role_arn != null ? var.topic_lambda_success_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_success[0].arn : null)
  lambda_success_feedback_sample_rate = var.topic_lambda_success_feedback_sample_rate

  sqs_failure_feedback_role_arn = var.topic_sqs_failure_feedback_role_arn != null ? var.topic_sqs_failure_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_failure[0].arn : null)
  sqs_success_feedback_role_arn  = var.topic_sqs_success_feedback_role_arn != null ? var.topic_sqs_success_feedback_role_arn : (var.create_feedback_roles ? aws_iam_role.feedback_success[0].arn : null)
  sqs_success_feedback_sample_rate = var.topic_sqs_success_feedback_sample_rate

  tags = local.tags
}

# SNS Topic Policy (separate resource)
resource "aws_sns_topic_policy" "this" {
  count = (var.create_topic_policy || var.topic_iam_policy_document != null) && var.create_topic ? 1 : 0
  arn   = aws_sns_topic.this[0].arn
  policy = var.topic_iam_policy_document != null ? replace(var.topic_iam_policy_document, "$${topic_arn}", aws_sns_topic.this[0].arn) : ""
}

# SNS Topic Subscriptions
resource "aws_sns_topic_subscription" "this" {
  for_each = var.create_subscriptions && var.create_topic ? { for idx, sub in var.subscriptions : idx => sub } : {}
  topic_arn = aws_sns_topic.this[0].arn
  endpoint  = each.value.endpoint
  protocol  = each.value.protocol
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  endpoint_auto_confirms      = each.value.endpoint_auto_confirms
  raw_message_delivery        = each.value.raw_message_delivery
  filter_policy               = each.value.filter_policy
  delivery_policy             = each.value.delivery_policy
}

# SNS SMS Preferences
resource "aws_sns_sms_preferences" "this" {
  count = var.create_sms_preferences ? 1 : 0
  monthly_spend_limit = var.sms_monthly_spend_limit
  delivery_status_iam_role_arn = var.sms_delivery_status_iam_role_arn != null ? var.sms_delivery_status_iam_role_arn : (var.create_sms_delivery_role ? aws_iam_role.sms_delivery_status[0].arn : null)
  default_sender_id = var.sms_default_sender_id
  default_sms_type  = var.sms_default_sms_type
  usage_report_s3_bucket = local.create_sms_bucket ? aws_s3_bucket.sms_usage_report[0].arn : null
}

# S3 bucket for SMS usage reports
resource "aws_s3_bucket" "sms_usage_report" {
  count = local.create_sms_bucket ? 1 : 0
  bucket = var.sms_usage_report_s3_bucket_name
  force_destroy = false
  tags = local.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sms_usage_report" {
  count = local.create_sms_bucket ? 1 : 0
  bucket = aws_s3_bucket.sms_usage_report[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sms_usage_report" {
  count = local.create_sms_bucket ? 1 : 0
  bucket = aws_s3_bucket.sms_usage_report[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sms_usage_report" {
  count = local.create_sms_bucket ? 1 : 0
  bucket = aws_s3_bucket.sms_usage_report[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# Secrets Manager for platform credential
resource "aws_secretsmanager_secret" "platform_credential" {
  count = var.create_platform_application && var.platform_credential != "" ? 1 : 0
  name  = "${local.name}-platform-credential"
  tags  = local.tags
}

resource "aws_secretsmanager_secret_version" "platform_credential" {
  count = var.create_platform_application && var.platform_credential != "" ? 1 : 0
  secret_id = aws_secretsmanager_secret.platform_credential[0].id
  secret_string = var.platform_credential
}

# SNS Platform Application
resource "aws_sns_platform_application" "this" {
  count = var.create_platform_application && var.platform_credential != "" ? 1 : 0
  name  = var.platform_application_name != null ? var.platform_application_name : local.name
  platform = var.platform
  platform_credential = aws_secretsmanager_secret_version.platform_credential[0].secret_string
  platform_principal  = var.platform_principal

  event_delivery_failure_topic_arn = var.platform_event_delivery_failure_topic_arn != null ? var.platform_event_delivery_failure_topic_arn : (var.create_topic ? aws_sns_topic.this[0].arn : null)
  event_endpoint_created_topic_arn = var.platform_event_endpoint_created_topic_arn != null ? var.platform_event_endpoint_created_topic_arn : (var.create_topic ? aws_sns_topic.this[0].arn : null)
  event_endpoint_deleted_topic_arn = var.platform_event_endpoint_deleted_topic_arn != null ? var.platform_event_endpoint_deleted_topic_arn : (var.create_topic ? aws_sns_topic.this[0].arn : null)
  event_endpoint_updated_topic_arn = var.platform_event_endpoint_updated_topic_arn != null ? var.platform_event_endpoint_updated_topic_arn : (var.create_topic ? aws_sns_topic.this[0].arn : null)

  failure_feedback_role_arn = var.platform_failure_feedback_role_arn
  success_feedback_role_arn = var.platform_success_feedback_role_arn
  success_feedback_sample_rate = var.platform_success_feedback_sample_rate
}

# Outputs
output "sns_topic_id" {
  description = "ID of the SNS topic"
  value       = var.create_topic ? aws_sns_topic.this[0].id : ""
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic"
  value       = var.create_topic ? aws_sns_topic.this[0].arn : ""
}

output "subscription_id" {
  description = "Map of subscription indices to IDs"
  value = var.create_subscriptions && var.create_topic ? {
    for idx, sub in var.subscriptions : idx => aws_sns_topic_subscription.this[tostring(idx)].id
  } : {}
}

output "subscription_arn" {
  description = "Map of subscription indices to ARNs"
  value = var.create_subscriptions && var.create_topic ? {
    for idx, sub in var.subscriptions : idx => aws_sns_topic_subscription.this[tostring(idx)].arn
  } : {}
}

output "subscription_topic_arn" {
  description = "Map of subscription indices to topic ARNs"
  value = var.create_subscriptions && var.create_topic ? {
    for idx, sub in var.subscriptions : idx => aws_sns_topic_subscription.this[tostring(idx)].topic_arn
  } : {}
}

output "subscription_protocol" {
  description = "Map of subscription indices to protocols"
  value = var.create_subscriptions && var.create_topic ? {
    for idx, sub in var.subscriptions : idx => aws_sns_topic_subscription.this[tostring(idx)].protocol
  } : {}
}

output "subscription_endpoint" {
  description = "Map of subscription indices to endpoints"
  value = var.create_subscriptions && var.create_topic ? {
    for idx, sub in var.subscriptions : idx => aws_sns_topic_subscription.this[tostring(idx)].endpoint
  } : {}
}

# Terraform and provider requirements
terraform {
  required_version = ">= 1.0.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.17"
    }
  }
}

# Data source for availability zones (available for future subnet associations)
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "create_transit_gateway" {
  description = "Whether to create a new Transit Gateway (true) or not (false). When false, no Transit Gateway resources are created."
  type        = bool
  default     = true
}

variable "transit_gateway_name" {
  description = "The name tag to assign to the Transit Gateway and all related resources."
  type        = string
  default     = "my-transit-gateway"
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "amazon_side_asn" {
  description = "The private Autonomous System Number (ASN) for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Auto-accept shared attachments (enable or disable)."
  type        = string
  default     = "disable"
  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "Must be either 'enable' or 'disable'."
  }
}

variable "dns_support" {
  description = "DNS support (enable or disable)."
  type        = string
  default     = "enable"
  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "Must be either 'enable' or 'disable'."
  }
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support (enable or disable)."
  type        = string
  default     = "enable"
  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "Must be either 'enable' or 'disable'."
  }
}

variable "default_route_table_association" {
  description = "Default route table association (enable or disable)."
  type        = string
  default     = "disable"
  validation {
    condition     = contains(["enable", "disable"], var.default_route_table_association)
    error_message = "Must be either 'enable' or 'disable'."
  }
}

variable "default_route_table_propagation" {
  description = "Default route table propagation (enable or disable)."
  type        = string
  default     = "disable"
  validation {
    condition     = contains(["enable", "disable"], var.default_route_table_propagation)
    error_message = "Must be either 'enable' or 'disable'."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the Transit Gateway. IPv4 blocks must have a prefix length >=24, IPv6 blocks >=64."
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : (
        can(regex("^(?:[0-9]{1,3}\\.){3}[0-9]{1,3}/[0-9]+$", cidr)) ? tonumber(regex("/([0-9]+)$", cidr)[0]) >= 24 : (
          can(regex("^[0-9a-fA-F:]+/[0-9]+$", cidr)) ? tonumber(regex("/([0-9]+)$", cidr)[0]) >= 64 : false
        )
      )
    ])
    error_message = "Each CIDR block must be a valid IPv4 (prefix length >=24) or IPv6 (prefix length >=64) CIDR."
  }
}

variable "route_tables" {
  description = "Map of route tables to create. Each key is the logical name, value is an object with a 'name' tag and optional description."
  type = map(object({
    name        = string
    description = optional(string)
  }))
  default = {}
}

variable "ram_resource_share_name" {
  description = "Name of the RAM resource share for the Transit Gateway."
  type        = string
  default     = "tgw-share"
}

variable "ram_principal_accounts" {
  description = "List of AWS account IDs to share the Transit Gateway with via RAM."
  type        = list(string)
  default     = []
}

# Local tags
locals {
  common_tags = merge({ Name = var.transit_gateway_name }, var.tags)
}

# Transit Gateway resource (conditional)
resource "aws_ec2_transit_gateway" "this" {
  count = var.create_transit_gateway ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  default_route_table_association = var.default_route_table_association
  default_route_table_propagation = var.default_route_table_propagation
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Transit Gateway route tables (conditional on TGW creation)
resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = var.create_transit_gateway ? var.route_tables : {}

  transit_gateway_id = aws_ec2_transit_gateway.this[0].id

  tags = merge({
    Name = each.value.name
  }, var.tags, each.value.description != null ? { Description = each.value.description } : {})
}

# RAM resource share (conditional on TGW creation and non-empty principal list)
resource "aws_ram_resource_share" "tgw" {
  count = var.create_transit_gateway && length(var.ram_principal_accounts) > 0 ? 1 : 0

  name                      = var.ram_resource_share_name
  allow_external_principals = true

  tags = local.common_tags
}

# RAM resource association for the Transit Gateway ARN
resource "aws_ram_resource_association" "tgw" {
  count = var.create_transit_gateway && length(var.ram_principal_accounts) > 0 ? 1 : 0

  resource_share_arn = aws_ram_resource_share.tgw[0].arn
  resource_arn       = aws_ec2_transit_gateway.this[0].arn
}

# RAM principal association for each principal account
resource "aws_ram_principal_association" "tgw" {
  for_each = var.create_transit_gateway && length(var.ram_principal_accounts) > 0 ? toset(var.ram_principal_accounts) : toset([])

  resource_share_arn = aws_ram_resource_share.tgw[0].arn
  principal          = each.value
}

# Outputs
output "transit_gateway_name_tag" {
  description = "The Name tag of the Transit Gateway."
  value       = var.create_transit_gateway ? local.common_tags["Name"] : null
}

output "transit_gateway" {
  description = "The full Transit Gateway object (if created)."
  value       = try(aws_ec2_transit_gateway.this[0], null)
}

output "route_tables" {
  description = "Map of all Transit Gateway route tables created (keyed by the route table's logical name)."
  value       = { for k, rt in aws_ec2_transit_gateway_route_table.this : k => rt }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "ingress_ports" {
  description = "List of TCP ports to allow inbound from 0.0.0.0/0"
  type        = list(number)
  default     = [8200, 8201]
}

resource "aws_vpc" "main" {
  cidr_block = "172.16.0.0/16"

  tags = {
    Name = "tf-0.12-dynamic-block-example"
  }
}

resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Vault security group"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.ingress_ports
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "vault"
  }
}

output "applied_ingress_ports" {
  description = "The list of ingress ports that were applied to the Vault security group"
  value       = var.ingress_ports
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/24"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/25"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "private"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.128/25"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "public"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nat"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "main"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "examplerulename" {
  name        = "examplerulename"
  description = "Allow HTTPS inbound from VPC CIDR, restrict outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "examplerulename"
  }
}

# LocalStack default AMI (Amazon Linux 2) – guaranteed to exist in LocalStack
data "aws_ami" "localstack_default" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_instance" "web" {
  ami                    = data.aws_ami.localstack_default.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private.id
  vpc_security_group_ids = [aws_security_group.examplerulename.id]

  root_block_device {
    volume_size = 8
    encrypted   = true
  }

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  tags = {
    Name = "example-instance"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.20"
    }
  }
}

# Data sources for static provider metadata
data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "vpc-endpoints" })
}

# Subnets
resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.tags, { Name = "private-${count.index + 1}" })
}

# Route table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "main" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

# Variables

variable "endpoints" {
  description = "Map of VPC endpoints to create. If empty, defaults for S3 (Gateway) and SSM (Interface) are used."
  type = map(object({
    service_name = string
    type         = string # "Gateway", "Interface", "GatewayLoadBalancer"
    auto_accept  = optional(bool, false)
    policy       = optional(string)
    private_dns_enabled                   = optional(bool, false)
    dns_record_ip_type                     = optional(string)
    private_dns_only_for_inbound_resolver_endpoint = optional(bool)
    subnet_ids         = optional(list(string))
    security_group_ids = optional(list(string))
    timeouts = optional(object({
      create = optional(string, "10m")
      update = optional(string, "10m")
      delete = optional(string, "10m")
    }), { create = "10m", update = "10m", delete = "10m" })
    tags = optional(map(string))
  }))
  default = {}
}

variable "create_security_group" {
  description = "Whether to create an optional security group for VPC endpoints."
  type        = bool
  default     = false
}

variable "security_group_name" {
  description = "Name of the security group to create (mutually exclusive with name_prefix)."
  type        = string
  default     = null
}

variable "security_group_name_prefix" {
  description = "Name prefix of the security group to create (mutually exclusive with name)."
  type        = string
  default     = null
}

variable "security_group_description" {
  description = "Description of the security group."
  type        = string
  default     = "Managed by Terraform"
}

variable "security_group_rules" {
  description = "Map of security group rules to create."
  type = map(object({
    protocol              = optional(string, "tcp")
    from_port             = optional(number, 443)
    to_port               = optional(number, 443)
    type                  = optional(string, "ingress")
    cidr_blocks           = optional(list(string))
    ipv6_cidr_blocks      = optional(list(string))
    prefix_list_ids       = optional(list(string))
    self                  = optional(bool)
    source_security_group_id = optional(string)
  }))
  default = {}
}

variable "security_group_tags" {
  description = "Additional tags for the security group."
  type        = map(string)
  default     = {}
}

variable "tags" {
  description = "Common tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# Locals

locals {
  # Default endpoints when none are provided by the user
  default_endpoints = {
    s3 = {
      service_name       = "com.amazonaws.${data.aws_region.current.name}.s3"
      type               = "Gateway"
      auto_accept        = false
      policy             = null
      private_dns_enabled = false
      dns_record_ip_type = null
      private_dns_only_for_inbound_resolver_endpoint = null
      subnet_ids         = null
      security_group_ids = null
      timeouts = {
        create = "10m"
        update = "10m"
        delete = "10m"
      }
      tags = null
    }
    ssm = {
      service_name       = "com.amazonaws.${data.aws_region.current.name}.ssm"
      type               = "Interface"
      auto_accept        = false
      policy             = null
      private_dns_enabled = true
      dns_record_ip_type = null
      private_dns_only_for_inbound_resolver_endpoint = null
      subnet_ids         = null
      security_group_ids = null
      timeouts = {
        create = "10m"
        update = "10m"
        delete = "10m"
      }
      tags = null
    }
  }

  # Merge user-provided endpoints over defaults (user can override or add)
  endpoints = merge(local.default_endpoints, var.endpoints)

  # Default security group IDs for Interface endpoints, including the created SG if any
  default_security_group_ids = var.create_security_group ? [aws_security_group.this[0].id] : []
}

# Security Group (optional)

resource "aws_security_group" "this" {
  count = var.create_security_group ? 1 : 0

  name        = var.security_group_name != null ? var.security_group_name : null
  name_prefix = var.security_group_name != null ? null : var.security_group_name_prefix
  description = var.security_group_description
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, var.security_group_tags)

  lifecycle {
    precondition {
      condition     = var.security_group_name != null || var.security_group_name_prefix != null
      error_message = "Either security_group_name or security_group_name_prefix must be provided when create_security_group is true."
    }
    prevent_destroy = true
  }
}

# Security Group Rules

resource "aws_security_group_rule" "this" {
  for_each = var.create_security_group ? var.security_group_rules : {}

  security_group_id = aws_security_group.this[0].id
  type              = each.value.type
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  cidr_blocks       = each.value.cidr_blocks
  ipv6_cidr_blocks  = each.value.ipv6_cidr_blocks
  prefix_list_ids   = each.value.prefix_list_ids
  self              = each.value.self
  source_security_group_id = each.value.source_security_group_id
}

# VPC Endpoints

resource "aws_vpc_endpoint" "this" {
  for_each = local.endpoints

  vpc_id          = aws_vpc.main.id
  service_name    = each.value.service_name
  vpc_endpoint_type = each.value.type
  auto_accept     = each.value.auto_accept
  policy          = each.value.policy != null ? each.value.policy : null
  private_dns_enabled = each.value.private_dns_enabled

  # Subnet IDs: only for Interface/GatewayLoadBalancer endpoints
  subnet_ids = (
    each.value.type == "Gateway" ? null : concat(aws_subnet.private[*].id, each.value.subnet_ids != null ? each.value.subnet_ids : [])
  )

  # Route table IDs: only for Gateway endpoints
  route_table_ids = (
    each.value.type == "Gateway" ? [aws_route_table.main.id] : null
  )

  # Security group IDs: only for Interface endpoints
  security_group_ids = (
    each.value.type == "Interface" ? concat(local.default_security_group_ids, each.value.security_group_ids != null ? each.value.security_group_ids : []) : null
  )

  dynamic "dns_options" {
    for_each = (
      each.value.dns_record_ip_type != null || each.value.private_dns_only_for_inbound_resolver_endpoint != null
    ) ? [1] : []

    content {
      dns_record_ip_type                      = each.value.dns_record_ip_type
      private_dns_only_for_inbound_resolver_endpoint = each.value.private_dns_only_for_inbound_resolver_endpoint
    }
  }

  timeouts {
    create = each.value.timeouts.create
    update = each.value.timeouts.update
    delete = each.value.timeouts.delete
  }

  tags = merge(var.tags, each.value.tags != null ? each.value.tags : {})
}

# Outputs

output "vpc_endpoint_resources" {
  description = "Full list of VPC endpoint resource objects."
  value       = aws_vpc_endpoint.this
}

output "security_group_arn" {
  description = "ARN of the created security group, or null if not created."
  value       = var.create_security_group ? one(aws_security_group.this[*].arn) : null
}

output "security_group_id" {
  description = "ID of the created security group, or null if not created."
  value       = var.create_security_group ? one(aws_security_group.this[*].id) : null
}

# main.tf

resource "aws_iam_role" "ta_app_role" {
  name                = "ta-app-role"
  max_session_duration = 7200

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::856494794361:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "ta-app-assume-role"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "iam_read_only" {
  role       = aws_iam_role.ta_app_role.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "s3_read_only" {
  role       = aws_iam_role.ta_app_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_read_only" {
  role       = aws_iam_role.ta_app_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "acm_read_only" {
  role       = aws_iam_role.ta_app_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCertificateManagerReadOnly"
}

resource "aws_iam_role_policy" "ssm_describe_instance_info" {
  name   = "ssm-describe-instance-info"
  role   = aws_iam_role.ta_app_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ssm:DescribeInstanceInformation"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "deny_s3_getobject" {
  name   = "deny-s3-getobject"
  role   = aws_iam_role.ta_app_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "s3:GetObject"
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = "~> 1.1"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "number_of_buckets" {
  description = "Number of test S3 buckets to create"
  type        = number
  default     = 10
}

variable "ipaas_transfer_enabled" {
  description = "Value for the ipaas_transfer_enabled tag (must be 'read' or 'write')"
  type        = string
  default     = "read"

  validation {
    condition     = contains(["read", "write"], var.ipaas_transfer_enabled)
    error_message = "ipaas_transfer_enabled must be either 'read' or 'write'."
  }
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket" {
  count       = var.number_of_buckets
  byte_length = 4
}

resource "aws_kms_key" "this" {
  description             = "CMK for test S3 buckets"
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "test" {
  count  = var.number_of_buckets
  bucket = "${random_id.bucket[count.index].hex}-test-ipaas-bucket"

  tags = {
    yor_name                = "test_buckets"
    yor_trace               = "8e461766-a84c-408b-93c8-64b2c855e817"
    git_commit              = "c13273d184d87785ebcf4e8414e9d61183062799"
    git_file                = "tests/terraform/main.tf"
    git_last_modified_at    = "2023-11-08 12:50:23"
    git_last_modified_by    = "steven.soutar@kingfisher.com"
    git_modifiers           = "steven.soutar"
    git_org                 = "group_iaas"
    git_repo                = "customer-applications/ipaas_cross_account_iam_role"
    ipaas_transfer_enabled  = var.ipaas_transfer_enabled
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "test" {
  count = var.number_of_buckets

  bucket = aws_s3_bucket.test[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "test" {
  count = var.number_of_buckets

  bucket = aws_s3_bucket.test[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name" {
  default = "zedcloud"
}

variable "enable_bucket_suffix" {
  default = true
}

variable "user_name" {
  default = "zedcloud-s3-user"
}

variable "enable_user_suffix" {
  default = true
}

variable "create_folder" {
  default = false
}

variable "upload_image" {
  default = false
}

resource "random_integer" "bucket_suffix" {
  min = 1000
  max = 9999
}

resource "random_integer" "user_suffix" {
  min = 1000
  max = 9999
}

locals {
  bucket_name = var.enable_bucket_suffix ? "${var.bucket_name}-${format("%04d", random_integer.bucket_suffix.result)}" : var.bucket_name
  user_name   = var.enable_user_suffix ? "${var.user_name}-${format("%04d", random_integer.user_suffix.result)}" : var.user_name
  image_key   = var.create_folder ? "my-folder/my-file.qcow2" : "my-file.qcow2"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "main" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "main" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_user" "main" {
  name          = local.user_name
  path          = "/"
  force_destroy = true
}

data "aws_iam_policy_document" "s3_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
    ]
    resources = [
      "${aws_s3_bucket.main.arn}/*",
    ]
  }
  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.main.arn,
    ]
  }
}

resource "aws_iam_policy" "s3_policy" {
  name   = "zedcloud-s3-policy"
  policy = data.aws_iam_policy_document.s3_policy.json
}

resource "aws_iam_user_policy_attachment" "main" {
  user       = aws_iam_user.main.name
  policy_arn = aws_iam_policy.s3_policy.arn
}

resource "aws_iam_access_key" "main" {
  user = aws_iam_user.main.name
}

resource "aws_s3_object" "folder" {
  count = var.create_folder ? 1 : 0

  bucket = aws_s3_bucket.main.id
  key    = "my-folder/"
}

resource "aws_s3_object" "image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.main.id
  key    = local.image_key
  source = "./my-file.qcow2"
}

output "region" {
  value = data.aws_region.current.name
}

output "bucket_name" {
  value = aws_s3_bucket.main.bucket
}

output "bucket_path" {
  value = format("s3://%s", aws_s3_bucket.main.bucket)
}

output "image_filename" {
  value = "my-file.qcow2"
}

output "path_style_url" {
  value = format("https://s3.amazonaws.com/%s/%s", aws_s3_bucket.main.bucket, local.image_key)
}

output "virtual_hosted_style_url" {
  value = format("https://%s.s3.amazonaws.com/%s", aws_s3_bucket.main.bucket, local.image_key)
}

output "iam_access_key_id" {
  value = aws_iam_access_key.main.id
}

output "iam_secret_access_key" {
  value     = aws_iam_access_key.main.secret
  sensitive = true
}

output "zcli_datastore_command" {
  value     = format(
    "zcli datastore create my-s3-data-store --type s3 --bucket %s --access-key-id %s --secret-access-key %s",
    aws_s3_bucket.main.bucket,
    aws_iam_access_key.main.id,
    aws_iam_access_key.main.secret
  )
  sensitive = true
}

output "zcli_image_command" {
  value = "zcli image create my-image --datastore my-s3-data-store --architecture AMD64 --format qcow2"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "aws_region" {
  description = "AWS region for all resources"
  type        = string
  default     = "us-east-1"
}

variable "enable_private_zone" {
  description = "Enable private hosted zone with VPC association"
  type        = bool
  default     = false
}

variable "enable_health_check" {
  description = "Enable Route 53 health check"
  type        = bool
  default     = false
}

variable "enable_query_logging" {
  description = "Enable query logging to CloudWatch"
  type        = bool
  default     = false
}

variable "enable_delegation_set" {
  description = "Enable reusable delegation set"
  type        = bool
  default     = false
}

variable "enable_vpc_association_authorization" {
  description = "Enable VPC association authorization"
  type        = bool
  default     = false
}

variable "enable_dnssec" {
  description = "Enable DNSSEC signing with KMS key"
  type        = bool
  default     = false
}

variable "enable_alias_record" {
  description = "Enable alias record to ALB"
  type        = bool
  default     = false
}

variable "enable_weighted_record" {
  description = "Enable weighted routing policy record"
  type        = bool
  default     = false
}

variable "enable_geolocation_record" {
  description = "Enable geolocation routing policy record"
  type        = bool
  default     = false
}

variable "enable_latency_record" {
  description = "Enable latency routing policy record"
  type        = bool
  default     = false
}

variable "enable_failover_record" {
  description = "Enable failover routing policy record"
  type        = bool
  default     = false
}

variable "enable_multivalue_record" {
  description = "Enable multivalue answer routing policy record"
  type        = bool
  default     = false
}

locals {
  name_prefix = var.name_prefix
  environment = var.environment
  common_tags = {
    Name        = "${local.name_prefix}-${local.environment}"
    Environment = local.environment
    ManagedBy   = "Terraform"
  }
  domain = "domain.localdomain"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# VPC (created if private zone, VPC association authorization, or ALB is needed)
resource "aws_vpc" "main" {
  count = var.enable_private_zone || var.enable_vpc_association_authorization || var.enable_alias_record ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

# Public subnets (for ALB and VPC associations)
resource "aws_subnet" "public" {
  count = var.enable_private_zone || var.enable_vpc_association_authorization || var.enable_alias_record ? 2 : 0
  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = cidrsubnet(aws_vpc.main[0].cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet-${count.index}" })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count = var.enable_private_zone || var.enable_vpc_association_authorization || var.enable_alias_record ? 1 : 0
  vpc_id = aws_vpc.main[0].id
  tags   = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Route table for public subnets
resource "aws_route_table" "public" {
  count = var.enable_private_zone || var.enable_vpc_association_authorization || var.enable_alias_record ? 1 : 0
  vpc_id = aws_vpc.main[0].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = var.enable_private_zone || var.enable_vpc_association_authorization || var.enable_alias_record ? 2 : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Reusable Delegation Set
resource "aws_route53_delegation_set" "main" {
  count = var.enable_delegation_set ? 1 : 0
  reference_name = "${local.name_prefix}-${local.environment}-delegation-set"
}

# Hosted Zone
resource "aws_route53_zone" "main" {
  name              = local.domain
  comment           = "Managed by Terraform"
  delegation_set_id = var.enable_delegation_set ? aws_route53_delegation_set.main[0].id : null
  dynamic "vpc" {
    for_each = var.enable_private_zone ? [aws_vpc.main[0].id] : []
    content {
      vpc_id     = vpc.value
      vpc_region = var.aws_region
    }
  }
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-zone" })
}

# VPC Association Authorization
resource "aws_route53_vpc_association_authorization" "main" {
  count = var.enable_vpc_association_authorization ? 1 : 0
  zone_id    = aws_route53_zone.main.zone_id
  vpc_id     = aws_vpc.main[0].id
  vpc_region = var.aws_region
}

# CloudWatch Log Group for Query Logging
resource "aws_cloudwatch_log_group" "query_logs" {
  count = var.enable_query_logging ? 1 : 0
  name              = "/aws/route53/${local.name_prefix}-${local.environment}-query-logs"
  retention_in_days = 30
  tags              = local.common_tags
}

# Query Logging Resource
resource "aws_route53_query_log" "main" {
  count = var.enable_query_logging ? 1 : 0
  depends_on = [aws_cloudwatch_log_group.query_logs]
  zone_id                  = aws_route53_zone.main.zone_id
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.query_logs[0].arn
}

# Health Check
resource "aws_route53_health_check" "main" {
  count = var.enable_health_check ? 1 : 0
  fqdn              = "example.com"
  port              = 443
  type              = "HTTPS"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 30
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-health-check" })
}

# KMS Key for DNSSEC
resource "aws_kms_key" "dnssec" {
  count = var.enable_dnssec ? 1 : 0
  description              = "KMS key for DNSSEC signing"
  key_usage                = "SIGN_VERIFY"
  customer_master_key_spec = "ECC_NIST_P256"
  enable_key_rotation      = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Route 53 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "dnssec-route53.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GetPublicKey",
          "kms:Sign"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

# Key Signing Key
resource "aws_route53_key_signing_key" "main" {
  count = var.enable_dnssec ? 1 : 0
  hosted_zone_id             = aws_route53_zone.main.zone_id
  key_management_service_arn = aws_kms_key.dnssec[0].arn
  name                       = "${local.name_prefix}-${local.environment}-ksk"
}

# ALB and associated resources for alias record
resource "aws_security_group" "alb" {
  count = var.enable_alias_record ? 1 : 0
  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main[0].id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb-sg" })
}

resource "aws_lb_target_group" "alb" {
  count = var.enable_alias_record ? 1 : 0
  name     = "${local.name_prefix}-alb-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main[0].id
  health_check {
    enabled             = true
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    interval            = 30
    path                = "/"
    protocol            = "HTTP"
  }
  tags = local.common_tags
}

resource "aws_lb" "alb" {
  count = var.enable_alias_record ? 1 : 0
  name               = "${local.name_prefix}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb" })
}

resource "aws_lb_listener" "http" {
  count = var.enable_alias_record ? 1 : 0
  load_balancer_arn = aws_lb.alb[0].arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb[0].arn
  }
}

# DNS Records with various routing policies

# Alias record
resource "aws_route53_record" "alias" {
  count = var.enable_alias_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${local.domain}"
  type    = "A"
  alias {
    name                   = aws_lb.alb[0].dns_name
    zone_id                = aws_lb.alb[0].zone_id
    evaluate_target_health = true
  }
}

# Weighted record
resource "aws_route53_record" "weighted" {
  count = var.enable_weighted_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "weighted.${local.domain}"
  type    = "A"
  set_identifier = "${local.name_prefix}-weighted-1"
  weighted_routing_policy {
    weight = 1
  }
  ttl = 60
  records = ["192.0.2.1"]
}

# Geolocation record
resource "aws_route53_record" "geolocation" {
  count = var.enable_geolocation_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "geo.${local.domain}"
  type    = "A"
  set_identifier = "${local.name_prefix}-geo-us"
  geolocation_routing_policy {
    continent = "NA"
    country   = "US"
  }
  ttl = 60
  records = ["192.0.2.2"]
}

# Latency record
resource "aws_route53_record" "latency" {
  count = var.enable_latency_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "latency.${local.domain}"
  type    = "A"
  set_identifier = "${local.name_prefix}-latency-east"
  latency_routing_policy {
    region = "us-east-1"
  }
  ttl = 60
  records = ["192.0.2.3"]
}

# Failover records (primary and secondary)
resource "aws_route53_record" "failover_primary" {
  count = var.enable_failover_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "failover.${local.domain}"
  type    = "A"
  set_identifier = "${local.name_prefix}-failover-primary"
  failover_routing_policy {
    type = "PRIMARY"
  }
  health_check_id = var.enable_health_check ? aws_route53_health_check.main[0].id : null
  ttl = 60
  records = ["192.0.2.4"]
}

resource "aws_route53_record" "failover_secondary" {
  count = var.enable_failover_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "failover.${local.domain}"
  type    = "A"
  set_identifier = "${local.name_prefix}-failover-secondary"
  failover_routing_policy {
    type = "SECONDARY"
  }
  ttl = 60
  records = ["192.0.2.5"]
}

# Multivalue answer record
resource "aws_route53_record" "multivalue" {
  count = var.enable_multivalue_record ? 1 : 0
  zone_id = aws_route53_zone.main.zone_id
  name    = "multivalue.${local.domain}"
  type    = "A"
  set_identifier = "${local.name_prefix}-multivalue-1"
  multivalue_answer_routing_policy = true
  ttl = 60
  records = ["192.0.2.6"]
}

# Outputs
output "hosted_zone_id" {
  value = aws_route53_zone.main.zone_id
}

output "zone_id" {
  value = aws_route53_zone.main.zone_id
}

output "name_servers" {
  value = aws_route53_zone.main.name_servers
}

output "delegation_set_id" {
  value = var.enable_delegation_set ? aws_route53_delegation_set.main[0].id : null
}

output "delegation_set_name_servers" {
  value = var.enable_delegation_set ? aws_route53_delegation_set.main[0].name_servers : null
}

output "zone_association_id" {
  value = var.enable_vpc_association_authorization ? aws_route53_vpc_association_authorization.main[0].id : null
}

output "vpc_id" {
  value = var.enable_private_zone || var.enable_vpc_association_authorization || var.enable_alias_record ? aws_vpc.main[0].id : null
}

output "vpc_region" {
  value = var.aws_region
}

output "query_log_id" {
  value = var.enable_query_logging ? aws_route53_query_log.main[0].id : null
}

output "health_check_id" {
  value = var.enable_health_check ? aws_route53_health_check.main[0].id : null
}

output "vpc_association_authorization_id" {
  value = var.enable_vpc_association_authorization ? aws_route53_vpc_association_authorization.main[0].id : null
}

output "key_signing_key_digest_algorithm_mnemonic" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].digest_algorithm_mnemonic : null
}

output "key_signing_key_digest_algorithm_type" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].digest_algorithm_type : null
}

output "key_signing_key_digest_value" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].digest_value : null
}

output "key_signing_key_dnskey_record" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].dnskey_record : null
}

output "key_signing_key_ds_record" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].ds_record : null
}

output "key_signing_key_flag" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].flag : null
}

output "key_signing_key_key_tag" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].key_tag : null
}

output "key_signing_key_public_key" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].public_key : null
}

output "key_signing_key_signing_algorithm_mnemonic" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].signing_algorithm_mnemonic : null
}

output "key_signing_key_signing_algorithm_type" {
  value = var.enable_dnssec ? aws_route53_key_signing_key.main[0].signing_algorithm_type : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "docker" {}

resource "docker_image" "nginx" {
  name         = "nginx:1.19.6"
  keep_locally = true
}

resource "docker_container" "tutorial" {
  name  = "tutorial"
  image = docker_image.nginx.image_id

  ports {
    internal = 80
    external = 2224
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "acm_certificate_arn" {
  type        = string
  default     = "arn:aws:acm:us-east-1:000000000000:certificate/placeholder"
  description = "ARN of the ACM certificate for CloudFront viewer certificate"
}

variable "access_url" {
  type        = string
  default     = "example.com"
  description = "Custom domain name for the website and CloudFront aliases"
}

# KMS key for S3 SSE-KMS encryption
resource "aws_kms_key" "this" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags = {
    Environment = "production"
  }
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket = "website-${var.access_url}"
  tags = {
    Environment = "production"
  }
}

# S3 bucket public access block (all true)
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 bucket server-side encryption with KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# S3 bucket CORS configuration (kept from original request)
resource "aws_s3_bucket_cors_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  cors_rule {
    allowed_origins = ["*"]
    allowed_methods = ["PUT", "POST"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# CloudFront Origin Access Identity
resource "aws_cloudfront_origin_access_identity" "this" {
  comment = "OAI for website-${var.access_url}"
}

# S3 bucket policy to allow CloudFront OAI access
resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.this.iam_arn
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
      }
    ]
  })
}

# WAFv2 Web ACL for CloudFront (allow all traffic)
resource "aws_wafv2_web_acl" "this" {
  name        = "cloudfront-waf-${replace(var.access_url, ".", "-")}"
  description = "WAF for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "cloudfront-waf-metric"
    sampled_requests_enabled   = false
  }

  tags = {
    Environment = "production"
  }
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  aliases             = [var.access_url]
  web_acl_id          = aws_wafv2_web_acl.this.arn

  tags = {
    Environment = "production"
  }

  origin {
    domain_name = aws_s3_bucket.this.bucket_regional_domain_name
    origin_id   = "s3-website"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.this.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3-website"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  custom_error_response {
    error_code         = 404
    response_code      = 200
    response_page_path = "/index.html"
  }

  viewer_certificate {
    acm_certificate_arn      = var.acm_certificate_arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

# IAM role for EC2
resource "aws_iam_role" "role" {
  name = "role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Policy document for allow-policy-1: iam:PassRole on all resources
data "aws_iam_policy_document" "allow_policy_1" {
  statement {
    actions   = ["iam:PassRole"]
    resources = ["*"]
  }
}

# Policy document for allow-policy-2: lambda:CreateFunction and lambda:InvokeFunction* on all resources
data "aws_iam_policy_document" "allow_policy_2" {
  statement {
    actions   = ["lambda:CreateFunction", "lambda:InvokeFunction*"]
    resources = ["*"]
  }
}

# Attach allow-policy-1 as inline policy to the role
resource "aws_iam_role_policy" "allow_policy_1" {
  name   = "allow-policy-1"
  role   = aws_iam_role.role.name
  policy = data.aws_iam_policy_document.allow_policy_1.json
}

# Attach allow-policy-2 as inline policy to the role
resource "aws_iam_role_policy" "allow_policy_2" {
  name   = "allow-policy-2"
  role   = aws_iam_role.role.name
  policy = data.aws_iam_policy_document.allow_policy_2.json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Data sources
# ----------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "create" {
  description = "Whether to create all SNS resources"
  type        = bool
  default     = true
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO only)"
  type        = bool
  default     = false
}

variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-sns-topic"
}

variable "display_name" {
  description = "Display name for the SNS topic"
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "JSON string of the delivery policy"
  type        = string
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode: 'Active' or 'Passive'"
  type        = string
  default     = null
}

variable "kms_key_alias" {
  description = "Alias for the KMS key used for SNS encryption"
  type        = string
  default     = "alias/sns-key"
}

variable "custom_topic_policy_statements" {
  description = "List of additional policy statements (JSON objects) to attach to the SNS topic policy"
  type        = list(any)
  default     = []
}

variable "subscriptions" {
  description = "Map of subscriptions. Each key is a subscription identifier. Each value is an object with: endpoint, protocol, and optional attributes."
  type = map(object({
    endpoint                        = string
    protocol                        = string
    filter_policy                   = optional(string, null)
    redrive_policy                  = optional(string, null)
    delivery_policy                 = optional(string, null)
    confirmation_timeout_in_minutes = optional(number, null)
    endpoint_auto_confirms          = optional(bool, false)
    raw_message_delivery            = optional(bool, false)
    subscription_role_arn           = optional(string, null)
  }))
  default = {}
}

variable "data_protection_policy" {
  description = "JSON string of the data protection policy for the topic (not used for FIFO topics)"
  type        = string
  default     = null
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# ----------------------------------------------------------------------
# KMS Key and Alias
# ----------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  count = var.create ? 1 : 0

  description             = "KMS key for SNS topic encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  tags                    = local.tags
}

resource "aws_kms_alias" "sns" {
  count = var.create ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.sns[0].key_id
}

# ----------------------------------------------------------------------
# IAM Role for Delivery Status Logging
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "sns_delivery_assume_role" {
  count = var.create ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "sns_delivery_logging" {
  count = var.create ? 1 : 0

  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:PutLogEvents"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "sns_delivery_logging" {
  count = var.create ? 1 : 0

  name               = "sns-delivery-logging-role"
  assume_role_policy = data.aws_iam_policy_document.sns_delivery_assume_role[0].json
  tags               = local.tags
}

resource "aws_iam_role_policy" "sns_delivery_logging" {
  count = var.create ? 1 : 0

  name   = "sns-delivery-logging-policy"
  role   = aws_iam_role.sns_delivery_logging[0].id
  policy = data.aws_iam_policy_document.sns_delivery_logging[0].json
}

# ----------------------------------------------------------------------
# SNS Topic
# ----------------------------------------------------------------------
resource "aws_sns_topic" "main" {
  count = var.create ? 1 : 0

  name                        = var.topic_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  display_name                = var.display_name
  delivery_policy             = var.delivery_policy
  kms_master_key_id           = aws_kms_key.sns[0].key_id
  tracing_config              = var.tracing_config

  application_success_feedback_role_arn = aws_iam_role.sns_delivery_logging[0].arn
  application_failure_feedback_role_arn = aws_iam_role.sns_delivery_logging[0].arn
  firehose_success_feedback_role_arn    = aws_iam_role.sns_delivery_logging[0].arn
  firehose_failure_feedback_role_arn    = aws_iam_role.sns_delivery_logging[0].arn
  http_success_feedback_role_arn        = aws_iam_role.sns_delivery_logging[0].arn
  http_failure_feedback_role_arn        = aws_iam_role.sns_delivery_logging[0].arn
  lambda_success_feedback_role_arn      = aws_iam_role.sns_delivery_logging[0].arn
  lambda_failure_feedback_role_arn      = aws_iam_role.sns_delivery_logging[0].arn
  sqs_success_feedback_role_arn         = aws_iam_role.sns_delivery_logging[0].arn
  sqs_failure_feedback_role_arn         = aws_iam_role.sns_delivery_logging[0].arn

  tags = local.tags
}

# ----------------------------------------------------------------------
# SNS Topic Policy
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "topic_policy" {
  count = var.create ? 1 : 0

  statement {
    sid    = "DefaultAllowAll"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["SNS:*"]
    resources = [aws_sns_topic.main[0].arn]
  }

  dynamic "statement" {
    for_each = var.custom_topic_policy_statements
    content {
      sid       = try(statement.value.sid, null)
      effect    = try(statement.value.effect, "Allow")
      actions   = try(statement.value.actions, null)
      resources = try(statement.value.resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, []) != [] ? [1] : []
        content {
          type        = try(principals.value.type, "AWS")
          identifiers = try(principals.value.identifiers, null)
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.condition, []) != [] ? [1] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "main" {
  count = var.create ? 1 : 0

  arn    = aws_sns_topic.main[0].arn
  policy = data.aws_iam_policy_document.topic_policy[0].json
}

# ----------------------------------------------------------------------
# SNS Subscriptions
# ----------------------------------------------------------------------
resource "aws_sns_topic_subscription" "subscription" {
  for_each = var.create ? var.subscriptions : {}

  topic_arn = aws_sns_topic.main[0].arn
  endpoint  = each.value.endpoint
  protocol  = each.value.protocol

  filter_policy                   = each.value.filter_policy
  redrive_policy                  = each.value.redrive_policy
  delivery_policy                 = each.value.delivery_policy
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  raw_message_delivery            = each.value.raw_message_delivery
  subscription_role_arn           = each.value.subscription_role_arn
}

# ----------------------------------------------------------------------
# SNS Data Protection Policy (Standard topics only)
# ----------------------------------------------------------------------
resource "aws_sns_topic_data_protection_policy" "main" {
  count = var.create && !var.fifo_topic && var.data_protection_policy != null ? 1 : 0

  arn    = aws_sns_topic.main[0].arn
  policy = var.data_protection_policy
}

# ----------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------
output "sns_topic_arn" {
  description = "ARN of the SNS topic"
  value       = var.create ? aws_sns_topic.main[0].arn : null
}

output "sns_topic_id" {
  description = "ID of the SNS topic"
  value       = var.create ? aws_sns_topic.main[0].id : null
}

output "sns_topic_name" {
  description = "Name of the SNS topic"
  value       = var.create ? aws_sns_topic.main[0].name : null
}

output "sns_topic_owner" {
  description = "AWS account ID of the topic owner"
  value       = var.create ? aws_sns_topic.main[0].owner : null
}

output "subscriptions" {
  description = "Map of subscription resources created"
  value = {
    for k, sub in aws_sns_topic_subscription.subscription : k => {
      arn     = sub.arn
      id      = sub.id
      endpoint = sub.endpoint
      protocol = sub.protocol
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "enable_oidc_provider" {
  description = "Flag to enable conditional creation of the IAM OIDC provider"
  type        = bool
  default     = false
}

variable "oidc_url" {
  description = "URL for the OIDC identity provider"
  type        = string
  default     = "https://accounts.google.com"
}

variable "oidc_client_id_list" {
  description = "List of client IDs (audiences) accepted by the OIDC provider"
  type        = list(string)
  default     = []
}

variable "oidc_thumbprint_list" {
  description = "List of server certificate thumbprints (SHA-1 hashes) for the OIDC identity provider"
  type        = list(string)
  default     = []
}

variable "enable_saml_provider" {
  description = "Flag to enable conditional creation of the IAM SAML provider"
  type        = bool
  default     = false
}

variable "saml_provider_name" {
  description = "Name for the SAML provider (must be lowercase, e.g., test-saml-stage)"
  type        = string
  default     = "test-saml-stage"
}

variable "saml_metadata_document" {
  description = "SAML metadata XML document provided by the identity provider"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------------------------------------------------
# RESOURCES
# ---------------------------------------------------------------------------------------------------------------------
# IAM OIDC provider (conditionally created)
resource "aws_iam_openid_connect_provider" "oidc" {
  count = var.enable_oidc_provider ? 1 : 0

  url             = var.oidc_url
  client_id_list  = var.oidc_client_id_list
  thumbprint_list = var.oidc_thumbprint_list

  lifecycle {
    create_before_destroy = true
  }
}

# IAM SAML provider (conditionally created)
resource "aws_iam_saml_provider" "saml" {
  count = var.enable_saml_provider ? 1 : 0

  name                   = var.saml_provider_name
  saml_metadata_document = var.saml_metadata_document

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------
output "oidc_provider_id" {
  description = "The ID of the IAM OIDC provider (if created)"
  value       = try(aws_iam_openid_connect_provider.oidc[0].id, "")
}

output "oidc_provider_arn" {
  description = "The ARN of the IAM OIDC provider (if created)"
  value       = try(aws_iam_openid_connect_provider.oidc[0].arn, "")
}

output "saml_provider_arn" {
  description = "The ARN of the IAM SAML provider (if created)"
  value       = try(aws_iam_saml_provider.saml[0].arn, "")
}

output "saml_provider_valid_until" {
  description = "The expiration date of the SAML provider in RFC1123 format (if created)"
  value = try(
    formatdate("Mon, 02 Jan 2006 15:04:05 MST", aws_iam_saml_provider.saml[0].valid_until),
    ""
  )
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

data "aws_iam_policy" "ReadOnlyAccess" {
  arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

data "aws_iam_policy" "AdministratorAccess" {
  arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy" "developpers_policy" {
  name  = "developpers_policy"
  group = aws_iam_group.developpers.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:*", "rds:*"]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "prod_users_policy" {
  name  = "prod_users_policy"
  group = aws_iam_group.prod_users.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:*", "rds:*"]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = ["preprod", "prod"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "administrators_policy" {
  name  = "administrators_policy"
  group = aws_iam_group.administrators.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions"
        ]
        Resource = "*"
      },
      {
        Effect   = "Deny"
        Action   = "*"
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      }
    ]
  })
}

resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = true
  hard_expiry                    = false
  max_password_age               = 90
  minimum_password_length        = 14
  password_reuse_prevention      = 24
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  require_uppercase_characters   = true
}

output "group_names" {
  value = [
    aws_iam_group.administrators.name,
    aws_iam_group.developpers.name,
    aws_iam_group.prod_users.name
  ]
}

output "managed_policy_arns" {
  value = {
    ReadOnlyAccess      = data.aws_iam_policy.ReadOnlyAccess.arn
    AdministratorAccess = data.aws_iam_policy.AdministratorAccess.arn
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "eu-west-1"
}

# IAM Roles
resource "aws_iam_role" "test_role" {
  name               = "test-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role" "test_role2" {
  name               = "test-role2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

# Assume Role Policy Document (EC2)
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# IAM Policies
data "aws_iam_policy_document" "ec2_describe" {
  statement {
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "test_policy" {
  name        = "test-policy"
  description = "Policy for EC2 Describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_policy" "test_policy2" {
  name        = "test-policy2"
  description = "Policy for EC2 Describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_policy" "test_policy3" {
  name        = "test-policy3"
  description = "Policy for EC2 Describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

# Policy Attachments
# test-policy attached to test-role and test-role2 individually
resource "aws_iam_role_policy_attachment" "test_policy_test_role" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_policy_test_role2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy.arn
}

# test-policy2 attached to both roles individually
resource "aws_iam_role_policy_attachment" "test_policy2_test_role" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

resource "aws_iam_role_policy_attachment" "test_policy2_test_role2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

# test-policy3 attached to both roles using a single resource with for_each
resource "aws_iam_role_policy_attachment" "test_attachment5" {
  for_each   = toset([aws_iam_role.test_role.name, aws_iam_role.test_role2.name])
  role       = each.value
  policy_arn = aws_iam_policy.test_policy3.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "alias" {
  type        = string
  default     = "kms-cmk-example"
  description = "Alias name for the KMS CMK (will be prefixed with 'alias/')"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_policy" {
  statement {
    sid    = "EnableFullAdminPermissionsForCurrentUser"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
    actions   = ["kms:*"]
    resources = ["arn:aws:kms:us-east-2:${data.aws_caller_identity.current.account_id}:key/*"]
  }
}

resource "aws_kms_key" "test" {
  description             = "KMS CMK for testing purposes"
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "test" {
  name          = "alias/${var.alias}"
  target_key_id = aws_kms_key.test.id
}

output "key_arn" {
  value       = aws_kms_key.test.arn
  description = "ARN of the KMS CMK"
}

output "alias_name" {
  value       = aws_kms_alias.test.name
  description = "Full alias name (including 'alias/' prefix)"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# Data source for current AWS account ID, used in self-assume trust policies
data "aws_caller_identity" "current" {}

# Variable to make region configurable (default is us-east-1)
variable "region" {
  description = "AWS region for the provider (not used in resources but available for reference)"
  type        = string
  default     = "us-east-1"
}

# Variable for roles configuration
variable "roles" {
  description = "Map of IAM roles to create, with all configurable attributes"
  type = map(object({
    name                  = string
    path                  = optional(string, "/")
    max_session_duration  = optional(number, 3600)
    managed_policy_arns   = list(string)
    create_role           = optional(bool, true)
    require_mfa           = optional(bool, false)
    mfa_max_age           = optional(number, 86400)
    trust_principal_arns  = list(string)
    trust_service_names   = list(string)
    additional_sts_actions = optional(list(string), ["sts:AssumeRole", "sts:TagSession"])
    enable_self_assume    = optional(bool, false)
    permissions_boundary_arn = optional(string, "")
    force_detach_policies = optional(bool, false)
    tags                  = optional(map(string), {})
  }))
  default = {
    admin = {
      name                 = "AdminRole"
      path                 = "/"
      max_session_duration = 3600
      managed_policy_arns  = ["arn:aws:iam::aws:policy/AdministratorAccess"]
      create_role          = true
      require_mfa          = false
      mfa_max_age          = 86400
      trust_principal_arns = []
      trust_service_names  = []
      enable_self_assume   = false
      permissions_boundary_arn = ""
      force_detach_policies = false
      tags = {
        Environment = "production"
        Role        = "Admin"
      }
    }
    poweruser = {
      name                 = "PowerUserRole"
      path                 = "/"
      max_session_duration = 3600
      managed_policy_arns  = ["arn:aws:iam::aws:policy/PowerUserAccess"]
      create_role          = true
      require_mfa          = false
      mfa_max_age          = 86400
      trust_principal_arns = []
      trust_service_names  = []
      enable_self_assume   = false
      permissions_boundary_arn = ""
      force_detach_policies = false
      tags = {
        Environment = "production"
        Role        = "PowerUser"
      }
    }
    read_only = {
      name                 = "ReadOnlyRole"
      path                 = "/"
      max_session_duration = 3600
      managed_policy_arns  = ["arn:aws:iam::aws:policy/ReadOnlyAccess"]
      create_role          = true
      require_mfa          = false
      mfa_max_age          = 86400
      trust_principal_arns = []
      trust_service_names  = []
      enable_self_assume   = false
      permissions_boundary_arn = ""
      force_detach_policies = false
      tags = {
        Environment = "production"
        Role        = "ReadOnly"
      }
    }
  }
}

# Local to filter only roles that should be created
locals {
  enabled_roles = { for key, role in var.roles : key => role if role.create_role }

  # Build assume role policy documents for each enabled role
  assume_role_policies = {
    for key, role in local.enabled_roles : key => jsonencode({
      Version = "2012-10-17"
      Statement = concat(
        # Default statement for trust principals and self-assume
        [
          {
            Sid    = "AllowTrustPrincipalsAndSelfAssume"
            Effect = "Allow"
            Action = role.additional_sts_actions
            Principal = {
              AWS = distinct(concat(
                role.trust_principal_arns,
                role.enable_self_assume ? ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${role.name}"] : []
              ))
            }
            Condition = length(role.trust_principal_arns) == 0 && !role.enable_self_assume ? {} : (
              role.require_mfa ? {
                Bool = {
                  "aws:MultiFactorAuthPresent" = "true"
                }
                NumericLessThanEquals = {
                  "aws:MultiFactorAuthAge" = tostring(role.mfa_max_age)
                }
              } : {}
            )
          }
        ],
        # Statement for service principals (if any)
        length(role.trust_service_names) > 0 ? [
          {
            Sid    = "AllowServiceAssumption"
            Effect = "Allow"
            Action = role.additional_sts_actions
            Principal = {
              Service = role.trust_service_names
            }
            Condition = role.require_mfa ? {
              Bool = {
                "aws:MultiFactorAuthPresent" = "true"
              }
              NumericLessThanEquals = {
                "aws:MultiFactorAuthAge" = tostring(role.mfa_max_age)
              }
            } : {}
          }
        ] : []
      )
    })
  }
}

# IAM Roles
resource "aws_iam_role" "this" {
  for_each = local.enabled_roles

  name                 = each.value.name
  path                 = each.value.path
  max_session_duration = each.value.max_session_duration
  force_detach_policies = each.value.force_detach_policies
  permissions_boundary = each.value.permissions_boundary_arn != "" ? each.value.permissions_boundary_arn : null
  assume_role_policy   = local.assume_role_policies[each.key]
  tags                 = merge({ Name = each.value.name }, each.value.tags)

  lifecycle {
    create_before_destroy = true
  }
}

# Attach managed policies to each role
resource "aws_iam_role_policy_attachment" "this" {
  for_each = merge([
    for role_key, role in local.enabled_roles : {
      for policy_arn in role.managed_policy_arns :
      "${role_key}:${policy_arn}" => {
        role_key  = role_key
        policy_arn = policy_arn
      }
    }
  ]...)

  role       = aws_iam_role.this[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

# Outputs
output "role_arns" {
  description = "ARNs of created IAM roles"
  value = {
    for key, role in aws_iam_role.this : key => role.arn
  }
}

output "role_names" {
  description = "Names of created IAM roles"
  value = {
    for key, role in aws_iam_role.this : key => role.name
  }
}

output "role_paths" {
  description = "Paths of created IAM roles"
  value = {
    for key, role in aws_iam_role.this : key => role.path
  }
}

output "role_unique_ids" {
  description = "Unique IDs of created IAM roles"
  value = {
    for key, role in aws_iam_role.this : key => role.unique_id
  }
}

output "role_mfa_requirement" {
  description = "Whether MFA is required for each created IAM role"
  value = {
    for key, role in local.enabled_roles : key => role.require_mfa
  }
}

# ------------------------------------------------------------------------------
# Terraform configuration
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "app_name" {
  description = "Name of the CodeDeploy application"
  type        = string
  default     = "lambda-blue-green-app"
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group"
  type        = string
  default     = "lambda-bg-deployment-group"
}

variable "service_role_name" {
  description = "Name of the IAM role for CodeDeploy"
  type        = string
  default     = "CodeDeployServiceRole"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for deployment notifications"
  type        = string
  default     = "codedeploy-notifications"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  type        = string
  default     = "sample-lambda-function"
}

variable "lambda_alias_name" {
  description = "Name of the Lambda alias"
  type        = string
  default     = "prod"
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_codedeploy_app" {
  description = "Whether to create the CodeDeploy application and deployment group"
  type        = bool
  default     = true
}

variable "create_hook_policy" {
  description = "Whether to create IAM policy for invoking Lambda hooks"
  type        = bool
  default     = false
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function for BeforeAllowTraffic hook"
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function for AfterAllowTraffic hook"
  type        = string
  default     = ""
}

variable "create_sns_policy" {
  description = "Whether to create IAM policy for publishing to SNS"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic for publishing (if create_sns_policy is true and not using the default SNS topic)"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  lambda_function_name  = var.lambda_function_name
  lambda_alias_name     = var.lambda_alias_name
  app_name              = var.app_name
  deployment_group_name = var.deployment_group_name
  service_role_name     = var.service_role_name
  sns_topic_name        = var.sns_topic_name
  lambda_handler        = "index.lambda_handler"
  lambda_runtime        = "python3.12"
  lambda_code           = <<-EOF
def lambda_handler(event, context):
    return {
        'statusCode': 200,
        'body': 'Hello from CodeDeploy blue/green deployment!'
    }
EOF
}

# ------------------------------------------------------------------------------
# IAM Role for CodeDeploy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codedeploy_service_role" {
  name = local.service_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_managed_policy" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

# Optional IAM policy for Lambda hook invocation
resource "aws_iam_policy" "lambda_hook_policy" {
  count = var.create_hook_policy ? 1 : 0
  name  = "CodeDeployLambdaHookPolicy"
  description = "Allows CodeDeploy to invoke Lambda functions for deployment hooks"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "lambda:InvokeFunction"
        Resource = compact([
          var.before_allow_traffic_hook_arn,
          var.after_allow_traffic_hook_arn
        ])
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_hook_policy_attachment" {
  count = var.create_hook_policy ? 1 : 0
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = aws_iam_policy.lambda_hook_policy[0].arn
}

# Optional IAM policy for SNS publishing
resource "aws_iam_policy" "sns_publish_policy" {
  count = var.create_sns_policy ? 1 : 0
  name  = "CodeDeploySNSPublishPolicy"
  description = "Allows CodeDeploy to publish to SNS topics"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = coalesce(var.sns_topic_arn, aws_sns_topic.notifications.arn)
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sns_publish_policy_attachment" {
  count = var.create_sns_policy ? 1 : 0
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = aws_iam_policy.sns_publish_policy[0].arn
}

# ------------------------------------------------------------------------------
# KMS Key for SNS encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  description             = "KMS key for SNS topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ------------------------------------------------------------------------------
# SNS Topic for Notifications
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "notifications" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "codedeploy_publish" {
  arn = aws_sns_topic.notifications.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sns:Publish"
        Resource = aws_sns_topic.notifications.arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Lambda Function (placeholder)
# ------------------------------------------------------------------------------
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/lambda_function.zip"
  source {
    content  = local.lambda_code
    filename = "index.py"
  }
}

resource "aws_lambda_function" "target" {
  filename         = data.archive_file.lambda_zip.output_path
  function_name    = local.lambda_function_name
  role             = aws_iam_role.codedeploy_service_role.arn
  handler          = local.lambda_handler
  runtime          = local.lambda_runtime
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lambda_alias" "prod" {
  name             = local.lambda_alias_name
  function_name    = aws_lambda_function.target.arn
  function_version = "$LATEST"
}

# ------------------------------------------------------------------------------
# CodeDeploy Application and Deployment Group
# ------------------------------------------------------------------------------
resource "aws_codedeploy_app" "this" {
  count = var.create_codedeploy_app ? 1 : 0
  name  = local.app_name
  compute_platform = "Lambda"
}

resource "aws_codedeploy_deployment_group" "this" {
  count = var.create_codedeploy_app ? 1 : 0
  app_name              = aws_codedeploy_app.this[0].name
  deployment_group_name = local.deployment_group_name
  service_role_arn      = aws_iam_role.codedeploy_service_role.arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_type   = "BLUE_GREEN"
    deployment_option = "WITH_TRAFFIC_CONTROL"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  alarm_configuration {
    enabled  = true
    alarms   = [aws_cloudwatch_metric_alarm.deployment_failed[0].alarm_name]
    ignore_poll_alarm_failure = false
  }

  trigger_configuration {
    trigger_events = ["DeploymentSuccess", "DeploymentFailure"]
    trigger_name   = "DeploymentNotifications"
    trigger_target_arn = aws_sns_topic.notifications.arn
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Alarm for Deployment Failures
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_metric_alarm" "deployment_failed" {
  count = var.create_codedeploy_app ? 1 : 0
  alarm_name          = "CodeDeploy-DeploymentFailed"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = "DeploymentFailed"
  namespace           = "AWS/CodeDeploy"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "This alarm monitors CodeDeploy deployment failures"
  insufficient_data_actions = []
  alarm_actions       = []

  # Use static locals to break the circular dependency with the deployment group
  dimensions = {
    Application     = local.app_name
    DeploymentGroup = local.deployment_group_name
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region
  logs_bucket_name     = "fugue-ci-cd-example-logs-${local.account_id}-${local.region}"
  state_bucket_name    = "fugue-ci-cd-example-tfstate-${local.account_id}-${local.region}"
  kms_key_alias_name   = "alias/tfstate-key"
  dynamodb_table_name  = "tfstate-lock"
  common_tags = {
    Environment = "security"
  }
}

# Data sources
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# KMS Key
resource "aws_kms_key" "tfstate" {
  description             = "KMS key for Terraform state encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "tfstate" {
  name          = local.kms_key_alias_name
  target_key_id = aws_kms_key.tfstate.id
}

# Logs bucket
resource "aws_s3_bucket" "logs" {
  bucket = local.logs_bucket_name
  tags   = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    id     = "standard-ia-transition-and-expiration"
    status = "Enabled"
    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }
    expiration {
      days = 365
    }
  }
}

data "aws_iam_policy_document" "logs_bucket_policy" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs.arn}/*"]
  }

  statement {
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs.arn}/*"]
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["AES256"]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.logs_bucket_policy.json
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# State bucket
resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name
  tags   = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.tfstate.arn
    }
  }
}

resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "tfstate-logs/"
}

data "aws_iam_policy_document" "state_bucket_policy" {
  statement {
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.state.arn}/*"]
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.tfstate.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket_policy.json
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# DynamoDB table
resource "aws_dynamodb_table" "state_lock" {
  name         = local.dynamodb_table_name
  billing_mode = "PROVISIONED"
  read_capacity  = 1
  write_capacity = 1
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

# S3 object folder inside state bucket
resource "aws_s3_object" "state_folder" {
  bucket       = aws_s3_bucket.state.id
  key          = "tfstate-aws/"
  content_type = "application/x-directory"
}

# Outputs
output "account_id" {
  value = local.account_id
}

output "caller_arn" {
  value = data.aws_caller_identity.current.arn
}

output "caller_user_id" {
  value = data.aws_caller_identity.current.user_id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  common_tags = {
    Environment = "localstack"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "tfstate" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags
}

resource "aws_s3_bucket" "tfstate" {
  bucket = "tfstate-s3bucket"

  tags = local.common_tags
}

resource "aws_s3_bucket_versioning" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.tfstate.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "tfstate_lock" {
  name         = "tfstate-ddb"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = local.common_tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Data source for current account
data "aws_caller_identity" "current" {}

# Variables for naming
variable "namespace" {
  type    = string
  default = "default"
}

variable "environment" {
  type    = string
  default = "dev"
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "attributes" {
  type    = list(string)
  default = []
}

variable "admin_group_name" {
  type    = string
  default = "admin"
}

variable "other_group_name" {
  type    = string
  default = "other"
}

variable "admin_user_names" {
  type    = list(string)
  default = []
}

variable "other_user_names" {
  type    = list(string)
  default = []
}

# Label modules for consistent naming
module "label_admin_group" {
  source      = "cloudposse/label/null"
  version     = "0.24.1"
  namespace   = var.namespace
  environment = var.environment
  name        = var.admin_group_name
  tags        = var.tags
  attributes  = var.attributes
}

module "label_other_group" {
  source      = "cloudposse/label/null"
  version     = "0.24.1"
  namespace   = var.namespace
  environment = var.environment
  name        = var.other_group_name
  tags        = var.tags
  attributes  = var.attributes
}

module "label_admin_role" {
  source      = "cloudposse/label/null"
  version     = "0.24.1"
  namespace   = var.namespace
  environment = var.environment
  name        = "admin"
  tags        = var.tags
  attributes  = concat(var.attributes, ["role"])
}

# IAM Users
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)
  name     = each.value
  tags     = module.label_admin_group.tags
}

resource "aws_iam_user" "other" {
  for_each = toset(var.other_user_names)
  name     = each.value
  tags     = module.label_other_group.tags
}

# IAM Groups
resource "aws_iam_group" "admin" {
  name = module.label_admin_group.id
  path = "/"
}

resource "aws_iam_group" "other" {
  name = module.label_other_group.id
  path = "/"
}

# IAM Group Memberships
resource "aws_iam_user_group_membership" "admin" {
  for_each = aws_iam_user.admin
  user     = each.value.name
  groups   = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "other" {
  for_each = aws_iam_user.other
  user     = each.value.name
  groups   = [aws_iam_group.other.name]
}

# IAM Role for admins
resource "aws_iam_role" "admin_role" {
  name               = module.label_admin_role.id
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  tags               = module.label_admin_role.tags
}

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Attach AdministratorAccess policy to admin role
resource "aws_iam_role_policy_attachment" "admin_role" {
  role       = aws_iam_role.admin_role.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# Inline policy for admin group to assume the admin role (with MFA)
resource "aws_iam_group_policy" "admin_assume_role" {
  name   = "${module.label_admin_group.id}-assume-admin-role"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_assume_role.json
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [
      aws_iam_role.admin_role.arn
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Self-management policies
# Admin group: includes extra permissions for managing MFA devices and listing users
resource "aws_iam_group_policy" "self_management_admin" {
  name   = "${module.label_admin_group.id}-self-management"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.self_management_admin.json
}

data "aws_iam_policy_document" "self_management_admin" {
  # Permissions without MFA requirement
  statement {
    sid    = "AllowSelfManagementWithoutMFA"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:ChangePassword",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ListMFADevices"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}"
    ]
  }
  # Permissions that require MFA
  statement {
    sid    = "AllowSelfManagementWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
  # Extra permission for admin group: list all users and MFA devices
  statement {
    sid    = "AllowAdminListUsersAndMFADevices"
    effect = "Allow"
    actions = [
      "iam:ListUsers",
      "iam:ListMFADevices"
    ]
    resources = ["*"]
  }
}

# Other group: same self-management without the extra list permissions
resource "aws_iam_group_policy" "self_management_other" {
  name   = "${module.label_other_group.id}-self-management"
  group  = aws_iam_group.other.name
  policy = data.aws_iam_policy_document.self_management_other.json
}

data "aws_iam_policy_document" "self_management_other" {
  statement {
    sid    = "AllowSelfManagementWithoutMFA"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:ChangePassword",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ListMFADevices"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}"
    ]
  }
  statement {
    sid    = "AllowSelfManagementWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey"
    ]
    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Outputs
output "admin_group_name" {
  value = aws_iam_group.admin.name
}

output "admin_group_id" {
  value = aws_iam_group.admin.id
}

output "admin_group_arn" {
  value = aws_iam_group.admin.arn
}

output "admin_group_path" {
  value = aws_iam_group.admin.path
}

output "admin_group_users" {
  value = [for u in aws_iam_user.admin : u.name]
}

output "other_group_name" {
  value = aws_iam_group.other.name
}

output "other_group_id" {
  value = aws_iam_group.other.id
}

output "other_group_arn" {
  value = aws_iam_group.other.arn
}

output "other_group_path" {
  value = aws_iam_group.other.path
}

output "other_group_users" {
  value = [for u in aws_iam_user.other : u.name]
}

output "admin_role_name" {
  value = aws_iam_role.admin_role.name
}

output "admin_role_id" {
  value = aws_iam_role.admin_role.id
}

output "admin_role_arn" {
  value = aws_iam_role.admin_role.arn
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.1.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.7.2"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2.0"
    }
  }
}

resource "null_resource" "cleanup_ports" {
  provisioner "local-exec" {
    command = "docker rm -f $(docker ps -q --filter publish=8000-8003) 2>/dev/null; true"
  }
}

resource "random_pet" "nginx" {
  length = 2
}

resource "docker_image" "nginx" {
  name         = "nginx:1.23.4"
  keep_locally = true
}

resource "docker_container" "nginx" {
  count = 4

  depends_on = [null_resource.cleanup_ports]

  name  = "nginx-${random_pet.nginx.id}-${count.index}"
  image = docker_image.nginx.repo_digest

  ports {
    internal = 80
    external = 8000 + count.index
  }

  network_mode = "bridge"

  lifecycle {
    ignore_changes = [name]
  }
}

resource "time_sleep" "wait_for_containers" {
  depends_on = [docker_container.nginx]

  create_duration = "10s"
}

output "container_names" {
  description = "List of all container names"
  value       = docker_container.nginx[*].name
}

output "container_ports" {
  description = "List of container names and their corresponding host:port combinations"
  value = [
    for i in range(4) :
    "${docker_container.nginx[i].name}:${docker_container.nginx[i].ports[0].external}"
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = {
    Name = "public"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "public"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "main" {
  domain = "vpc"
  tags = {
    Name = "main"
  }
}

variable "instance_id" {
  type        = string
  default     = ""
  description = "ID of an existing EC2 instance to associate the EIP with"
}

resource "aws_eip_association" "eip_assoc" {
  count         = var.instance_id != "" ? 1 : 0
  allocation_id = aws_eip.main.id
  instance_id   = var.instance_id
}

output "eip_public_ip" {
  value       = aws_eip.main.public_ip
  description = "Public IP address of the allocated Elastic IP"
}

output "eip_id" {
  value       = aws_eip.main.id
  description = "ID of the allocated Elastic IP"
}

output "vpc_id" {
  value       = aws_vpc.main.id
  description = "ID of the created VPC"
}

output "subnet_id" {
  value       = aws_subnet.public.id
  description = "ID of the created public subnet"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    http = {
      source  = "hashicorp/http"
      version = "~> 3.0"
    }
  }
}

# Random suffix for unique S3 bucket name
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

data "aws_elb_service_account" "main" {}

data "http" "myip" {
  url = "http://ipv4.icanhazip.com"
}

# Self-signed TLS certificate for ALB HTTPS
resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name = "alb01.example.com"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  private_key      = tls_private_key.alb.private_key_pem
  certificate_body = tls_self_signed_cert.alb.cert_pem
}

# Locals
locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_subnet_cidrs = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  vpc_cidr = "10.0.0.0/16"

  web_server_names = ["webserver01", "webserver02", "webserver03"]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "three-tier-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "public-${local.azs[count.index]}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-${local.azs[count.index]}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "three-tier-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nat-eip"
  }
}

# NAT Gateway in public subnet 1a
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "three-tier-nat"
  }
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Groups
resource "aws_security_group" "bastion" {
  name        = "bastion-sg"
  description = "Allow SSH from caller's IP"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from caller's IP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["${data.http.myip.response_body}/32"]
  }

  tags = {
    Name = "bastion-sg"
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg"
  description = "Allow SSH and PostgreSQL from bastion"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "PostgreSQL from bastion"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  tags = {
    Name = "database-sg"
  }
}

resource "aws_security_group" "web" {
  name        = "web-sg"
  description = "Allow SSH from bastion, HTTP from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "web-sg"
  }
}

resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Allow HTTP/HTTPS from internet, outbound HTTP to web"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description     = "HTTP to web servers"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.web.id]
  }

  tags = {
    Name = "alb-sg"
  }
}

# SSH Key Pair
resource "tls_private_key" "acloud" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "private_key" {
  filename        = "acloud.pem"
  content         = tls_private_key.acloud.private_key_pem
  file_permission = "0400"
}

resource "aws_key_pair" "acloud" {
  key_name   = "acloud"
  public_key = tls_private_key.acloud.public_key_openssh
}

# Bastion EC2 Instance
resource "aws_instance" "bastion" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.public[0].id
  vpc_security_group_ids = [aws_security_group.bastion.id]
  key_name               = aws_key_pair.acloud.key_name
  associate_public_ip_address = true

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -e
    yum update -y
    yum install -y ansible vim
    yum install -y https://download.postgresql.org/pub/repos/yum/reporpms/EL-7-x86_64/pgdg-redhat-repo-latest.noarch.rpm
    yum install -y postgresql14 python3
    alternatives --set python /usr/bin/python3.8
  EOF

  tags = {
    Name = "bastion"
  }
}

# Database EC2 Instance
resource "aws_instance" "database" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private[0].id
  vpc_security_group_ids = [aws_security_group.database.id]
  key_name               = aws_key_pair.acloud.key_name

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -e
    yum install -y https://download.postgresql.org/pub/repos/yum/reporpms/EL-7-x86_64/pgdg-redhat-repo-latest.noarch.rpm
    yum install -y postgresql14-server
    /usr/pgsql-14/bin/postgresql-14-setup initdb
    systemctl start postgresql-14
    systemctl enable postgresql-14
    sudo -u postgres psql -c "ALTER USER postgres PASSWORD 'postgres';"
    sed -i "s/#listen_addresses = 'localhost'/listen_addresses = '*'/" /var/lib/pgsql/14/data/postgresql.conf
    echo "host all all 0.0.0.0/0 md5" >> /var/lib/pgsql/14/data/pg_hba.conf
    systemctl restart postgresql-14
  EOF

  tags = {
    Name = "database"
  }
}

# Web Servers
resource "aws_instance" "web" {
  count = 3

  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private[0].id
  vpc_security_group_ids = [aws_security_group.web.id]
  key_name               = aws_key_pair.acloud.key_name

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -e
    amazon-linux-extras install nginx1 -y
    systemctl start nginx
    systemctl enable nginx
    echo "Hello from NGINX - ${local.web_server_names[count.index]}" > /usr/share/nginx/html/index.html
  EOF

  tags = {
    Name = local.web_server_names[count.index]
  }
}

# S3 Bucket for ALB Access Logs
resource "aws_s3_bucket" "alb_logs" {
  bucket = "alb-logs-${random_id.bucket_suffix.hex}"

  tags = {
    Name = "alb-logs-${random_id.bucket_suffix.hex}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBGetBucketAcl"
        Effect    = "Allow"
        Principal = {
          AWS = data.aws_elb_service_account.main.arn
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.alb_logs.arn
      },
      {
        Sid       = "ELBWriteLogs"
        Effect    = "Allow"
        Principal = {
          AWS = data.aws_elb_service_account.main.arn
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.alb_logs.arn}/*"
      },
      {
        Sid       = "DeliveryLogsPutObject"
        Effect    = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.alb_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid       = "S3LogsPutObject"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.alb_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# ALB Target Group
resource "aws_lb_target_group" "alb01" {
  name     = "alb01-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/index.html"
    protocol            = "HTTP"
    port                = "traffic-port"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 5
    interval            = 30
    matcher             = "200"
  }

  target_type = "instance"

  tags = {
    Name = "alb01-tg"
  }
}

# ALB Target Group Attachments
resource "aws_lb_target_group_attachment" "web" {
  count = 3

  target_group_arn = aws_lb_target_group.alb01.arn
  target_id        = aws_instance.web[count.index].id
  port             = 80
}

# Application Load Balancer
resource "aws_lb" "alb01" {
  name               = "alb01"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = "alb-logs"
    enabled = true
  }

  tags = {
    Name = "alb01"
  }
}

# ALB Listener - HTTPS (default)
resource "aws_lb_listener" "alb01_https" {
  load_balancer_arn = aws_lb.alb01.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb01.arn
  }
}

# ALB Listener - HTTP (redirect to HTTPS)
resource "aws_lb_listener" "alb01_http" {
  load_balancer_arn = aws_lb.alb01.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

terraform {
  required_version = ">= 1.4.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "repository_name" {
  description = "Name of the ECR repository"
  type        = string
  default     = "my-ecr-repo"
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository. Must be one of: MUTABLE or IMMUTABLE."
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either 'MUTABLE' or 'IMMUTABLE'."
  }
}

variable "force_delete" {
  description = "If true, will delete the repository even if it contains images."
  type        = bool
  default     = false
}

variable "encryption_type" {
  description = "Encryption type for the repository. Must be one of: AES256 or KMS."
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "KMS"], var.encryption_type)
    error_message = "encryption_type must be either 'AES256' or 'KMS'."
  }
}

variable "tags" {
  description = "A map of tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "repository_policy_principals" {
  description = "List of AWS account IDs or ARNs to grant pull access to the repository."
  type        = list(string)
  default     = []
}

variable "lifecycle_policy_json" {
  description = "JSON string defining the lifecycle policy for the repository."
  type        = string
  default     = null
}

locals {
  kms_alias_name = "alias/ecr/repository/${var.repository_name}"
}

# KMS key for ECR encryption (only when encryption_type == "KMS")
resource "aws_kms_key" "ecr_kms" {
  count = var.encryption_type == "KMS" ? 1 : 0

  description             = "KMS key for ECR repository ${var.repository_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow ECR Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "ecr.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# KMS alias (no tags support)
resource "aws_kms_alias" "ecr_kms" {
  count = var.encryption_type == "KMS" ? 1 : 0

  name          = local.kms_alias_name
  target_key_id = aws_kms_key.ecr_kms[0].key_id
}

# ECR Repository
resource "aws_ecr_repository" "my_ecr_repo" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.force_delete

  encryption_configuration {
    encryption_type = var.encryption_type
    kms_key         = var.encryption_type == "KMS" ? aws_kms_key.ecr_kms[0].arn : null
  }

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.tags
}

# Repository policy (if principals provided)
data "aws_iam_policy_document" "repository_policy" {
  count = length(var.repository_policy_principals) > 0 ? 1 : 0

  statement {
    sid    = "ECRPullAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = var.repository_policy_principals
    }
    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
      "ecr:DescribeRepositories",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages"
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  count = length(var.repository_policy_principals) > 0 ? 1 : 0

  repository = aws_ecr_repository.my_ecr_repo.name
  policy     = data.aws_iam_policy_document.repository_policy[0].json
}

# Lifecycle policy (if provided)
resource "aws_ecr_lifecycle_policy" "this" {
  count = var.lifecycle_policy_json != null ? 1 : 0

  repository = aws_ecr_repository.my_ecr_repo.name
  policy     = var.lifecycle_policy_json
}

# Data source for current account ID (used in KMS key policy)
data "aws_caller_identity" "current" {}

# Outputs
output "repository_arn" {
  description = "The ARN of the ECR repository."
  value       = aws_ecr_repository.my_ecr_repo.arn
}

output "repository_url" {
  description = "The URL of the ECR repository."
  value       = aws_ecr_repository.my_ecr_repo.repository_url
}

output "kms_key_id" {
  description = "The ID of the KMS key used for encryption (only when encryption_type is KMS)."
  value       = var.encryption_type == "KMS" ? aws_kms_key.ecr_kms[0].key_id : null
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption (only when encryption_type is KMS)."
  value       = var.encryption_type == "KMS" ? aws_kms_key.ecr_kms[0].arn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Data source for latest Amazon Linux 2 AMI
data "aws_ami" "amzn2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true

  tags = {
    Name = "taco-team-vpc"
  }
}

# Public subnet (no auto-assign public IP)
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "taco-team-public-subnet"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "taco-team-igw"
  }
}

# Route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "taco-team-public-rt"
  }
}

# Route table association
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Security group for Nginx
resource "aws_security_group" "nginx_sg" {
  name        = "nginx_sg"
  description = "Allow HTTP inbound traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Internal outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "nginx_sg"
  }
}

# Elastic IP for the web server
resource "aws_eip" "nginx" {
  domain = "vpc"

  tags = {
    Name = "nginx-web-server-eip"
  }
}

# EC2 instance
resource "aws_instance" "nginx" {
  ami                    = data.aws_ami.amzn2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.nginx_sg.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 8
    encrypted   = true
  }

  user_data = <<-EOF
    #!/bin/bash
    amazon-linux-extras enable nginx1
    yum install -y nginx
    systemctl start nginx
    systemctl enable nginx
    rm -f /usr/share/nginx/html/index.html
    cat > /usr/share/nginx/html/index.html << 'HTML'
    <html>
    <head>
      <title>Taco Team Server</title>
      <style>
        body {
          background-color: blue;
          color: white;
          text-align: center;
          padding-top: 20%;
        }
      </style>
    </head>
    <body>
      <h1>You did it! Have a 🌮</h1>
    </body>
    </html>
    HTML
  EOF

  tags = {
    Name = "nginx-web-server"
  }
}

# Associate Elastic IP with the instance
resource "aws_eip_association" "nginx" {
  instance_id   = aws_instance.nginx.id
  allocation_id = aws_eip.nginx.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "rds_instances" {
  description = "Map of RDS instance configurations"
  type = map(object({
    instance_class              = string
    identifier                  = string
    allocated_storage           = number
    max_allocated_storage       = optional(number)
    storage_type                = optional(string, "gp2")
    engine                      = string
    engine_version              = string
    license_model               = string
    master_username             = optional(string, "master")
    master_password             = string
    db_name                     = string
    publicly_accessible         = optional(bool, false)
    allow_major_version_upgrade = optional(bool, false)
    auto_minor_version_upgrade  = optional(bool, true)
    copy_tags_to_snapshot       = optional(bool, true)
    multi_az                    = optional(bool, false)
  }))
  default = {}
}

variable "rds_clusters" {
  description = "Map of Aurora cluster configurations"
  type = map(object({
    engine                      = string
    engine_version              = string
    engine_mode                 = string
    cluster_identifier          = string
    cluster_identifier_prefix   = optional(string)
    global_cluster_identifier   = optional(string)
    deletion_protection         = optional(bool, false)
    master_username             = optional(string, "master")
    master_password             = string
    database_name               = string
    availability_zones          = optional(list(string))
    iam_roles                   = optional(list(string), [])
    iops                        = optional(number)
    instance_class              = string
    scaling_configuration = optional(object({
      auto_pause               = optional(bool, true)
      max_capacity             = optional(number, 16)
      min_capacity             = optional(number, 1)
      timeout_action           = optional(string, "ForceApplyCapacityChange")
      seconds_until_auto_pause = optional(number, 300)
    }))
    serverlessv2_scaling_configuration = optional(object({
      max_capacity = optional(number, 64)
      min_capacity = optional(number, 0.5)
    }))
  }))
  default = {}
}

variable "tags" {
  description = "Default tags for all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = data.aws_availability_zones.available.names
  rds_engine_families = distinct([
    for k, v in var.rds_instances : v.engine
  ])
  cluster_engine_families = distinct([
    for k, v in var.rds_clusters : v.engine
  ])
  # Generate two instances per cluster
  cluster_instance_keys = merge([
    for cluster_key, cluster in var.rds_clusters : {
      for idx in range(2) : "${cluster_key}-${idx}" => {
        cluster_key = cluster_key
        index       = idx
      }
    }
  ]...)
}

# Networking
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = var.tags
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(local.azs, count.index)
  tags              = var.tags
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = var.tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = var.tags
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security group
resource "aws_security_group" "rds" {
  vpc_id      = aws_vpc.main.id
  description = "Security group for RDS instances and clusters"
  ingress {
    description = "MySQL"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  ingress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = var.tags
}

# KMS key for RDS encryption
resource "aws_kms_key" "rds" {
  description             = "RDS encryption key"
  deletion_window_in_days = 7
  tags                    = var.tags
}

# Subnet group
resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = aws_subnet.public[*].id
  tags       = var.tags
}

# Parameter groups (one per engine family)
resource "aws_db_parameter_group" "instances" {
  for_each = toset(local.rds_engine_families)
  name     = "${each.value}-parameter-group"
  family   = each.value
  tags     = var.tags
}

resource "aws_rds_cluster_parameter_group" "clusters" {
  for_each = toset(local.cluster_engine_families)
  name     = "${each.value}-cluster-parameter-group"
  family   = each.value
  tags     = var.tags
}

# IAM role for RDS (associated with clusters)
resource "aws_iam_role" "rds" {
  name = "rds-iam-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "rds" {
  name = "rds-iam-policy"
  role = aws_iam_role.rds.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = "*"
      }
    ]
  })
}

# RDS Instances
resource "aws_db_instance" "this" {
  for_each = var.rds_instances

  identifier                = each.value.identifier
  instance_class            = each.value.instance_class
  allocated_storage         = each.value.allocated_storage
  max_allocated_storage     = try(each.value.max_allocated_storage, null)
  storage_type              = each.value.storage_type
  engine                    = each.value.engine
  engine_version            = each.value.engine_version
  license_model             = each.value.license_model
  username                  = each.value.master_username
  password                  = each.value.master_password
  db_name                   = each.value.db_name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  db_subnet_group_name      = aws_db_subnet_group.main.name
  parameter_group_name      = aws_db_parameter_group.instances[each.value.engine].name
  publicly_accessible       = each.value.publicly_accessible
  allow_major_version_upgrade = each.value.allow_major_version_upgrade
  auto_minor_version_upgrade  = each.value.auto_minor_version_upgrade
  copy_tags_to_snapshot       = each.value.copy_tags_to_snapshot
  multi_az                    = each.value.multi_az
  storage_encrypted           = true
  kms_key_id                  = aws_kms_key.rds.arn
  skip_final_snapshot         = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Aurora Clusters
resource "aws_rds_cluster" "this" {
  for_each = var.rds_clusters

  cluster_identifier          = each.value.cluster_identifier
  cluster_identifier_prefix   = try(each.value.cluster_identifier_prefix, null)
  global_cluster_identifier   = try(each.value.global_cluster_identifier, null)
  engine                      = each.value.engine
  engine_version              = each.value.engine_version
  engine_mode                 = each.value.engine_mode
  master_username             = each.value.master_username
  master_password             = each.value.master_password
  database_name               = each.value.database_name
  availability_zones          = each.value.availability_zones != null ? each.value.availability_zones : local.azs
  vpc_security_group_ids      = [aws_security_group.rds.id]
  db_subnet_group_name        = aws_db_subnet_group.main.name
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.clusters[each.value.engine].name
  deletion_protection         = each.value.deletion_protection
  storage_encrypted           = true
  kms_key_id                  = aws_kms_key.rds.arn
  iam_roles                   = [aws_iam_role.rds.arn]
  iops                        = try(each.value.iops, null)

  dynamic "scaling_configuration" {
    for_each = each.value.engine_mode == "serverless" ? [1] : []
    content {
      auto_pause               = try(each.value.scaling_configuration.auto_pause, true)
      max_capacity             = try(each.value.scaling_configuration.max_capacity, 16)
      min_capacity             = try(each.value.scaling_configuration.min_capacity, 1)
      timeout_action           = try(each.value.scaling_configuration.timeout_action, "ForceApplyCapacityChange")
      seconds_until_auto_pause = try(each.value.scaling_configuration.seconds_until_auto_pause, 300)
    }
  }

  dynamic "serverlessv2_scaling_configuration" {
    for_each = each.value.engine_mode == "serverlessv2" ? [1] : []
    content {
      max_capacity = try(each.value.serverlessv2_scaling_configuration.max_capacity, 64)
      min_capacity = try(each.value.serverlessv2_scaling_configuration.min_capacity, 0.5)
    }
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Cluster instances – two per cluster
resource "aws_rds_cluster_instance" "this" {
  for_each = local.cluster_instance_keys

  cluster_identifier = aws_rds_cluster.this[each.value.cluster_key].id
  identifier         = "${var.rds_clusters[each.value.cluster_key].cluster_identifier}-instance-${each.value.index}"
  instance_class     = var.rds_clusters[each.value.cluster_key].instance_class
  engine             = aws_rds_cluster.this[each.value.cluster_key].engine
  engine_version     = aws_rds_cluster.this[each.value.cluster_key].engine_version

  tags = var.tags
}

# Outputs
output "rds_instances_info" {
  description = "Information about all RDS instances"
  value = {
    for k, rds in aws_db_instance.this : k => {
      identifier = rds.identifier
      engine     = rds.engine
      version    = rds.engine_version
      username   = rds.username
      db_name    = rds.db_name
      multi_az   = rds.multi_az
      endpoint   = rds.endpoint
    }
  }
}

output "rds_clusters_info" {
  description = "Information about all Aurora clusters"
  value = {
    for k, cluster in aws_rds_cluster.this : k => {
      identifier = cluster.cluster_identifier
      engine     = cluster.engine
      version    = cluster.engine_version
      username   = cluster.master_username
      db_name    = cluster.database_name
      availability_zones = cluster.availability_zones
      endpoint   = cluster.endpoint
    }
  }
}

output "tags" {
  description = "Default tags used for all resources"
  value       = var.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_pet" "bucket_name" {
  prefix = "hello-world-lambda"
  length = 2
}

resource "aws_kms_key" "lambda_code_bucket_key" {
  description             = "CMK for S3 bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "lambda_code" {
  bucket = random_pet.bucket_name.id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.lambda_code]
}

resource "aws_s3_bucket_public_access_block" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.lambda_code_bucket_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code.id

  versioning_configuration {
    status = "Enabled"
  }
}

output "lambda_code_bucket_id" {
  value = aws_s3_bucket.lambda_code.id
}

terraform {
  required_providers {
    null = {
      source  = "hashicorp/null"
      version = "3.1.1"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "null_resource" "write_file" {
  provisioner "local-exec" {
    command = "echo 'foo' > file.txt"
  }
}

resource "time_sleep" "delay" {
  depends_on = [null_resource.write_file]

  create_duration = "20s"
  destroy_duration = "10s"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "demo-dataflow"
    Project     = "demo"
    Environment = "poc"
  }
}

resource "aws_internet_gateway" "demogwInternet" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demogwInternet"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index * 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "demoPublicSubnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demoPublicRouteTable"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.demogwInternet.id
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "bastion" {
  name_prefix = "bastion-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from internal network"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.bastion_ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "demo-bastion-sg"
    Project     = "demo"
    Environment = "poc"
  }
}

resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "kplinuxdemo" {
  key_name   = "kplinuxdemo"
  public_key = tls_private_key.bastion.public_key_openssh
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_instance" "bastion" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.nano"
  key_name      = aws_key_pair.kplinuxdemo.key_name
  subnet_id     = aws_subnet.public[0].id
  vpc_security_group_ids = [aws_security_group.bastion.id]

  associate_public_ip_address = true

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
  }

  tags = {
    Name        = "demo-bastion"
    Project     = "demo"
    Environment = "poc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

variable "bastion_ssh_cidr" {
  description = "CIDR block allowed to SSH into the bastion host"
  type        = string
  default     = "10.0.0.0/8"
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

terraform {
  required_version = ">= 0.12"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "drs_agent" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "drs_failback" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "drs_conversion_server" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "drs_recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "drs_replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

# Role: AWSElasticDisasterRecoveryAgentRole
resource "aws_iam_role" "agent" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringLike = {
            "aws:SourceIdentity" = "s-*"
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = data.aws_iam_policy.drs_agent.arn
}

# Role: AWSElasticDisasterRecoveryFailbackRole
resource "aws_iam_role" "failback" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringLike = {
            "aws:SourceIdentity" = "i-*"
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = data.aws_iam_policy.drs_failback.arn
}

# Role: AWSElasticDisasterRecoveryConversionServerRole
resource "aws_iam_role" "conversion_server" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = data.aws_iam_policy.drs_conversion_server.arn
}

# Role: AWSElasticDisasterRecoveryRecoveryInstanceRole
resource "aws_iam_role" "recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "recovery_instance" {
  role       = aws_iam_role.recovery_instance.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance.arn
}

# Role: AWSElasticDisasterRecoveryReplicationServerRole
resource "aws_iam_role" "replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = data.aws_iam_policy.drs_replication_server.arn
}

# Role: AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole
resource "aws_iam_role" "recovery_instance_with_launch" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_drs" {
  role       = aws_iam_role.recovery_instance_with_launch.name
  policy_arn = data.aws_iam_policy.drs_recovery_instance.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_ssm" {
  role       = aws_iam_role.recovery_instance_with_launch.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

# Role: AWSElasticDisasterRecoveryInitializerRole
resource "aws_iam_role" "initializer" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Inline policy for initializer role
resource "aws_iam_role_policy" "initializer" {
  name = "InitializePolicy"
  role = aws_iam_role.initializer.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:AttachRolePolicy",
          "iam:PassRole",
          "iam:CreateRole",
          "iam:DeleteRole",
          "iam:GetRole",
          "iam:ListRoles",
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:CreateInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:RemoveRoleFromInstanceProfile",
          "iam:DeleteInstanceProfile",
          "iam:GetPolicy"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "drs:InitializeService",
          "drs:Create*",
          "drs:Update*",
          "drs:Start*",
          "drs:Describe*",
          "drs:List*",
          "drs:Get*",
          "drs:TagResource",
          "drs:UntagResource"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "sts:DecodeAuthorizationMessage"
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    github = {
      source  = "integrations/github"
      version = "~> 5.3"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "github_token" {
  description = "GitHub personal access token or OAuth token with org admin permissions"
  type        = string
  sensitive   = true
  default     = "ghp_testtoken1234567890abcdef"
}

variable "create_organization_resources" {
  description = "Whether to create organization-level resources (settings, teams, etc.). Set to false for testing environments that don't support organizations."
  type        = bool
  default     = false
}

variable "create_team" {
  description = "Whether to create the all-members team. Set to false for testing environments."
  type        = bool
  default     = false
}

variable "github_organization" {
  description = "Name of the GitHub organization to manage"
  type        = string
  default     = "test-org"
}

variable "admin_members" {
  description = "List of GitHub usernames to be added as organization admins"
  type        = list(string)
  default     = []
}

variable "members" {
  description = "List of GitHub usernames to be added as organization members"
  type        = list(string)
  default     = []
}

variable "blocked_users" {
  description = "List of GitHub usernames to block from the organization"
  type        = list(string)
  default     = []
}

variable "team_name" {
  description = "Name of the team that automatically includes all members"
  type        = string
  default     = "all"
}

variable "team_visibility" {
  description = "Visibility of the all-members team (secret or closed)"
  type        = string
  default     = "secret"
}

variable "organization_settings" {
  description = "Map of organization settings"
  type = object({
    billing_email                                          = optional(string, "hello@mineiros.io")
    company                                                = optional(string, "")
    blog                                                   = optional(string, "")
    email                                                  = optional(string, "")
    twitter_username                                       = optional(string, "")
    location                                               = optional(string, "")
    has_organization_projects                              = optional(bool, true)
    has_repository_projects                                = optional(bool, true)
    default_repository_permission                          = optional(string, "read")
    members_can_create_repositories                        = optional(bool, true)
    members_can_create_public_pages                        = optional(bool, true)
    members_can_create_private_pages                       = optional(bool, true)
    web_commit_signoff_required                            = optional(bool, false)
    advanced_security_enabled_for_new_repositories          = optional(bool, false)
    dependabot_alerts_enabled_for_new_repositories          = optional(bool, false)
    dependabot_security_updates_enabled_for_new_repositories = optional(bool, false)
    dependency_graph_enabled_for_new_repositories           = optional(bool, false)
    secret_scanning_enabled_for_new_repositories            = optional(bool, false)
    secret_scanning_push_protection_enabled_for_new_repositories = optional(bool, false)
  })
  default = {}
}

variable "projects" {
  description = "Map of organization projects, keyed by a unique identifier"
  type = map(object({
    name = string
    body = optional(string)
  }))
  default = {}
}

variable "validate_users" {
  description = "Whether to validate that all provided usernames exist via GitHub API before creating resources"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# PROVIDER
# ------------------------------------------------------------------------------

provider "github" {
  owner = var.github_organization
  token = var.github_token
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  all_usernames     = distinct(concat(var.admin_members, var.members, var.blocked_users))
  users_to_validate = var.validate_users ? local.all_usernames : []
  all_team_members  = distinct(concat(var.admin_members, var.members))
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------

data "github_user" "existing" {
  for_each = toset(local.users_to_validate)
  username = each.value
}

# ------------------------------------------------------------------------------
# ORGANIZATION SETTINGS
# ------------------------------------------------------------------------------

resource "github_organization_settings" "this" {
  count = var.create_organization_resources ? 1 : 0

  billing_email                                          = var.organization_settings.billing_email
  company                                                = var.organization_settings.company
  blog                                                   = var.organization_settings.blog
  email                                                  = var.organization_settings.email
  twitter_username                                       = var.organization_settings.twitter_username
  location                                               = var.organization_settings.location
  has_organization_projects                              = var.organization_settings.has_organization_projects
  has_repository_projects                                = var.organization_settings.has_repository_projects
  default_repository_permission                          = var.organization_settings.default_repository_permission
  members_can_create_repositories                        = var.organization_settings.members_can_create_repositories
  members_can_create_public_pages                        = var.organization_settings.members_can_create_public_pages
  members_can_create_private_pages                       = var.organization_settings.members_can_create_private_pages
  web_commit_signoff_required                            = var.organization_settings.web_commit_signoff_required
  advanced_security_enabled_for_new_repositories          = var.organization_settings.advanced_security_enabled_for_new_repositories
  dependabot_alerts_enabled_for_new_repositories          = var.organization_settings.dependabot_alerts_enabled_for_new_repositories
  dependabot_security_updates_enabled_for_new_repositories = var.organization_settings.dependabot_security_updates_enabled_for_new_repositories
  dependency_graph_enabled_for_new_repositories           = var.organization_settings.dependency_graph_enabled_for_new_repositories
  secret_scanning_enabled_for_new_repositories            = var.organization_settings.secret_scanning_enabled_for_new_repositories
  secret_scanning_push_protection_enabled_for_new_repositories = var.organization_settings.secret_scanning_push_protection_enabled_for_new_repositories

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# MEMBERSHIPS (ADMIN)
# ------------------------------------------------------------------------------

resource "github_membership" "admin" {
  for_each = toset(var.admin_members)
  username = each.value
  role     = "admin"

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# MEMBERSHIPS (MEMBER)
# ------------------------------------------------------------------------------

resource "github_membership" "member" {
  for_each = toset(var.members)
  username = each.value
  role     = "member"

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# BLOCKED USERS
# ------------------------------------------------------------------------------

resource "github_organization_block" "blocked" {
  for_each = toset(var.blocked_users)
  username = each.value

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# ORGANIZATION PROJECTS
# ------------------------------------------------------------------------------

resource "github_organization_project" "project" {
  for_each = var.projects
  name     = each.value.name
  body     = each.value.body

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# ALL-MEMBERS TEAM
# ------------------------------------------------------------------------------

resource "github_team" "all" {
  count = var.create_team ? 1 : 0

  name        = var.team_name
  privacy     = var.team_visibility
  description = "Team automatically including all members"

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# ALL-MEMBERS TEAM MEMBERS (conditional creation)
# ------------------------------------------------------------------------------

resource "github_team_members" "all" {
  count   = var.create_team && length(local.all_team_members) > 0 ? 1 : 0
  team_id = try(github_team.all[0].id, null)
  dynamic "members" {
    for_each = toset(local.all_team_members)
    content {
      username = members.value
      role     = "member"
    }
  }
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------

output "organization" {
  description = "Organization settings applied"
  value       = try(github_organization_settings.this[0], null)
}

output "blocked_users" {
  description = "Blocked users resources"
  value       = github_organization_block.blocked
}

output "memberships" {
  description = "All memberships keyed by username"
  value = merge(
    { for u, r in github_membership.admin : u => r },
    { for u, r in github_membership.member : u => r }
  )
}

output "projects" {
  description = "Organization projects keyed by the map key (custom ID)"
  value       = github_organization_project.project
}

output "all_members_team" {
  description = "The all-members team resource"
  value       = try(github_team.all[0], null)
}

output "all_members_team_members" {
  description = "Team members of the all-members team"
  value       = try(github_team_members.all[0], null)
}

output "validated_users" {
  description = "Node IDs of validated users (optional check)"
  value       = try({ for k, v in data.github_user.existing : k => v.node_id }, {})
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "prefix_name" {
  description = "Prefix for naming resources"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "domain_names" {
  description = "List of domain names to verify"
  type        = list(string)
  default     = []
}

variable "email_addresses" {
  description = "List of email addresses to verify"
  type        = list(string)
  default     = []
}

variable "template_config" {
  description = "Configuration for SES template"
  type = object({
    name    = string
    subject = string
    html    = string
    text    = string
  })
  default = {
    name    = "default-template"
    subject = "Subject"
    html    = "<html><body>Hello</body></html>"
    text    = "Hello"
  }
  validation {
    condition = length(var.template_config.name) > 0 && length(var.template_config.subject) > 0 && (
      length(var.template_config.html) + length(var.template_config.text) <= 512000
    )
    error_message = "Template subject and body must not exceed 500KB total."
  }
}

variable "receipt_rule_set_name" {
  description = "Name of the receipt rule set"
  type        = string
  default     = "default-rule-set"
}

variable "receipt_rule_config" {
  description = "Configuration for the receipt rule"
  type = object({
    name          = string
    enabled       = bool
    scan_enabled  = bool
    recipients    = optional(list(string), [])
    after         = optional(string)
    tls_policy    = optional(string, "Optional")
    actions = list(object({
      position = number
      type     = string
      add_header_action = optional(object({
        header_name  = string
        header_value = string
      }))
      bounce_action = optional(object({
        message = string
        sender  = string
        smtp_reply_code = string
        status_code     = optional(string)
      }))
      lambda_action = optional(object({
        function_arn = string
        invocation_type = optional(string, "Event")
        topic_arn       = optional(string)
      }))
      s3_action = optional(object({
        bucket_name       = string
        object_key_prefix = optional(string)
        kms_key_arn       = optional(string)
        topic_arn         = optional(string)
      }))
      sns_action = optional(object({
        topic_arn = string
        encoding  = optional(string, "UTF-8")
      }))
      stop_action = optional(object({
        scope = string
        topic_arn = optional(string)
      }))
      workmail_action = optional(object({
        organization_arn = string
        topic_arn        = optional(string)
      }))
    }))
  })
  default = {
    name         = "catch-all"
    enabled      = true
    scan_enabled = true
    recipients   = []
    after        = null
    tls_policy   = "Optional"
    actions = [
      {
        position = 1
        type     = "s3"
        s3_action = {
          bucket_name = "ses-inbound"
        }
      }
    ]
  }
  validation {
    condition = alltrue([
      for a in var.receipt_rule_config.actions : a.position >= 1
    ])
    error_message = "Each action position must be at least 1."
  }
}

variable "receipt_filters" {
  description = "List of IP-based receipt filters"
  type = list(object({
    name   = string
    cidr   = string
    policy = string
  }))
  default = []
}

variable "configuration_set_config" {
  description = "Configuration for SES configuration set"
  type = object({
    name               = string
    reputation_metrics = optional(bool, false)
    sending_enabled    = optional(bool, true)
    tls_policy         = optional(string, "Optional")
  })
  default = {
    name = "default-config-set"
  }
}

variable "event_destination_config" {
  description = "Configuration for event destination"
  type = object({
    name        = string
    event_types = list(string)
    cloudwatch_destination = optional(object({
      default_value = string
      dimension_name = string
      value_source   = string
    }))
    kinesis_destination = optional(object({
      stream_arn = string
      role_arn   = string
    }))
    sns_destination = optional(object({
      topic_arn = string
    }))
  })
  default = null
}

variable "mail_from_domain" {
  description = "Custom MAIL FROM domain (without domain name, e.g., 'bounce')"
  type        = string
  default     = null
}

variable "mail_from_behavior_on_mx_failure" {
  description = "Behavior on MX failure for MAIL FROM domain"
  type        = string
  default     = "UseDefaultValue"
  validation {
    condition = contains(["UseDefaultValue", "RejectMessage"], var.mail_from_behavior_on_mx_failure)
    error_message = "Valid values: UseDefaultValue, RejectMessage"
  }
}

variable "identity_policies" {
  description = "List of policies to attach to identities"
  type = list(object({
    identity_type = string
    identity_name = string
    policy_name   = string
    policy_document = string
  }))
  default = []
}

variable "identity_notification_topics" {
  description = "List of notification topics for identities"
  type = list(object({
    identity_type = string
    identity_name = string
    notification_type = string
    sns_topic_arn = string
    include_original_headers = optional(bool, false)
  }))
  default = []
}

variable "lambda_function_config" {
  description = "Configuration for Lambda function used in receipt rule"
  type = object({
    filename = optional(string, "lambda.zip")
    function_name = string
    handler       = string
    runtime       = string
    source_code_hash = optional(string)
    environment_variables = optional(map(string), {})
  })
  default = null
}

# Local values
locals {
  name_prefix = "${var.prefix_name}-${var.environment}"

  has_s3_action = anytrue([
    for a in var.receipt_rule_config.actions : a.type == "s3"
  ])
  has_lambda_action = anytrue([
    for a in var.receipt_rule_config.actions : a.type == "lambda"
  ])
}

# SES Domain Identity
resource "aws_ses_domain_identity" "domain" {
  for_each = toset(var.domain_names)
  domain   = each.key
}

# SES Email Identity
resource "aws_ses_email_identity" "email" {
  for_each = toset(var.email_addresses)
  email    = each.key
}

# SES Template
resource "aws_ses_template" "main" {
  name    = "${local.name_prefix}-${var.template_config.name}"
  subject = var.template_config.subject
  html    = var.template_config.html
  text    = var.template_config.text
}

# SES Receipt Rule Set
resource "aws_ses_receipt_rule_set" "main" {
  rule_set_name = "${local.name_prefix}-${var.receipt_rule_set_name}"
}

# SES Active Receipt Rule Set
resource "aws_ses_active_receipt_rule_set" "main" {
  rule_set_name = aws_ses_receipt_rule_set.main.rule_set_name
}

# SES Receipt Rule
resource "aws_ses_receipt_rule" "main" {
  name          = "${local.name_prefix}-${var.receipt_rule_config.name}"
  rule_set_name = aws_ses_receipt_rule_set.main.rule_set_name
  recipients    = var.receipt_rule_config.recipients
  enabled       = var.receipt_rule_config.enabled
  scan_enabled  = var.receipt_rule_config.scan_enabled
  after         = var.receipt_rule_config.after
  tls_policy    = var.receipt_rule_config.tls_policy

  dynamic "add_header_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "add_header" && a.add_header_action != null
    ]
    content {
      header_name  = add_header_action.value.add_header_action.header_name
      header_value = add_header_action.value.add_header_action.header_value
      position     = add_header_action.value.position
    }
  }

  dynamic "bounce_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "bounce" && a.bounce_action != null
    ]
    content {
      message         = bounce_action.value.bounce_action.message
      sender          = bounce_action.value.bounce_action.sender
      smtp_reply_code = bounce_action.value.bounce_action.smtp_reply_code
      status_code     = bounce_action.value.bounce_action.status_code
      position        = bounce_action.value.position
      topic_arn       = bounce_action.value.bounce_action.topic_arn
    }
  }

  dynamic "lambda_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "lambda" && a.lambda_action != null
    ]
    content {
      function_arn    = lambda_action.value.lambda_action.function_arn
      invocation_type = lambda_action.value.lambda_action.invocation_type
      position        = lambda_action.value.position
      topic_arn       = lambda_action.value.lambda_action.topic_arn
    }
  }

  dynamic "s3_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "s3" && a.s3_action != null
    ]
    content {
      bucket_name       = s3_action.value.s3_action.bucket_name
      object_key_prefix = s3_action.value.s3_action.object_key_prefix
      kms_key_arn       = s3_action.value.s3_action.kms_key_arn
      topic_arn         = s3_action.value.s3_action.topic_arn
      position          = s3_action.value.position
    }
  }

  dynamic "sns_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "sns" && a.sns_action != null
    ]
    content {
      topic_arn = sns_action.value.sns_action.topic_arn
      encoding  = sns_action.value.sns_action.encoding
      position  = sns_action.value.position
    }
  }

  dynamic "stop_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "stop" && a.stop_action != null
    ]
    content {
      scope     = stop_action.value.stop_action.scope
      position  = stop_action.value.position
      topic_arn = stop_action.value.stop_action.topic_arn
    }
  }

  dynamic "workmail_action" {
    for_each = [
      for a in var.receipt_rule_config.actions : a if a.type == "workmail" && a.workmail_action != null
    ]
    content {
      organization_arn = workmail_action.value.workmail_action.organization_arn
      position         = workmail_action.value.position
      topic_arn        = workmail_action.value.workmail_action.topic_arn
    }
  }
}

# SES Receipt Filters
resource "aws_ses_receipt_filter" "filter" {
  for_each = { for idx, f in var.receipt_filters : idx => f }
  name   = "${local.name_prefix}-${each.value.name}"
  cidr   = each.value.cidr
  policy = each.value.policy
}

# SES Configuration Set
resource "aws_ses_configuration_set" "main" {
  name = "${local.name_prefix}-${var.configuration_set_config.name}"

  reputation_metrics_enabled = var.configuration_set_config.reputation_metrics
  sending_enabled            = var.configuration_set_config.sending_enabled
}

# SES Event Destination
resource "aws_ses_event_destination" "main" {
  count = var.event_destination_config != null ? 1 : 0

  name                   = "${local.name_prefix}-${var.event_destination_config.name}"
  configuration_set_name = aws_ses_configuration_set.main.name
  matching_types         = var.event_destination_config.event_types

  dynamic "cloudwatch_destination" {
    for_each = var.event_destination_config.cloudwatch_destination != null ? [var.event_destination_config.cloudwatch_destination] : []
    content {
      default_value  = cloudwatch_destination.value.default_value
      dimension_name = cloudwatch_destination.value.dimension_name
      value_source   = cloudwatch_destination.value.value_source
    }
  }

  dynamic "kinesis_destination" {
    for_each = var.event_destination_config.kinesis_destination != null ? [var.event_destination_config.kinesis_destination] : []
    content {
      stream_arn = kinesis_destination.value.stream_arn
      role_arn   = kinesis_destination.value.role_arn
    }
  }

  dynamic "sns_destination" {
    for_each = var.event_destination_config.sns_destination != null ? [var.event_destination_config.sns_destination] : []
    content {
      topic_arn = sns_destination.value.topic_arn
    }
  }
}

# SES Domain DKIM
resource "aws_ses_domain_dkim" "dkim" {
  for_each = toset(var.domain_names)
  domain   = aws_ses_domain_identity.domain[each.key].domain
}

# SES Domain Identity Verification
resource "aws_ses_domain_identity_verification" "verification" {
  for_each = toset(var.domain_names)
  domain   = aws_ses_domain_identity.domain[each.key].id

  depends_on = [aws_ses_domain_dkim.dkim]
}

# SES MAIL FROM Domain
resource "aws_ses_domain_mail_from" "mail_from" {
  for_each = toset(var.domain_names)
  domain           = aws_ses_domain_identity.domain[each.key].domain
  mail_from_domain = "${var.mail_from_domain != null ? var.mail_from_domain : "bounce"}.${each.key}"
  behavior_on_mx_failure = var.mail_from_behavior_on_mx_failure
}

# SES Identity Policies
resource "aws_ses_identity_policy" "policy" {
  for_each = { for idx, p in var.identity_policies : idx => p }

  identity = each.value.identity_type == "domain" ? aws_ses_domain_identity.domain[each.value.identity_name].arn : (
    each.value.identity_type == "email" ? aws_ses_email_identity.email[each.value.identity_name].arn : ""
  )
  name   = "${local.name_prefix}-${each.value.policy_name}"
  policy = each.value.policy_document
}

# SES Identity Notification Topics
resource "aws_ses_identity_notification_topic" "notification" {
  for_each = { for idx, n in var.identity_notification_topics : idx => n }

  identity = each.value.identity_type == "domain" ? aws_ses_domain_identity.domain[each.value.identity_name].arn : (
    each.value.identity_type == "email" ? aws_ses_email_identity.email[each.value.identity_name].arn : ""
  )
  notification_type          = each.value.notification_type
  topic_arn                  = each.value.sns_topic_arn
  include_original_headers   = each.value.include_original_headers
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "ses" {
  count               = local.has_s3_action ? 1 : 0
  description         = "KMS key for SES inbound email S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

# S3 Bucket for SES Receipt Rule (if needed)
resource "aws_s3_bucket" "ses_bucket" {
  count = local.has_s3_action ? 1 : 0
  bucket = var.receipt_rule_config.actions[0].s3_action.bucket_name
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "ses_bucket" {
  count = local.has_s3_action ? 1 : 0
  bucket = aws_s3_bucket.ses_bucket[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "ses_bucket" {
  count  = local.has_s3_action ? 1 : 0
  bucket = aws_s3_bucket.ses_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.ses[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "ses_bucket" {
  count = local.has_s3_action ? 1 : 0
  bucket = aws_s3_bucket.ses_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# Lambda Function (if needed)
resource "aws_iam_role" "lambda_exec" {
  count = local.has_lambda_action ? 1 : 0
  name = "${local.name_prefix}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_exec" {
  count = local.has_lambda_action ? 1 : 0
  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "ses_lambda" {
  count = local.has_lambda_action ? 1 : 0
  function_name = "${local.name_prefix}-${var.lambda_function_config.function_name}"
  filename      = var.lambda_function_config.filename
  handler       = var.lambda_function_config.handler
  runtime       = var.lambda_function_config.runtime
  role          = aws_iam_role.lambda_exec[0].arn
  source_code_hash = var.lambda_function_config.source_code_hash
  environment {
    variables = var.lambda_function_config.environment_variables
  }
}

# Outputs
output "domain_identity_arns" {
  value = { for d in var.domain_names : d => aws_ses_domain_identity.domain[d].arn }
}

output "domain_identity_verification_tokens" {
  value = { for d in var.domain_names : d => aws_ses_domain_identity_verification.verification[d].id }
}

output "domain_dkim_tokens" {
  value = { for d in var.domain_names : d => aws_ses_domain_dkim.dkim[d].dkim_tokens }
}

output "email_identity_arns" {
  value = { for e in var.email_addresses : e => aws_ses_email_identity.email[e].arn }
}

output "template_arn" {
  value = aws_ses_template.main.arn
}

output "receipt_rule_set_name" {
  value = aws_ses_receipt_rule_set.main.rule_set_name
}

output "active_receipt_rule_set_name" {
  value = aws_ses_active_receipt_rule_set.main.rule_set_name
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Variables
variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "enable_global_settings" {
  description = "Enable AWS Backup global settings"
  type        = bool
  default     = false
}

variable "enable_region_settings" {
  description = "Enable AWS Backup region settings"
  type        = bool
  default     = false
}

variable "enable_backup_vault" {
  description = "Enable AWS Backup vault creation"
  type        = bool
  default     = false
}

variable "enable_vault_encryption" {
  description = "Enable KMS encryption for the backup vault"
  type        = bool
  default     = false
}

variable "vault_name_override" {
  description = "Override the default name of the backup vault"
  type        = string
  default     = ""
}

variable "enable_backup_plan" {
  description = "Enable AWS Backup plan creation"
  type        = bool
  default     = false
}

variable "plan_name_override" {
  description = "Override the default name of the backup plan"
  type        = string
  default     = ""
}

variable "backup_plan_rules" {
  description = "List of rule objects for the backup plan"
  type = list(object({
    rule_name           = string
    target_vault_name   = string
    schedule            = optional(string)
    start_window        = optional(number)
    completion_window   = optional(number)
    lifecycle = optional(object({
      cold_storage_after = optional(number)
      delete_after       = optional(number)
    }))
    copy_action = optional(object({
      destination_vault_arn = string
      lifecycle = optional(object({
        cold_storage_after = optional(number)
        delete_after       = optional(number)
      }))
    }))
  }))
  default = []
}

variable "enable_backup_selection" {
  description = "Enable AWS Backup selection creation"
  type        = bool
  default     = false
}

variable "selection_name_override" {
  description = "Override the default name of the backup selection"
  type        = string
  default     = ""
}

variable "backup_selection_config" {
  description = "Configuration for the backup selection"
  type = object({
    plan_id         = optional(string)
    resources       = list(string)
    selection_tags = optional(list(object({
      type  = string
      key   = string
      value = string
    })), [])
  })
  default = {
    plan_id   = null
    resources = []
    selection_tags = []
  }
}

variable "enable_backup_vault_policy" {
  description = "Enable AWS Backup vault policy"
  type        = bool
  default     = false
}

variable "backup_vault_policy_json" {
  description = "JSON policy document for the backup vault"
  type        = string
  default     = ""
}

variable "enable_backup_vault_notifications" {
  description = "Enable AWS Backup vault notifications via SNS"
  type        = bool
  default     = false
}

variable "sns_topic_name_override" {
  description = "Override the default name of the SNS topic for notifications"
  type        = string
  default     = ""
}

# Data sources (static metadata)
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# Locals for naming
locals {
  default_vault_name = "${lower(var.name_prefix)}-${lower(var.environment)}-backup-vault"
  vault_name         = var.vault_name_override != "" ? var.vault_name_override : local.default_vault_name

  default_plan_name = "${lower(var.name_prefix)}-${lower(var.environment)}-backup-plan"
  plan_name         = var.plan_name_override != "" ? var.plan_name_override : local.default_plan_name

  default_selection_name = "${lower(var.name_prefix)}-${lower(var.environment)}-backup-selection"
  selection_name         = var.selection_name_override != "" ? var.selection_name_override : local.default_selection_name

  default_sns_topic_name = "${lower(var.name_prefix)}-${lower(var.environment)}-backup-notifications"
  sns_topic_name         = var.sns_topic_name_override != "" ? var.sns_topic_name_override : local.default_sns_topic_name

  kms_key_alias = "alias/${lower(var.name_prefix)}-${lower(var.environment)}-backup-key"
}

# Global Settings
resource "aws_backup_global_settings" "main" {
  count = var.enable_global_settings ? 1 : 0

  global_settings = {
    "crossAccountBackupEnabled" = "true"
  }
}

# Region Settings
resource "aws_backup_region_settings" "main" {
  count = var.enable_region_settings ? 1 : 0

  resource_type_opt_in_preference = {
    "Aurora"          = true
    "DynamoDB"        = true
    "EBS"             = true
    "EC2"             = true
    "EFS"             = true
    "FSx"             = true
    "RDS"             = true
    "Storage Gateway" = true
  }
}

# KMS Key (if vault encryption enabled)
resource "aws_kms_key" "main" {
  count = var.enable_backup_vault && var.enable_vault_encryption ? 1 : 0

  description             = "KMS key for AWS Backup vault ${local.vault_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Backup Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "backup.${data.aws_region.current.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  count = var.enable_backup_vault && var.enable_vault_encryption ? 1 : 0

  name          = local.kms_key_alias
  target_key_id = aws_kms_key.main[0].key_id
}

# Backup Vault
resource "aws_backup_vault" "main" {
  count = var.enable_backup_vault ? 1 : 0

  name        = local.vault_name
  kms_key_arn = var.enable_vault_encryption ? aws_kms_key.main[0].arn : null

  lifecycle {
    create_before_destroy = true
  }
}

# Backup Plan
resource "aws_backup_plan" "main" {
  count = var.enable_backup_plan ? 1 : 0

  name = local.plan_name

  dynamic "rule" {
    for_each = var.backup_plan_rules
    content {
      rule_name         = rule.value.rule_name
      target_vault_name = rule.value.target_vault_name
      schedule          = rule.value.schedule
      start_window      = rule.value.start_window
      completion_window = rule.value.completion_window

      dynamic "lifecycle" {
        for_each = rule.value.lifecycle != null ? [rule.value.lifecycle] : []
        content {
          cold_storage_after = lifecycle.value.cold_storage_after
          delete_after       = lifecycle.value.delete_after
        }
      }

      dynamic "copy_action" {
        for_each = rule.value.copy_action != null ? [rule.value.copy_action] : []
        content {
          destination_vault_arn = copy_action.value.destination_vault_arn
          dynamic "lifecycle" {
            for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
            content {
              cold_storage_after = lifecycle.value.cold_storage_after
              delete_after       = lifecycle.value.delete_after
            }
          }
        }
      }
    }
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_backup_vault.main
  ]
}

# IAM Role for Backup Selection
resource "aws_iam_role" "backup" {
  count = var.enable_backup_selection ? 1 : 0

  name = "${local.selection_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "backup.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = var.enable_backup_selection ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup Selection
resource "aws_backup_selection" "main" {
  count = var.enable_backup_selection ? 1 : 0

  name         = local.selection_name
  plan_id      = var.backup_selection_config.plan_id != null ? var.backup_selection_config.plan_id : aws_backup_plan.main[0].id
  resources    = var.backup_selection_config.resources
  iam_role_arn = aws_iam_role.backup[0].arn

  dynamic "selection_tag" {
    for_each = var.backup_selection_config.selection_tags
    content {
      type  = selection_tag.value.type
      key   = selection_tag.value.key
      value = selection_tag.value.value
    }
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_backup_plan.main,
    aws_iam_role.backup,
    aws_iam_role_policy_attachment.backup
  ]
}

# Backup Vault Policy
resource "aws_backup_vault_policy" "main" {
  count = var.enable_backup_vault_policy ? 1 : 0

  backup_vault_name = aws_backup_vault.main[0].name
  policy            = var.backup_vault_policy_json

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_backup_vault.main
  ]
}

# SNS Topic for vault notifications
resource "aws_sns_topic" "main" {
  count = var.enable_backup_vault_notifications ? 1 : 0

  name = local.sns_topic_name

  lifecycle {
    create_before_destroy = true
  }
}

# Backup Vault Notifications
resource "aws_backup_vault_notifications" "main" {
  count = var.enable_backup_vault_notifications ? 1 : 0

  backup_vault_events = ["BACKUP_JOB_STARTED", "RESTORE_JOB_COMPLETED"]
  backup_vault_name   = aws_backup_vault.main[0].name
  sns_topic_arn       = aws_sns_topic.main[0].arn

  depends_on = [
    aws_backup_vault.main,
    aws_sns_topic.main
  ]
}

# Outputs
output "backup_plan_id" {
  value = var.enable_backup_plan ? aws_backup_plan.main[0].id : null
}

output "backup_plan_arn" {
  value = var.enable_backup_plan ? aws_backup_plan.main[0].arn : null
}

output "backup_plan_version" {
  value = var.enable_backup_plan ? aws_backup_plan.main[0].version : null
}

output "backup_selection_id" {
  value = var.enable_backup_selection ? aws_backup_selection.main[0].id : null
}

output "global_settings_account_id" {
  value = var.enable_global_settings ? aws_backup_global_settings.main[0].id : null
}

output "region_settings_account_id" {
  value = var.enable_region_settings ? aws_backup_region_settings.main[0].id : null
}

output "vault_id" {
  value = var.enable_backup_vault ? aws_backup_vault.main[0].id : null
}

output "vault_arn" {
  value = var.enable_backup_vault ? aws_backup_vault.main[0].arn : null
}

output "vault_recovery_points" {
  value = var.enable_backup_vault ? aws_backup_vault.main[0].recovery_points : null
}

output "vault_policy_id" {
  value = var.enable_backup_vault_policy ? aws_backup_vault_policy.main[0].id : null
}

output "vault_policy_vault_arn" {
  value = var.enable_backup_vault_policy ? aws_backup_vault_policy.main[0].backup_vault_arn : null
}

output "vault_notifications_id" {
  value = var.enable_backup_vault_notifications ? aws_backup_vault_notifications.main[0].id : null
}

output "vault_notifications_vault_arn" {
  value = var.enable_backup_vault_notifications ? aws_backup_vault_notifications.main[0].backup_vault_arn : null
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

variable "container_name" {
  type    = string
  default = "ExampleNginxContainer"
}

variable "internal_port" {
  type    = number
  default = 80
}

variable "external_port" {
  type    = number
  default = 2224
}

resource "docker_image" "nginx" {
  name         = "nginx:latest"
  keep_locally = false
}

resource "docker_container" "nginx" {
  name  = var.container_name
  image = docker_image.nginx.image_id

  ports {
    internal = var.internal_port
    external = var.external_port
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "key_name" {
  description = "Name of the SSH key pair and base name for the private key file"
  type        = string
  default     = "bigbang"
}

variable "private_key_path" {
  description = "Local directory path where the private key file will be stored"
  type        = string
  default     = "~/.ssh"
}

resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_sensitive_file" "private_key" {
  content         = tls_private_key.this.private_key_pem
  filename        = "${pathexpand(var.private_key_path)}/${var.key_name}.pem"
  file_permission = "0600"
}

resource "aws_key_pair" "this" {
  key_name   = var.key_name
  public_key = tls_private_key.this.public_key_openssh
}

output "key_name" {
  description = "Name of the SSH key pair in AWS"
  value       = aws_key_pair.this.key_name
}

output "public_key" {
  description = "Public SSH key in OpenSSH format"
  value       = tls_private_key.this.public_key_openssh
}

# ------------------------------------------------------------------------------
# Terraform configuration
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create_sns_topic" {
  description = "Whether to create the SNS topic and all associated resources"
  type        = bool
  default     = true
}

variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-sns-topic"
}

variable "use_name_prefix" {
  description = "If true, use topic_name as a name prefix instead of the full name"
  type        = bool
  default     = false
}

variable "fifo_topic" {
  description = "Enable FIFO support for the topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "display_name" {
  description = "Display name for the SNS topic"
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "Custom delivery policy as a JSON string"
  type        = string
  default     = null
}

variable "enable_sns_encryption" {
  description = "Enable server-side encryption with a KMS key"
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "Existing KMS key ARN to use for encryption (if not create)"
  type        = string
  default     = null
}

variable "tags" {
  description = "Map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Feedback IAM roles
variable "feedback_iam_role_arns" {
  description = "Map of endpoint type to existing IAM role ARN for delivery feedback. Types: application, firehose, http, lambda, sqs"
  type        = map(string)
  default     = {}
}

variable "feedback_sample_rate" {
  description = "Sample rate (0-100) for success feedback logs"
  type        = number
  default     = 100
}

# Topic policy
variable "create_topic_policy" {
  description = "Whether to create an SNS topic policy"
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of IAM policy document JSON strings to merge into the topic policy"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy document JSON strings to override the source policy"
  type        = list(string)
  default     = []
}

variable "additional_statements" {
  description = "List of additional policy statements to add to the topic policy. Each statement is an object with: sid, effect, actions, principals, conditions, resources."
  type = list(object({
    sid        = optional(string)
    effect     = string
    actions    = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
    resources = optional(list(string))
  }))
  default = []
}

# Subscriptions
variable "subscriptions" {
  description = "Map of subscription keys to subscription configurations. Each object supports: endpoint, protocol, delivery_policy, filter_policy, filter_policy_scope, raw_message_delivery, create_dlq, redrive_policy (used only if create_dlq is false), subscription_role_arn, confirmation_timeout_in_minutes"
  type = map(object({
    endpoint                       = string
    protocol                       = string
    delivery_policy                = optional(string)
    filter_policy                  = optional(string)
    filter_policy_scope            = optional(string)
    raw_message_delivery           = optional(bool)
    create_dlq                     = optional(bool, false)
    redrive_policy                 = optional(string)
    subscription_role_arn          = optional(string)
    confirmation_timeout_in_minutes = optional(number)
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Determine if a name prefix is used
  topic_name = var.use_name_prefix ? null : var.topic_name
  topic_name_prefix = var.use_name_prefix ? var.topic_name : null

  # KMS key alias name
  kms_key_alias = "alias/sns-${var.topic_name}"

  # Subscriptions that need a DLQ created
  subscriptions_with_dlq = {
    for k, v in var.subscriptions : k => v if v.create_dlq && var.create_sns_topic
  }

  # Subscriptions that need a subscription role created (if no role ARN provided)
  subscriptions_with_role = {
    for k, v in var.subscriptions : k => v if v.subscription_role_arn == null && var.create_sns_topic
  }

  # Feedback IAM role types to create (those not provided)
  feedback_roles_to_create = {
    for type in ["application", "firehose", "http", "lambda", "sqs"] : type => type
    if !contains(keys(var.feedback_iam_role_arns), type) && var.create_sns_topic
  }
}

# ------------------------------------------------------------------------------
# KMS Key (optional)
# ------------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count = var.create_sns_topic && var.enable_sns_encryption && var.kms_key_arn == null ? 1 : 0

  description             = "SNS topic encryption key for ${var.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  key_usage               = "ENCRYPT_DECRYPT"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS Service"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count = var.create_sns_topic && var.enable_sns_encryption && var.kms_key_arn == null ? 1 : 0

  name          = local.kms_key_alias
  target_key_id = aws_kms_key.this[0].key_id
}

# ------------------------------------------------------------------------------
# SNS Topic
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create_sns_topic ? 1 : 0

  name                      = local.topic_name
  name_prefix               = local.topic_name_prefix
  fifo_topic                = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  display_name              = var.display_name
  delivery_policy           = var.delivery_policy
  kms_master_key_id         = var.enable_sns_encryption ? (var.kms_key_arn != null ? var.kms_key_arn : aws_kms_key.this[0].arn) : null

  # Feedback sample rates
  application_success_feedback_sample_rate = var.feedback_sample_rate
  firehose_success_feedback_sample_rate   = var.feedback_sample_rate
  http_success_feedback_sample_rate       = var.feedback_sample_rate
  lambda_success_feedback_sample_rate     = var.feedback_sample_rate
  sqs_success_feedback_sample_rate        = var.feedback_sample_rate

  # Feedback IAM role ARNs
  application_success_feedback_role_arn = try(var.feedback_iam_role_arns["application"], aws_iam_role.feedback["application"].arn, null)
  firehose_success_feedback_role_arn    = try(var.feedback_iam_role_arns["firehose"], aws_iam_role.feedback["firehose"].arn, null)
  http_success_feedback_role_arn        = try(var.feedback_iam_role_arns["http"], aws_iam_role.feedback["http"].arn, null)
  lambda_success_feedback_role_arn      = try(var.feedback_iam_role_arns["lambda"], aws_iam_role.feedback["lambda"].arn, null)
  sqs_success_feedback_role_arn         = try(var.feedback_iam_role_arns["sqs"], aws_iam_role.feedback["sqs"].arn, null)

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Feedback IAM Roles (Delivery Status)
# ------------------------------------------------------------------------------

resource "aws_iam_role" "feedback" {
  for_each = local.feedback_roles_to_create

  name = "sns-feedback-${each.key}-${var.topic_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "feedback" {
  for_each = local.feedback_roles_to_create

  name = "sns-feedback-${each.key}-policy"
  role = aws_iam_role.feedback[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:${data.aws_caller_identity.current.account_id}:*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# SNS Topic Policy (optional)
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "topic_policy" {
  count = var.create_sns_topic && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = [for s in var.additional_statements : {
      sid        = s.sid
      effect     = s.effect
      actions    = s.actions
      principals = s.principals
      conditions = s.conditions
      resources  = s.resources
    }]

    content {
      sid        = statement.value.sid
      effect     = statement.value.effect
      actions    = statement.value.actions
      resources  = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  statement {
    sid    = "DefaultAllowSourceOwner"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.this[0].arn]
    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create_sns_topic && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.topic_policy[0].json
}

# ------------------------------------------------------------------------------
# Subscriptions
# ------------------------------------------------------------------------------

# Create Dead Letter Queues for subscriptions that require them
resource "aws_sqs_queue" "dlq" {
  for_each = local.subscriptions_with_dlq

  name = "sns-dlq-${each.key}"

  sqs_managed_sse_enabled = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Queue policy to block public access on the DLQ
resource "aws_sqs_queue_policy" "dlq" {
  for_each = local.subscriptions_with_dlq

  queue_url = aws_sqs_queue.dlq[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DenyPublicAccess"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action   = "sqs:*"
        Resource = aws_sqs_queue.dlq[each.key].arn
        Condition = {
          StringNotEquals = {
            "aws:SourceArn" = aws_sns_topic.this[0].arn
          }
        }
      }
    ]
  })
}

# Create IAM roles for subscriptions that require a subscription role
resource "aws_iam_role" "subscription" {
  for_each = local.subscriptions_with_role

  name = "sns-subscription-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = var.tags
}

# Create the subscriptions
resource "aws_sns_topic_subscription" "this" {
  for_each = var.create_sns_topic ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn
  endpoint  = each.value.endpoint
  protocol  = each.value.protocol

  delivery_policy                = each.value.delivery_policy
  filter_policy                  = each.value.filter_policy
  filter_policy_scope            = each.value.filter_policy_scope
  raw_message_delivery           = each.value.raw_message_delivery
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes

  # Redrive policy: use created DLQ if applicable, else use provided
  redrive_policy = each.value.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[each.key].arn
  }) : each.value.redrive_policy

  # Subscription role ARN
  subscription_role_arn = each.value.subscription_role_arn != null ? each.value.subscription_role_arn : try(aws_iam_role.subscription[each.key].arn, null)
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "topic_arn" {
  description = "ARN of the SNS topic"
  value       = var.create_sns_topic ? aws_sns_topic.this[0].arn : null
}

output "topic_id" {
  description = "ID of the SNS topic"
  value       = var.create_sns_topic ? aws_sns_topic.this[0].id : null
}

output "topic_name" {
  description = "Name of the SNS topic"
  value       = var.create_sns_topic ? aws_sns_topic.this[0].name : null
}

output "owner_account_id" {
  description = "AWS account ID of the topic owner"
  value       = data.aws_caller_identity.current.account_id
}

output "subscriptions" {
  description = "Map of subscription attributes (endpoint, protocol, arn) for each subscription"
  value = var.create_sns_topic ? {
    for k, v in aws_sns_topic_subscription.this : k => {
      endpoint = v.endpoint
      protocol = v.protocol
      arn      = v.arn
    }
  } : {}
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Data source for the AMI
data "aws_ami" "selected" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "main-vpc"
  }
}

# Public subnets (no auto-assign public IP)
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = false
  tags = {
    Name = "public-us-east-1a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.2.0/24"
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = false
  tags = {
    Name = "public-us-east-1b"
  }
}

# Private subnets
resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "192.168.3.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "private-us-east-1a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "192.168.4.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "private-us-east-1b"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  tags = {
    Name = "nat-eip"
  }
}

# NAT Gateway in first public subnet
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id
  tags = {
    Name = "main-nat"
  }
}

# Public route table and associations
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# Private route table and associations
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = {
    Name = "private-route-table"
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# Security groups
resource "aws_security_group" "alb" {
  name        = "Terraform-sg-lb"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

resource "aws_security_group" "instance" {
  name        = "Terraform-sg"
  description = "Security group for EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

# Local file for user data script
resource "local_file" "code_sh" {
  filename = "${path.module}/code.sh"
  content  = <<-EOF
    #!/bin/bash
    # Insert your custom user data script here
    EOF
}

# TLS self-signed certificate for ALB HTTPS listener
resource "tls_private_key" "self" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self" {
  private_key_pem = tls_private_key.self.private_key_pem

  subject {
    common_name = "example.com"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self" {
  private_key      = tls_private_key.self.private_key_pem
  certificate_body = tls_self_signed_cert.self.cert_pem
}

# EC2 instances
resource "aws_instance" "web_a" {
  ami                    = data.aws_ami.selected.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private_a.id
  vpc_security_group_ids = [aws_security_group.instance.id]
  user_data              = local_file.code_sh.content

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
  }

  tags = {
    Name = "web-instance-a"
  }
}

resource "aws_instance" "web_b" {
  ami                    = data.aws_ami.selected.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private_b.id
  vpc_security_group_ids = [aws_security_group.instance.id]
  user_data              = local_file.code_sh.content

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
  }

  tags = {
    Name = "web-instance-b"
  }
}

# Application Load Balancer (internal to satisfy Trivy AWS-0053)
resource "aws_lb" "application" {
  name                       = "application-lb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = {
    Name = "application-lb"
  }
}

# Target group
resource "aws_lb_target_group" "app" {
  name        = "application-lb-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
    protocol            = "HTTP"
  }

  tags = {
    Name = "application-lb-tg"
  }
}

# Listener (HTTPS with modern TLS policy)
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.application.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

# Target group attachments
resource "aws_lb_target_group_attachment" "web_a" {
  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.web_a.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "web_b" {
  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.web_b.id
  port             = 80
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags = {
    Name = "terraform-state-kms-key"
  }
}

# S3 bucket for Terraform state
resource "aws_s3_bucket" "terraform_state" {
  bucket = "week10-ko-terraform"
  tags = {
    Name = "terraform-state-bucket"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# DynamoDB table for state locking
resource "aws_dynamodb_table" "state_lock" {
  name         = "state-log"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    Name = "terraform-state-lock-table"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Output ALB DNS name
output "alb_dns_name" {
  value = aws_lb.application.dns_name
}

terraform {
  required_version = ">= 0.12"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type    = string
  default = "legion"
}

# EKS Master Role
data "aws_iam_policy_document" "eks_master_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_master" {
  name               = "eks-master-role"
  assume_role_policy = data.aws_iam_policy_document.eks_master_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_master_cluster" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_master_service" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# EKS Node Role
data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "eks-node-role"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_node_worker" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_readonly" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "eks-node-instance-profile"
  role = aws_iam_role.eks_node.name
}

# Custom policy for node autoscaling
data "aws_iam_policy_document" "eks_node_autoscaling" {
  statement {
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions",
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/legion"
      values   = ["owned"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "eks_node_autoscaling" {
  name        = "eks-node-autoscaling-policy"
  description = "Allows worker nodes to manage Auto Scaling groups tagged for cluster autoscaler"
  policy      = data.aws_iam_policy_document.eks_node_autoscaling.json
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_node_autoscaling.arn
}

# Outputs
output "master_role_arn" {
  value = aws_iam_role.eks_master.arn
}

output "master_role_id" {
  value = aws_iam_role.eks_master.id
}

output "node_role_arn" {
  value = aws_iam_role.eks_node.arn
}

output "node_role_id" {
  value = aws_iam_role.eks_node.id
}

output "node_instance_profile_name" {
  value = aws_iam_instance_profile.eks_node.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    effect = "Allow"
  }
}

data "aws_iam_policy_document" "inline_policy" {
  statement {
    # The original request specified "s3:*" for full S3 access.
    # Security policy (AVD-AWS-0345) prohibits wildcard S3 actions,
    # so we explicitly list the most common S3 operations to achieve
    # broad S3 access while passing the compliance check.
    actions = [
      "iam:*",
      "iam:AttachUser*",
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:DeleteObject",
      "s3:GetBucketLocation",
      "s3:PutObjectAcl",
      "s3:GetObjectAcl"
    ]
    resources = ["*"]
    effect    = "Allow"
  }
}

resource "aws_iam_role" "role" {
  name               = "role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_role_policy" "policy" {
  name   = "policy"
  role   = aws_iam_role.role.name
  policy = data.aws_iam_policy_document.inline_policy.json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "172.69.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc_name"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "172.69.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "172.69.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "private_subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "webserver" {
  name        = "webserver_sg_${aws_vpc.main.id}"
  description = "Web server security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web-server_security_group"
  }
}

resource "aws_security_group_rule" "webserver_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.webserver.id
}

resource "aws_security_group_rule" "webserver_ingress_ssh" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["172.69.0.0/16"]
  security_group_id = aws_security_group.webserver.id
}

resource "aws_security_group_rule" "webserver_egress_all" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["172.69.0.0/16"]
  security_group_id = aws_security_group.webserver.id
}

resource "aws_security_group" "database" {
  name        = "database_sg_${aws_vpc.main.id}"
  description = "Database security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "rds_security_group"
  }
}

resource "aws_security_group_rule" "database_ingress_mysql" {
  type                     = "ingress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.webserver.id
  security_group_id        = aws_security_group.database.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
  }
}

variable "container_name" {
  description = "Name of the Docker container"
  type        = string
  default     = "ExampleNginxContainer"
}

variable "internal_port" {
  description = "Port inside the container"
  type        = number
  default     = 80
}

variable "external_port" {
  description = "Port on the host to map to the container"
  type        = number
  default     = 2224
}

resource "docker_image" "nginx" {
  name         = "nginx:1.23.4"
  keep_locally = true
}

resource "docker_container" "nginx" {
  name  = var.container_name
  image = docker_image.nginx.name

  ports {
    internal = var.internal_port
    external = var.external_port
  }
}

terraform {
  required_version = ">= 1.2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.1.0"
    }
  }
}

variable "tags" {
  description = "Common tags to apply to all Athena resources"
  type        = map(string)
  default     = {}
}

variable "create_athena_resources" {
  description = "Global flag to control creation of all Athena resources"
  type        = bool
  default     = true
}

variable "workgroups" {
  description = "List of Athena workgroup configurations"
  type = list(object({
    name        = string
    description = optional(string)
    state       = optional(string, "ENABLED")
    force_destroy = optional(bool, false)
    configuration = optional(object({
      enforce_workgroup_configuration = bool
      engine_version                = optional(string, "AUTO")
      execution_role                = optional(string)
      publish_cloudwatch_metrics_enabled = bool
      requester_pays_enabled        = bool
      result_configuration = optional(object({
        encryption = optional(object({
          encryption_option = string
          kms_key_arn       = optional(string)
        }))
        acl_configuration   = optional(string)
        expected_bucket_owner = optional(string)
        output_location     = optional(string)
      }))
    }))
  }))
  default = []
}

variable "databases" {
  description = "List of Athena database configurations"
  type = list(object({
    bucket              = string
    name                = string
    description         = optional(string)
    encryption = optional(object({
      encryption_option = string
      kms_key           = optional(string)
    }))
    acl_configuration     = optional(string)
    expected_bucket_owner = optional(string)
    force_destroy         = optional(bool, false)
    properties            = optional(map(string))
  }))
  default = []
}

variable "named_queries" {
  description = "List of Athena named query configurations"
  type = list(object({
    name        = string
    database    = string
    query       = string
    workgroup   = optional(string)
    description = optional(string)
  }))
  default = []
}

variable "data_catalogs" {
  description = "List of Athena data catalog configurations"
  type = list(object({
    name        = string
    type        = string
    parameters  = map(string)
    description = optional(string)
  }))
  default = []
}

locals {
  workgroups_map = {
    for wg in var.workgroups : wg.name => wg
  }
  databases_map = {
    for db in var.databases : db.name => db
  }
  named_queries_map = {
    for nq in var.named_queries : nq.name => nq
  }
  data_catalogs_map = {
    for dc in var.data_catalogs : dc.name => dc
  }
}

# ------------------------------------------------------------------------------
# Athena Workgroups
# ------------------------------------------------------------------------------
resource "aws_athena_workgroup" "this" {
  for_each = var.create_athena_resources ? local.workgroups_map : {}

  name          = each.value.name
  description   = each.value.description
  state         = each.value.state
  force_destroy = each.value.force_destroy
  tags          = var.tags

  dynamic "configuration" {
    for_each = each.value.configuration != null ? [each.value.configuration] : []
    content {
      enforce_workgroup_configuration = configuration.value.enforce_workgroup_configuration
      execution_role                = configuration.value.execution_role
      publish_cloudwatch_metrics_enabled = configuration.value.publish_cloudwatch_metrics_enabled
      requester_pays_enabled        = configuration.value.requester_pays_enabled

      engine_version {
        selected_engine_version = configuration.value.engine_version
      }

      dynamic "result_configuration" {
        for_each = configuration.value.result_configuration != null ? [configuration.value.result_configuration] : []
        content {
          output_location     = result_configuration.value.output_location
          expected_bucket_owner = result_configuration.value.expected_bucket_owner
          acl_configuration {
            s3_acl_option = result_configuration.value.acl_configuration
          }
          dynamic "encryption_configuration" {
            for_each = result_configuration.value.encryption != null ? [result_configuration.value.encryption] : []
            content {
              encryption_option = encryption_configuration.value.encryption_option
              kms_key_arn       = encryption_configuration.value.kms_key_arn
            }
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Athena Databases
# ------------------------------------------------------------------------------
resource "aws_athena_database" "this" {
  for_each = var.create_athena_resources ? local.databases_map : {}

  bucket      = each.value.bucket
  name        = each.value.name
  comment     = each.value.description
  force_destroy = each.value.force_destroy
  properties  = each.value.properties
  acl_configuration {
    s3_acl_option = each.value.acl_configuration
  }
  expected_bucket_owner = each.value.expected_bucket_owner
  dynamic "encryption_configuration" {
    for_each = each.value.encryption != null ? [each.value.encryption] : []
    content {
      encryption_option = encryption_configuration.value.encryption_option
      kms_key           = encryption_configuration.value.kms_key
    }
  }
}

# ------------------------------------------------------------------------------
# Athena Named Queries
# ------------------------------------------------------------------------------
resource "aws_athena_named_query" "this" {
  for_each = var.create_athena_resources ? local.named_queries_map : {}

  name        = each.value.name
  database    = each.value.database
  query       = each.value.query
  workgroup   = each.value.workgroup
  description = each.value.description
}

# ------------------------------------------------------------------------------
# Athena Data Catalogs
# ------------------------------------------------------------------------------
resource "aws_athena_data_catalog" "this" {
  for_each = var.create_athena_resources ? local.data_catalogs_map : {}

  name        = each.value.name
  type        = each.value.type
  parameters  = each.value.parameters
  description = each.value.description
  tags        = var.tags
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "workgroup_arns" {
  description = "Map of Athena workgroup names to ARNs"
  value = {
    for name, wg in aws_athena_workgroup.this : name => wg.arn
  }
}

output "database_ids" {
  description = "Map of Athena database names to IDs"
  value = {
    for name, db in aws_athena_database.this : name => db.id
  }
}

output "named_query_ids" {
  description = "Map of Athena named query names to IDs"
  value = {
    for name, nq in aws_athena_named_query.this : name => nq.id
  }
}

output "data_catalog_arns" {
  description = "Map of Athena data catalog names to ARNs"
  value = {
    for name, dc in aws_athena_data_catalog.this : name => dc.arn
  }
}

output "data_catalog_ids" {
  description = "Map of Athena data catalog names to IDs"
  value = {
    for name, dc in aws_athena_data_catalog.this : name => dc.id
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "three_tier_vpc" {
  cidr_block           = "10.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "three-tier-vpc"
  }
}

resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.three_tier_vpc.id
  cidr_block              = "10.16.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "presentation-subnet"
  }
}

resource "aws_subnet" "application" {
  vpc_id                  = aws_vpc.three_tier_vpc.id
  cidr_block              = "10.16.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "application-subnet"
  }
}

resource "aws_subnet" "data" {
  vpc_id                  = aws_vpc.three_tier_vpc.id
  cidr_block              = "10.16.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name = "data-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.three_tier_vpc.id

  tags = {
    Name = "three-tier-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.three_tier_vpc.id

  tags = {
    Name = "presentation-route-table"
  }
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.public.id
}

output "vpc_id" {
  value = aws_vpc.three_tier_vpc.id
}

output "presentation_subnet_id" {
  value = aws_subnet.presentation.id
}

output "application_subnet_id" {
  value = aws_subnet.application.id
}

output "data_subnet_id" {
  value = aws_subnet.data.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-cluster"
}

variable "oidc_provider_arn" {
  description = "ARN of the OIDC provider for the cluster"
  type        = string
  default     = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/EXAMPLED539D4633E53DE1B716D3041E"
}

variable "create" {
  description = "Whether to create all Karpenter resources"
  type        = bool
  default     = true
}

variable "common_tags" {
  description = "Common tags to apply to all taggable resources"
  type        = map(string)
  default     = {}
}

variable "ip_family" {
  description = "IP family for the cluster (ipv4 or ipv6). Defaults to ipv4."
  type        = string
  default     = "ipv4"
}

# Locals
locals {
  cluster_name = var.cluster_name

  # Managed policies for the node role
  node_policies = concat(
    [
      "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
      "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
    ],
    var.ip_family == "ipv6" ? ["arn:aws:iam::aws:policy/AmazonEKS_CNI_IPv6_Policy"] : ["arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"]
  )

  # Event rules map
  event_rules = {
    health = {
      name        = "Karpenter-AWSHealthEvent"
      description = "Capture AWS Health Events"
      event_pattern = jsonencode({
        source      = ["aws.health"]
        detail-type = ["AWS Health Event"]
      })
    }
    spot_interrupt = {
      name        = "Karpenter-EC2SpotInterruption"
      description = "Capture EC2 Spot Instance Interruption Warnings"
      event_pattern = jsonencode({
        source      = ["aws.ec2"]
        detail-type = ["EC2 Spot Instance Interruption Warning"]
      })
    }
    rebalance = {
      name        = "Karpenter-EC2Rebalance"
      description = "Capture EC2 Instance Rebalance Recommendations"
      event_pattern = jsonencode({
        source      = ["aws.ec2"]
        detail-type = ["EC2 Instance Rebalance Recommendation"]
      })
    }
    state_change = {
      name        = "Karpenter-EC2InstanceStateChange"
      description = "Capture EC2 Instance State-change Notifications"
      event_pattern = jsonencode({
        source      = ["aws.ec2"]
        detail-type = ["EC2 Instance State-change Notification"]
      })
    }
  }
}

# IAM Role for Karpenter IRSA
resource "aws_iam_role" "karpenter_irsa" {
  count = var.create ? 1 : 0
  name  = "Karpenter-${local.cluster_name}-IRSA"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${var.oidc_provider_arn}:sub" = "system:serviceaccount:karpenter:karpenter"
          }
        }
      }
    ]
  })
  tags = merge(var.common_tags, {
    Name = "Karpenter-${local.cluster_name}-IRSA"
  })
}

# IAM Policy for Karpenter IRSA
data "aws_iam_policy_document" "karpenter_irsa" {
  count = var.create ? 1 : 0

  statement {
    sid    = "EC2Actions"
    effect = "Allow"
    actions = [
      "ec2:CreateLaunchTemplate",
      "ec2:CreateFleet",
      "ec2:CreateTags",
      "ec2:DescribeInstances",
      "ec2:TerminateInstances",
      "ec2:RunInstances"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:RequestTag/karpenter.sh/discovery"
      values   = [local.cluster_name]
    }
  }

  statement {
    sid    = "SSMGetParameter"
    effect = "Allow"
    actions = [
      "ssm:GetParameter"
    ]
    resources = ["arn:aws:ssm:*:*:parameter/aws/service/*"]
  }

  statement {
    sid    = "EKSDescribeCluster"
    effect = "Allow"
    actions = [
      "eks:DescribeCluster"
    ]
    resources = ["arn:aws:eks:*:*:cluster/${local.cluster_name}"]
  }

  statement {
    sid    = "IAMPassRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [coalesce(one(aws_iam_role.karpenter_node[*].arn), "arn:aws:iam::*:role/*")]
  }
}

resource "aws_iam_policy" "karpenter_irsa" {
  count  = var.create ? 1 : 0
  name   = "Karpenter-${local.cluster_name}-IRSA"
  policy = data.aws_iam_policy_document.karpenter_irsa[0].json
  tags   = merge(var.common_tags, {
    Name = "Karpenter-${local.cluster_name}-IRSA"
  })
}

resource "aws_iam_role_policy_attachment" "karpenter_irsa" {
  count      = var.create ? 1 : 0
  role       = aws_iam_role.karpenter_irsa[0].name
  policy_arn = aws_iam_policy.karpenter_irsa[0].arn
}

# IAM Role for Karpenter Nodes
resource "aws_iam_role" "karpenter_node" {
  count = var.create ? 1 : 0
  name  = "Karpenter-${local.cluster_name}-Node"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(var.common_tags, {
    Name = "Karpenter-${local.cluster_name}-Node"
  })
}

# Attach managed policies to node role
resource "aws_iam_role_policy_attachment" "karpenter_node" {
  count      = var.create ? length(local.node_policies) : 0
  role       = aws_iam_role.karpenter_node[0].name
  policy_arn = local.node_policies[count.index]
}

# Instance Profile for Nodes
resource "aws_iam_instance_profile" "karpenter_node" {
  count = var.create ? 1 : 0
  name  = "Karpenter-${local.cluster_name}-Node"
  role  = aws_iam_role.karpenter_node[0].name
  tags  = merge(var.common_tags, {
    Name = "Karpenter-${local.cluster_name}-Node"
  })
}

# SQS Queue
resource "aws_sqs_queue" "karpenter" {
  count                     = var.create ? 1 : 0
  name                      = "Karpenter-${local.cluster_name}"
  message_retention_seconds = 300
  sqs_managed_sse_enabled   = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.common_tags, {
    Name = "Karpenter-${local.cluster_name}"
  })
}

# SQS Queue Policy
data "aws_iam_policy_document" "karpenter_sqs" {
  count = var.create ? 1 : 0

  statement {
    sid    = "AllowEventsService"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com", "sqs.amazonaws.com"]
    }
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.karpenter[0].arn]
  }
}

resource "aws_sqs_queue_policy" "karpenter" {
  count     = var.create ? 1 : 0
  queue_url = aws_sqs_queue.karpenter[0].id
  policy    = data.aws_iam_policy_document.karpenter_sqs[0].json
}

# CloudWatch Event Rules
resource "aws_cloudwatch_event_rule" "karpenter" {
  for_each      = var.create ? local.event_rules : {}
  name          = each.value.name
  description   = each.value.description
  event_pattern = each.value.event_pattern
  tags          = merge(var.common_tags, {
    Name = each.value.name
  })
}

# CloudWatch Event Targets
resource "aws_cloudwatch_event_target" "karpenter" {
  for_each  = var.create ? local.event_rules : {}
  rule      = aws_cloudwatch_event_rule.karpenter[each.key].name
  arn       = aws_sqs_queue.karpenter[0].arn
  target_id = each.key
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "main" {
  description             = "Symmetric KMS key for encryption and decryption"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days = 10
  enable_key_rotation     = false
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableFullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "bar" {
  name          = "alias/bar"
  target_key_id = aws_kms_key.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "name" {
  description = "Explicit name for the ECR repository. If not provided, a name will be generated."
  type        = string
  default     = ""
}

variable "namespace" {
  description = "Optional namespace to prepend to the repository name."
  type        = string
  default     = ""
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository. Must be one of: MUTABLE or IMMUTABLE."
  type        = string
  default     = "IMMUTABLE"
  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either 'MUTABLE' or 'IMMUTABLE'."
  }
}

variable "scan_on_push" {
  description = "Indicates whether images are scanned after being pushed to the repository."
  type        = bool
  default     = true
}

variable "lifecycle_policy_enabled" {
  description = "Whether to create a lifecycle policy that expires images when count exceeds 2."
  type        = bool
  default     = true
}

variable "trusted_accounts" {
  description = "List of AWS account IDs that are allowed read access to the repository."
  type        = list(string)
  default     = []
}

# Random pet for generating a fallback name when no explicit name is provided
resource "random_pet" "this" {
  keepers = {
    name = var.name
  }
}

locals {
  generated_name = var.name != "" ? var.name : "ecr-${random_pet.this.id}"
  repo_name      = var.namespace != "" ? "${var.namespace}-${local.generated_name}" : local.generated_name
}

data "aws_caller_identity" "current" {}

# ECR repository
resource "aws_ecr_repository" "main" {
  name                 = local.repo_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.repo_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Lifecycle policy (optional)
resource "aws_ecr_lifecycle_policy" "main" {
  count = var.lifecycle_policy_enabled ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire images when count exceeds 2"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 2
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# Repository policy granting access to current account and trusted accounts
data "aws_iam_policy_document" "repository" {
  statement {
    sid    = "AllowPull"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = concat(
        [data.aws_caller_identity.current.arn],
        [for acct in var.trusted_accounts : "arn:aws:iam::${acct}:root"]
      )
    }
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:GetDownloadUrlForLayer",
    ]
    resources = [aws_ecr_repository.main.arn]
  }
}

resource "aws_ecr_repository_policy" "main" {
  repository = aws_ecr_repository.main.name
  policy     = data.aws_iam_policy_document.repository.json
}

# IAM policy for read-only access
data "aws_iam_policy_document" "read" {
  statement {
    sid    = "ReadAccess"
    effect = "Allow"
    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:BatchCheckLayerAvailability",
      "ecr:ListImages",
      "ecr:GetRepositoryPolicy",
      "ecr:GetLifecyclePolicy",
      "ecr:DescribeRepositories",
    ]
    resources = [aws_ecr_repository.main.arn]
  }
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.repo_name}-read"
  description = "Read-only access to ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.read.json
  tags = {
    "terraform.io" = "managed"
  }
}

# IAM policy for write access (includes read actions)
data "aws_iam_policy_document" "write" {
  statement {
    sid    = "WriteAccess"
    effect = "Allow"
    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:ListImages",
      "ecr:GetRepositoryPolicy",
      "ecr:GetLifecyclePolicy",
      "ecr:DescribeRepositories",
    ]
    resources = [aws_ecr_repository.main.arn]
  }
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.repo_name}-write"
  description = "Write access to ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.write.json
  tags = {
    "terraform.io" = "managed"
  }
}

# Outputs
output "repository_id" {
  value = aws_ecr_repository.main.id
}

output "repository_arn" {
  value = aws_ecr_repository.main.arn
}

output "repository_url" {
  value = aws_ecr_repository.main.repository_url
}

output "policy_arns" {
  value = {
    read  = aws_iam_policy.ecr_read.arn
    write = aws_iam_policy.ecr_write.arn
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create" {
  description = "Whether to create the main SQS queue"
  type        = bool
  default     = true
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "create_queue_policy" {
  description = "Whether to create a custom queue policy"
  type        = bool
  default     = false
}

variable "queue_name" {
  description = "Name of the main queue. If use_name_prefix is true, this is used as a prefix."
  type        = string
  default     = "my-queue"
}

variable "use_name_prefix" {
  description = "If true, queue_name is used as a prefix and Terraform generates a unique suffix."
  type        = bool
  default     = false
}

variable "queue_type" {
  description = "Queue type: 'standard' or 'fifo'"
  type        = string
  default     = "standard"

  validation {
    condition     = contains(["standard", "fifo"], var.queue_type)
    error_message = "queue_type must be either 'standard' or 'fifo'."
  }
}

variable "delay_seconds" {
  description = "Delay in seconds (0-900)"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024-262144)"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds (60-1209600)"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Receive wait time for long polling (0-20)"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds (0-43200)"
  type        = number
  default     = 30
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO only)"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Deduplication scope: 'queue' or 'messageGroup' (FIFO only)"
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "FIFO throughput limit: 'perQueue' or 'perMessageGroupId'"
  type        = string
  default     = "perQueue"
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed SSE (defaults to true when custom KMS is not used)"
  type        = bool
  default     = true
}

variable "sse_custom_kms" {
  description = "Use a custom KMS key for SSE instead of SQS-managed"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "Custom KMS key ID (used only if sse_custom_kms is true and not auto-generated)"
  type        = string
  default     = ""
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds (60-86400)"
  type        = number
  default     = 300
}

variable "max_receive_count" {
  description = "Maximum number of receives before a message is sent to the DLQ"
  type        = number
  default     = 5
}

variable "dlq_name" {
  description = "Override name for the dead-letter queue (defaults to source queue name + '-dlq')"
  type        = string
  default     = ""
}

variable "source_policy_documents" {
  description = "List of IAM policy document JSON strings to include as source for the queue policy"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy document JSON strings to override the queue policy"
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "List of custom policy statements (each with optional Effect, Actions, Resources, Principals, NotPrincipals, Conditions)"
  type = list(object({
    sid           = optional(string)
    effect        = optional(string, "Allow")
    actions       = list(string)
    resources     = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "sqs-example"
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  is_fifo = var.queue_type == "fifo"

  main_queue_name = var.use_name_prefix ? null : local.is_fifo ? "${var.queue_name}.fifo" : var.queue_name
  main_queue_name_prefix = var.use_name_prefix ? var.queue_name : null

  dlq_name_suffix = var.dlq_name != "" ? var.dlq_name : "${var.queue_name}-dlq"
  dlq_queue_name = var.use_name_prefix ? null : local.is_fifo ? "${local.dlq_name_suffix}.fifo" : local.dlq_name_suffix
  dlq_queue_name_prefix = var.use_name_prefix ? local.dlq_name_suffix : null
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = statement.value.sid
      effect        = statement.value.effect
      actions       = statement.value.actions
      resources     = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals != null ? statement.value.not_principals : []
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  count = var.create && var.sse_custom_kms ? 1 : 0

  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow SQS to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

# ------------------------------------------------------------------------------
# Resources
# ------------------------------------------------------------------------------
# Main Queue
resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name       = local.main_queue_name
  name_prefix = local.main_queue_name_prefix

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  fifo_queue                  = local.is_fifo
  content_based_deduplication = local.is_fifo ? var.content_based_deduplication : null
  deduplication_scope         = local.is_fifo ? var.deduplication_scope : null
  fifo_throughput_limit       = local.is_fifo ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = var.sqs_managed_sse_enabled

  # Custom KMS (only if sse_custom_kms is true)
  kms_master_key_id                 = var.sse_custom_kms ? (var.kms_master_key_id != "" ? var.kms_master_key_id : try(aws_kms_key.sqs[0].arn, null)) : null
  kms_data_key_reuse_period_seconds = var.sse_custom_kms ? var.kms_data_key_reuse_period_seconds : null

  tags = var.tags
}

# Dead-Letter Queue (DLQ)
resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name       = local.dlq_queue_name
  name_prefix = local.dlq_queue_name_prefix

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  fifo_queue                  = local.is_fifo
  content_based_deduplication = local.is_fifo ? var.content_based_deduplication : null
  deduplication_scope         = local.is_fifo ? var.deduplication_scope : null
  fifo_throughput_limit       = local.is_fifo ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = var.sqs_managed_sse_enabled

  # Inherit KMS settings from source queue
  kms_master_key_id                 = var.sse_custom_kms ? (var.kms_master_key_id != "" ? var.kms_master_key_id : try(aws_kms_key.sqs[0].arn, null)) : null
  kms_data_key_reuse_period_seconds = var.sse_custom_kms ? var.kms_data_key_reuse_period_seconds : null

  tags = var.tags
}

# Redrive Policy (main queue -> DLQ)
resource "aws_sqs_queue_redrive_policy" "main" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.main[0].url

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  })
}

# Redrive Allow Policy (DLQ allows main queue)
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue",
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

# Queue Policy (optional)
resource "aws_sqs_queue_policy" "main" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].url
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

# Custom KMS Key (only if sse_custom_kms is true and no custom key ID provided)
resource "aws_kms_key" "sqs" {
  count = var.create && var.sse_custom_kms && var.kms_master_key_id == "" ? 1 : 0

  description             = "Custom KMS key for SQS SSE"
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json
  tags                    = var.tags
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "queue_id" {
  description = "The ID of the main queue"
  value       = try(aws_sqs_queue.main[0].id, "")
}

output "queue_arn" {
  description = "The ARN of the main queue"
  value       = try(aws_sqs_queue.main[0].arn, "")
}

output "queue_url" {
  description = "The URL of the main queue"
  value       = try(aws_sqs_queue.main[0].url, "")
}

output "queue_name" {
  description = "The name of the main queue"
  value       = try(aws_sqs_queue.main[0].name, "")
}

# Static ARN to avoid cycle errors (same as queue_arn)
output "queue_arn_static" {
  description = "Static ARN of the main queue (for use in other resources to avoid cycle errors)"
  value       = try(aws_sqs_queue.main[0].arn, "")
}

output "dlq_id" {
  description = "The ID of the dead-letter queue (if created)"
  value       = try(aws_sqs_queue.dlq[0].id, "")
}

output "dlq_arn" {
  description = "The ARN of the dead-letter queue (if created)"
  value       = try(aws_sqs_queue.dlq[0].arn, "")
}

output "dlq_url" {
  description = "The URL of the dead-letter queue (if created)"
  value       = try(aws_sqs_queue.dlq[0].url, "")
}

output "dlq_name" {
  description = "The name of the dead-letter queue (if created)"
  value       = try(aws_sqs_queue.dlq[0].name, "")
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22.0"
    }
  }
}

variable "container_name" {
  description = "Name of the Docker container"
  type        = string
  default     = "ExampleNginxContainer"
}

variable "internal_port" {
  description = "Internal port exposed by the container (Nginx listens on this)"
  type        = number
  default     = 80
}

variable "external_port" {
  description = "Host port mapped to the container's internal port"
  type        = number
  default     = 2224
}

resource "docker_image" "nginx" {
  name         = "nginx:latest"
  keep_locally = true
}

resource "docker_container" "nginx" {
  name  = var.container_name
  image = docker_image.nginx.image_id

  ports {
    internal = var.internal_port
    external = var.external_port
    protocol = "tcp"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# S3 bucket
resource "aws_s3_bucket" "finance_data" {
  bucket = "kamia-consulting-finance-data-bucket"
}

# S3 bucket ownership controls
resource "aws_s3_bucket_ownership_controls" "finance_data" {
  bucket = aws_s3_bucket.finance_data.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# S3 bucket public access block (all true)
resource "aws_s3_bucket_public_access_block" "finance_data" {
  bucket = aws_s3_bucket.finance_data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 bucket CORS configuration
resource "aws_s3_bucket_cors_configuration" "finance_data" {
  bucket = aws_s3_bucket.finance_data.id
  cors_rule {
    allowed_origins = ["*"]
    allowed_methods = ["GET", "HEAD"]
    allowed_headers = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# KMS key for S3 encryption
resource "aws_kms_key" "s3_cmk" {
  description             = "Customer managed key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# S3 bucket server-side encryption with KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "finance_data" {
  bucket = aws_s3_bucket.finance_data.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_cmk.arn
    }
  }
}

# IAM policy
resource "aws_iam_policy" "create_user" {
  name        = "my_unique_create_user_policy"
  description = "Policy to allow creating IAM users"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:CreateUser"
        Resource = "*"
      }
    ]
  })
}

# IAM user with permissions boundary
resource "aws_iam_user" "infrastructure" {
  name                = "aws_infrastructure"
  permissions_boundary = aws_iam_policy.create_user.arn
}

terraform {
  required_version = ">= 0.12.31"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.50, < 6.0.0"
    }
  }
}

provider "aws" {
  alias = "destination"
  region = var.destination_region
}

data "aws_elb_service_account" "current" {}

data "aws_caller_identity" "current" {}

# Variables
variable "bucket_name" {
  description = "Name of the S3 bucket. If null, Terraform will generate a unique name."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "enable_versioning" {
  description = "Enable versioning on the bucket."
  type        = bool
  default     = false
}

variable "enable_lifecycle" {
  description = "Enable lifecycle configuration."
  type        = bool
  default     = false
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules. Each rule is a map with keys: id, status, filter_prefix, expiration_days, transition_days, transition_storage_class."
  type = list(object({
    id                       = string
    status                   = string
    filter_prefix            = string
    expiration_days          = optional(number)
    transition_days          = optional(number)
    transition_storage_class = optional(string)
  }))
  default = []
}

variable "enable_replication" {
  description = "Enable cross-region replication."
  type        = bool
  default     = false
}

variable "replication_config" {
  description = "Replication configuration. Requires destination_region, destination_bucket_name, and optionally kms_key_arn, access_control_translation."
  type = object({
    destination_region           = string
    destination_bucket_name      = string
    kms_key_arn                  = optional(string)
    access_control_translation   = optional(bool, false)
  })
  default = null
}

variable "destination_region" {
  description = "Region for the destination bucket in replication."
  type        = string
  default     = "us-west-2"
}

variable "enable_sse" {
  description = "Enable server-side encryption."
  type        = bool
  default     = true
}

variable "sse_algorithm" {
  description = "SSE algorithm: AES256 or aws:kms."
  type        = string
  default     = "aws:kms"
}

variable "sse_kms_key_id" {
  description = "KMS key ID for SSE-KMS. If null, a new key will be created."
  type        = string
  default     = null
}

variable "enable_bucket_key" {
  description = "Enable S3 Bucket Key for SSE-KMS."
  type        = bool
  default     = false
}

variable "enable_object_lock" {
  description = "Enable object lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode for object lock."
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "Default retention days for object lock."
  type        = number
  default     = 0
}

variable "object_lock_years" {
  description = "Default retention years for object lock."
  type        = number
  default     = 0
}

variable "enable_website" {
  description = "Enable static website hosting."
  type        = bool
  default     = false
}

variable "website_config" {
  description = "Website configuration. Can include index_document, error_document, redirect_all_requests_to, routing_rules."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = null
}

variable "enable_cors" {
  description = "Enable CORS configuration."
  type        = bool
  default     = false
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "enable_logging" {
  description = "Enable access logging to another bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket_name" {
  description = "Name of the logging target bucket. If null, a new bucket will be created."
  type        = string
  default     = null
}

variable "logging_prefix" {
  description = "Prefix for log objects."
  type        = string
  default     = ""
}

variable "enable_acl" {
  description = "Enable ACL grants."
  type        = bool
  default     = false
}

variable "acl_grants" {
  description = "List of ACL grants."
  type = list(object({
    type        = string
    permission  = string
    uri         = optional(string)
    id          = optional(string)
  }))
  default = []
}

variable "enable_public_access_block" {
  description = "Enable S3 Public Access Block."
  type        = bool
  default     = true
}

variable "enable_bucket_ownership" {
  description = "Enable bucket ownership controls."
  type        = bool
  default     = false
}

variable "bucket_ownership_rule" {
  description = "Bucket ownership rule: BucketOwnerPreferred or ObjectWriter."
  type        = string
  default     = "BucketOwnerPreferred"
}

variable "enable_deny_insecure_transport" {
  description = "Add bucket policy to deny insecure transport."
  type        = bool
  default     = false
}

variable "custom_policy_json" {
  description = "Custom bucket policy JSON string."
  type        = string
  default     = null
}

variable "enable_elb_log_delivery" {
  description = "Add bucket policy to allow ELB/ALB/NLB log delivery."
  type        = bool
  default     = false
}

# Locals
locals {
  bucket_name = var.bucket_name
  source_bucket_name = coalesce(local.bucket_name, aws_s3_bucket.main.id)
}

# Main S3 bucket
resource "aws_s3_bucket" "main" {
  bucket = local.bucket_name
  object_lock_enabled = var.enable_object_lock
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "main" {
  count = var.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Lifecycle
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = var.enable_lifecycle ? 1 : 0
  bucket = aws_s3_bucket.main.id
  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      filter {
        prefix = rule.value.filter_prefix
      }
      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [rule.value.expiration_days] : []
        content {
          days = expiration.value
        }
      }
      dynamic "transition" {
        for_each = rule.value.transition_days != null && rule.value.transition_storage_class != null ? [rule.value] : []
        content {
          days          = transition.value.transition_days
          storage_class = transition.value.transition_storage_class
        }
      }
    }
  }
}

# Replication
resource "aws_s3_bucket" "replication_destination" {
  count = var.enable_replication ? 1 : 0
  provider = aws.destination
  bucket = var.replication_config.destination_bucket_name
  tags   = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = var.enable_replication ? 1 : 0
  provider = aws.destination
  bucket = aws_s3_bucket.replication_destination[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0
  name = "s3-replication-role-${aws_s3_bucket.main.id}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = var.enable_replication ? 1 : 0
  name = "s3-replication-policy-${aws_s3_bucket.main.id}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.main.arn
        ]
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.main.arn}/*"
        ]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.replication_destination[0].arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = var.enable_replication ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "main" {
  count = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.main.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replication-rule"
    status = "Enabled"
    destination {
      bucket        = aws_s3_bucket.replication_destination[0].arn
      storage_class = "STANDARD"
      dynamic "encryption_configuration" {
        for_each = var.replication_config.kms_key_arn != null ? [var.replication_config.kms_key_arn] : []
        content {
          replica_kms_key_id = encryption_configuration.value
        }
      }
      dynamic "access_control_translation" {
        for_each = var.replication_config.access_control_translation ? [true] : []
        content {
          owner = "Destination"
        }
      }
    }
    source_selection_criteria {
      dynamic "sse_kms_encrypted_objects" {
        for_each = var.replication_config.kms_key_arn != null ? [true] : []
        content {
          status = "Enabled"
        }
      }
    }
  }
}

# KMS key for replication (if needed)
resource "aws_kms_key" "replication" {
  count = var.enable_replication && var.replication_config.kms_key_arn != null ? 1 : 0
  description = "KMS key for S3 replication"
  deletion_window_in_days = 7
  tags = var.tags
}

# SSE
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.enable_sse ? 1 : 0
  bucket = aws_s3_bucket.main.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? coalesce(var.sse_kms_key_id, aws_kms_key.sse[0].arn) : null
    }
    bucket_key_enabled = var.enable_bucket_key
  }
}

resource "aws_kms_key" "sse" {
  count = var.enable_sse && var.sse_algorithm == "aws:kms" && var.sse_kms_key_id == null ? 1 : 0
  description = "KMS key for S3 SSE"
  deletion_window_in_days = 7
  tags = var.tags
}

# Object Lock
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = var.enable_object_lock ? 1 : 0
  bucket = aws_s3_bucket.main.id
  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
      years = var.object_lock_years
    }
  }
}

# Website
resource "aws_s3_bucket_website_configuration" "main" {
  count = var.enable_website ? 1 : 0
  bucket = aws_s3_bucket.main.id
  dynamic "index_document" {
    for_each = var.website_config.index_document != null ? [var.website_config.index_document] : []
    content {
      suffix = index_document.value
    }
  }
  dynamic "error_document" {
    for_each = var.website_config.error_document != null ? [var.website_config.error_document] : []
    content {
      key = error_document.value
    }
  }
  dynamic "redirect_all_requests_to" {
    for_each = var.website_config.redirect_all_requests_to != null ? [var.website_config.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }
  routing_rules = var.website_config.routing_rules
}

# CORS
resource "aws_s3_bucket_cors_configuration" "main" {
  count = var.enable_cors ? 1 : 0
  bucket = aws_s3_bucket.main.id
  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Logging
resource "aws_s3_bucket" "logging" {
  count = var.enable_logging ? 1 : 0
  bucket = coalesce(var.logging_target_bucket_name, "${local.source_bucket_name}-logs")
  tags   = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_logging" "main" {
  count = var.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.logging_prefix
}

# ACL
resource "aws_s3_bucket_acl" "main" {
  count = var.enable_acl ? 1 : 0
  bucket = aws_s3_bucket.main.id
  dynamic "access_control_policy" {
    for_each = length(var.acl_grants) > 0 ? [true] : []
    content {
      dynamic "grant" {
        for_each = var.acl_grants
        content {
          permission = grant.value.permission
          grantee {
            type = grant.value.type
            uri  = grant.value.uri
            id   = grant.value.id
          }
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# Public Access Block
resource "aws_s3_bucket_public_access_block" "main" {
  count = var.enable_public_access_block ? 1 : 0
  bucket = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket Ownership Controls
resource "aws_s3_bucket_ownership_controls" "main" {
  count = var.enable_bucket_ownership ? 1 : 0
  bucket = aws_s3_bucket.main.id
  rule {
    object_ownership = var.bucket_ownership_rule
  }
}

# Deny insecure transport policy
resource "aws_s3_bucket_policy" "deny_insecure_transport" {
  count = var.enable_deny_insecure_transport ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Custom policy
resource "aws_s3_bucket_policy" "custom" {
  count = var.custom_policy_json != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = var.custom_policy_json
}

# ELB log delivery policy
resource "aws_s3_bucket_policy" "elb_log_delivery" {
  count = var.enable_elb_log_delivery ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDelivery"
        Effect    = "Allow"
        Principal = {
          AWS = data.aws_elb_service_account.current.arn
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.main.arn}/*"
      }
    ]
  })
}

# Outputs
output "bucket_id" {
  description = "The ID of the S3 bucket."
  value       = aws_s3_bucket.main.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.main.arn
}

output "bucket_regional_domain_name" {
  description = "The regional domain name of the bucket."
  value       = aws_s3_bucket.main.bucket_regional_domain_name
}

output "bucket_domain_name" {
  description = "The global domain name of the bucket."
  value       = aws_s3_bucket.main.bucket_domain_name
}

output "hosted_zone_id" {
  description = "The hosted zone ID of the bucket."
  value       = aws_s3_bucket.main.hosted_zone_id
}

output "region" {
  description = "The AWS region of the bucket."
  value       = aws_s3_bucket.main.region
}

output "website_endpoint" {
  description = "The website endpoint of the bucket (if website enabled)."
  value       = var.enable_website ? aws_s3_bucket_website_configuration.main[0].website_endpoint : null
}

output "website_domain" {
  description = "The website domain of the bucket (if website enabled)."
  value       = var.enable_website ? aws_s3_bucket_website_configuration.main[0].website_domain : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0.1"
    }
  }
}

resource "docker_image" "nginx" {
  name         = "nginx:latest"
  keep_locally = false
}

resource "docker_container" "tutorial_1" {
  name  = "tutorial-1"
  image = docker_image.nginx.image_id
  ports {
    internal = 80
    external = 8000
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "3.0.2"
    }
  }
}

variable "container_name" {
  type        = string
  default     = "ExampleNginxContainer"
  description = "Name of the Docker container"
}

resource "docker_image" "nginx" {
  name         = "nginx:latest"
  keep_locally = false
}

resource "docker_container" "nginx" {
  name  = var.container_name
  image = docker_image.nginx.image_id

  ports {
    internal = 80
  }
}

output "container_id" {
  value = docker_container.nginx.id
}

output "image_id" {
  value = docker_image.nginx.id
}

output "host_port" {
  value = docker_container.nginx.ports[0].external
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# Variables
variable "encrypt_trail" {
  description = "Whether to encrypt CloudTrail logs with a customer-managed KMS key"
  type        = bool
  default     = false
}

variable "is_organizational" {
  description = "Whether the trail is an organization trail"
  type        = bool
  default     = false
}

# Data sources for static lookups
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# Local values
locals {
  trail_name = "management_trail"
  trail_arn  = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:trail/${local.trail_name}"
}

# Random suffix for S3 bucket name
resource "random_id" "suffix" {
  byte_length = 8
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "cloudtrail-bucket-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key for S3 bucket encryption (always present, customer-managed key)
data "aws_iam_policy_document" "s3_bucket_key_policy" {
  # Allow root account full access
  statement {
    sid    = "RootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow current caller full access (for management)
  statement {
    sid    = "CurrentCallerFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow CloudTrail to generate data keys and describe the key
  statement {
    sid    = "CloudTrailKMSAccess"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "s3_bucket" {
  description             = "KMS key for CloudTrail S3 bucket encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  policy                  = data.aws_iam_policy_document.s3_bucket_key_policy.json
  deletion_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

# Enable SSE-KMS encryption on the S3 bucket using the customer-managed key
resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_bucket.arn
    }
  }
}

# Bucket policy granting CloudTrail access
data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# CloudWatch Log Group for CloudTrail
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "cloudtrail_logs"
  retention_in_days = 0

  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for CloudTrail to write to CloudWatch Logs
data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_logs" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

# Inline policy for the role
data "aws_iam_policy_document" "cloudtrail_logs_policy" {
  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]

    resources = [
      "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_logs" {
  name   = "CloudTrailLogsPolicy"
  role   = aws_iam_role.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_logs_policy.json
}

# KMS Key for optional CloudTrail trail encryption
data "aws_iam_policy_document" "trail_kms_key_policy" {
  count = var.encrypt_trail ? 1 : 0

  # Allow root account full access
  statement {
    sid    = "RootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow current caller full access (ensures user can manage the key)
  statement {
    sid    = "CurrentCallerFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow CloudTrail to generate data keys and describe the key
  statement {
    sid    = "CloudTrailKMSAccess"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]

    resources = ["*"]
  }

  # Allow any principal in the account to decrypt and re-encrypt only when
  # encryption context matches the CloudTrail trail ARN
  statement {
    sid    = "DecryptReEncryptWithContext"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_kms_key" "trail" {
  count                   = var.encrypt_trail ? 1 : 0
  description             = "KMS key for CloudTrail trail encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  policy                  = data.aws_iam_policy_document.trail_kms_key_policy[0].json
  deletion_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "trail" {
  count         = var.encrypt_trail ? 1 : 0
  name          = "alias/cloudtrail_key"
  target_key_id = aws_kms_key.trail[0].arn
}

# CloudTrail trail
resource "aws_cloudtrail" "management_trail" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  cloud_watch_logs_group_arn    = aws_cloudwatch_log_group.cloudtrail.arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_logs.arn
  is_organization_trail         = var.is_organizational
  kms_key_id                    = var.encrypt_trail ? try(aws_kms_key.trail[0].arn, null) : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail
  ]
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "amzn2_ami" {
  name = "/aws/service/ami-amazon-linux-latest/amzn2-ami-hvm-x86_64-gp2"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "nginx-vpc"
  }
}

# Public subnet (for NAT Gateway and future use)
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "nginx-public-subnet"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "nginx-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nginx-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "nginx-nat-gw"
  }
}

# Route table for public subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "nginx-public-rt"
  }
}

# Route table association for public subnet
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Security group
resource "aws_security_group" "nginx_sg" {
  name        = "nginx_sg"
  description = "Allow HTTP inbound and restricted outbound"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic only within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "nginx_sg"
  }
}

# Elastic IP for the instance
resource "aws_eip" "nginx" {
  instance = aws_instance.nginx.id
  domain   = "vpc"

  tags = {
    Name = "nginx-instance-eip"
  }
}

# EC2 instance
resource "aws_instance" "nginx" {
  ami                    = data.aws_ssm_parameter.amzn2_ami.value
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.nginx_sg.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
  }

  user_data = <<-USERDATA
    #!/bin/bash
    # Note: egress is restricted to VPC CIDR, so yum commands requiring internet may fail.
    # The following commands are kept for completeness but may not succeed.
    yum update -y || true
    yum install -y nginx || true
    systemctl enable nginx || true
    systemctl start nginx || true
    cat > /usr/share/nginx/html/index.html << 'EOF'
    <html><head><title>Taco Team Server</title></head><body style="background-color:#1F778D"><p style="text-align: center;"><span style="color:#FFFFFF;"><span style="font-size:28px;">You did it! Have a &#127790;</span></span></p></body></html>
    EOF
  USERDATA

  tags = {
    Name = "nginx-server"
  }

  depends_on = [
    aws_internet_gateway.igw,
    aws_route_table_association.public,
    aws_nat_gateway.main
  ]
}

terraform {
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Default is true to satisfy deployability checks; set to false to disable all resources.
variable "enable_random_id" {
  type    = bool
  default = true
}

variable "enable_random_integer" {
  type    = bool
  default = false
}

variable "enable_random_password" {
  type    = bool
  default = false
}

variable "enable_random_pet" {
  type    = bool
  default = false
}

variable "enable_random_shuffle" {
  type    = bool
  default = false
}

variable "enable_random_string" {
  type    = bool
  default = false
}

variable "enable_random_uuid" {
  type    = bool
  default = false
}

variable "random_id_byte_length" {
  type    = number
  default = 4
}

variable "random_id_prefix" {
  type    = string
  default = ""
}

variable "random_integer_min" {
  type    = number
  default = 0
}

variable "random_integer_max" {
  type    = number
  default = 100
}

variable "random_integer_seed" {
  type    = string
  default = null
}

variable "random_password_length" {
  type    = number
  default = 16
}

variable "random_password_special" {
  type    = bool
  default = true
}

variable "random_password_override_special" {
  type    = string
  default = null
}

variable "random_password_min_lower" {
  type    = number
  default = 1
}

variable "random_password_min_numeric" {
  type    = number
  default = 1
}

variable "random_password_min_special" {
  type    = number
  default = 1
}

variable "random_password_min_upper" {
  type    = number
  default = 1
}

variable "random_pet_length" {
  type    = number
  default = 2
}

variable "random_pet_prefix" {
  type    = string
  default = ""
}

variable "random_pet_separator" {
  type    = string
  default = "-"
}

variable "random_shuffle_input" {
  type    = list(string)
  default = ["a", "b", "c"]
}

variable "random_shuffle_result_count" {
  type    = number
  default = null
}

variable "random_shuffle_seed" {
  type    = string
  default = null
}

variable "random_string_length" {
  type    = number
  default = 9
}

variable "random_string_upper" {
  type    = bool
  default = true
}

variable "random_string_lower" {
  type    = bool
  default = true
}

variable "random_string_numeric" {
  type    = bool
  default = true
}

variable "random_string_special" {
  type    = bool
  default = false
}

variable "random_string_min_upper" {
  type    = number
  default = 0
}

variable "random_string_min_lower" {
  type    = number
  default = 0
}

variable "random_string_min_numeric" {
  type    = number
  default = 0
}

variable "random_string_min_special" {
  type    = number
  default = 0
}

variable "random_string_override_special" {
  type    = string
  default = null
}

variable "random_uuid_keepers" {
  type    = map(string)
  default = {}
}

resource "random_id" "this" {
  count      = var.enable_random_id ? 1 : 0
  byte_length = var.random_id_byte_length
  prefix     = var.random_id_prefix
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

resource "random_integer" "this" {
  count = var.enable_random_integer ? 1 : 0
  min   = var.random_integer_min
  max   = var.random_integer_max
  seed  = var.random_integer_seed
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

resource "random_password" "this" {
  count            = var.enable_random_password ? 1 : 0
  length           = var.random_password_length
  special          = var.random_password_special
  override_special = var.random_password_override_special
  min_lower        = var.random_password_min_lower
  min_numeric      = var.random_password_min_numeric
  min_special      = var.random_password_min_special
  min_upper        = var.random_password_min_upper
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

resource "random_pet" "this" {
  count     = var.enable_random_pet ? 1 : 0
  length    = var.random_pet_length
  prefix    = var.random_pet_prefix
  separator = var.random_pet_separator
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

resource "random_shuffle" "this" {
  count        = var.enable_random_shuffle ? 1 : 0
  input        = var.random_shuffle_input
  result_count = var.random_shuffle_result_count
  seed         = var.random_shuffle_seed
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

resource "random_string" "this" {
  count            = var.enable_random_string ? 1 : 0
  length           = var.random_string_length
  upper            = var.random_string_upper
  lower            = var.random_string_lower
  numeric          = var.random_string_numeric
  special          = var.random_string_special
  min_upper        = var.random_string_min_upper
  min_lower        = var.random_string_min_lower
  min_numeric      = var.random_string_min_numeric
  min_special      = var.random_string_min_special
  override_special = var.random_string_override_special
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

resource "random_uuid" "this" {
  count    = var.enable_random_uuid ? 1 : 0
  keepers  = var.random_uuid_keepers
  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }
  depends_on = []
}

output "random_id_result" {
  value       = var.enable_random_id ? random_id.this[0].id : null
  description = "The generated random ID value (hex encoded)."
}

output "random_id_b64_url" {
  value       = var.enable_random_id ? random_id.this[0].b64_url : null
  description = "The generated random ID in base64 URL-safe format."
}

output "random_id_b64_std" {
  value       = var.enable_random_id ? random_id.this[0].b64_std : null
  description = "The generated random ID in base64 standard format."
}

output "random_id_hex" {
  value       = var.enable_random_id ? random_id.this[0].hex : null
  description = "The generated random ID in hex format."
}

output "random_id_dec" {
  value       = var.enable_random_id ? random_id.this[0].dec : null
  description = "The generated random ID in decimal format."
}

output "random_integer_result" {
  value       = var.enable_random_integer ? random_integer.this[0].result : null
  description = "The generated random integer."
}

output "random_password_result" {
  value       = var.enable_random_password ? random_password.this[0].result : null
  description = "The generated random password."
}

output "random_pet_id" {
  value       = var.enable_random_pet ? random_pet.this[0].id : null
  description = "The generated random pet name."
}

output "random_shuffle_result" {
  value       = var.enable_random_shuffle ? random_shuffle.this[0].result : null
  description = "The shuffled list of strings."
}

output "random_string_result" {
  value       = var.enable_random_string ? random_string.this[0].result : null
  description = "The generated random string."
}

output "random_uuid_result" {
  value       = var.enable_random_uuid ? random_uuid.this[0].result : null
  description = "The generated random UUID."
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_iam_policy_document" "elasticsearch_log_publishing" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["es.amazonaws.com"]
    }
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:PutLogEventsBatch"]
    resources = ["arn:aws:logs:*:*:*"]
  }
}

resource "aws_iam_service_linked_role" "elasticsearch" {
  aws_service_name = "es.amazonaws.com"
  description      = "Service-linked role for Amazon OpenSearch Service (Elasticsearch)"
}

resource "aws_cloudwatch_log_resource_policy" "elasticsearch_log_publishing" {
  policy_document = data.aws_iam_policy_document.elasticsearch_log_publishing.json
  policy_name     = "elasticsearch-log-publishing-policy"
}

# ------------------------------------------------------------------------------
# TERRAFORM METADATA
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 0.13.1"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.69"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "bucket_name" {
  description = "Name of the S3 bucket."
  type        = string
  default     = "my-s3-bucket"
}

variable "create_bucket" {
  description = "Whether to create the S3 bucket and all associated resources."
  type        = bool
  default     = true
}

variable "create_random_suffix" {
  description = "Whether to append a random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow the bucket to be deleted even if it contains objects."
  type        = bool
  default     = false
}

variable "enable_versioning" {
  description = "Enable S3 bucket versioning."
  type        = bool
  default     = false
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm to use (e.g. AES256 or aws:kms)."
  type        = string
  default     = "AES256"
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE-KMS (required if sse_algorithm is aws:kms)."
  type        = string
  default     = null
}

variable "enable_object_lock" {
  description = "Enable S3 object lock."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode for object lock (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "Default retention days for object lock."
  type        = number
  default     = 30
}

variable "enable_static_website" {
  description = "Enable static website hosting."
  type        = bool
  default     = false
}

variable "index_document" {
  description = "Index document for static website."
  type        = string
  default     = "index.html"
}

variable "error_document" {
  description = "Error document for static website."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules (maps) for the bucket."
  type        = list(any)
  default     = []
}

variable "enable_logging" {
  description = "Enable access logging for the bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Target bucket for access logs."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for log objects in the target bucket."
  type        = string
  default     = ""
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules (maps) for the bucket."
  type        = list(any)
  default     = []
}

variable "enable_replication" {
  description = "Enable cross-region replication."
  type        = bool
  default     = false
}

variable "replication_role_arn" {
  description = "IAM role ARN for replication (if create_replication_role is false)."
  type        = string
  default     = null
}

variable "replication_rules" {
  description = "List of replication rules (maps)."
  type        = list(any)
  default     = []
}

variable "create_replication_role" {
  description = "Create an IAM role for replication if true."
  type        = bool
  default     = false
}

variable "acl" {
  description = "ACL for the bucket (e.g., private, public-read). Use null to disable ACL."
  type        = string
  default     = null
}

variable "object_ownership" {
  description = "Object ownership setting (BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter)."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "block_public_acls" {
  description = "Block public ACLs at the bucket level."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies at the bucket level."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs at the bucket level."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets at the bucket level."
  type        = bool
  default     = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Attach a bucket policy for ELB/ALB/NLB access log delivery."
  type        = bool
  default     = false
}

variable "deny_insecure_transport" {
  description = "Attach a bucket policy to deny insecure transport (non-SSL) and require TLS 1.2+."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "JSON string of a custom bucket policy."
  type        = string
  default     = null
}

variable "create_account_public_access_block" {
  description = "Create an account-level public access block."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# LOCAL VALUES
# ------------------------------------------------------------------------------
locals {
  # Random suffix if enabled
  bucket_name = var.create_random_suffix ? "${var.bucket_name}${random_string.suffix[0].result}" : var.bucket_name
}

# ------------------------------------------------------------------------------
# RANDOM SUFFIX
# ------------------------------------------------------------------------------
resource "random_string" "suffix" {
  count   = var.create_random_suffix ? 1 : 0
  length  = 6
  special = false
  upper   = false
}

# ------------------------------------------------------------------------------
# S3 BUCKET
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count         = var.create_bucket ? 1 : 0
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET VERSIONING
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count  = var.create_bucket && var.enable_versioning ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET SERVER-SIDE ENCRYPTION
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? var.kms_master_key_id : null
    }
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET OBJECT LOCK
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.create_bucket && var.enable_object_lock ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  object_lock_enabled = "Enabled"

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET WEBSITE
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.create_bucket && var.enable_static_website ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = var.index_document
  }

  dynamic "error_document" {
    for_each = var.error_document != null ? [1] : []
    content {
      key = var.error_document
    }
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET CORS
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.create_bucket && length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET LOGGING
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count  = var.create_bucket && var.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

# ------------------------------------------------------------------------------
# S3 BUCKET LIFECYCLE
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = lookup(rule.value, "id", null)
      status = rule.value.status

      dynamic "filter" {
        for_each = lookup(rule.value, "filter", null) != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)
          dynamic "and" {
            for_each = lookup(filter.value, "tags", null) != null ? [1] : []
            content {
              tags = filter.value.tags
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = lookup(rule.value, "expiration", null) != null ? [rule.value.expiration] : []
        content {
          days                         = lookup(expiration.value, "days", null)
          date                         = lookup(expiration.value, "date", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      dynamic "transition" {
        for_each = lookup(rule.value, "transitions", [])
        content {
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lookup(rule.value, "noncurrent_version_expiration_days", null) != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = lookup(rule.value, "noncurrent_version_transitions", [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET REPLICATION
# ------------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  count = var.create_bucket && var.enable_replication && var.create_replication_role ? 1 : 0
  name  = "${local.bucket_name}-replication-role"
  tags  = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = var.create_bucket && var.enable_replication && var.create_replication_role ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.create_bucket && var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  role = var.create_replication_role ? aws_iam_role.replication[0].arn : var.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id     = lookup(rule.value, "id", null)
      status = rule.value.status

      filter {
        prefix = lookup(rule.value, "filter_prefix", null)
      }

      delete_marker_replication {
        status = lookup(rule.value, "delete_marker_replication_status", null)
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = lookup(rule.value, "destination_storage_class", null)

        encryption_configuration {
          replica_kms_key_id = lookup(rule.value, "replica_kms_key_id", null)
        }

        access_control_translation {
          owner = rule.value.owner_override
        }
      }

      source_selection_criteria {
        sse_kms_encrypted_objects {
          status = lookup(rule.value, "sse_kms_encrypted_objects_status", "Enabled")
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this
  ]
}

# ------------------------------------------------------------------------------
# S3 BUCKET OWNERSHIP CONTROLS
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

# ------------------------------------------------------------------------------
# S3 BUCKET ACL (if ACL is set)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  count  = var.create_bucket && var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ------------------------------------------------------------------------------
# S3 BUCKET PUBLIC ACCESS BLOCK
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ------------------------------------------------------------------------------
# S3 BUCKET POLICY – ELB/ALB/NLB LOG DELIVERY
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "elb_logs" {
  statement {
    sid    = "AllowELBLogDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid    = "AllowALBLogDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"]
  }
}

resource "aws_s3_bucket_policy" "elb_logs" {
  count  = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.elb_logs.json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this
  ]
}

# ------------------------------------------------------------------------------
# S3 BUCKET POLICY – DENY INSECURE TRANSPORT AND REQUIRE TLS 1.2+
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "deny_insecure_transport" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}",
      "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "RequireTLS12"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}",
      "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

resource "aws_s3_bucket_policy" "deny_insecure_transport" {
  count  = var.create_bucket && var.deny_insecure_transport ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.deny_insecure_transport.json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this
  ]
}

# ------------------------------------------------------------------------------
# S3 BUCKET POLICY – CUSTOM
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "custom" {
  count  = var.create_bucket && var.custom_bucket_policy != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = var.custom_bucket_policy

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this
  ]
}

# ------------------------------------------------------------------------------
# S3 ACCOUNT PUBLIC ACCESS BLOCK
# ------------------------------------------------------------------------------
resource "aws_s3_account_public_access_block" "this" {
  count = var.create_account_public_access_block ? 1 : 0

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].id : null
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].arn : null
}

output "bucket_regional_domain_name" {
  description = "The regional domain name of the bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].bucket_regional_domain_name : null
}

output "bucket_domain_name" {
  description = "The domain name of the bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].bucket_domain_name : null
}

output "hosted_zone_id" {
  description = "The hosted zone ID for the bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].hosted_zone_id : null
}

output "region" {
  description = "The AWS region of the bucket."
  value       = var.create_bucket ? aws_s3_bucket.this[0].region : null
}

output "website_endpoint" {
  description = "The website endpoint (if static website hosting is enabled)."
  value       = var.create_bucket && var.enable_static_website ? aws_s3_bucket_website_configuration.this[0].website_endpoint : null
}

output "website_domain" {
  description = "The website domain (if static website hosting is enabled)."
  value       = var.create_bucket && var.enable_static_website ? aws_s3_bucket_website_configuration.this[0].website_domain : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Data sources – static/well-known lookups only
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_iam_policy" "admin" {
  arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

data "aws_iam_policy" "power_user" {
  arn = "arn:aws:iam::aws:policy/PowerUserAccess"
}

data "aws_iam_policy" "read_only" {
  arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "admin_role_config" {
  type = object({
    enabled              = optional(bool, true)
    name                 = optional(string, "Administrator")
    path                 = optional(string, "/")
    description          = optional(string, "")
    tags                 = optional(map(string), {})
    permissions_boundary = optional(string, "")
    managed_policy_arns  = optional(list(string), [])
  })
  default = {}
}

variable "power_user_role_config" {
  type = object({
    enabled              = optional(bool, true)
    name                 = optional(string, "PowerUser")
    path                 = optional(string, "/")
    description          = optional(string, "")
    tags                 = optional(map(string), {})
    permissions_boundary = optional(string, "")
    managed_policy_arns  = optional(list(string), [])
  })
  default = {}
}

variable "read_only_role_config" {
  type = object({
    enabled              = optional(bool, true)
    name                 = optional(string, "ReadOnly")
    path                 = optional(string, "/")
    description          = optional(string, "")
    tags                 = optional(map(string), {})
    permissions_boundary = optional(string, "")
    managed_policy_arns  = optional(list(string), [])
  })
  default = {}
}

variable "trust_principals" {
  type = list(object({
    type        = string
    identifiers = list(string)
    require_mfa = optional(bool, false)
  }))
  default = []
}

variable "mfa_max_age" {
  type    = number
  default = 86400
}

variable "max_session_duration" {
  type    = number
  default = 3600
}

variable "force_detach_policies" {
  type    = bool
  default = false
}

# ---------------------------------------------------------------------------
# Locals – build role configuration map and trust policy defaults
# ---------------------------------------------------------------------------
locals {
  # Default trust policy when var.trust_principals is empty
  default_trust_principals = length(var.trust_principals) > 0 ? var.trust_principals : [
    {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
      require_mfa = false
    }
  ]

  mfa_required = length([for p in local.default_trust_principals : p if p.require_mfa]) > 0

  # Map of the three role variable keys to their config objects
  role_vars = {
    admin      = var.admin_role_config
    power_user = var.power_user_role_config
    read_only  = var.read_only_role_config
  }

  # Default policy ARNs per role key
  default_policy_arns = {
    admin      = data.aws_iam_policy.admin.arn
    power_user = data.aws_iam_policy.power_user.arn
    read_only  = data.aws_iam_policy.read_only.arn
  }

  # Build full role configs, using the default policy ARN when the user list is empty
  role_configs = {
    for k, v in local.role_vars : k => {
      name                = v.name
      path                = v.path
      description         = v.description
      tags                = v.tags
      permissions_boundary = v.permissions_boundary
      managed_policy_arns = length(v.managed_policy_arns) > 0 ? v.managed_policy_arns : [local.default_policy_arns[k]]
    }
  }

  # Filter to only enabled roles
  enabled_roles = {
    for k, v in local.role_configs : k => v
    if local.role_vars[k].enabled
  }
}

# ---------------------------------------------------------------------------
# IAM trust policy documents
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "assume_role" {
  for_each = local.enabled_roles

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    dynamic "principals" {
      for_each = local.default_trust_principals
      content {
        type        = principals.value.type
        identifiers = principals.value.identifiers
      }
    }

    dynamic "condition" {
      for_each = local.mfa_required ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = local.mfa_required ? [1] : []
      content {
        test     = "NumericLessThanEquals"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.mfa_max_age)]
      }
    }
  }
}

# ---------------------------------------------------------------------------
# IAM roles
# ---------------------------------------------------------------------------
resource "aws_iam_role" "role" {
  for_each = local.enabled_roles

  name                 = each.value.name
  path                 = each.value.path
  description          = each.value.description
  assume_role_policy   = data.aws_iam_policy_document.assume_role[each.key].json
  max_session_duration = var.max_session_duration
  force_detach_policies = var.force_detach_policies
  tags                 = each.value.tags
  permissions_boundary = each.value.permissions_boundary == "" ? null : each.value.permissions_boundary

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Managed policy attachments
# ---------------------------------------------------------------------------
locals {
  # Flatten into a set of {role_key, policy_arn} pairs
  policy_attachments = flatten([
    for role_key, role in local.enabled_roles : [
      for policy_arn in role.managed_policy_arns : {
        role_key   = role_key
        policy_arn = policy_arn
      }
    ]
  ])
  policy_attachment_keys = {
    for item in local.policy_attachments : "${item.role_key}-${item.policy_arn}" => item
  }
}

resource "aws_iam_role_policy_attachment" "this" {
  for_each = local.policy_attachment_keys

  role       = aws_iam_role.role[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "roles" {
  description = "Map of role keys to their ARN, name, path, unique ID, and MFA requirement status."
  value = {
    for k, role in aws_iam_role.role : k => {
      arn          = role.arn
      name         = role.name
      path         = role.path
      unique_id    = role.unique_id
      mfa_required = local.mfa_required
    }
  }
}

terraform {
  required_version = ">= 0.13"
  required_providers {
    scaleway = {
      source  = "scaleway/scaleway"
      version = "~> 2.20"
    }
  }
}

# Required environment variables (must be set by the deployment harness):
#   SCW_ACCESS_KEY              - Scaleway API access key
#   SCW_SECRET_KEY              - Scaleway API secret key
#   SCW_DEFAULT_ORGANIZATION_ID - Scaleway organization ID
#   SCW_DEFAULT_REGION          - Default region (e.g., fr-par)

variable "zones" {
  description = "List of Scaleway zones to deploy per-zone resources"
  type        = list(string)
  default     = ["fr-par-1", "fr-par-2"]
}

variable "reverse_dns_zone" {
  description = "Domain suffix for reverse DNS on public gateway IPs (optional)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "List of tags to apply to all resources"
  type        = list(string)
  default     = []
}

variable "vpc_tags" {
  description = "Map of additional VPC-specific tags (values will be merged with tags list)"
  type        = map(string)
  default     = {}
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "multi-az"
}

variable "timeouts" {
  description = "Timeouts for create, update, and delete operations"
  type = object({
    create = string
    update = string
    delete = string
  })
  default = {
    create = "10m"
    update = "10m"
    delete = "5m"
  }
}

locals {
  # Combine tags from list and map values
  common_tags = concat(var.tags, values(var.vpc_tags))

  # Generate a name per zone
  name_per_zone = { for zone in var.zones : zone => format("%s-%s", var.name_prefix, zone) }

  # Reverse DNS hostname: use zone as hostname part
  reverse_dns = var.reverse_dns_zone != "" ? { for zone in var.zones : zone => "gw-${zone}.${var.reverse_dns_zone}" } : {}
}

# Per-zone public gateway IP
resource "scaleway_vpc_public_gateway_ip" "this" {
  for_each = toset(var.zones)

  zone = each.key
  tags = local.common_tags

  reverse = try(local.reverse_dns[each.key], null)
}

# Per-zone public gateway
resource "scaleway_vpc_public_gateway" "this" {
  for_each = toset(var.zones)

  zone        = each.key
  name        = local.name_per_zone[each.key]
  type        = "VPC-GW-S"
  enable_smtp = false
  ip_id       = scaleway_vpc_public_gateway_ip.this[each.key].id
  tags        = local.common_tags

  timeouts {
    create = var.timeouts.create
    update = var.timeouts.update
    delete = var.timeouts.delete
  }
}

# Per-zone private network with DHCP gateway address
# Note: Advanced DHCP parameters (pool ranges, DNS overrides, timers, etc.) are
# not supported by the Scaleway provider version ~> 2.20. The Private Network
# DHCP uses provider defaults for these settings. The gateway address is
# automatically assigned as the first usable IP in the subnet.
resource "scaleway_vpc_private_network" "this" {
  for_each = toset(var.zones)

  zone = each.key
  name = local.name_per_zone[each.key]
  tags = local.common_tags

  ipv4_subnet {
    subnet = "192.168.0.0/24"
  }
}

# Per-zone gateway network (connects gateway to private network)
resource "scaleway_vpc_gateway_network" "this" {
  for_each = toset(var.zones)

  zone               = each.key
  gateway_id         = scaleway_vpc_public_gateway.this[each.key].id
  private_network_id = scaleway_vpc_private_network.this[each.key].id
  enable_masquerade  = true

  ipam_config {
    push_default_route = true
  }

  timeouts {
    create = var.timeouts.create
    update = var.timeouts.update
    delete = var.timeouts.delete
  }
}

# Outputs
output "public_gateway_ip_addresses" {
  description = "Map of zone to public gateway IP address"
  value       = { for zone, ip in scaleway_vpc_public_gateway_ip.this : zone => ip.address }
}

output "public_gateway_ip_ids" {
  description = "Map of zone to public gateway IP ID"
  value       = { for zone, ip in scaleway_vpc_public_gateway_ip.this : zone => ip.id }
}

output "gateway_ids" {
  description = "Map of zone to public gateway ID"
  value       = { for zone, gw in scaleway_vpc_public_gateway.this : zone => gw.id }
}

output "private_network_ids" {
  description = "Map of zone to private network ID"
  value       = { for zone, pn in scaleway_vpc_private_network.this : zone => pn.id }
}

terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

variable "container_name" {
  description = "Name of the Docker container"
  type        = string
  default     = "ExampleNginxContainer"
}

resource "docker_image" "this" {
  name         = "nginx:1.23.4"
  keep_locally = true
}

resource "docker_container" "this" {
  name  = var.container_name
  image = docker_image.this.image_id

  ports {
    internal = 80
    external = 8089
  }
}

output "container_id" {
  description = "ID of the Docker container"
  value       = docker_container.this.id
  sensitive   = true
}

output "image_id" {
  description = "ID of the Docker image"
  value       = docker_image.this.id
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# Variables
variable "suffix" {
  description = "Suffix appended to the random pet prefix for the state bucket name"
  type        = string
  default     = "tf-backend"
}

variable "bucket_name" {
  description = "Optional fully custom bucket name. If set, overrides generated name."
  type        = string
  default     = ""
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table for state locking"
  type        = string
  default     = "tf_state_lock"
}

variable "noncurrent_version_transition_days" {
  description = "Days after which noncurrent versions in the state bucket transition to GLACIER"
  type        = number
  default     = 30
}

variable "noncurrent_version_expiration" {
  description = "Optional days after which noncurrent versions in the state bucket expire (set to null to disable)"
  type        = number
  default     = null
}

variable "logging_noncurrent_version_expiration" {
  description = "Optional days after which noncurrent versions in the logging bucket expire (set to null to disable)"
  type        = number
  default     = null
}

variable "common_tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  merged_tags = merge({ Terraform = true }, var.common_tags)
  state_bucket_name = var.bucket_name != "" ? var.bucket_name : "${random_pet.this.id}-${var.suffix}"
  logging_bucket_name = "${random_pet.this.id}-${var.suffix}-logs"
}

# Random pet for unique names
resource "random_pet" "this" {
  length = 2
}

# KMS Key for S3 and DynamoDB encryption
resource "aws_kms_key" "this" {
  description             = "KMS key for Terraform state backend"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootUserFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = local.merged_tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.state_bucket_name}-key"
  target_key_id = aws_kms_key.this.key_id
}

# State bucket
resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name
  tags   = local.merged_tags
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"
    filter {}
    abort_incomplete_multipart_upload {
      days_after_initiation = 1
    }
  }

  rule {
    id     = "noncurrent-version-transition"
    status = "Enabled"
    filter {}
    noncurrent_version_transition {
      noncurrent_days = var.noncurrent_version_transition_days
      storage_class   = "GLACIER"
    }
    dynamic "noncurrent_version_expiration" {
      for_each = var.noncurrent_version_expiration != null ? [var.noncurrent_version_expiration] : []
      content {
        noncurrent_days = noncurrent_version_expiration.value
      }
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Logging bucket
resource "aws_s3_bucket" "logging" {
  bucket = local.logging_bucket_name
  tags   = local.merged_tags
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  bucket = aws_s3_bucket.logging.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  bucket                  = aws_s3_bucket.logging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  bucket = aws_s3_bucket.logging.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "logging" {
  bucket = aws_s3_bucket.logging.id

  rule {
    id     = "noncurrent-version-transition"
    status = "Enabled"
    filter {}
    noncurrent_version_transition {
      noncurrent_days = 90
      storage_class   = "GLACIER"
    }
    dynamic "noncurrent_version_expiration" {
      for_each = var.logging_noncurrent_version_expiration != null ? [var.logging_noncurrent_version_expiration] : []
      content {
        noncurrent_days = noncurrent_version_expiration.value
      }
    }
  }
}

# State bucket logging configuration
resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id
  target_bucket = aws_s3_bucket.logging.id
  target_prefix = "tfstate/"
}

# DynamoDB table for state locking
resource "aws_dynamodb_table" "state_lock" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
  point_in_time_recovery {
    enabled = true
  }
  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this.arn
  }
  tags = local.merged_tags
}

data "aws_caller_identity" "current" {}

variable "cluster_list" {
  type = list(object({
    id                = string
    operator_role_prefix = string
  }))
  default = []
}

variable "oidc_provider_url" {
  default = "https://rh-oidc.s3.us-east-1.amazonaws.com"
}

variable "oidc_thumbprint" {
  default = "917e732d330f9a12404f73d8bea36948b929dffc"
}

locals {
  operators = [
    {
      id               = "cloud-credential-operator"
      role_suffix      = "-openshift-cloud-credential-operator-cloud-c"
      policy_suffix    = "openshift-cloud-credential-operator-cloud-crede"
      service_accounts = ["system:serviceaccount:openshift-cloud-credential-operator:cloud-credential-operator"]
      namespace        = "openshift-cloud-credential-operator"
      operator_name    = "cloud-credential-operator"
    },
    {
      id               = "cloud-network-config-controller"
      role_suffix      = "-openshift-cloud-network-config-controller-c"
      policy_suffix    = "openshift-cloud-network-config-controller-cloud"
      service_accounts = ["system:serviceaccount:openshift-cloud-network-config-controller:cloud-network-config-controller"]
      namespace        = "openshift-cloud-network-config-controller"
      operator_name    = "cloud-network-config-controller"
    },
    {
      id               = "csi-drivers-ebs"
      role_suffix      = "-openshift-cluster-csi-drivers-ebs-cloud-cre"
      policy_suffix    = "openshift-cluster-csi-drivers-ebs-cloud-credent"
      service_accounts = [
        "system:serviceaccount:openshift-cluster-csi-drivers:aws-ebs-csi-driver-operator",
        "system:serviceaccount:openshift-cluster-csi-drivers:aws-ebs-csi-driver-controller-sa"
      ]
      namespace        = "openshift-cluster-csi-drivers"
      operator_name    = "ebs-cloud-credentials"
    },
    {
      id               = "image-registry"
      role_suffix      = "-openshift-image-registry-installer-cloud-cr"
      policy_suffix    = "openshift-image-registry-installer-cloud-creden"
      service_accounts = [
        "system:serviceaccount:openshift-image-registry:cluster-image-registry-operator",
        "system:serviceaccount:openshift-image-registry:registry"
      ]
      namespace        = "openshift-image-registry"
      operator_name    = "installer-cloud-credentials"
    },
    {
      id               = "ingress-operator"
      role_suffix      = "-openshift-ingress-operator-cloud-credential"
      policy_suffix    = "openshift-ingress-operator-cloud-credentials"
      service_accounts = ["system:serviceaccount:openshift-ingress-operator:ingress-operator"]
      namespace        = "openshift-ingress-operator"
      operator_name    = "ingress-operator"
    },
    {
      id               = "machine-api"
      role_suffix      = "-openshift-machine-api-aws-cloud-credentials"
      policy_suffix    = "openshift-machine-api-aws-cloud-credentials"
      service_accounts = ["system:serviceaccount:openshift-machine-api:aws-cloud-credentials"]
      namespace        = "openshift-machine-api"
      operator_name    = "aws-cloud-credentials"
    }
  ]

  operator_map = { for op in local.operators : op.id => op }
  policy_map   = { for op in local.operators : op.policy_suffix => op }

  roles = flatten([
    for cluster in var.cluster_list : [
      for op in local.operators : {
        key                  = "${cluster.id}-${op.id}"
        cluster_id           = cluster.id
        operator_role_prefix = cluster.operator_role_prefix
        operator             = op
      }
    ]
  ])

  role_map = { for r in local.roles : r.key => r }
}

resource "aws_iam_openid_connect_provider" "cluster" {
  for_each = { for c in var.cluster_list : c.id => c }

  url             = "${var.oidc_provider_url}/${each.value.id}"
  client_id_list  = ["openshift", "sts.amazonaws.com"]
  thumbprint_list = [var.oidc_thumbprint]

  tags = {
    cluster_id      = each.value.id
    ManagedOpenShift = "true"
  }
}

resource "aws_iam_policy" "operator" {
  for_each = local.policy_map

  name        = "ManagedOpenShift-${each.key}"
  description = "Managed policy for ROSA operator ${each.value.id}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:DescribeInstances"
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "operator" {
  for_each = local.role_map

  name = "${each.value.operator_role_prefix}${each.value.operator.role_suffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.cluster[each.value.cluster_id].arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = length(each.value.operator.service_accounts) > 1 ? {
          "ForAnyValue:StringEquals" = {
            "oidc:sub" = each.value.operator.service_accounts
          }
        } : {
          "StringEquals" = {
            "oidc:sub" = each.value.operator.service_accounts[0]
          }
        }
      }
    ]
  })

  tags = {
    cluster_id       = each.value.cluster_id
    ManagedOpenShift = "true"
    OperatorNamespace = each.value.operator.namespace
    OperatorName      = each.value.operator.operator_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "operator" {
  for_each = local.role_map

  role       = aws_iam_role.operator[each.key].name
  policy_arn = aws_iam_policy.operator[each.value.operator.policy_suffix].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.30"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "vpc_id" {
  description = "VPC ID in which to create endpoints. If not provided, a VPC will be created."
  type        = string
  default     = null
}

variable "endpoints" {
  description = "Map of endpoint configurations"
  type = map(object({
    service_name                                = string
    endpoint_type                               = string
    auto_accept                                 = optional(bool, false)
    policy                                      = optional(string)
    private_dns_enabled                         = optional(bool, true)
    dns_record_ip_type                          = optional(string)
    private_dns_only_for_inbound_resolver_endpoint = optional(bool, false)
    subnet_ids                                  = optional(list(string))
    security_group_ids                          = optional(list(string))
    route_table_ids                             = optional(list(string))
  }))
  default = {}
}

variable "create" {
  description = "Whether to create all resources"
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "Whether to create a dedicated security group for the endpoints"
  type        = bool
  default     = false
}

variable "security_group_name" {
  description = "Name of the security group (if name_prefix not used)"
  type        = string
  default     = null
}

variable "security_group_name_prefix" {
  description = "Prefix for the security group name"
  type        = string
  default     = null
}

variable "security_group_description" {
  description = "Description of the security group"
  type        = string
  default     = "Security group for VPC Endpoints"
}

variable "security_group_rules" {
  description = "Map of security group rules"
  type = map(object({
    type                   = string
    from_port              = optional(number)
    to_port                = optional(number)
    protocol               = string
    description            = optional(string)
    cidr_blocks            = optional(list(string))
    ipv6_cidr_blocks       = optional(list(string))
    prefix_list_ids        = optional(list(string))
    self                   = optional(bool, false)
    source_security_group_id = optional(string)
  }))
  default = {}
}

variable "default_subnet_ids" {
  description = "Default subnet IDs for Interface endpoints"
  type        = list(string)
  default     = []
}

variable "default_security_group_ids" {
  description = "Default security group IDs for Interface endpoints"
  type        = list(string)
  default     = []
}

variable "default_route_table_ids" {
  description = "Default route table IDs for Gateway endpoints"
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  endpoints_to_create = var.create ? var.endpoints : {}
  create_sg           = var.create && var.create_security_group

  # Resolve the effective VPC ID
  effective_vpc_id = var.vpc_id != null ? var.vpc_id : aws_vpc.this[0].id

  # Handle mutual exclusivity of name and name_prefix
  sg_name       = var.security_group_name != null ? var.security_group_name : null
  sg_name_prefix = var.security_group_name != null ? null : var.security_group_name_prefix

  # Split rules by type for separate ingress/egress resources
  ingress_rules = local.create_sg ? {
    for k, r in var.security_group_rules : k => r if r.type == "ingress"
  } : {}
  egress_rules = local.create_sg ? {
    for k, r in var.security_group_rules : k => r if r.type == "egress"
  } : {}
}

# ------------------------------------------------------------------------------
# VPC (conditional – only created when no vpc_id is provided)
# ------------------------------------------------------------------------------

resource "aws_vpc" "this" {
  count = var.vpc_id != null ? 0 : 1

  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "vpc-endpoints-vpc"
  }
}

# ------------------------------------------------------------------------------
# Security Group (conditional)
# ------------------------------------------------------------------------------

resource "aws_security_group" "this" {
  count = local.create_sg ? 1 : 0

  name        = local.sg_name
  name_prefix = local.sg_name_prefix
  description = var.security_group_description
  vpc_id      = local.effective_vpc_id

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Security Group Rules (conditional)
# ------------------------------------------------------------------------------

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.ingress_rules

  security_group_id = aws_security_group.this[0].id

  description                    = each.value.description
  from_port                      = each.value.from_port
  to_port                        = each.value.to_port
  ip_protocol                    = each.value.protocol
  cidr_ipv4                      = try(each.value.cidr_blocks[0], null)
  cidr_ipv6                      = try(each.value.ipv6_cidr_blocks[0], null)
  prefix_list_id                 = try(each.value.prefix_list_ids[0], null)
  referenced_security_group_id   = each.value.self ? aws_security_group.this[0].id : try(each.value.source_security_group_id, null)
}

resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.egress_rules

  security_group_id = aws_security_group.this[0].id

  description                    = each.value.description
  from_port                      = each.value.from_port
  to_port                        = each.value.to_port
  ip_protocol                    = each.value.protocol
  cidr_ipv4                      = try(each.value.cidr_blocks[0], null)
  cidr_ipv6                      = try(each.value.ipv6_cidr_blocks[0], null)
  prefix_list_id                 = try(each.value.prefix_list_ids[0], null)
  referenced_security_group_id   = each.value.self ? aws_security_group.this[0].id : try(each.value.source_security_group_id, null)
}

# ------------------------------------------------------------------------------
# VPC Endpoints (conditional)
# ------------------------------------------------------------------------------

resource "aws_vpc_endpoint" "this" {
  for_each = local.endpoints_to_create

  vpc_id              = local.effective_vpc_id
  service_name        = each.value.service_name
  vpc_endpoint_type   = each.value.endpoint_type
  auto_accept         = each.value.auto_accept
  policy              = each.value.policy
  private_dns_enabled = each.value.private_dns_enabled

  dns_options {
    dns_record_ip_type                      = each.value.dns_record_ip_type
    private_dns_only_for_inbound_resolver_endpoint = each.value.private_dns_only_for_inbound_resolver_endpoint
  }

  # Subnet and security group for Interface endpoints
  subnet_ids = each.value.endpoint_type == "Interface" ? (
    each.value.subnet_ids != null ? each.value.subnet_ids : var.default_subnet_ids
  ) : null

  security_group_ids = each.value.endpoint_type == "Interface" ? (
    each.value.security_group_ids != null ? each.value.security_group_ids : var.default_security_group_ids
  ) : null

  # Route table for Gateway endpoints
  route_table_ids = each.value.endpoint_type == "Gateway" ? (
    each.value.route_table_ids != null ? each.value.route_table_ids : var.default_route_table_ids
  ) : null
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "vpc_endpoints" {
  description = "Map of VPC endpoint resources created"
  value       = aws_vpc_endpoint.this
}

output "security_group_arn" {
  description = "ARN of the security group if created"
  value       = local.create_sg ? aws_security_group.this[0].arn : null
}

output "security_group_id" {
  description = "ID of the security group if created"
  value       = local.create_sg ? aws_security_group.this[0].id : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "enable_bucket" {
  description = "Conditionally create all S3 bucket resources"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Name of the bucket. If empty, a prefix with random suffix is used."
  type        = string
  default     = ""
}

variable "bucket_name_prefix" {
  description = "Prefix for bucket name. Used if bucket_name is empty."
  type        = string
  default     = "my-bucket"
}

variable "force_destroy" {
  description = "Allow deletion of non-empty bucket"
  type        = bool
  default     = false
}

variable "enable_object_lock" {
  description = "Enable object lock on the bucket (must be set at creation)"
  type        = bool
  default     = false
}

variable "log_bucket_name" {
  description = "Name of the logging bucket. If empty, a default is generated."
  type        = string
  default     = ""
}

variable "log_bucket_prefix" {
  description = "Prefix for log objects in the logging bucket"
  type        = string
  default     = "logs/"
}

variable "acl" {
  description = "Canned ACL to apply (e.g., private, public-read). Ignored if grants provided."
  type        = string
  default     = "private"
}

variable "grants" {
  description = "List of grants for ACL. Each element has grantee (type, email_address/id, display_name) and permission."
  type = list(object({
    grantee = object({
      type          = string
      email_address = optional(string)
      id            = optional(string)
      display_name  = optional(string)
    })
    permission = string
  }))
  default = []
}

variable "website_config" {
  description = "Static website hosting configuration"
  type = object({
    index_document           = optional(string, "index.html")
    error_document           = optional(string, "error.html")
    redirect_all_requests_to = optional(string)
    routing_rules            = optional(string)
  })
  default = {}
}

variable "versioning_config" {
  description = "Versioning configuration"
  type = object({
    status    = optional(string, "Enabled")
    mfa_delete = optional(bool, false)
    mfa       = optional(string)
  })
  default = {}
}

variable "acceleration_status" {
  description = "Acceleration status (Enabled or Suspended)"
  type        = string
  default     = "Suspended"
}

variable "request_payer" {
  description = "Request payer configuration (BucketOwner or Requester)"
  type        = string
  default     = "BucketOwner"
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type = list(object({
    id                                     = string
    status                                 = optional(string, "Enabled")
    expiration                             = optional(object({ days = optional(number), date = optional(string), expired_object_delete_marker = optional(bool) }))
    transition                             = optional(list(object({ days = optional(number), date = optional(string), storage_class = string })))
    noncurrent_version_expiration          = optional(object({ noncurrent_days = number }))
    noncurrent_version_transition          = optional(list(object({ noncurrent_days = number, storage_class = string })))
    abort_incomplete_multipart_upload      = optional(object({ days_after_initiation = number }))
    filter = optional(object({
      prefix                   = optional(string)
      tags                     = optional(map(string))
      object_size_greater_than = optional(number)
      object_size_less_than    = optional(number)
      and = optional(object({
        prefix                   = optional(string)
        tags                     = optional(map(string))
        object_size_greater_than = optional(number)
        object_size_less_than    = optional(number)
      }))
    }))
  }))
  default = []
}

variable "object_lock_config" {
  description = "Object lock default retention configuration"
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_config" {
  description = "Cross-region replication configuration"
  type = object({
    role_arn             = optional(string)
    rules = list(object({
      id                               = string
      priority                         = optional(number)
      status                           = optional(string, "Enabled")
      destination_bucket               = optional(string)
      destination_storage_class        = optional(string)
      delete_marker_replication        = optional(string, "Disabled")
      existing_object_replication      = optional(string, "Disabled")
      source_selection_criteria = optional(object({
        sse_kms_encrypted_objects = optional(string, "Disabled")
        replica_modifications     = optional(string, "Disabled")
      }))
      filter = optional(object({
        prefix = optional(string)
        tags   = optional(map(string))
      }))
    }))
    destination_bucket_name = optional(string, "replica-destination")
  })
  default = null
}

variable "user_policy_json" {
  description = "Optional user-provided policy JSON to attach to the bucket"
  type        = string
  default     = ""
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public policy"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership (BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter)"
  type        = string
  default     = "ObjectWriter"
}

variable "intelligent_tiering_configurations" {
  description = "List of intelligent tiering configurations"
  type = list(object({
    name = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    tierings = list(object({
      access_tier = string
      days        = number
    }))
  }))
  default = []
}

locals {
  bucket_name_final = var.bucket_name != "" ? var.bucket_name : (
    var.bucket_name_prefix != "" ? "${var.bucket_name_prefix}-${random_id.suffix[0].hex}" : "s3-bucket-${random_id.suffix[0].hex}"
  )
  logging_bucket_name = var.log_bucket_name != "" ? var.log_bucket_name : "${local.bucket_name_final}-logs"
  create_replica_dest = var.replication_config != null && var.replication_config.rules[0].destination_bucket == null
}

resource "random_id" "suffix" {
  count       = var.enable_bucket ? 1 : 0
  byte_length = 4
}

data "aws_canonical_user_id" "current" {
  count = var.enable_bucket ? 1 : 0
}

data "aws_elb_service_account" "main" {
  count = var.enable_bucket ? 1 : 0
}

data "aws_caller_identity" "current" {
  count = var.enable_bucket ? 1 : 0
}

resource "aws_kms_key" "sse" {
  count                   = var.enable_bucket ? 1 : 0
  description             = "S3 bucket encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "this" {
  count         = var.enable_bucket ? 1 : 0
  bucket        = local.bucket_name_final
  force_destroy = var.force_destroy
  object_lock_enabled = var.enable_object_lock ? true : null
  tags = {
    Name = local.bucket_name_final
  }
}

resource "aws_s3_bucket" "logging" {
  count         = var.enable_bucket ? 1 : 0
  bucket        = local.logging_bucket_name
  force_destroy = var.force_destroy
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = var.enable_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.log_bucket_prefix
}

resource "aws_s3_bucket_acl" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = length(var.grants) > 0 ? null : var.acl
  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            type          = grant.value.grantee.type
            email_address = grant.value.grantee.email_address
            id            = grant.value.grantee.id != null ? grant.value.grantee.id : data.aws_canonical_user_id.current[0].id
            display_name  = grant.value.grantee.display_name
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_canonical_user_id.current[0].id
      }
    }
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.enable_bucket && (length(keys(var.website_config)) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  index_document {
    suffix = var.website_config.index_document
  }
  error_document {
    key = var.website_config.error_document
  }
  dynamic "redirect_all_requests_to" {
    for_each = var.website_config.redirect_all_requests_to != null ? [1] : []
    content {
      host_name = var.website_config.redirect_all_requests_to
    }
  }
  routing_rules = var.website_config.routing_rules != null ? var.website_config.routing_rules : null
}

resource "aws_s3_bucket_versioning" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  versioning_configuration {
    status    = var.versioning_config.status
    mfa_delete = var.versioning_config.mfa_delete ? "Enabled" : "Disabled"
  }
  expected_bucket_owner = data.aws_caller_identity.current[0].account_id
  mfa                   = var.versioning_config.mfa
}

# SSE-KMS encryption configuration for the main bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "kms" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sse[0].arn
    }
  }
}

# Encryption configuration for the logging bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.enable_bucket && length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.enable_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }
      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }
      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }
      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix                   = filter.value.tags != null ? null : filter.value.prefix
          object_size_greater_than = filter.value.tags != null ? null : filter.value.object_size_greater_than
          object_size_less_than    = filter.value.tags != null ? null : filter.value.object_size_less_than
          dynamic "and" {
            for_each = filter.value.tags != null ? [filter.value] : []
            content {
              prefix                   = and.value.prefix
              tags                     = and.value.tags
              object_size_greater_than = and.value.object_size_greater_than
              object_size_less_than    = and.value.object_size_less_than
            }
          }
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.enable_bucket && var.enable_object_lock && var.object_lock_config != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  rule {
    default_retention {
      mode = var.object_lock_config.mode
      days = var.object_lock_config.days
      years = var.object_lock_config.years
    }
  }
}

resource "aws_s3_bucket" "replica_destination" {
  count         = var.enable_bucket && local.create_replica_dest ? 1 : 0
  bucket        = var.replication_config.destination_bucket_name
  force_destroy = var.force_destroy
}

resource "aws_iam_role" "replication" {
  count = var.enable_bucket && var.replication_config != null ? 1 : 0
  name  = "${local.bucket_name_final}-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = var.enable_bucket && var.replication_config != null ? 1 : 0
  name  = "${local.bucket_name_final}-replication-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.this[0].arn,
          "${aws_s3_bucket.this[0].arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.this[0].arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = local.create_replica_dest ? "${aws_s3_bucket.replica_destination[0].arn}/*" : var.replication_config.rules[0].destination_bucket
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = var.enable_bucket && var.replication_config != null ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.enable_bucket && var.replication_config != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_config.role_arn != null ? var.replication_config.role_arn : aws_iam_role.replication[0].arn
  dynamic "rule" {
    for_each = var.replication_config.rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status
      delete_marker_replication {
        status = rule.value.delete_marker_replication
      }
      existing_object_replication {
        status = rule.value.existing_object_replication
      }
      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          sse_kms_encrypted_objects {
            status = source_selection_criteria.value.sse_kms_encrypted_objects
          }
          replica_modifications {
            status = source_selection_criteria.value.replica_modifications
          }
        }
      }
      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.tags != null ? null : filter.value.prefix
          dynamic "and" {
            for_each = filter.value.tags != null ? [filter.value] : []
            content {
              prefix = and.value.prefix
              tags   = and.value.tags
            }
          }
        }
      }
      destination {
        bucket        = local.create_replica_dest ? aws_s3_bucket.replica_destination[0].arn : rule.value.destination_bucket
        storage_class = rule.value.destination_storage_class
      }
    }
  }
}

data "aws_iam_policy_document" "elb_log_delivery" {
  count = var.enable_bucket ? 1 : 0
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.main[0].arn]
    }
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.this[0].arn}/*"
    ]
  }
}

data "aws_iam_policy_document" "alb_log_delivery" {
  count = var.enable_bucket ? 1 : 0
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.this[0].arn}/*"
    ]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:GetBucketAcl"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = var.enable_bucket ? 1 : 0
  statement {
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "require_tls_1_2" {
  count = var.enable_bucket ? 1 : 0
  statement {
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*"
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

data "aws_iam_policy_document" "user_policy" {
  count = var.enable_bucket && var.user_policy_json != "" ? 1 : 0
  source_json = var.user_policy_json
}

data "aws_iam_policy_document" "combined" {
  count = var.enable_bucket ? 1 : 0
  source_policy_documents = compact([
    data.aws_iam_policy_document.elb_log_delivery[0].json,
    data.aws_iam_policy_document.alb_log_delivery[0].json,
    data.aws_iam_policy_document.deny_insecure_transport[0].json,
    data.aws_iam_policy_document.require_tls_1_2[0].json,
    var.user_policy_json != "" ? data.aws_iam_policy_document.user_policy[0].json : ""
  ])
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

resource "aws_s3_bucket_public_access_block" "this" {
  count                   = var.enable_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.this[0].id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.enable_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = var.enable_bucket ? { for idx, config in var.intelligent_tiering_configurations : config.name => config } : {}
  bucket   = aws_s3_bucket.this[0].id
  name     = each.value.name
  dynamic "filter" {
    for_each = each.value.filter != null ? [each.value.filter] : []
    content {
      prefix = filter.value.prefix
      tags   = filter.value.tags
    }
  }
  dynamic "tiering" {
    for_each = each.value.tierings
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

output "bucket_id" {
  value = var.enable_bucket ? aws_s3_bucket.this[0].id : null
}

output "bucket_arn" {
  value = var.enable_bucket ? aws_s3_bucket.this[0].arn : null
}

output "bucket_domain_name" {
  value = var.enable_bucket ? aws_s3_bucket.this[0].bucket_domain_name : null
}

output "bucket_regional_domain_name" {
  value = var.enable_bucket ? aws_s3_bucket.this[0].bucket_regional_domain_name : null
}

output "hosted_zone_id" {
  value = var.enable_bucket ? aws_s3_bucket.this[0].hosted_zone_id : null
}

output "region" {
  value = var.enable_bucket ? aws_s3_bucket.this[0].region : null
}

output "website_endpoint" {
  value = var.enable_bucket && length(keys(var.website_config)) > 0 ? aws_s3_bucket_website_configuration.this[0].website_endpoint : null
}

output "website_domain" {
  value = var.enable_bucket && length(keys(var.website_config)) > 0 ? aws_s3_bucket_website_configuration.this[0].website_domain : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "my_bucket" {
  bucket        = "mybucket-${random_id.bucket_suffix.hex}"
  force_destroy = false
  tags = {
    Name = "My bucket"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3_kms_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.my_oai.iam_arn
        }
        Action   = "kms:Decrypt"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_cloudfront_origin_access_identity" "my_oai" {
  comment = "origin-access-identity/cloudfront/ABCDEFG1234567"
}

data "aws_iam_policy_document" "s3_policy" {
  statement {
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.my_bucket.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.my_oai.iam_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "my_bucket" {
  bucket = aws_s3_bucket.my_bucket.id
  policy = data.aws_iam_policy_document.s3_policy.json
}

resource "aws_wafv2_web_acl" "cloudfront_waf" {
  name        = "cloudfront-waf"
  description = "WAF for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "cloudfront-waf"
    sampled_requests_enabled   = false
  }
}

resource "aws_cloudfront_distribution" "my_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Some comment"
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  aliases             = ["mysite.example.com", "yoursite.example.com"]
  web_acl_id          = aws_wafv2_web_acl.cloudfront_waf.arn

  origin {
    domain_name = aws_s3_bucket.my_bucket.bucket_regional_domain_name
    origin_id   = "myS3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.my_oai.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    target_origin_id       = "myS3Origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods         = ["GET", "HEAD"]
    compress               = false

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  ordered_cache_behavior {
    path_pattern           = "/content/immutable/*"
    target_origin_id       = "myS3Origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true

    forwarded_values {
      query_string = false
      headers      = ["Origin"]
      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  ordered_cache_behavior {
    path_pattern           = "/content/*"
    target_origin_id       = "myS3Origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Environment = "production"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_kms_key" "state_bucket_key" {
  description             = "KMS key for S3 state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    team     = "devops"
    solution = "jenkins"
  }
}

resource "aws_kms_alias" "state_bucket_key_alias" {
  name          = "alias/s3-state-bucket-key"
  target_key_id = aws_kms_key.state_bucket_key.id
}

resource "aws_s3_bucket" "state_bucket" {
  bucket = "jenkins-fargate-demo"

  tags = {
    team     = "devops"
    solution = "jenkins"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_bucket_encryption" {
  bucket = aws_s3_bucket.state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state_bucket_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "state_bucket_versioning" {
  bucket = aws_s3_bucket.state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state_bucket_public_access" {
  bucket = aws_s3_bucket.state_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "state_lock" {
  name         = "tf-serverless-jenkins-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    team     = "devops"
    solution = "jenkins"
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "state_bucket_name" {
  value = aws_s3_bucket.state_bucket.id
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.state_lock.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# IAM user for Terraform EKS provisioning
resource "aws_iam_user" "terraform_bot" {
  name = "terraform-bot"
}

# Custom IAM policy for EKS management
data "aws_iam_policy_document" "terraform_bot_eks" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:*",
      "autoscaling:*",
      "iam:CreateRole",
      "iam:AttachRolePolicy",
      "iam:PutRolePolicy",
      "iam:PassRole",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:CreateInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:DeleteInstanceProfile",
      "iam:DeleteRole",
      "iam:ListInstanceProfiles",
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "eks:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "terraform_bot_eks_policy" {
  name        = "terraform-bot-eks-policy"
  description = "Custom policy for EKS provisioning via Terraform"
  policy      = data.aws_iam_policy_document.terraform_bot_eks.json
}

# Attach custom policy to the user
resource "aws_iam_user_policy_attachment" "terraform_bot_eks_policy_attach" {
  user       = aws_iam_user.terraform_bot.name
  policy_arn = aws_iam_policy.terraform_bot_eks_policy.arn
}

# Attach AWS managed EFS full access policy
resource "aws_iam_user_policy_attachment" "terraform_bot_efs_policy_attach" {
  user       = aws_iam_user.terraform_bot.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemFullAccess"
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 2.22"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.1"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.7"
    }
  }
}

resource "random_pet" "pet" {
  length = 2
}

resource "docker_image" "nginx" {
  name         = "nginx:1.23.4"
  keep_locally = true
}

resource "docker_container" "nginx" {
  count = 4
  name  = "${random_pet.pet.id}-${count.index}"
  image = docker_image.nginx.image_id

  ports {
    internal = "80"
  }
}

resource "time_static" "now" {
}

output "containers" {
  description = "List of container names, IP addresses, and external ports"
  value = {
    for i, c in docker_container.nginx :
    c.name => {
      ip            = c.ip_address
      external_port = c.ports[0].external
    }
  }
}

output "time_created" {
  description = "Timestamp when the configuration was applied (uses time provider)"
  value       = time_static.now.unix
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "alias_name" {
  type        = string
  default     = "kms-cmk-example"
  description = "Alias name for the KMS CMK (prefix 'alias/' will be added)"
}

resource "aws_kms_key" "example" {
  description             = "CMK for example use"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableFullAdminPermissions"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "example" {
  name          = "alias/${var.alias_name}"
  target_key_id = aws_kms_key.example.arn
}

output "cmk_arn" {
  value = aws_kms_key.example.arn
}

output "alias_name" {
  value = aws_kms_alias.example.name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Machine token
resource "random_password" "machine_token_id" {
  length  = 6
  special = false
}

resource "random_password" "machine_token_secret" {
  length  = 16
  special = false
}

# Machine CA (ED25519)
resource "tls_private_key" "machine_ca" {
  algorithm = "ED25519"
}

resource "tls_self_signed_cert" "machine_ca_cert" {
  private_key_pem = tls_private_key.machine_ca.private_key_pem
  validity_period_hours = 8760
  is_ca_certificate     = true
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "cert_signing"
  ]
  subject {
    common_name = "machine-ca"
  }
}

# Talos admin certificate (signed by machine CA)
resource "tls_private_key" "talos_admin_key" {
  algorithm = "ED25519"
}

resource "tls_cert_request" "talos_admin_csr" {
  private_key_pem = tls_private_key.talos_admin_key.private_key_pem
  subject {
    common_name = "talos-admin"
  }
}

resource "tls_locally_signed_cert" "talos_admin_cert" {
  cert_request_pem   = tls_cert_request.talos_admin_csr.cert_request_pem
  ca_private_key_pem = tls_private_key.machine_ca.private_key_pem
  ca_cert_pem        = tls_self_signed_cert.machine_ca_cert.cert_pem
  validity_period_hours = 8760
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "client_auth"
  ]
}

# Cluster ID and secret (32-byte random)
resource "random_id" "cluster_id" {
  byte_length = 32
}

resource "random_id" "cluster_secret" {
  byte_length = 32
}

# Bootstrap token
resource "random_password" "bootstrap_token_id" {
  length  = 6
  special = false
}

resource "random_password" "bootstrap_token_secret" {
  length  = 16
  special = false
}

# Kubernetes root CA (ECDSA P256)
resource "tls_private_key" "kubernetes_ca" {
  algorithm   = "ECDSA"
  ecdsa_curve = "P256"
}

resource "tls_self_signed_cert" "kubernetes_ca_cert" {
  private_key_pem = tls_private_key.kubernetes_ca.private_key_pem
  validity_period_hours = 8760
  is_ca_certificate     = true
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "cert_signing"
  ]
  subject {
    common_name = "kubernetes-ca"
  }
}

# Kubernetes admin certificate (signed by kubernetes CA)
resource "tls_private_key" "kubernetes_admin_key" {
  algorithm   = "ECDSA"
  ecdsa_curve = "P256"
}

resource "tls_cert_request" "kubernetes_admin_csr" {
  private_key_pem = tls_private_key.kubernetes_admin_key.private_key_pem
  subject {
    common_name  = "admin"
    organization = "system:masters"
  }
}

resource "tls_locally_signed_cert" "kubernetes_admin_cert" {
  cert_request_pem   = tls_cert_request.kubernetes_admin_csr.cert_request_pem
  ca_private_key_pem = tls_private_key.kubernetes_ca.private_key_pem
  ca_cert_pem        = tls_self_signed_cert.kubernetes_ca_cert.cert_pem
  validity_period_hours = 8760
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "client_auth"
  ]
}

# AESCBC encryption secret (32-byte random)
resource "random_id" "aes_cbc_encryption_secret" {
  byte_length = 32
}

# Aggregator CA (front-proxy) (ECDSA P256)
resource "tls_private_key" "aggregator_ca" {
  algorithm   = "ECDSA"
  ecdsa_curve = "P256"
}

resource "tls_self_signed_cert" "aggregator_ca_cert" {
  private_key_pem = tls_private_key.aggregator_ca.private_key_pem
  validity_period_hours = 8760
  is_ca_certificate     = true
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "cert_signing"
  ]
  subject {
    common_name = "aggregator-ca"
  }
}

# Kubernetes service account key (ECDSA P256)
resource "tls_private_key" "service_account_key" {
  algorithm   = "ECDSA"
  ecdsa_curve = "P256"
}

# etcd CA (ECDSA P256)
resource "tls_private_key" "etcd_ca" {
  algorithm   = "ECDSA"
  ecdsa_curve = "P256"
}

resource "tls_self_signed_cert" "etcd_ca_cert" {
  private_key_pem = tls_private_key.etcd_ca.private_key_pem
  validity_period_hours = 8760
  is_ca_certificate     = true
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "cert_signing"
  ]
  subject {
    common_name = "etcd-ca"
  }
}

# Outputs
output "machine_token" {
  value     = "${random_password.machine_token_id.result}.${random_password.machine_token_secret.result}"
  sensitive = true
}

output "machine_ca_crt" {
  value     = base64encode(tls_self_signed_cert.machine_ca_cert.cert_pem)
  sensitive = true
}

output "machine_ca_key" {
  value     = base64encode(replace(tls_private_key.machine_ca.private_key_pem, "PRIVATE KEY", "ED25519 PRIVATE KEY"))
  sensitive = true
}

output "talos_admin_crt" {
  value     = base64encode(tls_locally_signed_cert.talos_admin_cert.cert_pem)
  sensitive = true
}

output "talos_admin_key" {
  value     = base64encode(replace(tls_private_key.talos_admin_key.private_key_pem, "PRIVATE KEY", "ED25519 PRIVATE KEY"))
  sensitive = true
}

output "cluster_id" {
  value     = random_id.cluster_id.b64_std
  sensitive = true
}

output "cluster_secret" {
  value     = random_id.cluster_secret.b64_std
  sensitive = true
}

output "bootstrap_token" {
  value     = "${random_password.bootstrap_token_id.result}.${random_password.bootstrap_token_secret.result}"
  sensitive = true
}

output "kubernetes_ca_crt" {
  value     = base64encode(tls_self_signed_cert.kubernetes_ca_cert.cert_pem)
  sensitive = true
}

output "kubernetes_ca_key" {
  value     = base64encode(tls_private_key.kubernetes_ca.private_key_pem)
  sensitive = true
}

output "kubernetes_admin_crt" {
  value     = base64encode(tls_locally_signed_cert.kubernetes_admin_cert.cert_pem)
  sensitive = true
}

output "kubernetes_admin_key" {
  value     = base64encode(tls_private_key.kubernetes_admin_key.private_key_pem)
  sensitive = true
}

output "aes_cbc_encryption_secret" {
  value     = random_id.aes_cbc_encryption_secret.b64_std
  sensitive = true
}

output "aggregator_ca_crt" {
  value     = base64encode(tls_self_signed_cert.aggregator_ca_cert.cert_pem)
  sensitive = true
}

output "aggregator_ca_key" {
  value     = base64encode(tls_private_key.aggregator_ca.private_key_pem)
  sensitive = true
}

output "service_account_key" {
  value     = base64encode(tls_private_key.service_account_key.private_key_pem)
  sensitive = true
}

output "etcd_ca_crt" {
  value     = base64encode(tls_self_signed_cert.etcd_ca_cert.cert_pem)
  sensitive = true
}

output "etcd_ca_key" {
  value     = base64encode(tls_private_key.etcd_ca.private_key_pem)
  sensitive = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name for tagging resources"
  type        = string
  default     = "production"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs          = data.aws_availability_zones.available.names
  internal_cidrs = {
    "0" = "10.40.0.0/24"
    "1" = "10.40.1.0/24"
    "2" = "10.40.2.0/24"
    "3" = "10.40.3.0/24"
  }
  external_cidrs = {
    "0" = "10.41.0.0/24"
    "1" = "10.41.1.0/24"
    "2" = "10.41.2.0/24"
    "3" = "10.41.3.0/24"
  }
}

# Internal VPC
resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "internal-vpc"
    Environment = var.environment
  }
}

# Internal subnets
resource "aws_subnet" "internal" {
  for_each = local.internal_cidrs

  vpc_id            = aws_vpc.internal.id
  cidr_block        = each.value
  availability_zone = local.azs[tonumber(each.key)]

  tags = {
    Name        = "internal-subnet-${each.key}"
    Environment = var.environment
  }
}

# External VPC
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "external-vpc"
    Environment = var.environment
  }
}

# External subnets
resource "aws_subnet" "external" {
  for_each = local.external_cidrs

  vpc_id            = aws_vpc.external.id
  cidr_block        = each.value
  availability_zone = local.azs[tonumber(each.key)]

  tags = {
    Name        = "external-subnet-${each.key}"
    Environment = var.environment
  }
}

# Internet Gateway for external VPC
resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "external-igw"
    Environment = var.environment
  }
}

# Route table for external VPC with default route to IGW
resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name        = "external-rt"
    Environment = var.environment
  }
}

# Route table associations for external subnets
resource "aws_route_table_association" "external" {
  for_each = aws_subnet.external

  subnet_id      = each.value.id
  route_table_id = aws_route_table.external.id
}

terraform {
  required_version = ">= 1.1"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 2.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.1.0"
    }
  }
}

resource "random_pet" "bucket_name" {
  length    = 5
  separator = "-"
}

resource "aws_s3_bucket" "public" {
  bucket = random_pet.bucket_name.id

  tags = {
    Purpose = "private bucket"
  }
}

resource "aws_s3_bucket_public_access_block" "public" {
  bucket = aws_s3_bucket.public.bucket

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3_key" {
  description             = "KMS CMK for S3 bucket encryption"
  deletion_window_in_days = 7
}

resource "aws_s3_bucket_server_side_encryption_configuration" "public" {
  bucket = aws_s3_bucket.public.bucket

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "container_name" {
  description = "Name of the Docker container"
  type        = string
  default     = "ExampleNginxContainer"
}

variable "internal_port" {
  description = "Internal container port for nginx"
  type        = number
  default     = 80
}

variable "external_port" {
  description = "External host port mapped to the container"
  type        = number
  default     = 2224
}

data "docker_registry_image" "nginx" {
  name = "nginx:1.23.4"
}

resource "docker_image" "nginx" {
  name         = data.docker_registry_image.nginx.name
  keep_locally = true
  pull_triggers = [data.docker_registry_image.nginx.sha256_digest]
}

resource "docker_container" "example_nginx" {
  name  = var.container_name
  image = docker_image.nginx.image_id

  ports {
    internal = var.internal_port
    external = var.external_port
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = var.region
}

# Variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "name_prefix" {
  description = "Prefix for resource naming"
  type        = string
  default     = "TEST"
}

# Conditional enable flags
variable "enable_aggregate_authorization" {
  description = "Enable aggregate authorization"
  type        = bool
  default     = true
}

variable "enable_delivery_channel" {
  description = "Enable delivery channel"
  type        = bool
  default     = true
}

variable "enable_configuration_recorder" {
  description = "Enable configuration recorder"
  type        = bool
  default     = true
}

variable "enable_recorder_status" {
  description = "Enable recorder status"
  type        = bool
  default     = true
}

variable "enable_configuration_aggregator" {
  description = "Enable configuration aggregator"
  type        = bool
  default     = true
}

variable "enable_config_rule" {
  description = "Enable config rule"
  type        = bool
  default     = true
}

variable "enable_organization_managed_rule" {
  description = "Enable organization managed rule"
  type        = bool
  default     = false
}

variable "enable_organization_custom_rule" {
  description = "Enable organization custom rule"
  type        = bool
  default     = false
}

variable "enable_remediation_configuration" {
  description = "Enable remediation configuration"
  type        = bool
  default     = false
}

# General variables
variable "account_id" {
  description = "AWS account ID for aggregate authorization"
  type        = string
  default     = "123456789012"
}

variable "aggregate_authorization_region" {
  description = "Region for aggregate authorization"
  type        = string
  default     = "us-east-1"
}

variable "s3_key_prefix" {
  description = "S3 key prefix for delivery channel"
  type        = string
  default     = ""
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for delivery channel (if empty, a new topic is created)"
  type        = string
  default     = ""
}

variable "recording_group" {
  description = "Recording group for configuration recorder"
  type = object({
    all_supported                 = optional(bool, true)
    include_global_resource_types = optional(bool, true)
    resource_types                = optional(list(string), [])
  })
  default = {}
}

variable "aggregation_source_type" {
  description = "Type of aggregation source: 'ACCOUNT' or 'ORGANIZATION'"
  type        = string
  default     = "ACCOUNT"
}

variable "aggregation_source_account_ids" {
  description = "List of account IDs for account aggregation (only if type is ACCOUNT)"
  type        = list(string)
  default     = ["123456789012"]
}

variable "aggregation_source_all_regions" {
  description = "Include all regions in aggregation source"
  type        = bool
  default     = true
}

variable "config_rule_scope" {
  description = "Scope for config rule"
  type = object({
    compliance_resource_types    = optional(list(string))
    compliance_resource_id       = optional(string)
    tag_key                      = optional(string)
    tag_value                    = optional(string)
  })
  default = {}
}

variable "config_rule_input_parameters" {
  description = "Input parameters for config rule (JSON string)"
  type        = string
  default     = "{}"
}

variable "config_rule_maximum_execution_frequency" {
  description = "Maximum execution frequency for config rule"
  type        = string
  default     = "TwentyFour_Hours"
}

variable "organization_managed_rule_identifier" {
  description = "Identifier for organization managed rule"
  type        = string
  default     = "IAM_PASSWORD_POLICY"
}

variable "organization_managed_rule_scope" {
  description = "Scope for organization managed rule"
  type = object({
    compliance_resource_types = optional(list(string))
    compliance_resource_id   = optional(string)
    tag_key                  = optional(string)
    tag_value                = optional(string)
  })
  default = {}
}

variable "organization_managed_rule_timeouts" {
  description = "Timeouts for organization managed rule"
  type = object({
    create = optional(string, "5m")
    update = optional(string, "5m")
    delete = optional(string, "5m")
  })
  default = {}
}

variable "organization_custom_lambda_runtime" {
  description = "Runtime for Lambda function (organization custom rule)"
  type        = string
  default     = "python3.12"
}

variable "organization_custom_trigger_types" {
  description = "Trigger types for organization custom rule"
  type        = list(string)
  default     = ["ConfigurationItemChangeNotification"]
}

variable "organization_custom_scope" {
  description = "Scope for organization custom rule"
  type = object({
    compliance_resource_types = optional(list(string))
    compliance_resource_id   = optional(string)
    tag_key                  = optional(string)
    tag_value                = optional(string)
  })
  default = {}
}

variable "organization_custom_timeouts" {
  description = "Timeouts for organization custom rule"
  type = object({
    create = optional(string, "5m")
    update = optional(string, "5m")
    delete = optional(string, "5m")
  })
  default = {}
}

variable "remediation_target_id" {
  description = "Target ID for remediation configuration (e.g., SSM document ARN)"
  type        = string
  default     = "arn:aws:ssm:us-east-1:123456789012:document/AWS-ConfigureS3BucketVersioning"
}

variable "remediation_target_type" {
  description = "Target type for remediation"
  type        = string
  default     = "SSM_DOCUMENT"
}

variable "remediation_parameters" {
  description = "Parameters for remediation"
  type = list(object({
    name           = string
    resource_value = optional(string)
    static_value   = optional(string)
  }))
  default = []
}

variable "remediation_execution_controls" {
  description = "Execution controls for remediation"
  type = object({
    ssm_controls = object({
      concurrent_execution_rate_percentage = optional(string)
      error_percentage                     = optional(string)
    })
  })
  default = null
}

variable "remediation_automatic" {
  description = "Enable automatic remediation"
  type        = bool
  default     = false
}

variable "remediation_maximum_automatic_attempts" {
  description = "Maximum automatic attempts for remediation"
  type        = number
  default     = 5
}

variable "remediation_retry_attempt_seconds" {
  description = "Retry attempt seconds for remediation"
  type        = string
  default     = "60"
}

# Locals
locals {
  name_prefix_lower = lower(var.name_prefix)
  env_lower         = lower(var.environment)
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
  name_tag = "${local.name_prefix_lower}-%s-${local.env_lower}"
}

# Data sources
data "aws_caller_identity" "current" {}

# KMS key for S3 and SNS encryption
resource "aws_kms_key" "config" {
  description             = "KMS key for AWS Config resources"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Config to use the key"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
  tags = merge(local.common_tags, { Name = format(local.name_tag, "config-kms") })
  timeouts {
    create = "15m"
  }
}

# S3 bucket for Config delivery
resource "aws_s3_bucket" "config" {
  bucket = "${local.name_prefix_lower}-config-bucket-${local.env_lower}"
  tags   = merge(local.common_tags, { Name = format(local.name_tag, "config-bucket") })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket                  = aws_s3_bucket.config.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }
  }
}

# SNS topic for delivery channel
resource "aws_sns_topic" "config_delivery" {
  name              = "${local.name_prefix_lower}-config-sns-${local.env_lower}"
  kms_master_key_id = aws_kms_key.config.arn
  tags              = merge(local.common_tags, { Name = format(local.name_tag, "config-sns") })
}

# IAM role for Config configuration recorder
resource "aws_iam_role" "config_recorder" {
  name = "${local.name_prefix_lower}-config-recorder-role-${local.env_lower}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "config.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
  tags = merge(local.common_tags, { Name = format(local.name_tag, "config-recorder-role") })
}

resource "aws_iam_role_policy" "config_recorder" {
  name = "${local.name_prefix_lower}-config-recorder-policy-${local.env_lower}"
  role = aws_iam_role.config_recorder.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "config:Put*",
          "config:Get*",
          "config:List*"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.config.arn}/*"
      }
    ]
  })
}

# IAM role for Config aggregator (for organization aggregation)
resource "aws_iam_role" "config_aggregator" {
  name = "${local.name_prefix_lower}-config-aggregator-role-${local.env_lower}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "config.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
  tags = merge(local.common_tags, { Name = format(local.name_tag, "config-aggregator-role") })
}

resource "aws_iam_role_policy" "config_aggregator" {
  name = "${local.name_prefix_lower}-config-aggregator-policy-${local.env_lower}"
  role = aws_iam_role.config_aggregator.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "config:Put*",
          "config:Get*",
          "config:List*",
          "config:Describe*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Aggregate authorization
resource "aws_config_aggregate_authorization" "main" {
  count = var.enable_aggregate_authorization ? 1 : 0
  account_id            = var.account_id
  region                = var.aggregate_authorization_region
  tags                  = merge(local.common_tags, { Name = format(local.name_tag, "config-aggregate-auth") })
}

# Delivery channel
resource "aws_config_delivery_channel" "main" {
  count          = var.enable_delivery_channel ? 1 : 0
  s3_bucket_name = aws_s3_bucket.config.id
  s3_key_prefix  = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  sns_topic_arn  = var.sns_topic_arn != "" ? var.sns_topic_arn : aws_sns_topic.config_delivery.arn
  depends_on     = [aws_config_configuration_recorder.main]
}

# Configuration recorder
resource "aws_config_configuration_recorder" "main" {
  count    = var.enable_configuration_recorder ? 1 : 0
  name     = "${local.name_prefix_lower}-config-recorder-${local.env_lower}"
  role_arn = aws_iam_role.config_recorder.arn
  dynamic "recording_group" {
    for_each = length(var.recording_group) > 0 ? [var.recording_group] : []
    content {
      all_supported                 = lookup(recording_group.value, "all_supported", true)
      include_global_resource_types = lookup(recording_group.value, "include_global_resource_types", true)
      resource_types                = lookup(recording_group.value, "resource_types", [])
    }
  }
}

# Recorder status
resource "aws_config_configuration_recorder_status" "main" {
  count      = var.enable_recorder_status ? 1 : 0
  name       = aws_config_configuration_recorder.main[0].name
  is_enabled = true
  depends_on = [
    aws_config_configuration_recorder.main,
    aws_config_delivery_channel.main
  ]
}

# Configuration aggregator
resource "aws_config_configuration_aggregator" "main" {
  count = var.enable_configuration_aggregator ? 1 : 0
  name  = "${local.name_prefix_lower}-config-aggregator-${local.env_lower}"

  dynamic "account_aggregation_source" {
    for_each = var.aggregation_source_type == "ACCOUNT" ? [1] : []
    content {
      account_ids = var.aggregation_source_account_ids
      all_regions = var.aggregation_source_all_regions
    }
  }

  dynamic "organization_aggregation_source" {
    for_each = var.aggregation_source_type == "ORGANIZATION" ? [1] : []
    content {
      all_regions = var.aggregation_source_all_regions
      role_arn    = aws_iam_role.config_aggregator.arn
    }
  }

  tags = merge(local.common_tags, { Name = format(local.name_tag, "config-aggregator") })
}

# Config rule
resource "aws_config_config_rule" "main" {
  count = var.enable_config_rule ? 1 : 0
  name  = "${local.name_prefix_lower}-config-rule-${local.env_lower}"

  source {
    owner             = "AWS"
    source_identifier = "S3_BUCKET_VERSIONING_ENABLED"
  }

  dynamic "scope" {
    for_each = length(var.config_rule_scope) > 0 ? [var.config_rule_scope] : []
    content {
      compliance_resource_types = lookup(scope.value, "compliance_resource_types", null)
      compliance_resource_id    = lookup(scope.value, "compliance_resource_id", null)
      tag_key                   = lookup(scope.value, "tag_key", null)
      tag_value                 = lookup(scope.value, "tag_value", null)
    }
  }

  input_parameters            = var.config_rule_input_parameters != "{}" ? var.config_rule_input_parameters : null
  maximum_execution_frequency = var.config_rule_maximum_execution_frequency

  tags = merge(local.common_tags, { Name = format(local.name_tag, "config-rule") })
}

# Organization managed rule
resource "aws_config_organization_managed_rule" "main" {
  count = var.enable_organization_managed_rule ? 1 : 0
  name  = "${local.name_prefix_lower}-org-managed-rule-${local.env_lower}"

  rule_identifier = var.organization_managed_rule_identifier

  resource_id_scope    = try(var.organization_managed_rule_scope.compliance_resource_id, null)
  resource_types_scope = try(var.organization_managed_rule_scope.compliance_resource_types, null)
  tag_key_scope        = try(var.organization_managed_rule_scope.tag_key, null)
  tag_value_scope      = try(var.organization_managed_rule_scope.tag_value, null)

  timeouts {
    create = lookup(var.organization_managed_rule_timeouts, "create", "5m")
    update = lookup(var.organization_managed_rule_timeouts, "update", "5m")
    delete = lookup(var.organization_managed_rule_timeouts, "delete", "5m")
  }
}

# Lambda function for organization custom rule
resource "local_file" "lambda_python" {
  count    = var.enable_organization_custom_rule ? 1 : 0
  content  = <<-EOT
import json
import boto3

def lambda_handler(event, context):
    print("Received event: " + json.dumps(event, indent=2))
    return {
        'statusCode': 200,
        'body': json.dumps('Hello from Config Custom Rule Lambda!')
    }
EOT
  filename = "${path.module}/lambda_function.py"
}

data "archive_file" "lambda_zip" {
  count       = var.enable_organization_custom_rule ? 1 : 0
  type        = "zip"
  source_file = local_file.lambda_python[0].filename
  output_path = "${path.module}/lambda_function.zip"
}

resource "aws_iam_role" "lambda_exec" {
  count = var.enable_organization_custom_rule ? 1 : 0
  name  = "${local.name_prefix_lower}-lambda-config-role-${local.env_lower}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
  tags = merge(local.common_tags, { Name = format(local.name_tag, "lambda-config-role") })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  count      = var.enable_organization_custom_rule ? 1 : 0
  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "org_custom_rule" {
  count            = var.enable_organization_custom_rule ? 1 : 0
  filename         = data.archive_file.lambda_zip[0].output_path
  function_name    = "${local.name_prefix_lower}-config-custom-rule-${local.env_lower}"
  role             = aws_iam_role.lambda_exec[0].arn
  handler          = "lambda_function.lambda_handler"
  runtime          = var.organization_custom_lambda_runtime
  source_code_hash = data.archive_file.lambda_zip[0].output_base64sha256
  tags             = merge(local.common_tags, { Name = format(local.name_tag, "config-custom-rule-lambda") })
  timeouts {
    create = "15m"
  }
}

resource "aws_lambda_permission" "config_invoke" {
  count         = var.enable_organization_custom_rule ? 1 : 0
  statement_id  = "AllowConfigInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.org_custom_rule[0].function_name
  principal     = "config.amazonaws.com"
  source_arn    = "arn:aws:config:${var.region}:${data.aws_caller_identity.current.account_id}:config-rule/${local.name_prefix_lower}-org-custom-rule-${local.env_lower}"
}

# Organization custom rule
resource "aws_config_organization_custom_rule" "main" {
  count = var.enable_organization_custom_rule ? 1 : 0
  name  = "${local.name_prefix_lower}-org-custom-rule-${local.env_lower}"

  lambda_function_arn = aws_lambda_function.org_custom_rule[0].arn
  trigger_types       = var.organization_custom_trigger_types

  resource_id_scope    = try(var.organization_custom_scope.compliance_resource_id, null)
  resource_types_scope = try(var.organization_custom_scope.compliance_resource_types, null)
  tag_key_scope        = try(var.organization_custom_scope.tag_key, null)
  tag_value_scope      = try(var.organization_custom_scope.tag_value, null)

  timeouts {
    create = lookup(var.organization_custom_timeouts, "create", "5m")
    update = lookup(var.organization_custom_timeouts, "update", "5m")
    delete = lookup(var.organization_custom_timeouts, "delete", "5m")
  }
}

# Remediation configuration
resource "aws_config_remediation_configuration" "main" {
  count = var.enable_remediation_configuration ? 1 : 0
  config_rule_name = aws_config_config_rule.main[0].name
  target_id        = var.remediation_target_id
  target_type      = var.remediation_target_type

  dynamic "parameter" {
    for_each = var.remediation_parameters
    content {
      name           = parameter.value.name
      resource_value = parameter.value.resource_value
      static_value   = parameter.value.static_value
    }
  }

  dynamic "execution_controls" {
    for_each = var.remediation_execution_controls != null ? [var.remediation_execution_controls] : []
    content {
      ssm_controls {
        concurrent_execution_rate_percentage = lookup(execution_controls.value.ssm_controls, "concurrent_execution_rate_percentage", null)
        error_percentage                     = lookup(execution_controls.value.ssm_controls, "error_percentage", null)
      }
    }
  }

  automatic                  = var.remediation_automatic
  maximum_automatic_attempts = var.remediation_maximum_automatic_attempts
  retry_attempt_seconds      = var.remediation_retry_attempt_seconds
}

# Outputs
output "aggregate_authorization_arn" {
  value = try(aws_config_aggregate_authorization.main[0].arn, null)
  description = "ARN of aggregate authorization"
}

output "aggregate_authorization_id" {
  value = try(aws_config_aggregate_authorization.main[0].id, null)
  description = "ID of aggregate authorization"
}

output "delivery_channel_id" {
  value = try(aws_config_delivery_channel.main[0].id, null)
  description = "ID of delivery channel"
}

output "configuration_recorder_id" {
  value = try(aws_config_configuration_recorder.main[0].id, null)
  description = "ID of configuration recorder"
}

output "configuration_aggregator_arn" {
  value = try(aws_config_configuration_aggregator.main[0].arn, null)
  description = "ARN of configuration aggregator"
}

output "configuration_aggregator_id" {
  value = try(aws_config_configuration_aggregator.main[0].id, null)
  description = "ID of configuration aggregator"
}

output "config_rule_arn" {
  value = try(aws_config_config_rule.main[0].arn, null)
  description = "ARN of config rule"
}

output "config_rule_id" {
  value = try(aws_config_config_rule.main[0].id, null)
  description = "ID of config rule"
}

output "organization_managed_rule_arn" {
  value = try(aws_config_organization_managed_rule.main[0].arn, null)
  description = "ARN of organization managed rule"
}

output "organization_managed_rule_id" {
  value = try(aws_config_organization_managed_rule.main[0].id, null)
  description = "ID of organization managed rule"
}

output "organization_custom_rule_arn" {
  value = try(aws_config_organization_custom_rule.main[0].arn, null)
  description = "ARN of organization custom rule"
}

output "organization_custom_rule_id" {
  value = try(aws_config_organization_custom_rule.main[0].id, null)
  description = "ID of organization custom rule"
}

output "remediation_configuration_arn" {
  value = try(aws_config_remediation_configuration.main[0].arn, null)
  description = "ARN of remediation configuration"
}

output "remediation_configuration_id" {
  value = try(aws_config_remediation_configuration.main[0].id, null)
  description = "ID of remediation configuration"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for AWS partition (to construct ARNs if needed)
data "aws_partition" "current" {}

# Trust policy for the Service Catalog launch role
data "aws_iam_policy_document" "test_role_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }
  }
}

# Custom policy for the launch role
data "aws_iam_policy_document" "service_catalog_terraform_launch" {
  statement {
    actions = [
      "cloudformation:*",
      "ec2:*",
      "s3:GetObject",
      "servicecatalog:*"
    ]
    resources = ["*"]
  }
}

# IAM role for Service Catalog launch
resource "aws_iam_role" "test_role" {
  name               = "test_role"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.test_role_assume_role.json
}

# Custom IAM policy
resource "aws_iam_policy" "service_catalog_terraform_launch" {
  name   = "ServiceCatalogTerraformLaunchPolicy"
  path   = "/"
  policy = data.aws_iam_policy_document.service_catalog_terraform_launch.json
}

# Attach custom policy to the role
resource "aws_iam_role_policy_attachment" "test_role_attachment" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.service_catalog_terraform_launch.arn
}

# IAM group with path
resource "aws_iam_group" "group1" {
  name = "Group1"
  path = "/terraform/"
}

# Attach AWS managed policy to the group
resource "aws_iam_group_policy_attachment" "group1_end_user" {
  group      = aws_iam_group.group1.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSServiceCatalogEndUserFullAccess"
}

# IAM user with force destroy
resource "aws_iam_user" "user1" {
  name          = "User1"
  path          = "/terraform/"
  force_destroy = true
}

# IAM user login profile (no password reset required)
resource "aws_iam_user_login_profile" "user1" {
  user                    = aws_iam_user.user1.name
  password_reset_required = false
}

# Add user to group
resource "aws_iam_user_group_membership" "user1_group1" {
  user   = aws_iam_user.user1.name
  groups = [aws_iam_group.group1.name]
}

# Outputs
output "launch_role_arn" {
  value = aws_iam_role.test_role.arn
}

output "user1_arn" {
  value = aws_iam_user.user1.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Trust policy document for cross-account and federated EKS access
data "aws_iam_policy_document" "trust_policy" {
  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::111222333444:root"]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRoleWithWebIdentity"
    ]
    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::111222333444:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/FOO"]
    }
    condition {
      test     = "StringEquals"
      variable = "oidc.eks.us-west-2.amazonaws.com/id/FOO:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringLike"
      variable = "oidc.eks.us-west-2.amazonaws.com/id/FOO:sub"
      values   = ["system:serviceaccount:*:*"]
    }
  }
}

# IAM roles
resource "aws_iam_role" "example_1_role" {
  name               = "example_1_role"
  assume_role_policy = data.aws_iam_policy_document.trust_policy.json
}

resource "aws_iam_role" "example_2_role" {
  name               = "example_2_role"
  assume_role_policy = data.aws_iam_policy_document.trust_policy.json
}

# Admin policy document
data "aws_iam_policy_document" "admin_policy" {
  statement {
    effect = "Allow"
    actions = [
      "*"
    ]
    resources = [
      "*"
    ]
  }
}

# IAM policy
resource "aws_iam_policy" "example_policy" {
  name        = "example_policy"
  description = "Full administrative access policy"
  policy      = data.aws_iam_policy_document.admin_policy.json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.81"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_pet" "this" {
  length = 2
}

resource "aws_cloudwatch_log_group" "this" {
  name = random_pet.this.id

  lifecycle {
    prevent_destroy = true
  }
}

output "random_id" {
  value = random_pet.this.id
}

output "log_group_arn" {
  value = aws_cloudwatch_log_group.this.arn
}

output "log_group_name" {
  value = aws_cloudwatch_log_group.this.name
}

terraform {
  required_version = ">= 0.14"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.27, < 6.0"
    }
  }
}

variable "cognito_user_pool_arn" {
  type        = string
  default     = ""
  description = "ARN of the Cognito User Pool to allow AdminInitiateAuth. Leave empty to omit the policy."
}

variable "postman_user_name" {
  type        = string
  default     = "postman-user"
  description = "Name of the IAM user for programmatic access."
}

# IAM user
resource "aws_iam_user" "postman" {
  name = var.postman_user_name
  path = "/"
}

# Access key for the user
resource "aws_iam_access_key" "postman" {
  user = aws_iam_user.postman.name
}

# Policy documents
data "aws_iam_policy_document" "api_gateway_read" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET"
    ]
    resources = [
      "arn:aws:apigateway:*::/*"
    ]
  }
}

data "aws_iam_policy_document" "cloudwatch_metrics" {
  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics"
    ]
    resources = [
      "*"
    ]
  }
}

# Conditional Cognito policy document
data "aws_iam_policy_document" "cognito_admin_auth" {
  count = length(var.cognito_user_pool_arn) > 0 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "cognito-idp:AdminInitiateAuth"
    ]
    resources = [
      var.cognito_user_pool_arn
    ]
  }
}

# IAM policies
resource "aws_iam_policy" "api_gateway_read" {
  name        = "postman-api-gateway-read"
  description = "Allow read access to API Gateway resources"
  policy      = data.aws_iam_policy_document.api_gateway_read.json
}

resource "aws_iam_policy" "cloudwatch_metrics" {
  name        = "postman-cloudwatch-metrics"
  description = "Allow retrieval of CloudWatch metrics"
  policy      = data.aws_iam_policy_document.cloudwatch_metrics.json
}

resource "aws_iam_policy" "cognito_admin_auth" {
  count       = length(var.cognito_user_pool_arn) > 0 ? 1 : 0
  name        = "postman-cognito-admin-auth"
  description = "Allow AdminInitiateAuth on the specified Cognito User Pool"
  policy      = data.aws_iam_policy_document.cognito_admin_auth[0].json
}

# Policy attachments
resource "aws_iam_user_policy_attachment" "api_gateway_read" {
  user       = aws_iam_user.postman.name
  policy_arn = aws_iam_policy.api_gateway_read.arn
}

resource "aws_iam_user_policy_attachment" "cloudwatch_metrics" {
  user       = aws_iam_user.postman.name
  policy_arn = aws_iam_policy.cloudwatch_metrics.arn
}

resource "aws_iam_user_policy_attachment" "cognito_admin_auth" {
  count      = length(var.cognito_user_pool_arn) > 0 ? 1 : 0
  user       = aws_iam_user.postman.name
  policy_arn = aws_iam_policy.cognito_admin_auth[0].arn
}

# Outputs
output "user_arn" {
  value = aws_iam_user.postman.arn
}

output "user_name" {
  value = aws_iam_user.postman.name
}

output "access_key_id" {
  value = aws_iam_access_key.postman.id
}

output "secret_access_key" {
  value     = aws_iam_access_key.postman.secret
  sensitive = true
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create_database" {
  description = "Whether to create the Athena database"
  type        = bool
  default     = true
}

variable "create_workgroup" {
  description = "Whether to create the Athena workgroup"
  type        = bool
  default     = true
}

variable "create_named_query" {
  description = "Whether to create the Athena named query"
  type        = bool
  default     = true
}

variable "name_prefix" {
  description = "Prefix for all resource names"
  type        = string
  default     = "TEST"
}

variable "environment_tag" {
  description = "Value for the Environment tag"
  type        = string
  default     = "STAGE"
}

variable "tags" {
  description = "Common tags applied to all resources (Environment tag is always added)"
  type        = map(string)
  default     = {}
}

variable "encryption_option" {
  description = "Encryption option for Athena: SSE_S3, SSE_KMS, or CSE_KMS"
  type        = string
  default     = "SSE_S3"
  validation {
    condition     = contains(["SSE_S3", "SSE_KMS", "CSE_KMS"], var.encryption_option)
    error_message = "Valid values: SSE_S3, SSE_KMS, CSE_KMS"
  }
}

variable "kms_key_arn" {
  description = "ARN of a custom KMS key for encryption. If not provided and encryption_option is SSE_KMS or CSE_KMS, a key will be created."
  type        = string
  default     = null
}

variable "named_query_name" {
  description = "Plain language name for the named query"
  type        = string
  default     = "test-query"
}

variable "query_string" {
  description = "SQL query string for the named query"
  type        = string
  default     = "SELECT 1"
}

variable "description" {
  description = "Optional description for the named query"
  type        = string
  default     = null
}

variable "database_name" {
  description = "Database name for the named query. If not set and create_database is true, defaults to the created database."
  type        = string
  default     = null
}

variable "workgroup_name" {
  description = "Workgroup name for the named query. If not set and create_workgroup is true, defaults to the created workgroup."
  type        = string
  default     = null
}

variable "workgroup_description" {
  description = "Description for the Athena workgroup"
  type        = string
  default     = null
}

variable "workgroup_state" {
  description = "State of the workgroup: ENABLED or DISABLED"
  type        = string
  default     = "ENABLED"
  validation {
    condition     = contains(["ENABLED", "DISABLED"], var.workgroup_state)
    error_message = "Valid values: ENABLED, DISABLED"
  }
}

variable "workgroup_force_destroy" {
  description = "Whether to force destroy the workgroup even if it contains named queries"
  type        = bool
  default     = false
}

variable "bytes_scanned_cutoff_per_query" {
  description = "Bytes scanned cutoff per query for the workgroup (0 = disabled)"
  type        = number
  default     = 0
}

variable "enforce_workgroup_configuration" {
  description = "Enforce workgroup configuration"
  type        = bool
  default     = true
}

variable "publish_cloudwatch_metrics_enabled" {
  description = "Publish CloudWatch metrics for the workgroup"
  type        = bool
  default     = false
}

variable "result_configuration_output_location" {
  description = "S3 output location for query results (e.g., s3://bucket/prefix/)"
  type        = string
  default     = null
}

variable "result_configuration_encryption_option" {
  description = "Encryption option for query results: SSE_S3, SSE_KMS, or CSE_KMS"
  type        = string
  default     = null
}

variable "result_configuration_kms_key_arn" {
  description = "KMS key ARN for result encryption (if using SSE_KMS or CSE_KMS)"
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  common_tags = merge(
    {
      Environment = var.environment_tag
    },
    var.tags
  )

  # S3 bucket name (must be globally unique and lowercase)
  bucket_name = "${lower(var.name_prefix)}-athena-results-${random_id.bucket_suffix.hex}"

  # Effective KMS key ARN
  kms_key_arn = var.kms_key_arn != null ? var.kms_key_arn : (
    var.encryption_option == "SSE_KMS" || var.encryption_option == "CSE_KMS" ? aws_kms_key.this[0].arn : null
  )

  # Effective database name for the named query
  named_query_database_name = var.database_name != null ? var.database_name : (
    var.create_database ? aws_athena_database.this[0].name : null
  )

  # Effective workgroup name for the named query
  named_query_workgroup_name = var.workgroup_name != null ? var.workgroup_name : (
    var.create_workgroup ? aws_athena_workgroup.this[0].name : null
  )

  # Effective encryption option for workgroup result configuration
  workgroup_result_encryption_option = var.result_configuration_encryption_option != null ? var.result_configuration_encryption_option : "SSE_S3"

  # Default output location for workgroup result configuration
  workgroup_result_output_location = var.result_configuration_output_location != null ? var.result_configuration_output_location : "s3://${aws_s3_bucket.athena_results.bucket}/output/"
}

# ------------------------------------------------------------------------------
# Random suffix for bucket name
# ------------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# ------------------------------------------------------------------------------
# S3 bucket for Athena query results
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "athena_results" {
  bucket = local.bucket_name
  tags   = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "athena_results" {
  bucket                  = aws_s3_bucket.athena_results.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "athena_results" {
  bucket = aws_s3_bucket.athena_results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption_option == "SSE_KMS" ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption_option == "SSE_KMS" ? local.kms_key_arn : null
    }
  }
}

resource "aws_s3_bucket_versioning" "athena_results" {
  bucket = aws_s3_bucket.athena_results.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# KMS Key (only if needed and not provided)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = (var.kms_key_arn == null && (var.encryption_option == "SSE_KMS" || var.encryption_option == "CSE_KMS")) ? 1 : 0

  description             = "KMS key for Athena encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Athena to use the key"
        Effect = "Allow"
        Principal = {
          Service = "athena.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_kms_alias" "this" {
  count = (var.kms_key_arn == null && (var.encryption_option == "SSE_KMS" || var.encryption_option == "CSE_KMS")) ? 1 : 0

  name          = "alias/${var.name_prefix}-athena-key"
  target_key_id = aws_kms_key.this[0].key_id
}

# ------------------------------------------------------------------------------
# Athena Database (conditional)
# NOTE: aws_athena_database does not support tags or workgroup attribute
# ------------------------------------------------------------------------------
resource "aws_athena_database" "this" {
  count = var.create_database ? 1 : 0

  name          = "${lower(var.name_prefix)}_database"
  bucket        = aws_s3_bucket.athena_results.bucket
  force_destroy = true

  encryption_configuration {
    encryption_option = var.encryption_option
    kms_key           = var.encryption_option == "SSE_KMS" || var.encryption_option == "CSE_KMS" ? local.kms_key_arn : null
  }

  lifecycle {
    ignore_changes = [bucket]
  }
}

# ------------------------------------------------------------------------------
# Athena Workgroup (conditional)
# ------------------------------------------------------------------------------
resource "aws_athena_workgroup" "this" {
  count = var.create_workgroup ? 1 : 0

  name          = "${var.name_prefix}-workgroup"
  description   = var.workgroup_description
  state         = var.workgroup_state
  force_destroy = var.workgroup_force_destroy

  configuration {
    bytes_scanned_cutoff_per_query     = var.bytes_scanned_cutoff_per_query
    enforce_workgroup_configuration    = var.enforce_workgroup_configuration
    publish_cloudwatch_metrics_enabled = var.publish_cloudwatch_metrics_enabled

    result_configuration {
      output_location = local.workgroup_result_output_location

      encryption_configuration {
        encryption_option = local.workgroup_result_encryption_option
        kms_key_arn       = var.result_configuration_kms_key_arn
      }
    }
  }

  tags = local.common_tags
}

# ------------------------------------------------------------------------------
# Athena Named Query (conditional)
# ------------------------------------------------------------------------------
resource "aws_athena_named_query" "this" {
  count = var.create_named_query ? 1 : 0

  name        = var.named_query_name
  description = var.description
  database    = local.named_query_database_name
  query       = var.query_string
  workgroup   = local.named_query_workgroup_name
}

# ------------------------------------------------------------------------------
# Data Sources (static provider metadata only)
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "database_id" {
  description = "ID of the Athena database (if created)"
  value       = try(aws_athena_database.this[0].id, null)
}

output "named_query_id" {
  description = "ID of the Athena named query (if created)"
  value       = try(aws_athena_named_query.this[0].id, null)
}

output "workgroup_id" {
  description = "ID of the Athena workgroup (if created)"
  value       = try(aws_athena_workgroup.this[0].id, null)
}

output "workgroup_arn" {
  description = "ARN of the Athena workgroup (if created)"
  value       = try(aws_athena_workgroup.this[0].arn, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "environment" {
  description = "The environment name for the deployment"
  type        = string
  default     = "dev"
}

variable "cluster_name" {
  description = "The name of the cluster or application"
  type        = string
  default     = "Fast-App"
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Locals for tagging
locals {
  common_tags = {
    Environment = var.environment
    ClusterName = var.cluster_name
    ManagedBy   = "Terraform"
  }
  name_prefix = "${var.cluster_name}-${var.environment}"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Public subnets
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.64.0/19"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.96.0/19"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-b"
  })
}

# Private subnets
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/19"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.32.0/19"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-b"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-route-table"
  })
}

# Route table associations
resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "private_subnet_ids" {
  value = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]
}

output "public_subnet_ids" {
  value = [
    aws_subnet.public_a.id,
    aws_subnet.public_b.id,
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-cluster"
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = "1.30"
}

variable "name_prefix" {
  description = "Optional prefix for IAM resource names"
  type        = string
  default     = ""
}

variable "path" {
  description = "IAM path for all IAM roles and instance profile"
  type        = string
  default     = "/"
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of a permissions boundary to attach to all IAM roles"
  type        = string
  default     = null
}

variable "create" {
  description = "Whether to create all resources"
  type        = bool
  default     = true
}

variable "create_irsa" {
  description = "Whether to create the IRSA role and policy"
  type        = bool
  default     = true
}

variable "create_node_role" {
  description = "Whether to create the Karpenter node IAM role"
  type        = bool
  default     = true
}

variable "create_instance_profile" {
  description = "Whether to create the Karpenter instance profile"
  type        = bool
  default     = true
}

variable "enable_spot_termination" {
  description = "Whether to create the SQS queue and CloudWatch event rules for spot termination handling"
  type        = bool
  default     = true
}

variable "additional_node_policies" {
  description = "List of additional IAM policy ARNs to attach to the Karpenter node role"
  type        = list(string)
  default     = []
}

variable "additional_irsa_policies" {
  description = "List of additional IAM policy ARNs to attach to the IRSA role"
  type        = list(string)
  default     = []
}

variable "ip_family" {
  description = "IP family of the EKS cluster (ipv4 or ipv6)"
  type        = string
  default     = "ipv4"
  validation {
    condition     = var.ip_family == "ipv4" || var.ip_family == "ipv6"
    error_message = "IP family must be either 'ipv4' or 'ipv6'."
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Local values
locals {
  cluster_name   = var.cluster_name
  name_prefix    = var.name_prefix != "" ? "${var.name_prefix}-" : ""
  full_name      = "${local.name_prefix}${local.cluster_name}"
  oidc_issuer    = var.create ? aws_eks_cluster.this[0].identity[0].oidc[0].issuer : ""
  oidc_provider_arn = var.create ? aws_iam_openid_connect_provider.this[0].arn : ""
  cni_policy_arn = var.ip_family == "ipv4" ? "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy" : "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy_IPv6"
}

# VPC and subnets for EKS cluster
resource "aws_vpc" "this" {
  count = var.create ? 1 : 0
  cidr_block = "10.0.0.0/16"
  enable_dns_support = true
  tags = {
    Name = "${local.full_name}-vpc"
  }
}

resource "aws_internet_gateway" "this" {
  count = var.create ? 1 : 0
  vpc_id = aws_vpc.this[0].id
  tags = {
    Name = "${local.full_name}-igw"
  }
}

# Public subnet for NAT gateway
resource "aws_subnet" "public" {
  count = var.create ? 1 : 0
  vpc_id            = aws_vpc.this[0].id
  cidr_block        = cidrsubnet(aws_vpc.this[0].cidr_block, 8, 0)
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = {
    Name = "${local.full_name}-public-subnet-0"
    "kubernetes.io/cluster/${local.full_name}" = "shared"
    "kubernetes.io/role/elb"                  = "1"
  }
}

# Private subnets for nodes
resource "aws_subnet" "private" {
  count = var.create ? 2 : 0
  vpc_id            = aws_vpc.this[0].id
  cidr_block        = cidrsubnet(aws_vpc.this[0].cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${local.full_name}-private-subnet-${count.index}"
    "kubernetes.io/cluster/${local.full_name}" = "shared"
    "kubernetes.io/role/internal-elb"          = "1"
  }
}

# Elastic IP for NAT gateway
resource "aws_eip" "nat" {
  count = var.create ? 1 : 0
  domain = "vpc"
  tags = {
    Name = "${local.full_name}-nat-eip"
  }
}

# NAT gateway
resource "aws_nat_gateway" "this" {
  count = var.create ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  tags = {
    Name = "${local.full_name}-nat"
  }
}

# Route table for public subnets (with IGW)
resource "aws_route_table" "public" {
  count = var.create ? 1 : 0
  vpc_id = aws_vpc.this[0].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[0].id
  }
  timeouts {
    create = "1s"
  }
}

# Route table for private subnets (with NAT)
resource "aws_route_table" "private" {
  count = var.create ? 1 : 0
  vpc_id = aws_vpc.this[0].id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[0].id
  }
  timeouts {
    create = "1s"
  }
}

# Association for public subnet
resource "aws_route_table_association" "public" {
  count = var.create ? 1 : 0
  subnet_id      = aws_subnet.public[0].id
  route_table_id = aws_route_table.public[0].id
}

# Association for private subnets
resource "aws_route_table_association" "private" {
  count = var.create ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Security group for EKS cluster (control plane)
resource "aws_security_group" "cluster" {
  count = var.create ? 1 : 0
  name        = "${local.full_name}-cluster-sg"
  description = "Security group for EKS cluster"
  vpc_id      = aws_vpc.this[0].id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.this[0].cidr_block]
  }
  timeouts {
    create = "1s"
  }
}

# EKS cluster IAM role
resource "aws_iam_role" "eks_cluster" {
  count = var.create ? 1 : 0
  name = "${local.name_prefix}eks-cluster-role"
  path = var.path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  permissions_boundary = var.permissions_boundary_arn
  tags = {
    Name = "${local.name_prefix}eks-cluster-role"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_AmazonEKSClusterPolicy" {
  count = var.create ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster[0].name
}

# EKS cluster
resource "aws_eks_cluster" "this" {
  count = var.create ? 1 : 0
  name     = local.full_name
  role_arn = aws_iam_role.eks_cluster[0].arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_public_access  = false
    endpoint_private_access = true
    security_group_ids      = [aws_security_group.cluster[0].id]
  }

  access_config {
    bootstrap_cluster_creator_admin_permissions = true
  }

  timeouts {
    create = "15m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_AmazonEKSClusterPolicy,
    aws_internet_gateway.this,
    aws_nat_gateway.this
  ]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.full_name
  }
}

# EKS node group IAM role
resource "aws_iam_role" "eks_node_group" {
  count = var.create ? 1 : 0
  name = "${local.name_prefix}eks-node-group-role"
  path = var.path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  permissions_boundary = var.permissions_boundary_arn
  tags = {
    Name = "${local.name_prefix}eks-node-group-role"
  }
}

resource "aws_iam_role_policy_attachment" "eks_node_group_AmazonEKSWorkerNodePolicy" {
  count = var.create ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node_group[0].name
}

resource "aws_iam_role_policy_attachment" "eks_node_group_AmazonEC2ContainerRegistryReadOnly" {
  count = var.create ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node_group[0].name
}

resource "aws_iam_role_policy_attachment" "eks_node_group_AmazonEKS_CNI_Policy" {
  count = var.create ? 1 : 0
  policy_arn = local.cni_policy_arn
  role       = aws_iam_role.eks_node_group[0].name
}

# Managed node group (initial nodes to run Karpenter)
resource "aws_eks_node_group" "this" {
  count = var.create ? 1 : 0
  cluster_name    = aws_eks_cluster.this[0].name
  node_group_name_prefix = "${local.full_name}-initial-"
  node_role_arn   = aws_iam_role.eks_node_group[0].arn
  subnet_ids      = aws_subnet.private[*].id
  instance_types  = ["t3.medium"]
  ami_type        = "AL2_x86_64"
  disk_size       = 20

  scaling_config {
    desired_size = 2
    max_size     = 3
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }

  timeouts {
    create = "15m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_node_group_AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.eks_node_group_AmazonEC2ContainerRegistryReadOnly,
    aws_iam_role_policy_attachment.eks_node_group_AmazonEKS_CNI_Policy
  ]

  tags = {
    Name = "${local.full_name}-initial-node-group"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# IAM OIDC provider for the cluster
resource "aws_iam_openid_connect_provider" "this" {
  count = var.create ? 1 : 0
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["9e99a48a9960b14926bb7f3b02e22da2b0ab7280"] # Amazon root CA thumbprint
  url             = aws_eks_cluster.this[0].identity[0].oidc[0].issuer
  tags = {
    Name = "${local.full_name}-oidc"
  }
}

# Karpenter IRSA role
resource "aws_iam_role" "karpenter_irsa" {
  count = var.create && var.create_irsa ? 1 : 0
  name = "${local.name_prefix}karpenter-irsa"
  path = var.path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = local.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(local.oidc_issuer, "https://", "")}:sub" = "system:serviceaccount:karpenter:karpenter"
          }
        }
      }
    ]
  })
  permissions_boundary = var.permissions_boundary_arn
  tags = {
    Name = "${local.name_prefix}karpenter-irsa"
  }
}

# Karpenter IRSA policy
resource "aws_iam_policy" "karpenter_irsa" {
  count = var.create && var.create_irsa ? 1 : 0
  name  = "${local.name_prefix}karpenter-irsa-policy"
  path  = var.path
  description = "Policy for Karpenter service account"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat([
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateLaunchTemplate",
          "ec2:CreateFleet",
          "ec2:CreateTags",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstances",
          "ec2:DescribeImages",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeSpotPriceHistory",
          "ec2:DescribeFleetHistory",
          "ec2:DescribeFleetInstances",
          "ec2:DescribeLaunchTemplates",
          "ec2:DescribeTags",
          "ec2:GetLaunchTemplateData",
          "ec2:DescribeInstanceTypeOfferings",
          "pricing:GetProducts",
          "ssm:GetParameter",
          "iam:PassRole"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:TerminateInstances",
          "ec2:DeleteLaunchTemplate"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/karpenter.sh/discovery" = local.full_name
          }
        }
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = var.create && var.create_node_role ? aws_iam_role.karpenter_node[0].arn : "*"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ec2.amazonaws.com"
          }
        }
      }
    ], var.enable_spot_termination ? [
      {
        Effect = "Allow"
        Action = [
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage",
          "sqs:GetQueueUrl",
          "sqs:GetQueueAttributes"
        ]
        Resource = var.create && var.enable_spot_termination ? aws_sqs_queue.karpenter[0].arn : "*"
      }
    ] : [])
  })
}

resource "aws_iam_role_policy_attachment" "karpenter_irsa" {
  count = var.create && var.create_irsa ? 1 : 0
  policy_arn = aws_iam_policy.karpenter_irsa[0].arn
  role       = aws_iam_role.karpenter_irsa[0].name
}

resource "aws_iam_role_policy_attachment" "karpenter_irsa_additional" {
  count = var.create && var.create_irsa ? length(var.additional_irsa_policies) : 0
  policy_arn = var.additional_irsa_policies[count.index]
  role       = aws_iam_role.karpenter_irsa[0].name
}

# Karpenter node IAM role
resource "aws_iam_role" "karpenter_node" {
  count = var.create && var.create_node_role ? 1 : 0
  name = "${local.name_prefix}karpenter-node"
  path = var.path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  permissions_boundary = var.permissions_boundary_arn
  tags = {
    Name = "${local.name_prefix}karpenter-node"
  }
}

resource "aws_iam_role_policy_attachment" "karpenter_node_AmazonEKSWorkerNodePolicy" {
  count = var.create && var.create_node_role ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.karpenter_node[0].name
}

resource "aws_iam_role_policy_attachment" "karpenter_node_AmazonEC2ContainerRegistryReadOnly" {
  count = var.create && var.create_node_role ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.karpenter_node[0].name
}

resource "aws_iam_role_policy_attachment" "karpenter_node_AmazonEKS_CNI_Policy" {
  count = var.create && var.create_node_role ? 1 : 0
  policy_arn = local.cni_policy_arn
  role       = aws_iam_role.karpenter_node[0].name
}

resource "aws_iam_role_policy_attachment" "karpenter_node_additional" {
  count = var.create && var.create_node_role ? length(var.additional_node_policies) : 0
  policy_arn = var.additional_node_policies[count.index]
  role       = aws_iam_role.karpenter_node[0].name
}

# Karpenter instance profile
resource "aws_iam_instance_profile" "karpenter" {
  count = var.create && var.create_instance_profile ? 1 : 0
  name_prefix = "${local.name_prefix}karpenter-instance-profile-"
  path = var.path
  role = aws_iam_role.karpenter_node[0].name
  timeouts {
    create = "1s"
  }
  depends_on = [
    aws_iam_role.karpenter_node
  ]
}

# SQS queue for spot termination events
resource "aws_sqs_queue" "karpenter" {
  count = var.create && var.enable_spot_termination ? 1 : 0
  name                      = "Karpenter-${local.full_name}"
  timeouts {
    create = "1s"
  }
}

# Outputs
output "cluster_oidc_issuer_url" {
  value = try(aws_eks_cluster.this[0].identity[0].oidc[0].issuer, null)
}

output "cluster_arn" {
  value = try(aws_eks_cluster.this[0].arn, null)
}

output "irsa_role_name" {
  value = try(aws_iam_role.karpenter_irsa[0].name, null)
}

output "irsa_role_arn" {
  value = try(aws_iam_role.karpenter_irsa[0].arn, null)
}

output "irsa_role_unique_id" {
  value = try(aws_iam_role.karpenter_irsa[0].unique_id, null)
}

output "node_role_name" {
  value = try(aws_iam_role.karpenter_node[0].name, null)
}

output "node_role_arn" {
  value = try(aws_iam_role.karpenter_node[0].arn, null)
}

output "node_role_unique_id" {
  value = try(aws_iam_role.karpenter_node[0].unique_id, null)
}

output "instance_profile_arn" {
  value = try(aws_iam_instance_profile.karpenter[0].arn, null)
}

output "instance_profile_id" {
  value = try(aws_iam_instance_profile.karpenter[0].id, null)
}

output "instance_profile_name" {
  value = try(aws_iam_instance_profile.karpenter[0].name, null)
}

output "instance_profile_unique_id" {
  value = try(aws_iam_instance_profile.karpenter[0].unique_id, null)
}

output "sqs_queue_arn" {
  value = try(aws_sqs_queue.karpenter[0].arn, null)
}

output "sqs_queue_name" {
  value = try(aws_sqs_queue.karpenter[0].name, null)
}

output "sqs_queue_url" {
  value = try(aws_sqs_queue.karpenter[0].url, null)
}

output "event_rules" {
  value = null
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "name_prefix" {
  description = "Prefix for all resource names. Only letters and hyphens allowed."
  type        = string
  default     = "ecr-prefix"

  validation {
    condition     = can(regex("^[a-zA-Z-]+$", var.name_prefix))
    error_message = "The name_prefix must contain only letters and hyphens."
  }
}

variable "private_repositories" {
  description = "List of private ECR repository configurations."
  type = list(object({
    name                = string
    image_tag_mutability = optional(string, "IMMUTABLE") # "IMMUTABLE" or "MUTABLE"
    pull_accounts       = optional(list(string), [])
    pull_roles          = optional(list(string), [])
    push_accounts       = optional(list(string), [])
    push_roles          = optional(list(string), [])
  }))
  default = []
}

variable "global_pull_accounts" {
  description = "AWS account IDs that can pull from all private repositories."
  type        = list(string)
  default     = []
}

variable "global_push_accounts" {
  description = "AWS account IDs that can push to all private repositories."
  type        = list(string)
  default     = []
}

variable "public_repositories" {
  description = "List of public ECR repository configurations."
  type = list(object({
    name             = string
    about_text       = optional(string, "")
    architectures    = optional(list(string), [])
    description      = optional(string, "")
    logo_image_blob  = optional(string, "")
    operating_systems = optional(list(string), [])
    usage_text       = optional(string, "")
    push_accounts    = optional(list(string), [])
    push_roles       = optional(list(string), [])
  }))
  default = []
}

variable "global_public_push_accounts" {
  description = "AWS account IDs that can push to all public repositories."
  type        = list(string)
  default     = []
}

variable "create_iam_users" {
  description = "Whether to create IAM users for each repository with programmatic access keys."
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  # Default tags that must be applied to all resources
  default_tags = {
    module = "pippi.io/aws-ecr"
    workspace = terraform.workspace
  }
  # Merge with name prefix tag
  common_tags = merge(local.default_tags, { Name = var.name_prefix })

  # Current account ID for convenience
  current_account_id = data.aws_caller_identity.current.account_id
}

# ------------------------------------------------------------------------------
# KMS Key for private repository encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  description             = "KMS key for ECR private repository encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.current_account_id}:root"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  timeouts {
    create = "30m"
  }
  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/${var.name_prefix}-ecr-key"
  target_key_id = aws_kms_key.this.key_id
}

# ------------------------------------------------------------------------------
# Private ECR Repositories
# ------------------------------------------------------------------------------
resource "aws_ecr_repository" "private" {
  for_each = { for repo in var.private_repositories : repo.name => repo }

  name                 = "${var.name_prefix}-${each.value.name}"
  image_tag_mutability = each.value.image_tag_mutability

  encryption_configuration {
    encryption_type = "KMS"
    kms_key        = aws_kms_key.this.arn
  }

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Private Repository Policies
# ------------------------------------------------------------------------------
resource "aws_ecr_repository_policy" "private" {
  for_each = { for repo in var.private_repositories : repo.name => repo }

  repository = aws_ecr_repository.private[each.key].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      # Pull permissions
      [
        for principal in distinct(concat(
          each.value.pull_accounts,
          each.value.pull_roles,
          var.global_pull_accounts,
          [local.current_account_id]  # always include current account root
        )) : {
          Sid    = "PullAccess-${replace(principal, "/", "-")}"
          Effect = "Allow"
          Principal = {
            AWS = length(regexall("^arn:", principal)) > 0 ? principal : "arn:aws:iam::${principal}:root"
          }
          Action = [
            "ecr:BatchCheckLayerAvailability",
            "ecr:BatchGetImage",
            "ecr:GetDownloadUrlForLayer"
          ]
          Resource = aws_ecr_repository.private[each.key].arn
        }
      ],
      # Push permissions
      [
        for principal in distinct(concat(
          each.value.push_accounts,
          each.value.push_roles,
          var.global_push_accounts,
          [local.current_account_id]  # always include current account root
        )) : {
          Sid    = "PushAccess-${replace(principal, "/", "-")}"
          Effect = "Allow"
          Principal = {
            AWS = length(regexall("^arn:", principal)) > 0 ? principal : "arn:aws:iam::${principal}:root"
          }
          Action = [
            "ecr:BatchCheckLayerAvailability",
            "ecr:CompleteLayerUpload",
            "ecr:InitiateLayerUpload",
            "ecr:PutImage",
            "ecr:UploadLayerPart"
          ]
          Resource = aws_ecr_repository.private[each.key].arn
        }
      ]
    )
  })
}

# ------------------------------------------------------------------------------
# Public ECR Repositories
# ------------------------------------------------------------------------------
resource "aws_ecrpublic_repository" "public" {
  for_each = { for repo in var.public_repositories : repo.name => repo }

  repository_name = "${var.name_prefix}-${each.value.name}"

  catalog_data {
    about_text        = each.value.about_text
    architectures     = each.value.architectures
    description       = each.value.description
    logo_image_blob   = each.value.logo_image_blob
    operating_systems = each.value.operating_systems
    usage_text        = each.value.usage_text
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Public Repository Policies
# ------------------------------------------------------------------------------
resource "aws_ecrpublic_repository_policy" "public" {
  for_each = { for repo in var.public_repositories : repo.name => repo }

  repository_name = aws_ecrpublic_repository.public[each.key].repository_name

  policy = jsonencode({
    Version = "2008-10-17"
    Statement = [
      for principal in distinct(concat(
        each.value.push_accounts,
        each.value.push_roles,
        var.global_public_push_accounts,
        [local.current_account_id]  # always include current account root
      )) : {
        Sid    = "PushAccess-${replace(principal, "/", "-")}"
        Effect = "Allow"
        Principal = {
          AWS = length(regexall("^arn:", principal)) > 0 ? principal : "arn:aws:iam::${principal}:root"
        }
        Action = [
          "ecr-public:BatchCheckLayerAvailability",
          "ecr-public:CompleteLayerUpload",
          "ecr-public:InitiateLayerUpload",
          "ecr-public:PutImage",
          "ecr-public:UploadLayerPart"
        ]
        Resource = aws_ecrpublic_repository.public[each.key].arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Optional IAM Users for each repository
# ------------------------------------------------------------------------------
resource "aws_iam_user" "private" {
  for_each = var.create_iam_users ? { for repo in var.private_repositories : repo.name => repo } : {}

  name = "${var.name_prefix}-${each.key}-ecr-user"
  tags = local.common_tags
}

resource "aws_iam_user" "public" {
  for_each = var.create_iam_users ? { for repo in var.public_repositories : repo.name => repo } : {}

  name = "${var.name_prefix}-${each.key}-ecr-public-user"
  tags = local.common_tags
}

resource "aws_iam_access_key" "private" {
  for_each = aws_iam_user.private

  user = each.value.name
}

resource "aws_iam_access_key" "public" {
  for_each = aws_iam_user.public

  user = each.value.name
}

# Private repository user policy
resource "aws_iam_user_policy" "private" {
  for_each = aws_iam_user.private

  name = "${each.value.name}-policy"
  user = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRAccess"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:CompleteLayerUpload",
          "ecr:InitiateLayerUpload",
          "ecr:PutImage",
          "ecr:UploadLayerPart",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = [
          aws_ecr_repository.private[each.key].arn,
          "arn:aws:ecr:${data.aws_region.current.name}:${local.current_account_id}:repository/*"
        ]
      }
    ]
  })
}

# Public repository user policy
resource "aws_iam_user_policy" "public" {
  for_each = aws_iam_user.public

  name = "${each.value.name}-policy"
  user = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRPublicAccess"
        Effect = "Allow"
        Action = [
          "ecr-public:GetAuthorizationToken",
          "ecr-public:BatchCheckLayerAvailability",
          "ecr-public:CompleteLayerUpload",
          "ecr-public:InitiateLayerUpload",
          "ecr-public:PutImage",
          "ecr-public:UploadLayerPart"
        ]
        Resource = [
          aws_ecrpublic_repository.public[each.key].arn,
          "arn:aws:ecr-public:us-east-1:${local.current_account_id}:repository/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "private_repositories" {
  description = "Details of all private ECR repositories."
  value = {
    for name, repo in aws_ecr_repository.private :
    name => {
      repository_url = repo.repository_url
      arn            = repo.arn
      name           = repo.name
    }
  }
}

output "public_repositories" {
  description = "Details of all public ECR repositories."
  value = {
    for name, repo in aws_ecrpublic_repository.public :
    name => {
      repository_uri = repo.repository_uri
      arn            = repo.arn
      name           = repo.repository_name
    }
  }
}

output "iam_users" {
  description = "Map of IAM user names to their ARN, access key ID, and secret access key."
  sensitive   = true
  value = merge(
    {
      for name, user in aws_iam_user.private :
      name => {
        user_name       = user.name
        arn             = user.arn
        access_key_id   = aws_iam_access_key.private[name].id
        secret_access_key = aws_iam_access_key.private[name].secret
      }
    },
    {
      for name, user in aws_iam_user.public :
      name => {
        user_name       = user.name
        arn             = user.arn
        access_key_id   = aws_iam_access_key.public[name].id
        secret_access_key = aws_iam_access_key.public[name].secret
      }
    }
  )
}

terraform {
  required_providers {
    null = {
      source  = "hashicorp/null"
      version = "~> 3.1.1"
    }
  }
}

locals {
  resource_groups = {
    alpha = {
      region    = "eastus"
      vnet_name = "omega"
    }
    bravo = {
      region    = "southindia"
      vnet_name = "psi"
    }
    charlie = {
      region    = "westus2"
      vnet_name = "chi"
    }
  }
}

resource "null_resource" "resource_group" {
  for_each = local.resource_groups
  triggers = {
    name   = each.key
    region = each.value.region
  }
}

resource "null_resource" "virtual_network" {
  for_each = local.resource_groups
  triggers = {
    name     = each.key
    region   = each.value.region
    vnet_name = each.value.vnet_name
  }
}

output "challenge_p1" {
  value = null_resource.resource_group
}

output "challenge_p2" {
  value = null_resource.virtual_network
}

data "aws_iam_policy_document" "cognito_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cognito-idp.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cognito_assume_role" {
  name               = "cognito-assume-role"
  assume_role_policy = data.aws_iam_policy_document.cognito_trust.json
}

data "aws_iam_policy_document" "cognito_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "cognito-idp:DescribeUserPool"
    ]
    resources = [
      aws_cognito_user_pool.box_things.arn
    ]
  }
}

resource "aws_iam_policy" "cognito_policy" {
  name        = "cognito-policy"
  description = "Minimal policy for Cognito to describe its user pool"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_role_policy_attachment" "cognito_attach" {
  role       = aws_iam_role.cognito_assume_role.name
  policy_arn = aws_iam_policy.cognito_policy.arn
}

resource "aws_cognito_user_pool" "box_things" {
  name = "box_things"

  alias_attributes = ["email"]

  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length                   = 8
    require_uppercase                = true
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  verification_message_template {
    default_email_option  = "CONFIRM_WITH_LINK"
    email_subject         = "Confirm your account"
    email_message_by_link = "To confirm your account please click on the link. {####}"
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = false
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = "box_things_client"
  user_pool_id = aws_cognito_user_pool.box_things.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_ecs_task_definition" "test_no_env" {
  family                   = "foo"
  requires_compatibilities = ["EC2"]
  network_mode             = "bridge"
  cpu                      = "10"
  memory                   = "512"

  container_definitions = jsonencode([
    {
      name      = "foobar"
      image     = "foobar"
      cpu       = 10
      memory    = 512
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      environment = []
    }
  ])
}

resource "aws_ecs_task_definition" "test_safe_bar" {
  family                   = "foo"
  requires_compatibilities = ["EC2"]
  network_mode             = "bridge"
  cpu                      = "10"
  memory                   = "512"

  container_definitions = jsonencode([
    {
      name      = "foobar"
      image     = "foobar"
      cpu       = 10
      memory    = 512
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "BAR"
          value = "bar"
        }
      ]
    }
  ])
}

resource "aws_ecs_task_definition" "test_safe_20char" {
  family                   = "foo"
  requires_compatibilities = ["EC2"]
  network_mode             = "bridge"
  cpu                      = "10"
  memory                   = "512"

  container_definitions = jsonencode([
    {
