}

variable "poweruser_policy_arns" {
  description = "List of managed or custom policy ARNs to attach to the poweruser role."
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/PowerUserAccess"]
}

variable "poweruser_mfa_required" {
  description = "Whether MFA is required for the poweruser role."
  type        = bool
  default     = false
}

variable "poweruser_mfa_age" {
  description = "Maximum age in seconds for MFA token when MFA is required."
