# ----------------------------------------------------------------------------------------------------------------------
# READONLY ROLE VARIABLES
# ----------------------------------------------------------------------------------------------------------------------

variable "create_readonly_role" {
  description = "Whether to create the readonly role."
  type        = bool
  default     = true
}

variable "readonly_role_name" {
  description = "Name of the readonly IAM role."
  type        = string
  default     = "readonly"
}

variable "readonly_role_path" {
  description = "Path for the readonly IAM role."
  type        = string
  default     = "/"
}

variable "readonly_role_description" {
  description = "Description for the readonly IAM role."
  type        = string
  default     = "Read-only role with read-only access"
}

variable "readonly_permissions_boundary" {
  description = "ARN of the permissions boundary policy for the readonly role."
  type        = string
  default     = ""
}

variable "readonly_role_tags" {
  description = "Tags to attach to the readonly role."
  type        = map(string)
  default     = {}
}

variable "readonly_policy_arns" {
  description = "List of managed or custom policy ARNs to attach to the readonly role."
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/ReadOnlyAccess"]
}

variable "readonly_mfa_required" {
  description = "Whether MFA is required for the readonly role."
  type        = bool
  default     = false
}

variable "readonly_mfa_age" {
  description = "Maximum age in seconds for MFA token when MFA is required."
  type        = number
  default     = 86400
}

variable "readonly_trusted_role_arns" {
  description = "List of AWS principal ARNs allowed to assume the readonly role."
  type        = list(string)
  default     = []
}

variable "readonly_trusted_role_services" {
  description = "List of AWS services allowed to assume the readonly role."
  type        = list(string)
  default     = []
}

variable "readonly_session_duration" {
  description = "Maximum session duration in seconds for the readonly role (3600-43200)."
  type        = number
  default     = 3600

  validation {
    condition     = var.readonly_session_duration >= 3600 && var.readonly_session_duration <= 43200
    error_message = "The session duration must be between 3600 and 43200 seconds."
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# TRUST POLICY DOCUMENTS
# ----------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_trust_policy" {
  count = var.create_admin_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.admin_trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.admin_trusted_role_services
    }

    dynamic "condition" {
      for_each = var.admin_mfa_required ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = var.admin_mfa_required ? [1] : []
      content {
        test     = "NumericLessThan"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.admin_mfa_age)]
      }
    }
  }
}

data "aws_iam_policy_document" "poweruser_trust_policy" {
  count = var.create_poweruser_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.poweruser_trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.poweruser_trusted_role_services
    }

    dynamic "condition" {
      for_each = var.poweruser_mfa_required ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = var.poweruser_mfa_required ? [1] : []
      content {
        test     = "NumericLessThan"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.poweruser_mfa_age)]
      }
    }
  }
}

data "aws_iam_policy_document" "readonly_trust_policy" {
  count = var.create_readonly_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.readonly_trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.readonly_trusted_role_services
    }

    dynamic "condition" {
      for_each = var.readonly_mfa_required ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = var.readonly_mfa_required ? [1] : []
      content {
        test     = "NumericLessThan"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.readonly_mfa_age)]
      }
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# IAM ROLES
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "admin" {
  count = var.create_admin_role ? 1 : 0

  name                 = var.admin_role_name
  path                 = var.admin_role_path
  description          = var.admin_role_description
  assume_role_policy   = data.aws_iam_policy_document.admin_trust_policy[0].json
  permissions_boundary = var.admin_permissions_boundary != "" ? var.admin_permissions_boundary : null
  force_detach_policies = var.force_detach_policies
  max_session_duration  = var.admin_session_duration
  tags                  = var.admin_role_tags
}

resource "aws_iam_role" "poweruser" {
  count = var.create_poweruser_role ? 1 : 0

  name                 = var.poweruser_role_name
  path                 = var.poweruser_role_path
  description          = var.poweruser_role_description
  assume_role_policy   = data.aws_iam_policy_document.poweruser_trust_policy[0].json
  permissions_boundary = var.poweruser_permissions_boundary != "" ? var.poweruser_permissions_boundary : null
  force_detach_policies = var.force_detach_policies
  max_session_duration  = var.poweruser_session_duration
  tags                  = var.poweruser_role_tags
}

resource "aws_iam_role" "readonly" {
  count = var.create_readonly_role ? 1 : 0

  name                 = var.readonly_role_name
  path                 = var.readonly_role_path
  description          = var.readonly_role_description
  assume_role_policy   = data.aws_iam_policy_document.readonly_trust_policy[0].json
  permissions_boundary = var.readonly_permissions_boundary != "" ? var.readonly_permissions_boundary : null
  force_detach_policies = var.force_detach_policies
  max_session_duration  = var.readonly_session_duration
  tags                  = var.readonly_role_tags
}

# ----------------------------------------------------------------------------------------------------------------------
# POLICY ATTACHMENTS
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "admin" {
  for_each = var.create_admin_role ? toset(var.admin_policy_arns) : toset([])

  role       = aws_iam_role.admin[0].name
  policy_arn = each.value
}

resource "aws_iam_role_policy_attachment" "poweruser" {
  for_each = var.create_poweruser_role ? toset(var.poweruser_policy_arns) : toset([])

  role       = aws_iam_role.poweruser[0].name
  policy_arn = each.value
}

resource "aws_iam_role_policy_attachment" "readonly" {
  for_each = var.create_readonly_role ? toset(var.readonly_policy_arns) : toset([])

  role       = aws_iam_role.readonly[0].name
  policy_arn = each.value
}

# ----------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ----------------------------------------------------------------------------------------------------------------------

output "admin_role_arn" {
  description = "ARN of the admin IAM role."
  value       = var.create_admin_role ? aws_iam_role.admin[0].arn : null
}

output "admin_role_name" {
  description = "Name of the admin IAM role."
  value       = var.create_admin_role ? aws_iam_role.admin[0].name : null
}

output "admin_role_path" {
  description = "Path of the admin IAM role."
  value       = var.create_admin_role ? aws_iam_role.admin[0].path : null
}

output "admin_role_unique_id" {
  description = "Unique ID of the admin IAM role."
  value       = var.create_admin_role ? aws_iam_role.admin[0].unique_id : null
}

output "admin_role_mfa_required" {
  description = "Whether MFA is required for the admin role."
  value       = var.admin_mfa_required
}

output "poweruser_role_arn" {
  description = "ARN of the poweruser IAM role."
  value       = var.create_poweruser_role ? aws_iam_role.poweruser[0].arn : null
}

output "poweruser_role_name" {
  description = "Name of the poweruser IAM role."
  value       = var.create_poweruser_role ? aws_iam_role.poweruser[0].name : null
}

output "poweruser_role_path" {
  description = "Path of the poweruser IAM role."
  value       = var.create_poweruser_role ? aws_iam_role.poweruser[0].path : null
}

output "poweruser_role_unique_id" {
  description = "Unique ID of the poweruser IAM role."
  value       = var.create_poweruser_role ? aws_iam_role.poweruser[0].unique_id : null
}

output "poweruser_role_mfa_required" {
  description = "Whether MFA is required for the poweruser role."
  value       = var.poweruser_mfa_required
}

output "readonly_role_arn" {
  description = "ARN of the readonly IAM role."
  value       = var.create_readonly_role ? aws_iam_role.readonly[0].arn : null
}

output "readonly_role_name" {
  description = "Name of the readonly IAM role."
  value       = var.create_readonly_role ? aws_iam_role.readonly[0].name : null
}

output "readonly_role_path" {
  description = "Path of the readonly IAM role."
  value       = var.create_readonly_role ? aws_iam_role.readonly[0].path : null
}

output "readonly_role_unique_id" {
  description = "Unique ID of the readonly IAM role."
  value       = var.create_readonly_role ? aws_iam_role.readonly[0].unique_id : null
}

output "readonly_role_mfa_required" {
  description = "Whether MFA is required for the readonly role."
  value       = var.readonly_mfa_required
}

terraform {
  required_version = "~> 1.12, < 2.0.0"
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5, < 4.0.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "string_length" {
  description = "Length of the generated random string"
  type        = number
  default     = 16
}

variable "include_uppercase" {
  description = "Whether to include uppercase letters in the generated string"
  type        = bool
  default     = false
}

variable "password_length" {
  description = "Length of the generated password"
  type        = number
  default     = 16
}

variable "integer_min" {
  description = "Minimum value for the random integer"
  type        = number
  default     = 1
}

variable "integer_max" {
  description = "Maximum value for the random integer"
  type        = number
  default     = 50000
}

resource "random_string" "string" {
  length    = var.string_length
  lower     = true
  upper     = var.include_uppercase
  numeric   = false
  special   = false
  min_lower = 1
  min_upper = var.include_uppercase ? 1 : 0
}

resource "random_password" "password" {
  length           = var.password_length
  lower            = true
  upper            = true
  numeric          = true
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_uuid" "uuid" {}

resource "random_integer" "integer" {
  min = var.integer_min
  max = var.integer_max
}

output "generated_string" {
  value = random_string.string.result
}

output "generated_uuid" {
  value = random_uuid.uuid.result
}

output "generated_integer" {
  value = random_integer.integer.result
}

output "generated_password" {
  value     = random_password.password.result
  sensitive = true
}
